(window.LUMINA_T = window.LUMINA_T || {})["sport"] = [{"pmid":"42997425","title":"Effect of High-Power Laser Acupuncture on Fatigue and Proprioception in Chronic Nonspecific Low Back Pain: A Randomized Controlled Trial.","journal_abbr":"J Pain Res","authors":["Elimy DA","Elsayed SH","Alshehre YM","et al."],"date":"2026-11-02","year":2026,"doi":"10.2147/JPR.S650033","pmcid":"PMC13741997","curated":false,"type":"autre","level":0,"ctx":["performance","récupération"],"l1":"In cases of CNLBP, adding HPLA as an adjunct to exercise therapy may improve back muscle fatigue, endurance, lumbar proprioception, pain severity, and pain self-efficacy over a six-week intervention period. However, these short-term…","kw":"laser acupuncture low back pain muscular endurance muscular fatigue proprioception"},{"pmid":"42902543","title":"Sleep, inflammation, and pain in musculoskeletal rehabilitation: a structured integrative review of neurobiological mechanisms and non-pharmacological pain management strategies.","journal_abbr":"Pain Manag","authors":["de Freitas EM","Silva A","Esteves AM"],"date":"2026-10-20","year":2026,"doi":"10.1080/17581869.2026.2748285","pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"title_fr":"Sommeil, inflammation et douleur dans la rééducation musculo-squelettique : examen intégratif structuré des mécanismes neurobiologiques et des stratégies non pharmacologiques de gestion de la douleur","tr":1,"l1":"Sleep assessment and sleep-focused interventions should be considered within multimodal musculoskeletal pain management, while further controlled research clarifies clinical effectiveness.","kw":"Sleep disturbance central sensitization chronic pain exercise therapy inflammation musculoskeletal rehabilitation"},{"pmid":"42924695","title":"Applications of Nanotechnology in Athletic and Exercise Performance: A Scoping Review.","journal_abbr":"J Funct Morphol Kinesiol","authors":["De Vitis R","Lombardi L","Guzzini M","et al."],"date":"2026-10-13","year":2026,"doi":"10.3390/jfmk11040416","pmcid":"PMC13692529","license":"cc by","oa":true,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["performance"],"title_fr":"Applications de la nanotechnologie dans le sport et la performance d'exercice : examen de la portée","tr":1,"l1":"Nanotechnology demonstrates theoretical and emerging translational potential across several domains relevant to athletic and exercise performance; however, direct evidence of meaningful performance enhancement in trained or elite athletes…","kw":"athletic performance biosensing techniques carbon nanotubes exercise nanoparticles nanotechnology"},{"pmid":"42841071","title":"Extreme Diagnostic and Therapeutic Heterogeneity Limits Treatment Conclusions in Iliotibial Band Syndrome: A Systematic Review with Level-of-Evidence Stratification.","journal_abbr":"Orthop Res Rev","authors":["Ferrero A","Moro A","Minelli M","et al."],"date":"2026-10-02","year":2026,"doi":"10.2147/ORR.S629195","pmcid":"PMC13641109","license":"cc by-nc","pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["blessures"],"title_fr":"Diagnostic extrême et l'hétérogénéité thérapeutique limite les conclusions du traitement dans le syndrome de bande iliotibiale : revue systématique avec stratification du niveau d'évidence","tr":1,"l1":"Despite a broad therapeutic landscape, most treatment modalities cannot yet be recommended over one another. Structured rehabilitation remains the reasonable first-line approach for newly diagnosed ITBS. For refractory ITBS, emerging…","kw":"iliotibial band syndrome lateral knee pain level of evidence rehabilitation running injuries systematic review"},{"pmid":"42799782","title":"Photobiomodulation versus ischemic preconditioning for protection against exercise-induced muscle damage: protocol for a randomized controlled trial.","journal_abbr":"Lasers Med Sci","authors":["Lima E","Pereira R","Pereira Pinto CT","et al."],"date":"2026-09-26","year":2026,"doi":"10.1007/s10103-026-05048-3","pmcid":"PMC13615937","license":"cc by","oa":true,"pub_types":["Clinical Trial Protocol"],"curated":false,"type":"protocol","level":0,"ctx":["performance","récupération"],"title_fr":"Photobiomodulation versus préconditionnement ischémique pour la protection contre les lésions musculaires induites par l'exercice: protocole pour un essai randomisé","tr":1,"l1":"This study will provide, to our knowledge, the first direct comparison between PBM and IPC as preconditioning strategies to attenuate EIMD. The findings may help determine the most effective and clinically applicable intervention by…","kw":"Eccentric exercise Muscle function Muscle soreness Randomized trial Recovery Adolescent Adult Humans Male Young Adult Exercise"},{"pmid":"42788224","title":"Preliminary pre-post changes in neuromuscular performance after application of a wearable photobiomodulation device in young tennis athletes.","journal_abbr":"Eur J Transl Myol","authors":["Grossi A","Fabris A","Campoli F","et al."],"date":"2026-09-24","year":2026,"doi":"10.4081/ejtm.2026.16043","pmcid":"PMC13688310","license":"cc by-nc","oa":true,"curated":false,"type":"autre","level":0,"ctx":["performance"],"title_fr":"Changements pré-postaux préliminaires des performances neuromusculaires après application d'un dispositif de photobiomodulation portable chez les jeunes athlètes de tennis","tr":1,"l1":"These preliminary findings suggest a potential association between Taopatch® application and acute changes neuromuscular performance. However, the statistical evidence was sensitive to the multiple-comparison correction applied, and…","kw":"Photobiomodulation explosive performance tennis youth athletes"},{"pmid":"42776298","title":"Combined photobiomodulation and exosome therapy for muscle and tendon regeneration: an experimental rabbit study.","journal_abbr":"Lasers Med Sci","authors":["Sabah Majeed A","Mokhtari-Dizaji M","Hormozi Moghaddam Z","et al."],"date":"2026-09-23","year":2026,"doi":"10.1007/s10103-026-05040-x","pmcid":"PMC13601094","license":"cc by-nc-nd","oa":true,"curated":false,"type":"preclinical","level":5,"ctx":["blessures","populations"],"nm":[830],"pre":"both","title_fr":"Thérapie combinée de la photobiomodulation et de l'exosome pour la régénération des muscles et des tendons: étude expérimentale chez le lapin","tr":1,"l1":"Combining low-level laser therapy with exosomes derived from ADSCs enhanced the histological, ultrasound-derived, and mechanical aspects related to Achilles tendon repair. This included improvements in tendon and gastrocnemius strain, as…","kw":"Achilles tendon Exosome Gastrocnemius Low-level laser therapy Animals Rabbits Low-Level Light Therapy Achilles Tendon Male Muscle, Skeletal"},{"pmid":"42802818","title":"Effect of High-Intensity Laser Acupuncture on Muscle Performance, Pain, and Quality of Life in Patients with Chronic Nonspecific Low Back Pain: A Randomized Placebo-Controlled Trial [Letter].","journal_abbr":"J Multidiscip Healthc","authors":["Kumar R","Sharma S","Meel T"],"date":"2026-09-23","year":2026,"doi":"10.2147/JMDH.S657536","pmcid":"PMC13616154","license":"cc by-nc","oa":true,"pub_types":["Letter"],"curated":false,"type":"letter","level":0,"ctx":["performance","populations"],"title_fr":"Effet de l'acupuncture laser à haute intensité sur la performance musculaire, la douleur et la qualité de vie chez les patients présentant une douleur chronique non spécifique au bas du dos : essai randomisé par placebo [Lettre]","tr":1,"l1":"","kw":""},{"pmid":"42840704","title_fr":"PBM cérébrale dans la commotion sportive aiguë : essai pilote RECOVERY","type":"rct","level":2,"pop":"adulte","ctx":["blessures"],"aim":"traitement","mode":["laser","LED"],"nm":[],"n":null,"effect":"—","theme":"Blessures sportives","l1":"Chez des sportifs commotionnés, la PBM cérébrale à 5 ou 10 Hz est bien tolérée ; l'essai, sans sham, prépare un essai contrôlé.","l2":"Essai pilote randomisé en simple aveugle (France).","l3":{"points":["Faisabilité."],"limites":["Pas de sham."],"pratique":"Prépare un essai contrôlé."},"em":["pulse"],"pre":"","topic":"sport","title":"Brain photobiomodulation therapy for acute sport-related concussion: a randomized, single-blinded, pilot clinical trial (RECOVERY study).","journal":"Frontiers in neurology","journal_abbr":"Front Neurol","authors":["Chermann JF","Malafosse P","Champleboux G","et al."],"date":"2026-09-22","year":2026,"week":"2026-S39","doi":"10.3389/fneur.2026.1894623","pmcid":"PMC13640603","license":"cc by","oa":false,"pdf":"pdfs/42840704.pdf","cited_by":0,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"BACKGROUND","text":"The current standard of care for concussion relies on symptom management; there are almost no disease-modifying treatments. The RECOVERY study investigated the safety of RGn550 (REGEnLIFE), a novel neurostimulation device combining brain photobiomodulation with a static magnetic field, in sportspeople with acute concussion and described concussion-related parameters in patients receiving this therapy."},{"label":"METHODS","text":"This prospective, randomized (central randomization, 1:1 ratio), single-blind, monocentric, pilot study compared two pulse frequencies (5 Hz and 10 Hz). Adult sportspeople with a concussion from a shock during sport practice occurring less than 72 h before inclusion were treated for 20 min at day 0 (D0) and D7 and followed up to D52. The primary outcome was the incidence of adverse device effects (ADEs). The secondary outcomes evaluated oculomotor, balance and executive function, concussion symptoms, and blood markers. The sample size was determined by the probability of observing at least one ADE, while all secondary analyses were exploratory and unadjusted for multiplicity."},{"label":"RESULTS","text":"Fifty patients were included, randomized, and treated at least once with 5 Hz (n = 26) or 10 Hz (n = 24); 49 (98.0%) of them completed the study. No difference was detected between the groups for primary or secondary outcomes. At least one ADE occurred in 38.5% (n = 10) [CI95: 20.2; 59.4] in the 5 Hz group and 41.7% (n = 10) [CI95: 22.1; 63.4] in the 10 Hz group. All ADEs were mild, non-serious (e.g., somnolence and medical device site discomfort), and resolved. Changes in several secondary outcomes were observed over the follow-up period, including within-visit changes in oculomotor measures."},{"label":"CONCLUSION","text":"No difference in tolerability was detected between the 5 and 10 Hz modalities, although the study was neither designed nor powered to establish equivalence. Both conditions were well tolerated. In the absence of a sham comparator, secondary outcome data are hypothesis-generating and cannot be described in terms of efficacy. However, these data still provide the feasibility and variability estimates required to design an adequately powered, double-blind, sham-controlled trial in an indication that currently lacks disease-modifying treatment."},{"label":"CLINICAL TRIAL REGISTRATION","text":"https://clinicaltrials.gov/study/NCT05647304, NCT05647304."}],"keywords":["brain","clinical trial","concussion","mTBI","neuromodulation","neurotech","photobiomodulation","sport"]},{"pmid":"42757739","title":"Effects of Photobiomodulation Therapy on Muscle Strength and Muscle Endurance: A Systematic Review and Meta-Analysis.","journal_abbr":"J Integr Complement Med","authors":["Zhai H","Wang T","Yan H","et al."],"date":"2026-09-18","year":2026,"doi":"10.1177/27683605261488795","pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["performance"],"title_fr":"Effets de la photobiomodulation thérapeutique sur la force musculaire et l'endurance musculaire : une revue systématique et une méta-analyse","tr":1,"l1":"PBMT may modestly improve muscle endurance and muscle strength, particularly for endurance-related outcomes. However, subgroup findings remain exploratory, and current evidence is insufficient to define optimal protocols. Further…","kw":"athletes muscle endurance muscle strength photobiomodulation therapy systematic analysis"},{"pmid":"42827784","title":"Photobiomodulation for skeletal muscle regeneration: mechanisms, dosimetry, and translational challenges.","journal_abbr":"Front Bioeng Biotechnol","authors":["Ahmed R","Zhang KL","Hamzah R","et al."],"date":"2026-09-18","year":2026,"doi":"10.3389/fbioe.2026.1921612","pmcid":"PMC13630729","license":"cc by","oa":true,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"title_fr":"Photobiomodulation pour la régénération du muscle squelettique : mécanismes, dosimétrie et défis translationnels","tr":1,"l1":"Emerging approaches, such as Monte Carlo light transport modeling and patient-specific optical simulations, are discussed as promising strategies for personalized treatment planning. Collectively, these advances support the transition of…","kw":"Monte Carlo simulation artificial intelligence cytochrome c oxidase dosimetry light transport low-level laser therapy"},{"pmid":"42701790","title":"Effect of High-Intensity Laser Acupuncture on Muscle Performance, Pain, and Quality of Life in Patients with Chronic Nonspecific Low Back Pain: A Randomized Placebo-Controlled Trial.","journal_abbr":"J Multidiscip Healthc","authors":["Elimy DA","Youssef ASA","Ragab MMM","et al."],"date":"2026-09-01","year":2026,"doi":"10.2147/JMDH.S625298","pmcid":"PMC13546005","license":"cc by-nc","oa":true,"cited_by":1,"pub_types":["Case Reports","Clinical Trial"],"curated":false,"type":"nrct","level":3,"ctx":["performance","populations"],"title_fr":"Effet de l'acupuncture laser à haute intensité sur la performance musculaire, la douleur et la qualité de vie chez les patients présentant une douleur chronique non spécifique au bas dos : un essai randomisé par placebo","tr":1,"l1":"HILA therapy, combined with physical exercise therapy, may provide greater improvement in trunk muscular performance, pain, and QoL for patients with CNSLBP in the short term compared to physical exercise therapy alone. These findings…","kw":"laser acupuncture low back pain muscle performance quality of life"},{"pmid":"42631884","title":"Photobiomodulation therapy and postoperative recovery after abdominoplasty: a non-randomized pilot study.","journal_abbr":"Lasers Med Sci","authors":["Araujo CLK","Fardin GS","Bernardi AP","et al."],"date":"2026-08-22","year":2026,"doi":"10.1007/s10103-026-05007-y","pmcid":"PMC13499719","license":"cc by","oa":true,"curated":false,"type":"autre","level":0,"ctx":["récupération"],"nm":[808],"title_fr":"Photobiomodulation et récupération postopératoire après abdominoplastie : étude pilote non randomisée","tr":1,"l1":"Limitations include small sample size, single-session PBM, lack of sham control, and no correction for multiple comparisons. Further randomized studies with larger sample sizes and multiple applications are warranted to better elucidate…","kw":"Abdominoplasty Cytokines Low-level laser therapy (LLLT) Oxidative stress Photobiomodulation therapy Postoperative pain Humans Female Pilot Projects Low-Level Li"},{"pmid":"42579184","title":"Efficacy of 810 nm low-level laser therapy on muscle regeneration after bupivacaine-induced myonecrosis in a rabbit model.","journal_abbr":"Lasers Med Sci","authors":["Sadeldin MT","Hamadah O","Abdo A","et al."],"date":"2026-08-11","year":2026,"doi":"10.1007/s10103-026-04989-z","pmcid":"PMC13461747","license":"cc by-nc-nd","oa":true,"curated":false,"type":"preclinical","level":5,"ctx":["récupération","populations"],"nm":[810],"pre":"vivo","title_fr":"Efficacité d'une thérapie laser basse énergie de 810 nm sur la régénération musculaire après une myonécrose induite par la bupivacaine chez un modèle de lapin","tr":1,"l1":"The current findings suggest that LLLT at 810 nm may accelerate histological recovery and attenuate muscle damage markers following bupivacaine-induced myonecrosis in rabbits. Further large-scale studies incorporating molecular and…","kw":"Bupivacaine Low-level laser therapy Muscle regeneration Myonecrosis Photobiomodulation Rabbit model Animals Rabbits Bupivacaine Low-Level Light Therapy Muscle, "},{"pmid":"42526498","title":"The in vitro application of high-intensity laser therapy on equine platelet-rich plasma and autologous protein solution does not alter select cytokine and growth factor concentrations.","journal_abbr":"J Am Vet Med Assoc","authors":["Max LNF","Brown KA","Struble SE","et al."],"date":"2026-07-29","year":2026,"doi":"10.2460/javma.26.02.0080","license":"cc by-nc","curated":false,"type":"preclinical","level":5,"ctx":[],"nm":[1064],"em":["pulse"],"pre":"both","title_fr":"L'application in vitro d'un traitement laser à haute intensité sur une solution plasmatique riche en plaquettes d'équine et de protéines autologues ne modifie pas les concentrations de cytokine et de facteur de croissance","tr":1,"l1":"These findings suggested that HILT, as applied to equine PRP and APS in vitro, neither enhances nor decreases the release of select cytokines and growth factors.","kw":"autologous protein solution high-intensity laser therapy orthobiologic photobiomodulation platelet-rich plasma Animals Horses Platelet-Rich Plasma Cytokines Las"},{"pmid":"42647335","title":"Non-Surgical Treatments for Rotator Cuff Tendinopathy: A Narrative Review.","journal_abbr":"J Funct Morphol Kinesiol","authors":["Nikolova SP","Naydenov A"],"date":"2026-07-26","year":2026,"doi":"10.3390/jfmk11030294","pmcid":"PMC13511432","license":"cc by","oa":true,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["blessures"],"title_fr":"Traitements non chirurgicaux pour la tendinopathie des menottes rotatives : un examen narratif","tr":1,"l1":"Adjunctive interventions, including PRP, extracorporeal shockwave therapy, and high-power laser therapy, may provide additional benefits in appropriately selected patients. However, methodological heterogeneity and differences in…","kw":"conservative treatment exercise therapy extracorporeal shockwave therapy physiotherapy platelet-rich plasma rotator cuff tendinopathy"},{"pmid":"42493723","title_fr":"PBM et erreurs de repositionnement de la cheville dues à la fatigue : essai contre placebo","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser","LED"],"nm":[830],"n":null,"effect":"neutre","theme":"Performance musculaire","l1":"Appliquée avant l'effort, la PBM ne réduit pas la perte de proprioception de la cheville due à la fatigue ; l'instabilité perçue pourrait moduler la réponse.","l2":"Essai randomisé contre placebo.","l3":{"points":["Interaction exploratoire avec le score CAIT."],"limites":["Hypothèse à confirmer."],"pratique":"Pas d'effet démontré."},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Effect of photobiomodulation on fatigue-related errors in ankle joint position reproduction: the moderating role of perceived ankle instability in a randomized, placebo-controlled trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Ikuta Y","Yamakawa R","Toriyama M","et al."],"date":"2026-07-23","year":2026,"week":"2026-S30","doi":"10.1007/s10103-026-04966-6","pmcid":"PMC13395833","license":"cc by","oa":true,"pdf":"pdfs/42493723.pdf","cited_by":0,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"To investigate whether pre-exercise photobiomodulation (PBM) attenuates fatigue-induced decline in ankle joint position reproduction (JPR) and determine whether perceived ankle instability modifies this response. In this randomized, placebo-controlled trial with participant blinding and blinded outcome assessment, 30 healthy young adults (age: 24.3 ± 3.7 years; 15 male, 15 female) received either PBM or placebo treatment applied to the lower-leg musculature before a fatiguing protocol. PBM parameters included a wavelength of 830 nm, average power of 1 W, and total energy of 300 J per limb. Ankle JPR was assessed before and after fatigue. Participants were stratified by Cumberland Ankle Instability Tool (CAIT) scores. All physical assessments were performed by independent outcome assessors blinded to group allocation, with each participant evaluated by the same designated assessor throughout the study. The primary analysis revealed no overall between-group difference in fatigue-related changes in ankle JPR. A secondary exploratory group × CAIT interaction was observed, suggesting potential effect modification by perceived ankle instability. In the higher perceived instability subgroup, the estimated between-group difference was consistent with less post-fatigue worsening of JPR error following PBM; however, this estimate was based on small subgroup sizes and was not adjusted for multiple comparisons. The primary hypothesis was not supported; pre-exercise PBM showed no overall effect on fatigue-induced changes in ankle JPR. The exploratory group × CAIT interaction suggests that perceived ankle instability may be an effect modifier the response to PBM. However, this hypothesis requires confirmation in a larger, preregistered trial prospectively powered for interaction testing and incorporating functional outcomes in populations with clinically diagnosed chronic ankle instability."}],"keywords":["Cumberland Ankle Instability Tool","Joint position reproduction","Low-level laser therapy","Muscle fatigue","Photobiomodulation","Proprioception"]},{"pmid":"42473844","title_fr":"PBM en complément du renforcement musculaire chez le sujet âgé : méta-analyse","type":"ma","level":1,"pop":"adulte","ctx":["populations"],"aim":"traitement","mode":["laser","LED"],"nm":[],"n":null,"effect":"neutre","theme":"Sujets âgés & malades chroniques","l1":"Chez le sujet âgé, la PBM n'apporte pas de bénéfice clair sur la force maximale ; elle pourrait aider la récupération chez les plus fragiles.","l2":"Revue systématique avec méta-analyse d'essais randomisés.","l3":{"points":["Intérêt possible chez les sujets fragiles ou en réanimation."],"limites":["Résultats incohérents."],"pratique":"Pas d'intérêt en routine pour la force."},"em":[],"pre":"","topic":"sport","title":"Photobiomodulation as an Adjunct to Resistance Training in Older Adults: A Systematic Review and Meta-Analysis.","journal":"Photobiomodulation, photomedicine, and laser surgery","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Chen H","Eungpinichpong W","Asawaphureekorn S","et al."],"date":"2026-07-20","year":2026,"week":"2026-S30","doi":"10.1177/25785478261469320","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Systematic Review","Meta-Analysis"],"curated":true,"depth":1,"abstract":[{"label":"BACKGROUND","text":"Photobiomodulation (PBM) has been proposed as an adjunct to resistance training to enhance strength adaptations; however, findings from randomized controlled trials (RCTs) remain inconsistent. This study aimed to evaluate whether adjunctive PBM improves maximal strength gains when combined with periodized resistance training in older adults."},{"label":"METHODS","text":"RCTs were identified through systematic searches of PubMed, Scopus, Embase, PEDro, Web of Science, the Cochrane Library, and CNKI from inception to January 2026. Eligible studies examined PBM delivered via low-level laser therapy or light-emitting diodes in combination with resistance training or other strength-oriented loading tasks. Prespecified meta-analyses were restricted to trials combining PBM with periodized resistance training that reported one-repetition maximum (1RM) outcomes; other studies were included in a narrative synthesis."},{"label":"RESULTS","text":"Eleven RCTs (n = 456) were included. Five trials (PBM plus resistance training: n = 74; control: n = 72) met the criteria for meta-analysis. PBM combined with resistance training did not significantly improve maximal muscle strength compared with sham PBM (SMD = 0.26, 95% CI -0.08 to 0.59; p = 0.14; I2 = 4%). Subgroup analyses showed a nonsignificant trend favoring PBM for unilateral 1RM, with no effect for bilateral outcomes and no significant subgroup differences. Sensitivity analyses indicated that the unilateral effect was dependent on individual studies. In nonresistance training contexts, some studies reported potential benefits for fatigue-, recovery-, or function-related outcomes, particularly in frail or critically ill older adults, although findings were inconsistent."},{"label":"CONCLUSION","text":"Current evidence does not demonstrate a clear additional benefit of PBM on maximal strength when combined with resistance training in older adults, although a small effect cannot be excluded. PBM may have selective value in improving recovery-related outcomes and supporting training tolerance in vulnerable populations. Larger, well-designed RCTs are needed to clarify its role."}],"keywords":["meta-analysis","muscle strength","older adults","photobiomodulation","resistance training","systematic review"]},{"pmid":"42528905","title":"High-intensity versus low-intensity laser acupuncture in chronic, non-specific low back pain: a double-blinded, randomized controlled trial.","journal_abbr":"Front Med (Lausanne)","authors":["Elimy DA","Allah NHN","Abdelwahed NAG","et al."],"date":"2026-07-15","year":2026,"doi":"10.3389/fmed.2026.1857622","pmcid":"PMC13416075","license":"cc by","oa":true,"cited_by":1,"pub_types":["Clinical Trial"],"curated":false,"type":"nrct","level":3,"ctx":["performance","récupération"],"l1":"Patients with CNSLBP may have a short-term benefit from HILA and LILA combined with exercise rather than from exercise alone in terms of trunk extensor strength and fatigue, pain, lumbar flexion ROM, and disability. However, both laser…","kw":"exercise therapy laser acupuncture low back pain muscle fatigue muscle strength"},{"pmid":"42429841","title":"Re: Effects of resistance training with/without photobiomodulation on muscle and respiratory function in difficult-to-control asthma: a randomized trial.","journal_abbr":"Lasers Med Sci","authors":["Li D","Ye Q"],"date":"2026-07-10","year":2026,"doi":"10.1007/s10103-026-04954-w","pmcid":"PMC13354608","license":"cc by-nc-nd","oa":true,"pub_types":["Letter"],"curated":false,"type":"letter","level":0,"ctx":["performance"],"l1":"The intervention did not improve lung function or asthma control, acting only peripherally. RT+PBMT is a useful adjuvant therapy; future studies should optimize PBMT dosing, test standalone PBMT, and examine long-term outcomes, and…","kw":"Humans Asthma Low-Level Light Therapy Muscle Strength Resistance Training Randomized Controlled Trials as Topic"},{"pmid":"42465967","title":"Associations of wearable photobiomodulation device use with mitochondrial bioenergetics and fatigue in athletes and individuals with chronic fatigue.","journal_abbr":"Front Sports Act Living","authors":["Valeyeva-Frost Z","Eckel G"],"date":"2026-07-02","year":2026,"doi":"10.3389/fspor.2026.1823212","pmcid":"PMC13374030","license":"cc by","oa":true,"curated":false,"type":"autre","level":0,"ctx":["récupération"],"l1":"Thirty days of wearable photobiomodulation use was associated with directional changes in selected bioenergetic parameters alongside reductions in perceived fatigue. These findings support further controlled studies to evaluate…","kw":"ATP production athletes cellular bioenergetics chronic fatigue glycolysis mitochondrial function"},{"pmid":"42271035","title_fr":"PBM et manipulation ostéopathique après dommages musculaires induits par l'exercice : essai contre placebo","type":"rct","level":2,"pop":"adulte","ctx":["récupération"],"aim":"prévention","mode":["laser","LED"],"nm":[650],"n":null,"effect":"mitigé","theme":"Récupération & courbatures","l1":"Chez de jeunes adultes, l'association PBM et manipulation ostéopathique améliore la cinétique de la CK et certains paramètres fonctionnels ; l'effet sur la force reste une tendance non significative.","l2":"Essai randomisé contre placebo.","l3":{"points":["Tendance sur le saut horizontal."],"limites":["Résultats exploratoires."],"pratique":"Exploratoire."},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Combined effects of photobiomodulation and osteopathic manipulation on the physical performance of young adults subjected to exercise-induced muscle damage: a randomized placebo-controlled trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Freitas JC","Bocchi M","Rodrigues Junior BA","et al."],"date":"2026-06-10","year":2026,"week":"2026-S24","doi":"10.1007/s10103-026-04907-3","pmcid":"PMC13253767","license":"cc by","oa":true,"pdf":"pdfs/42271035.pdf","cited_by":0,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"The aim of this study was to investigate the combined effects of photobiomodulation (PBM) and osteopathic manipulation (OM) on the physical performance of young adults subjected to exercise-induced muscle damage (EIMD). The study is a randomized, placebo-controlled clinical trial. Forty-five physically active male individuals were included and randomized into four groups: placebo (PL), PBM, OM, and PBM + OM. A red-light emitting diode (LED) (λ = 650 nm) was used. Participants in the PBM and PBM + OM groups received 144 J of energy in the right lower limb and/or underwent bilateral lumbar and pelvic manipulation (OM and PBM + OM) before the EIMD protocol. The following variables were analyzed before, immediately after, and 24, 48, and 72 h post-intervention: creatine kinase (CK), muscle strength, flexibility, and horizontal jump performance. Data normality was assessed using the Kolmogorov-Smirnov test. CK levels were evaluated using the Friedman test, and repeated measures ANOVA was used for the other variables, p < 0.05. A distinct recovery pattern was observed in the combined PBM + OM group, with increased CK levels only at 24 h, followed by a pronounced reduction at 72 h (p = 0.001). Only the PBM + OM group presented percentage values near to baseline within 48 h (-1.4%), in addition to a trend toward early improvement in the horizontal jump within 24 h. In conclusion, PBM + OM may have contributed to improved CK kinetics and selected functional outcomes; however, strength recovery should be interpreted strictly as a non-significant and exploratory trend."}],"keywords":["High-velocity low-amplitude thrust","Muscle injury","Physical functional performance","Post-exercise recovery"]},{"pmid":"42172262","title_fr":"PBM avec champ magnétique ou autres stratégies de récupération chez les athlètes de CrossFit : essai croisé","type":"rct","level":2,"pop":"adulte","ctx":["récupération"],"aim":"prévention","mode":["laser","LED"],"nm":[],"n":12,"effect":"favorable","theme":"Récupération & courbatures","l1":"Chez des athlètes de CrossFit, la PBM avec champ magnétique statique améliore la récupération et réduit le stress oxydatif mieux que le repos passif.","l2":"Essai randomisé croisé à 4 interventions, 12 athlètes.","l3":{"points":["Effet sur les marqueurs oxydatifs."],"limites":["Très petit effectif."],"pratique":"Option de récupération sportive."},"em":[],"pre":"","topic":"sport","title":"A randomised crossover trial comparing photobiomodulation therapy with other recovery strategies in CrossFit athletes.","journal":"PloS one","journal_abbr":"PLoS One","authors":["Martins PHGN","Tomazoni SS","Machado CDSM","et al."],"date":"2026-05-22","year":2026,"week":"2026-S21","doi":"10.1371/journal.pone.0349880","pmcid":"PMC13196929","license":"cc by","oa":true,"pdf":"pdfs/42172262.pdf","cited_by":0,"pub_types":["Randomized Controlled Trial","Comparative Study"],"curated":true,"depth":1,"abstract":[{"label":"BACKGROUND","text":"This study compared the effects of different therapeutic modalities on recovery following the workout of the day (WOD) in CrossFit athletes, focusing on reducing muscle damage and improving functional performance."},{"label":"METHODS","text":"In a randomised, controlled, crossover design, twelve CrossFit athletes underwent four post-WOD recovery interventions across four weeks: passive recovery (PR), intermittent pneumatic compression (IPC), extracorporeal shock wave therapy (ESWT), and photobiomodulation therapy combined with a static magnetic field (PBMT-sMF). Assessments were conducted at baseline, and at 1, 24, and 48 hours post-WOD. The primary outcome was vertical jump performance (countermovement jump [CMJ] height) at 1-hour post-WOD; secondary outcomes included lactate dehydrogenase (LDH) levels, superoxide dismutase (SOD) and catalase (CAT) activity, thiobarbituric acid reactive substances (TBARS), carbonylated proteins, perceived exertion, and intervention satisfaction."},{"label":"RESULTS","text":"There was no significant difference between interventions in CMJ height at 1-hour post-WOD. In contrast, PBMT-sMF outperformed the other interventions in the secondary outcomes. PBMT-sMF significantly improved CMJ height at 24 and 48 hours compared with PR (p < 0.05) and led to greater reductions in LDH at both time points (p < 0.05 and p < 0.001, respectively). PBMT-sMF also produced lower TBARS and carbonylated protein levels, with higher CAT and SOD activities at 24 and 48 hours (p < 0.05 and p < 0.0001, respectively). CAT and SOD activities were also significantly elevated at 1 hour post-WOD compared with PR (p < 0.05)."},{"label":"CONCLUSIONS","text":"PBMT-sMF may be an effective recovery strategy for CrossFit athletes, with its benefits possibly related to the modulation of oxidative stress as an underlying mechanism."},{"label":"TRIAL REGISTRATION","text":"Trial registration number: NCT06628609."}],"keywords":[]},{"pmid":"42174255","title_fr":"Effet aigu de la PBM sur la force du quadriceps dans l'insuffisance rénale chronique : essai croisé","type":"rct","level":2,"pop":"adulte","ctx":["populations"],"aim":"traitement","mode":["laser","LED"],"nm":[830],"n":null,"effect":"neutre","theme":"Sujets âgés & malades chroniques","l1":"Chez des patients hémodialysés, une séance unique de PBM (30, 60 ou 90 J) ne modifie ni la force du quadriceps ni la fatigue ni la douleur.","l2":"Essai croisé randomisé en double aveugle contre placebo.","l3":{"points":["Trois doses testées."],"limites":["Séance unique."],"pratique":"Aucun effet ergogène aigu dans cette population."},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Acute effect of photobiomodulation therapy in quadriceps strength, fatigue and pain of patients with chronic kidney failure: a randomized, double-blind, placebo controlled crossover clinical trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Barbosa APO","Santos LM","Catelli AM","et al."],"date":"2026-05-22","year":2026,"week":"2026-S21","doi":"10.1007/s10103-026-04886-5","pmcid":"PMC13197340","license":"cc by","oa":true,"pdf":"pdfs/42174255.pdf","cited_by":0,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Patients with chronic kidney failure (CKF) present changes in physical capacity and low exercise tolerance. Photobiomodulation therapy (PBMT) has shown an ergogenic effect on exercise in studies with different populations and may be an adjuvant treatment in rehabilitation programs for CKF patients. This study aimed to evaluate the acute effects of different doses of PBMT on quadriceps strength, fatigue and muscle pain in CKF patients. This study is a randomized, placebo-controlled, double-blind, crossover clinical trial. Adult patients with CKF received four PBMT applications with different energy doses (30J, 60J, 90J, or placebo), administered in a random order. A one-week interval was maintained between each dose, and an 830nm laser was applied to six points of the quadriceps muscle. Immediately after PBMT, maximal isometric quadriceps muscle strength was assessed by dynamometry. Before the intervention and after the assessment of muscle strength, muscle fatigue (Borg rating of perceived exertion scale and blood lactate) and pain perception in the lower limbs (visual analogue scale) were measured. Fifteen patients were randomized and fourteen completed the study. There was no significant difference between the doses tested for maximal isometric muscle strength in the right (p=0.053) and left (p=0.509) quadriceps. The perception of fatigue assessed by the modified Borg scale was not altered (p=0.703) nor were blood lactate levels, regardless of the PBMT dose and measurement time (t0: p=0.126; t3: p=0.667; t6: p=0.700). There was no change in pain perception after quadriceps irradiation for any of the PBMT doses tested (p=0.566). A single application of PBMT with a dose of 30J, 60J, or 90J did not alter maximal isometric quadriceps muscle strength, fatigue, or muscle pain perception in the lower limbs of CKF patients on HD."}],"keywords":["Kidney failure, chronic","Low-level light therapy","Phototherapy","Randomized controlled trial","Renal dialysis"]},{"pmid":"42059974","title_fr":"Renforcement musculaire avec ou sans PBM dans l'asthme difficile à contrôler : essai randomisé","type":"rct","level":2,"pop":"adulte","ctx":["populations"],"aim":"traitement","mode":["laser","LED"],"nm":[],"n":null,"effect":"favorable","theme":"Sujets âgés & malades chroniques","l1":"Dans l'asthme difficile à contrôler, ajouter la PBM au renforcement musculaire améliore la force et la capacité fonctionnelle, sans effet sur la fonction respiratoire.","l2":"Essai randomisé.","l3":{"points":["Rééducation des muscles périphériques."],"limites":["Petit effectif."],"pratique":"Adjuvant possible en réhabilitation respiratoire."},"em":[],"pre":"","topic":"sport","title":"Effects of resistance training with/without Photobiomodulation on muscle and respiratory function in difficult-to-control asthma: a randomized trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Costa IP","Nascimento ER","Cahalin LP","et al."],"date":"2026-04-30","year":2026,"week":"2026-S18","doi":"10.1007/s10103-026-04880-x","pmcid":"PMC13132882","license":"cc by","oa":true,"pdf":"pdfs/42059974.pdf","cited_by":2,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Difficult-to-Control Asthma (DTCA) is characterized by persistent symptoms, frequent exacerbations, and reduced functional capacity despite optimized pharmacological therapy. Patients with DTCA commonly exhibit peripheral muscle dysfunction, making strategies that may potentiate the effects of resistance training clinically relevant. Photobiomodulation therapy (PBMT) has been investigated as a modality capable of improving muscle performance and exercise tolerance. The aim of this study was to determine whether combining resistance training with LED-based PBMT (RT+LEDT) results in greater improvements in peripheral muscle strength and functional exercise capacity compared with resistance training alone in adults with DTCA. This randomized, triple-blind controlled trial included 30 adults with DTCA who met predefined inclusion and exclusion criteria. Participants were allocated equally to an experimental group (RT+LEDT; n = 15) or a control group (RT; n = 15). Both groups completed supervised resistance training twice weekly for 12 weeks. The experimental group received active PBMT before each session, while the control group received placebo PBMT. The primary outcome was peripheral muscle strength assessed by one-repetition maximum (1RM). Secondary outcomes included cardiopulmonary exercise test variables, shuttle walk test performance, spirometry, physical activity level, and asthma control. Post-intervention group comparisons were performed using independent t-tests. Compared with RT alone, RT+LEDT produced greater post-treatment gains in 1RM strength across major muscle groups, along with significant improvements in oxygen consumption at the anaerobic threshold and shuttle walk test distance. No between-group differences were observed in pulmonary function or asthma control. PBMT combined with resistance training yielded clinically meaningful improvements in muscle strength and functional capacity, suggesting its potential as an adjunctive strategy in rehabilitation programs for DTCA."}],"keywords":["Asthma","Muscle strength","Photobiomodulation","Resistance training","Respiratory function"]},{"pmid":"41841483","title":"Effects of photobiomodulation on inflammatory factors during skeletal muscle regeneration: A systematic review with meta-analysis of animal studies.","journal_abbr":"Photochem Photobiol","authors":["Yang JM","Liu F","Ai ZC","et al."],"date":"2026-03-17","year":2026,"doi":"10.1111/php.70092","curated":false,"type":"autre","level":0,"ctx":[],"l1":"The results show that PBM treatment reduces levels of tumor necrosis factor-α (TNF-α), interleukin (IL)-1β, and IL-6 during skeletal muscle regeneration, especially in the early stage of skeletal muscle injury (6 and 12 h), but its…","kw":"inflammatory factor photobiomodulation skeletal muscle regeneration"},{"pmid":"41913811","title":"Effects of transcranial photobiomodulation on performance and cardiovascular responses in trained cyclists.","journal_abbr":"Front Physiol","authors":["Arrighi T","Meloni A","Zaccaria G","et al."],"date":"2026-03-16","year":2026,"doi":"10.3389/fphys.2026.1766916","pmcid":"PMC13033375","license":"cc by","oa":true,"curated":false,"type":"autre","level":0,"ctx":["performance"],"l1":"Acute transcranial PBM did not influence cycling performance or perceptual and physiological responses in trained athletes. These findings suggest that the applied PBM parameters may have been insufficient to elicit measurable cortical or…","kw":"brain stimulation cycling performance photobiomodulation prefrontal cortex time trial"},{"pmid":"41817276","title":"Transcranial Photobiomodulation in Sports Medicine: Enhancing Athletic Performance and Injury Prevention.","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Iravani M","Moghaddam Salimi M","Jahan A","et al."],"date":"2026-03-12","year":2026,"doi":"10.1177/25785478261429308","pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["performance","blessures"],"l1":"tPBM may hold potential as a complementary tool to traditional approaches, but further rigorous trials are needed to establish standardized protocols and confirm its efficacy. Future trials should prioritize larger samples,…","kw":"athlete performance cognitive enhancement low-level laser therapy motor function photobiomodulation sports medicine Humans Low-Level Light Therapy Athletic Perf"},{"pmid":"41810483","title_fr":"PBM sur le nerf vague et variabilité cardiaque chez le sujet actif","type":"rct","level":2,"pop":"adulte","ctx":["récupération"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"neutre","theme":"Récupération & courbatures","l1":"Appliquée sur le nerf vague sous l'oreille, la PBM ne modifie que très peu la variabilité de la fréquence cardiaque.","l2":"Essai randomisé contrôlé.","l3":{"points":["Nouvelle cible."],"limites":["Une dose."],"pratique":"Effet minime."},"em":[],"pre":"","topic":"sport","title":"Effects of Acute Photobiomodulation on Heart Rate Variability in Physically Active Individuals: A Randomized and Controlled Clinical Trial.","journal":"Journal of biophotonics","journal_abbr":"J Biophotonics","authors":["Pereira RA","Catai AM","Milan-Mattos JC","et al."],"date":"2026-03-11","year":2026,"week":"2026-S11","doi":"10.1002/jbio.70242","pmcid":"PMC12976981","license":"cc by","oa":true,"pdf":"pdfs/41810483.pdf","cited_by":1,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Photobiomodulation (PBM) therapy is widely investigated for tissue recovery, performance enhancement, and post-exercise optimization. This study assessed whether PBM applied to the vagus nerve in the infra-auricular region, combined with resistance exercise, modulates cardiac autonomic function in healthy, physically active adults. In this acute randomized controlled trial, 34 volunteers were enrolled: 17 underwent PBM or sham PBM in a crossover design, while a control group (n = 17) received PBM without exercise. PBM was delivered with a total energy dose of 12 J. Heart rate variability (HRV) was analyzed in time, frequency, and non-linear domains. Results showed a slight reduction (p = 0.011) in approximate entropy (ApEn) in the PBM group compared with controls, but no significant differences were observed in other HRV indices. These findings suggest that PBM applied to the vagus nerve induces minimal acute modulation of autonomic complexity. Further studies with different dosimetries and exercise protocols are warranted."}],"keywords":["cardiac autonomic modulation","heart rate variability","photobiomodulation","strength training","vagal neuromodulation"]},{"pmid":"42300020","title_fr":"PBM transcrânienne et résilience neurologique chez des joueurs de football américain","type":"rct","level":2,"pop":"adulte","ctx":["blessures"],"aim":"prévention","mode":["laser","LED"],"nm":[810],"n":null,"effect":"favorable","theme":"Blessures sportives","l1":"Chez des joueurs exposés à des chocs répétés à la tête, la PBM transcrânienne favorise la résilience neurologique (imagerie, biomarqueurs).","l2":"Essai randomisé (J Neurotrauma).","l3":{"points":["Prévention chez le sportif de contact."],"limites":["Une saison."],"pratique":"Piste préventive."},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Transcranial Photobiomodulation Promotes Neurological Resilience in Current Collegiate American Football Players Exposed to Repetitive Head Acceleration Events.","journal":"Journal of neurotrauma","journal_abbr":"J Neurotrauma","authors":["Lindsey HM","Esopenko C","Jain D","et al."],"date":"2026-01-20","year":2026,"week":"2026-S04","doi":"10.1177/08977151251403554","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Repetitive head acceleration events (RHAE) are common in contact sports and associated with neuroinflammation, axonal injury, and long-term neurological impairments, including increased risk for chronic traumatic encephalopathy. Current strategies for addressing RHAE focus on post-injury care rather than proactive neuroprotection, leaving athletes vulnerable to cumulative neurotrauma. Transcranial photobiomodulation (PBM) has shown promise in reducing neuroinflammation and promoting neuroprotection in traumatic brain injury; however, its potential to mitigate the structural brain changes associated with RHAE in actively competing athletes has not been investigated. The aim of this study was to investigate whether PBM mitigates RHAE-related neuroinflammatory and microstructural changes in collegiate American football players over a single National Collegiate Athletic Association Division I season. We hypothesized that restricted diffusion imaging (RDI) and quantitative anisotropy (QA), diffusion magnetic resonance imaging markers of neuroinflammation and axonal remodeling, respectively, would increase in the Sham PBM group due to RHAE exposure but remain stable in the Active PBM group, indicating neurological resilience. Twenty-six collegiate football players were randomly assigned to Active (n = 13) or Sham (n = 13) PBM groups. PBM (810 nm) was self-administered 3 days a week under supervision in the athletic training room with a transcranial plus intranasal device throughout the preseason practice period and regular season (16 weeks). Diffusion MRI data were collected pre- and postseason, and correlational tractography was used to assess the effects of PBM on longitudinal changes in RDI and QA. Moderation analyses examined time × group interactions, with post hoc analyses exploring within- and between-group differences in RDI and QA cross-sectionally and longitudinally. Correlational tractography revealed significant main effects and interactions of time and group, with widespread increases in RDI and QA observed in the Sham PBM group over the season, consistent with neuroinflammation and axonal remodeling. In contrast, the Active PBM group showed relative stability in RDI and QA over time, with significant reductions observed in some areas. These findings suggest that PBM may mitigate ongoing neuroinflammation and facilitate the recovery processes. This study provides the first evidence suggesting that transcranial PBM reduces neuroinflammatory and axonal injury markers in American collegiate football players over a single season. PBM may serve as a noninvasive and accessible intervention for mitigating the cumulative neurological effects of RHAE exposure, offering a neuroprotective strategy for athletes participating in collision and contact sports. Future research should examine the long-term benefits of PBM across multiple seasons and its impact on functional outcomes to further establish the role of PBM in athlete brain health and wellness."}],"keywords":["connectometry","diffusion weighted imaging","neuroinflammation","photobiomodulation","repetitive head impacts","sport-related concussion"]},{"pmid":"41538589","title":"Photobiomodulation Combined with Moderate or High-Intensity Interval Training on Oxygen Consumption and Exercise Tolerance in Patients with Heart Failure.","journal_abbr":"Arq Bras Cardiol","authors":["Busin D","Franzoni LT","Turella D","et al."],"date":"2026-01-15","year":2026,"doi":"10.36660/abc.20250086","pmcid":"PMC12711225","license":"cc by","oa":true,"cited_by":1,"curated":false,"type":"autre","level":0,"ctx":["populations"],"l1":"AT, especially at high intensity, enhances exercise performance in patients with HF. The addition of PBMT did not confer significant additional benefits in this study. Further trials using optimized PBMT protocols are warranted.","kw":"Humans Heart Failure Oxygen Consumption Exercise Tolerance Middle Aged Female"},{"pmid":"41393334","title":"Effects of photobiomodulation therapy combined with static magnetic field on training adaptations and detraining responses: a randomised placebo-controlled trial.","journal_abbr":"BMJ Open Sport Exerc Med","authors":["de Paiva PRV","Tomazoni SS","Machado CDSM","et al."],"date":"2025-12-12","year":2025,"doi":"10.1136/bmjsem-2025-002799","pmcid":"PMC12699604","license":"cc by-nc","oa":true,"curated":false,"type":"autre","level":0,"ctx":["performance"],"l1":"PBMT-sMF significantly attenuated strength loss and structural muscle changes during the detraining period after a resistance training programme.","kw":"Adaptations of skeletal muscle to exercise and altered neuromuscular activity Assessing physical training modalities in enhancing sports performance Exercise Ph"},{"pmid":"41440787","title":"Potential Effect of Intravascular Laser Irradiation of Blood (ILIB) in Improving Physical Performance: A Narrative Review.","journal_abbr":"J Funct Morphol Kinesiol","authors":["Rotta-Ribas MCB","Zurutuza Y","Castoldi RC","et al."],"date":"2025-12-01","year":2025,"doi":"10.3390/jfmk10040466","pmcid":"PMC12734237","license":"cc by","oa":true,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["performance"],"l1":"In this context, ILIB may favor performance in aerobic exercises and contribute to practices involving anaerobic metabolism by facilitating phosphocreatine resynthesis and ATP restoration. Conclusions: Multiple findings seek to support…","kw":"exercise heart rate variability low-level laser therapy photobiomodulation sports performance"},{"pmid":"41302361","title":"Effectiveness of Exercise and Physiotherapy in Chemotherapy-Induced Peripheral Neuropathy: A Systematic Review.","journal_abbr":"Healthcare (Basel)","authors":["Tamayo Fajardo JA","León Parejo F"],"date":"2025-11-19","year":2025,"doi":"10.3390/healthcare13222973","pmcid":"PMC12652784","license":"cc by","oa":true,"pdf":"pdfs/41302361.pdf","cited_by":2,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"Conclusions: Exercise and physiotherapy are safe, feasible, and effective non-pharmacological strategies for managing CIPN. However, heterogeneity in intervention design highlights the need for high-quality RCTs to establish optimal…","kw":"cancer rehabilitation chemotherapy-induced peripheral neuropathy exercise exercise therapy physiotherapy quality of life"},{"pmid":"41114857","title":"Therapeutic synergy between swimming and photobiomodulation in a rat model of neuropathic pain.","journal_abbr":"Lasers Med Sci","authors":["Araujo LC","Silva DPFB","Rocha-Braga LC","et al."],"date":"2025-10-20","year":2025,"doi":"10.1007/s10103-025-04705-3","cited_by":2,"curated":false,"type":"preclinical","level":5,"ctx":["populations"],"nm":[904],"pre":"vivo","l1":"PBMT and swimming exercise independently alleviate neuropathic pain and mitigate muscle degeneration following sciatic nerve injury. When combined, these therapies produce additive or synergistic effects, supporting the implementation of…","kw":"CCI Muscle Neuropathic Pain Pain Photobiomodulation Swimming Animals Low-Level Light Therapy Male Swimming Rats, Wistar Neuralgia"},{"pmid":"41053985","title_fr":"Laser avant électrostimulation ischémique (BFR-NMES) : gains d'entraînement et remodelage des unités motrices","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser"],"nm":[850],"n":30,"effect":"favorable","theme":"Performance musculaire","l1":"Une préexposition au laser (850 nm) augmente la force gagnée après entraînement par électrostimulation sous restriction de flux sanguin et améliore l'efficience neuromusculaire.","l2":"Essai randomisé, 30 sujets, 3 semaines.","l3":{"points":["Analyse des unités motrices."],"limites":["Sujets sains ; petit effectif."],"pratique":"Recherche en physiologie de l'entraînement."},"em":[],"pre":"","topic":"sport","title":"Training Benefits and Motor Unit Remodeling after Ischemic Neuromuscular Electrical Stimulation with Low-Level Laser Preexposure.","journal":"Medicine and science in sports and exercise","journal_abbr":"Med Sci Sports Exerc","authors":["Chen YC","Wu CC","Lin YT","et al."],"date":"2025-10-06","year":2025,"week":"2025-S41","doi":"10.1249/MSS.0000000000003860","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":1,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"PURPOSE","text":"Neuromuscular electrical stimulation (NMES) combined with blood flow restriction (BFR) is a promising strategy to prevent muscle atrophy when resistance training is not feasible, though its efficacy may be limited by fatigue. This study examined whether low-level laser therapy (LLLT) can serve as an ergogenic aid during combined NMES-BFR training."},{"label":"METHODS","text":"Thirty adults were assigned to BFR or BFR + LLLT groups ( n = 15). Both groups underwent a 3-week wrist extension training on the nondominant limb using combined NMES and BFR. The BFR + LLLT group received 60 J of 850 nm laser therapy to the extensor carpi radialis longus (ECRL) before each session; the BFR group received sham treatment. Outcomes included maximal voluntary contraction (MVC) and 40% MVC submaximal force-tracking, with electromyography recorded from the ECRL and extensor carpi radialis brevis (ECRB) muscles."},{"label":"RESULTS","text":"The BFR + LLLT group exhibited a greater posttest/pretest MVC ratio (1.154 ± 0.127) than the control group (1.040 ± 0.058) ( P = 0.004). Although the post-/pretest ratio of force-tracking error did not differ between groups ( P > 0.05), training-related changes in motor unit discharge strategies in the ECRL and ECRB were more pronounced in the BFR + LLLT group. Following training, the BFR + LLLT group exhibited a steeper regression slope between the interspike interval and recruitment threshold in both muscles ( P < 0.001), a pattern that was less evident in the BFR group. In addition, the post-/pretest ratio of the common drive index (CDI) within and between the ECRL and ECRB muscles decreased in the BFR + LLLT group, in contrast to a significant training-related increase observed in the BFR group ( P < 0.001)."},{"label":"CONCLUSIONS","text":"Pre-exposure to LLLT enhances force output after BFR-NMES training and improves neuromuscular efficiency by increasing motor synergy flexibility, thereby preserving force scaling during submaximal contractions."}],"keywords":["BLOOD FLOW RESTRICTION","LOW-LEVEL LASER THERAPY","MOTOR UNITS","NEUROMUSCULAR ELECTRICAL STIMULATION","SYNERGY"]},{"pmid":"41070206","title":"Exercise, radial pressure waves, and photobiomodulation for management of non-insertional Achilles tendinopathy in runners: a three-arm non-blinded randomised control trial.","journal_abbr":"BMJ Open Sport Exerc Med","authors":["Tenforde AS","Pham L","Gaudette LW","et al."],"date":"2025-10-05","year":2025,"doi":"10.1136/bmjsem-2024-002442","pmcid":"PMC12506102","license":"cc by-nc","oa":true,"curated":false,"type":"autre","level":0,"ctx":["blessures"],"l1":"Larger studies in other physically active populations may clarify clinical benefits of each treatment. NCT04725513.","kw":"Achilles Shockwave Sport Tendon"},{"pmid":"40995827","title_fr":"PBM et performance musculaire chez les volleyeurs et les footballeurs : méta-analyse","type":"ma","level":1,"pop":"adulte","ctx":["récupération"],"aim":"prévention","mode":["laser","LED"],"nm":[],"n":null,"effect":"favorable","theme":"Récupération & courbatures","l1":"Chez les sportifs de ballon, la PBM améliore la performance et réduit la CK : plus de répétitions au volley, CK plus basse au football.","l2":"Méta-analyse d'essais randomisés.","l3":{"points":["Effet différent selon le sport."],"limites":["Peu d'essais ; protocoles variés."],"pratique":"Intérêt en préparation sportive."},"em":[],"pre":"","topic":"sport","title":"The Effect of Photobiomodulation Therapy on Muscle Performance in Volleyball and Football Players: A Meta-Analysis of Randomized Controlled Trials.","journal":"Sports health","journal_abbr":"Sports Health","authors":["Qiu D","He J","Li B","et al."],"date":"2025-09-25","year":2025,"week":"2025-S39","doi":"10.1177/19417381251372977","pmcid":"PMC12463863","license":null,"oa":false,"pdf":null,"cited_by":1,"pub_types":["Meta-Analysis","Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"CONTEXT","text":"The use of photobiomodulation therapy (PBMT) as an adjunct to improve muscle performance and accelerate recovery in high-level volleyball and football players remains controversial."},{"label":"OBJECTIVE","text":"To determine whether PBMT improves skeletal muscle performance in ball sports athletes, and whether there are differences in the improvement of skeletal muscle performance by PBMT between volleyballers and footballers."},{"label":"DATA SOURCES","text":"A comprehensive search of the Web of Science, Medline, Scopus, and PubMed databases was conducted through April 10, 2025."},{"label":"STUDY SELECTION","text":"Eligible studies included those explicitly categorized as randomized controlled trials (RCT) of PBMT interventions for high-level volleyballers and/or footballers; 14 studies met the inclusion criteria."},{"label":"STUDY DESIGN","text":"Meta-analysis."},{"label":"LEVEL OF EVIDENCE","text":"Level 2."},{"label":"DATA EXTRACTION","text":"The primary outcome measures included maximal voluntary contraction force (MVC), number of repetitions, and creatine kinase (CK) levels. Means and standard deviations for each variable of interest were used to calculate standardized mean differences (SMDs)."},{"label":"RESULTS","text":"The active laser had no significant effect on MVC (mean difference [MD], 19.67; 95% CI, 7.36 to 31.72; P = 0.31)]; however, it significantly increased the number of repetitions (SMD, 0.58; 95% CI, -0.05 to 1.21; P = 0.04) and significantly decreased CK levels (MD, -45.37; 95% CI, -55.52 to -35.22; P < 0.001)."},{"label":"CONCLUSION","text":"PBMT can delay muscle fatigue onset and reduce CK levels in ball sports athletes. The improvement in skeletal muscle performance induced by PBMT showed differences between volleyballers and footballers, as there was a significant increase the number of repetitions in volleyball players, whereas a significant decrease in CK levels was noted in footballers."}],"keywords":["PBMT","meta-analysis","muscle performance","volleyball and football players"]},{"pmid":"40985334","title":"Photobiomodulation Strengthens Muscles via Its Dual Functions in Gut Microbiota.","journal_abbr":"Adv Sci (Weinh)","authors":["Upadhyay P","Banstola A","Bhayana B","et al."],"date":"2025-09-23","year":2025,"doi":"10.1002/advs.202511582","pmcid":"PMC12697884","license":"cc by","oa":true,"cited_by":2,"curated":false,"type":"preclinical","level":5,"ctx":["performance"],"nm":[980],"pre":"vitro","l1":"In a lactic-acidosis model, abdominal PBMT reduces peak weight loss (≈5% vs ≈10%) and accelerates recovery. These findings establish abdominal PBMT as a non-invasive modality that reverses epithelial injury and dysbiosis, revealing…","kw":"anaerobic bacteria intense exercise microbiota mitochondria biogenesis photobiomodulation Gastrointestinal Microbiome Animals Low-Level Light Therapy Muscle, Sk"},{"pmid":"40931641","title":"Photobiomodulation and platelet-rich fibrin in the gastrocnemius muscle submitted to calcaneal tendinopathy in rats.","journal_abbr":"Photochem Photobiol","authors":["Pauletto PA","Schmitt CHE","da Silva FFA","et al."],"date":"2025-09-10","year":2025,"doi":"10.1111/php.70034","pmcid":"PMC13383025","license":"cc by","oa":true,"cited_by":1,"curated":false,"type":"preclinical","level":5,"ctx":["blessures"],"pre":"vivo","l1":"In contrast, the neuromuscular junctions in the groups treated with PRF were smaller, suggesting possible structural alterations. The combination of therapies showed superior results to treatment alone, promoting greater tissue repair in…","kw":"gastrocnemius muscle low‐intensity light therapy muscle atrophy platelet‐rich fibrin tendinopathy therapeutic Animals Tendinopathy Rats Low-Level Light Therapy "},{"pmid":"41036342","title":"Treatment of lower back pain to resolve symptoms of canine urethral sphincter mechanism incontinence.","journal_abbr":"Open Vet J","authors":["Bailey MM","Lane DM"],"date":"2025-07-31","year":2025,"doi":"10.5455/OVJ.2025.v15.i7.49","pmcid":"PMC12483440","license":"cc by-nc","oa":true,"pub_types":["Case Reports"],"curated":false,"type":"cases","level":4,"ctx":["populations"],"l1":"Although a relationship between canine USMI and LBP has already been drawn, this is the first published report of a patient who received a comprehensive workup to diagnose USMI, failed to respond to months of pharmaceutical therapy, but…","kw":"Incontinence Lower back pain Photobiomodulation Urethral sphincter mechanism incontinence Dogs Animals Female Dog Diseases Low Back Pain Urinary Incontinence"},{"pmid":"40712647","title":"Management protocol for early postoperative avian wing fractures.","journal_abbr":"J Am Vet Med Assoc","authors":["Hopf-Dennis C","Jennings C"],"date":"2025-07-25","year":2025,"doi":"10.2460/javma.25.04.0277","license":"cc by-nc","curated":false,"type":"preclinical","level":5,"ctx":[],"pre":"vivo","l1":"The early postoperative period is a critical time to establish appropriate tissue healing free of complications such as reduced joint range of motion, development of tissue adhesions, or loss of muscle length or elasticity. In this video,…","kw":"avian orthopedic surgery passive range of motion (PROM) photobiomodulation wing fractures Animals Wings, Animal Fractures, Bone Birds"},{"pmid":"40717873","title":"Comprehensive Review and Evidence-Based Treatment Framework for Optimizing Plantar Fasciitis Diagnosis and Management.","journal_abbr":"Cureus","authors":["Nweke TC"],"date":"2025-07-25","year":2025,"doi":"10.7759/cureus.88745","pmcid":"PMC12294660","license":"cc by","oa":true,"cited_by":2,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"Surgical options like endoscopic plantar fascia release are reserved for recalcitrant cases. Recommendations prioritize low-risk, high-efficacy interventions, progressing to invasive treatments only when necessary, ensuring tailored…","kw":"clinical practice guidelines (cpg) evidence based treatment heel pain initial therapies intermediate therapies plantar fascia"},{"pmid":"40954632","title_fr":"PBM, compression pneumatique et électrostimulation pour la récupération musculaire : méta-analyse","type":"ma","level":3,"pop":"adulte","ctx":["récupération"],"aim":"prévention","mode":["laser","LED"],"nm":[],"n":null,"effect":"favorable","theme":"Récupération & courbatures","l1":"Appliquée avant l'effort, la PBM réduit les courbatures et améliore la performance à 24 h ; la NMES et la compression appliquées après l'effort n'ont pas d'effet.","l2":"Revue systématique avec méta-analyse d'essais randomisés chez des sujets sains.","l3":{"points":["Effet préconditionnement (PBM avant l'exercice)."],"limites":["Peu d'essais par comparaison ; sujets sains uniquement."],"pratique":"Si on l'utilise, la PBM s'applique avant l'effort, pas après."},"em":[],"pre":"","topic":"sport","title":"Effects of photobiomodulation, intermittent pneumatic compression and neuromuscular electrical stimulation on muscle recovery: Systematic review with meta-analysis.","journal":"Journal of bodywork and movement therapies","journal_abbr":"J Bodyw Mov Ther","authors":["Canez MS","da Silva LI","Ferreira GD","et al."],"date":"2025-06-27","year":2025,"week":"2025-S26","doi":"10.1016/j.jbmt.2025.06.021","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Systematic Review","Meta-Analysis"],"curated":true,"depth":1,"abstract":[{"label":"BACKGROUND","text":"Muscle damage represents a performance-limiting factor for athletes, thus necessitating a thorough understanding of the most efficacious recovery modalities."},{"label":"OBJECTIVE","text":"This study aims to investigate the effects of photobiomodulation (PBMT), neuromuscular electrical stimulation (NMES), and intermittent pneumatic compression (IPC) on muscle recovery."},{"label":"DESIGN","text":"Systematic review with meta-analysis."},{"label":"METHODS","text":"We searched four databases in July 2023. Randomized clinical trials, with healthy asymptomatic participants aged ≥18 years, who received PBMT, NMES or IPC, measuring muscle recovery outcomes were included. Two independent authors selected the studies, assessed the risk of bias, and reviewed the certainty of the evidence (GRADE)."},{"label":"RESULTS","text":"We included 19 studies (n = 672 participants). There is low-certainty evidence that PBMT applied before exercise significantly reduces muscle soreness (MD: -12.27 points, 95 % CI -18.14 to -6.40; I2 = 48 %). There is low-certainty evidence that NMES (MD: -4.60 points, 95 % CI -20.03 to 10.83; I2 = NA) does not reduce muscle soreness immediately post-intervention. There is moderate-certainty evidence that IPC does not reduce muscle soreness at 24h post-intervention (MD: -2.20 points, 95 % CI -10.08 to 5.68; I2 = NA)."},{"label":"CONCLUSION","text":"PBMT applied prior to exercise reduces muscle soreness and increases muscle performance at 24h post-exercise induced damage. Furthermore, NMES and IPC applied after exercise does not reduce muscle soreness compared to control."}],"keywords":["Athletes","Intermittent compression","Muscle soreness","Neuromuscular electrical stimulation","Photobiomodulation","Recovery"]},{"pmid":"40538474","title":"Differences in the Effectiveness of Different Physical Therapy Modalities in the Treatment of Delayed-Onset Muscle Soreness: A Systematic Review and Bayesian Network Meta-Analysis.","journal_abbr":"J Pain Res","authors":["Chen J","Hu Q","Hu J","et al."],"date":"2025-06-15","year":2025,"doi":"10.2147/JPR.S519242","pmcid":"PMC12178262","license":"cc by-nc","oa":true,"cited_by":1,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["récupération"],"l1":"The findings from this investigation indicate that PBMT and sauna treatment produce significant effects within the first 48 hours; however, beyond this period, the impact of photobiomodulation diminishes significantly. Overall, physical…","kw":"bayesian network meta-analysis delayed-onset muscle soreness efficacy physical therapy modalities systematic review"},{"pmid":"40851926","title":"Impact of Photobiomodulation Therapy Dosing Strategies on Strength, Clinical Outcomes, and Metabolic Responses: A Blinded Randomized Clinical Trial.","journal_abbr":"J Lasers Med Sci","authors":["Girasol CE","Caseiro Filho LC","Ferraz Moraes JMA","et al."],"date":"2025-05-31","year":2025,"doi":"10.34172/jlms.2025.14","pmcid":"PMC12368566","cited_by":1,"curated":false,"type":"autre","level":0,"ctx":["performance"],"l1":"Similar patterns were found for psychophysiological responses and training loads across the groups. Conclusion: In the context of this research model, PBMT combined with strength training did not yield superior outcomes in muscle…","kw":"Exercise training Low-level light therapy Muscle strength Physical therapy Work load"},{"pmid":"40371595","title":"Effectiveness of Photobiomodulation and Exercise-Based Rehabilitation on Pain and Functional Recovery in Patients With Rotator Cuff Pathology.","journal_abbr":"Wound Repair Regen","authors":["Maiya GA","Harihar A","Joseph GM","et al."],"date":"2025-05-15","year":2025,"doi":"10.1111/wrr.70043","pmcid":"PMC12079619","license":"cc by","oa":true,"cited_by":1,"curated":false,"type":"autre","level":0,"ctx":["récupération","blessures","populations"],"l1":"Our study showed a statistically significant reduction in pain scores from baseline (7.33 ± 0.79) to 6 weeks (2.50 ± 0.69), p < 0.001 of PBM and exercise-based rehabilitation. The knowledge about the evidence regarding the effectiveness…","kw":"exercise rehabilitation laser photobiomodulation rotator cuff pathology Humans Low-Level Light Therapy Male Female Middle Aged Exercise Therapy"},{"pmid":"40299985","title":"The role of photobiomodulation in the functional recovery of proximal humerus fractures: a randomized controlled clinical protocol.","journal_abbr":"PLoS One","authors":["de Freitas LC","Kim DS","Santana da Costa D","et al."],"date":"2025-04-29","year":2025,"doi":"10.1371/journal.pone.0321746","pmcid":"PMC12040229","license":"cc by","oa":true,"cited_by":1,"pub_types":["Clinical Trial Protocol","Research Support, Non-U.S. Gov't"],"curated":false,"type":"protocol","level":0,"ctx":["récupération"],"nm":[660,850],"l1":"If the data are not normally distributed, they will be presented as medians and interquartile ranges, with comparisons made using non-parametric tests. A p-value of less than 0.05 will be considered statistically significant.","kw":"Adolescent Adult Aged Female Humans Male"},{"pmid":"40293646","title":"Synergy Between Neurofeedback and Biofeedback Enhances Therapeutic Outcomes.","journal_abbr":"Appl Psychophysiol Biofeedback","authors":["Thompson L"],"date":"2025-04-28","year":2025,"doi":"10.1007/s10484-025-09706-0","cited_by":1,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"Strategies can cover a wide range of approaches that are based on clients' needs and presenting problems; for example, psychotherapy to deal with emotional issues. The final section of the paper shares clinical examples of how treatments…","kw":"ADHD Biofeedback Heart rate variability Metacognitive strategies Neurofeedback Photobiomodulation Humans Neurofeedback Biofeedback, Psychology Attention Deficit"},{"pmid":"40250416","title_fr":"PBM avant exercice avec restriction de flux sanguin","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"—","mode":["laser","LED"],"nm":[],"n":null,"effect":"favorable","theme":"Performance musculaire","l1":"La PBM avant l'exercice avec restriction de flux augmente davantage les gains de force que le placebo.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Photobiomodulation before blood flow restriction exercises: a randomized clinical trial.","journal":"International journal of sports medicine","journal_abbr":"Int J Sports Med","authors":["Ferlito JV","Ferlito MV","Rolnick N","et al."],"date":"2025-04-18","year":2025,"week":"2025-S16","doi":"10.1055/a-2564-8876","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":1,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"This study investigate the effects of photobiomodulation therapy applied before exercises with blood flow restriction during low-load or high-load exercises on muscle adaptations, muscle damage, and redox status. Forty-five untrained men were randomly assigned to four groups: photobiomodulation therapy-blood flow restriction (30% of maximal isometric voluntary contraction), placebo-blood flow restriction (30% of maximal isometric voluntary contraction), photobiomodulation therapy-high-load exercise (80% of maximal isometric voluntary contraction), and placebo-high-load exercise (80% of maximal isometric voluntary contraction). Elbow flexion exercises were performed twice weekly for 8 weeks, followed by a 4-week detraining period. After 8 weeks, photobiomodulation therapy-blood flow restriction, photobiomodulation therapy-high-load exercises, and placebo-blood flow restriction groups significantly increased muscle strength (p<0.05) with non-significant increases in the placebo-high-load exercise group. The photobiomodulation therapy-blood flow restriction group demonstrated a superior magnitude of effects compared to the placebo-high-load exercise (+10.2%) and placebo-blood flow restriction (+7%; p<0.008) groups. Only the placebo-blood flow restriction group reduced the fatigue index post-intervention. During the detraining period, both blood flow restriction groups maintained superior muscle strength compared to baseline levels. The placebo-high-load exercise group exhibited higher creatine kinase activity post-exercise compared to the other groups. No significant changes were observed in nitric oxide, thiobarbituric acid reactive substances, carbonylated proteins, or total antioxidant capacity immediately post-exercise. However, the total antioxidant capacity levels were increased in all groups after 8 weeks of exercise and following a 4-week detraining period. Overall, the photobiomodulation therapy-blood flow restriction group promoted greater gains in muscle strength compared to the placebo-high-load exercise and placebo-blood flow restriction groups."}],"keywords":[]},{"pmid":"40205065","title_fr":"PBM et nombre maximal de répétitions chez le jeune adulte : méta-analyse","type":"ma","level":1,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser","LED"],"nm":[],"n":null,"effect":"mitigé","theme":"Performance musculaire","l1":"La PBM pourrait augmenter le nombre de répétitions en musculation, avec une certitude faible à très faible.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"A systematic review and meta-analysis of the acute effects of photobiomodulation therapy on the maximum number of repetitions in resistance exercise in young adults.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Aguirra P","do Nascimento AP","Casonatto J","et al."],"date":"2025-04-09","year":2025,"week":"2025-S15","doi":"10.1007/s10103-025-04441-8","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":2,"pub_types":["Systematic Review","Meta-Analysis"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Photobiomodulation therapy (PBMT) has reportedly improved muscle endurance in healthy individuals. However, the influence of possible moderating factors (light source, body limb, sex, and irradiation dose) on muscle endurance remains unknown. Therefore, this meta-analysis aimed to determine whether potential moderating factors (light source [laser vs. light-emitting diodes (LED)], body limb [upper vs. lower], sex [men vs. women], and irradiated dose]) influence the effects of PBMT on muscular endurance in terms of the maximum number of repetitions in resistance exercise in healthy young adults. The databases, PubMed, Central, Embase, Scopus, SPORTDiscus, and Web of Science (last updated February 5, 2025), were systematically searched for randomized controlled trials. The eligibility criteria were determined using the population, intervention, comparison, and outcome (PICO) method. The main outcome was the maximum number of repetitions, and the data were pooled using the random-effects model and expressed as the mean difference (MD) and 95% confidence interval (CI). The risk of bias was assessed using the RoB 2 tool, and evidence certainty was evaluated using the Grading of Recommendations Assessment, Development, and Evaluation (GRADE) guidelines. Twelve studies (n = 346 participants) were included in the analyses. There was an overall effect in favor of PBMT (MD = 3.87 [95% CI: 1.06; 6.69], p = 0.01), compared with the placebo. Compared with the placebo, there was an effect in favor of laser (MD = 3.68 [95% CI: -0.07; 7.44], p = 0.05) and LED (MD = 4.12 [95% CI: -0.13; 8.37], p = 0.057), without difference between the light sources. There was a greater effect of PBMT for the upper limb compared with the lower limb (p = 0.02). Compared with the placebo, there was a significant effect of PBMT for the lower (MD = 1.17 [95% CI: 0.03; 2.32], p = 0.04) and upper limbs (MD = 5.87 [95% CI: 3.11; 8.63], p < 0.001). Compared with the placebo, PBMT had an effect for men (MD = 5.24 [95% CI: 1.61; 8.87], p = 0.005) but not for women (MD = 2.37 [95% CI: -1.78; 6.53], p = 0.26), without difference between sexes. The slope of the meta-regression showed a reduction in effect with increasing dose for the upper limb (slope; p = 0.05; Fig. 7A), but not for the lower limb (slope; p = 0.44; Fig. 7B). In conclusion, PBMT improved muscular endurance in terms of the maximum number of repetitions in healthy young adults. This effect was similar between laser and LED, and to a greater extent in upper limb muscles than in lower limb muscles. Furthermore, PBMT appears to promote greater benefits in men than in women. However, these results should be cautiously interpreted because literature still presents a limited number of studies, and the certainty of the evidence was rated as low or very low."}],"keywords":["Laser","Light-emitting diodes","Number of repetitions","Performance","Phototherapy"]},{"pmid":"40260135","title":"Research progress in different physical therapies for treating peripheral nerve injuries.","journal_abbr":"Front Neurol","authors":["Chu XL","Zhao XX","Liu SY","et al."],"date":"2025-04-07","year":2025,"doi":"10.3389/fneur.2025.1508604","pmcid":"PMC12009707","license":"cc by","oa":true,"cited_by":8,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["blessures"],"l1":"In summary, this article offers theoretical and empirical evidence supporting the utilization of physical therapy in the management of PNI. This research aims to promote further research and clinical practice in this field, contributing…","kw":"aerobic exercise electricity peripheral nerve regeneration photobiomodulation ultrasound"},{"pmid":"40064728","title_fr":"PBM, monocytes et cytokines après exercice pliométrique","type":"rct","level":2,"pop":"adulte","ctx":["récupération"],"aim":"traitement","mode":["laser","LED"],"nm":[],"n":null,"effect":"favorable","theme":"Récupération & courbatures","l1":"La PBM atténue l'inflammation et favorise la récupération immunitaire après un exercice pliométrique.","l2":"—","l3":{"points":["Mécanisme immunitaire."],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Effect of photobiomodulation on monocyte dynamics and cytokine levels following plyometric exercise in physically active men.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Silva IM","Schipper L","Lira FS","et al."],"date":"2025-03-11","year":2025,"week":"2025-S11","doi":"10.1007/s10103-025-04386-y","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Photobiomodulation (PBMT) has been investigated as a non-invasive approach to modulate inflammation and muscle recovery, especially after intense exercise. This study aimed to evaluate the impact of PBMT on the dynamics of monocyte subpopulations and cytokine levels after a plyometric exercise session in physically active men aged 18-25 years. This randomized, double-blind, placebo-controlled study, 22 participants were divided into PBMT and placebo groups. Blood samples were collected before, immediately after, and 72 h post-exercise. Monocyte subpopulations were analyzed by flow cytometry, while cytokine levels (TNF-α and MCP-1) were quantified using enzyme-linked immunosorvent assays (ELISA). Plyometric exercise increases classic monocytes (CD14 + CD16-) at 72 h compared in the PBMT group (+ 2,38% p = 0.035). Intermediate monocytes (CD14 + CD16 +), increase immediately after (p < 0.001) and 72 h (PTBM + 21,43%; placebo + 36%; p = 0.023) after exercise in the both group; Non-classical monocytes (CD14-CD16 +) showed differences between groups at 72 h (11,11%; p = 0.002). Exercise increased TNF-α and MCP-1 levels immediately after (p < 0.01 for both groups). PBMT reduced TNF-α levels below baseline at 72 h (-12,50%; p = 0.035), while MCP-1 remained elevated in the placebo group (+ 27,78%; p < 0.035). Differences in MCP-1 changes (Δ%) were observed 72 h post-exercise (p = 0.03). These findings suggest that PBMT attenuates inflammation and promotes immune recovery after exercise."}],"keywords":["Inflammation","Monocytes","Muscle damage","Photobiomodulation","Plyometric exercise"]},{"pmid":"40063138","title_fr":"Irradiance de la PBM et musculation des membres inférieurs","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"—","mode":["laser","LED"],"nm":[],"n":42,"effect":"neutre","theme":"Performance musculaire","l1":"Chez 42 participants, la PBM (sonde ou couverture LED) n'améliore pas la performance d'un programme de musculation.","l2":"—","l3":{"points":["Double aveugle."],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Influence of irradiance on photobiomodulation therapy for muscle performance in healthy individuals in a strength training program for lower limbs. A double-blind randomized controlled trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Caseiro-Filho LC","Girasol CE","Rinaldi ML","et al."],"date":"2025-03-10","year":2025,"week":"2025-S11","doi":"10.1007/s10103-025-04384-0","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"This investigation attempts to elucidate power density's interplay with observed outcomes subsequent to a training regimen. Forty-two participants were stratified into three groups (Sham, Cluster, LED-Blanket), with irradiated groups receiving 300 J of energy under distinct parameters. Photobiomodulation irradiation was applied to the quadriceps and hamstrings before each of the ten prescribed training sessions, which consisted of three sets of stiff and squats. Participants underwent assessment during sessions, encompassing blood lactate measurements and psychophysiological scales (Numerical Rating Pain Scale for Pain and Rate of Perceived Effort). Additionally, pre-intervention, post-intervention, and follow-up evaluations on an isokinetic dynamometer measured peak torque. Two-way repeated measures ANOVA for intra- and inter-group comparisons. No significant inter-group differences or group-time interactions were discerned in lactate concentration or psychophysiological indices. Solely, a difference surfaced in the peak torque of the dominant limb during knee flexion, manifesting across pre-, post, and follow-up intervals (p = 0.003 and p < 0.001) with an effect size of n2 = 0.080. Within the outlined methodological framework, photobiomodulation was ineffective in eliciting performance enhancements, with divergent parameters evincing equivocal efficacy."}],"keywords":["Exercise training","Low-level light therapy","Muscle strength","Physical therapy"]},{"pmid":"40041535","title":"A Multimodal Chiropractic Approach to the Treatment and Management of Medial Elbow Injuries in Elite Javelin Throwers: A Case Series.","journal_abbr":"Int J Sports Phys Ther","authors":["McEntyre AS","Clohesy NC","Steven DJ"],"date":"2025-03-01","year":2025,"doi":"10.26603/001c.129970","pmcid":"PMC11872539","license":"cc by-nc","oa":true,"curated":false,"type":"autre","level":0,"ctx":["blessures"],"l1":"This case series presents results which demonstrate positive outcomes after using a multimodal chiropractic treatment and management approach in five javelin throwers with medial elbow injuries.","kw":"athlete chiropractic golfers elbow javelin manual therapies medial elbow injuries"},{"pmid":"39883205","k":5,"title_fr":"PBM corps entier, performance et récupération : revue systématique","type":"sr","level":3,"pop":"adulte","ctx":["récupération"],"aim":"traitement","mode":["laser","LED"],"nm":[],"n":null,"effect":"neutre","theme":"Récupération & courbatures","l1":"La PBM corps entier pourrait améliorer le sommeil mais n'a montré aucun bénéfice sur la récupération ni la performance.","l2":"Revue systématique de 5 études.","l3":{"points":["Contraste avec la PBM locale."],"limites":["Peu d'études."],"pratique":"Préférer la PBM locale."},"em":[],"pre":"","topic":"sport","title":"A systematic review on whole-body photobiomodulation for exercise performance and recovery.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Álvarez-Martínez M","Borden G"],"date":"2025-01-30","year":2025,"week":"2025-S05","doi":"10.1007/s10103-025-04318-w","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":5,"pub_types":["Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"PURPOSE","text":"Photobiomodulation (PBM) is a non-invasive therapeutic procedure that consists of irradiating a local area of the skin with red and near-infrared lasers or light emitting diodes (LEDs). Local PBM has been studied as a method to improve exercise performance and recovery. This review aims to evaluate the efficacy of whole-body PBM for exercise performance and recovery, comparing its findings to the established effects of localized PBM."},{"label":"METHODS","text":"This systematic review was conducted utilising PubMed, The Cochrane Library, EBSCO and Google Scholar, with the search terms (whole-body OR full-body) AND (photobiomodulation OR \"light therapy\"). We included studies on human participants that used whole-body PBM in the red or near-infrared spectrum, before or after exercise to enhance performance or recovery, and provided a qualitative synthesis of the findings."},{"label":"RESULTS","text":"A total of five studies were identified out of the 193 screened, with a total of 105 physically active participants, representing both sexes, engaging in different exercise modalities. Two studies reported better sleep quality, as determined by a subjective questionnaire and a commercial sleep tracker, including higher serum melatonin and lower nocturnal heart rate in participants using whole-body PBM. However, none of the five studies reported any benefit of whole-body PBM on biomarkers of fatigue and exercise performance."},{"label":"CONCLUSION","text":"Whole-body PBM may improve sleep quality but shows no evidence of benefits for exercise recovery or performance. Further research is necessary to resolve discrepancies with the benefits observed in localized PBM studies."}],"keywords":["Exercise performance","Exercise recovery","Low-level light therapy","Photobiomodulation","Whole-body"]},{"pmid":"39856265","title":"Influence of an aquatic resistance progressive exercise and low-level laser therapy on musculoskeletal atrophy: an experimental model of knee osteoarthritis.","journal_abbr":"Lasers Med Sci","authors":["Assis L","Domigos H","Tim C","et al."],"date":"2025-01-24","year":2025,"doi":"10.1007/s10103-025-04301-5","cited_by":1,"curated":false,"type":"preclinical","level":5,"ctx":["populations"],"nm":[808],"pre":"vivo","l1":"Moreover, both trained groups presented a reduced expression of atrogin and an intense myoD immunoexpression in the laser exercised animals. The results demonstrate that APRE was effective in reducing muscle atrophy markers and its…","kw":"Aquatic progressive resistance exercise Atrophy Low-level laser therapy Muscle Osteoarthritis Rehabilitation Animals Rats, Wistar Male Osteoarthritis, Knee Low-"},{"pmid":"39997648","title":"Proprioceptive Neuromuscular Facilitation and/or Electrical Stimulation in Patients with Peripheral Facial Paralysis: A Systematic Review.","journal_abbr":"Neurol Int","authors":["Dominguez-Defez N","Lopez-Barreiro J","Hernandez-Lucas P","et al."],"date":"2025-01-23","year":2025,"doi":"10.3390/neurolint17020017","pmcid":"PMC11858216","license":"cc by","oa":true,"cited_by":7,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["populations"],"l1":"PNF and/or electrical stimulation treatment in patients with PFP can be effective when employed early with appropriate parameters, showing promising results in improving quality of life, facial movement quality, and CMAP and reducing both…","kw":"Bell’s palsy electrotherapy exercise therapy facial nerve diseases musculoskeletal manipulations rehabilitation"},{"pmid":"39838713","title":"Effects of transcranial photobiomodulation on fine motor skills in boccia para-athletes.","journal_abbr":"Photochem Photobiol","authors":["de Morais Garcez E","Baptista A","Hamblin MR","et al."],"date":"2025-01-21","year":2025,"doi":"10.1111/php.14060","cited_by":1,"curated":false,"type":"autre","level":0,"ctx":[],"nm":[660,850],"l1":"No significant improvements were observed in the placebo group. t-PBM was shown to be a potentially effective treatment, with significant benefits in fine motor skills.","kw":"LED intralimbal coordination manual dexterity neuro‐photomodulation Humans Motor Skills Male Adult Low-Level Light Therapy Female"},{"pmid":"39799140","title":"Remote photobiomodulation ameliorates behavioral and neuropathological outcomes in a rat model of repeated closed head injury.","journal_abbr":"Transl Psychiatry","authors":["Wu C","Li M","Chen Z","et al."],"date":"2025-01-11","year":2025,"doi":"10.1038/s41398-025-03228-3","pmcid":"PMC11724958","license":"cc by-nc-nd","oa":true,"cited_by":5,"curated":false,"type":"preclinical","level":5,"ctx":["blessures","populations"],"nm":[808],"em":["cw"],"pre":"vivo","l1":"Analysis of lung microbiome changes revealed an enrichment of lipopolysaccharide (LPS) biosynthesis pathways, suggesting a potential link to neuroprotection. Furthermore, remote PBM mitigated hyperactivation of cortical microglia and…","kw":"Animals Low-Level Light Therapy Rats Male Disease Models, Animal Behavior, Animal"},{"pmid":"39652050","title":"The influence of photobiomodulation on upper body muscular performance in collegiate athletes.","journal_abbr":"J Sports Med Phys Fitness","authors":["D'Amico A","Bouranis C","Silva K","et al."],"date":"2024-12-09","year":2024,"doi":"10.23736/S0022-4707.24.16418-3","curated":false,"type":"autre","level":0,"ctx":["performance"],"l1":"These findings suggest that muscular performance during multi-joint resistance exercises such as the bench press may not benefit from PBM in the same fashion as single-joint resistance exercises.","kw":"Humans Young Adult Low-Level Light Therapy Male Myalgia Resistance Training"},{"pmid":"39624135","title":"Pelvic floor muscle training associated with the photobiomodulation therapy for women affected by the genitourinary syndrome of menopause: a study protocol.","journal_abbr":"PeerJ","authors":["Oliveira Bezerra L","de Carvalho MLAS","Silva-Filho E","et al."],"date":"2024-11-29","year":2024,"doi":"10.7717/peerj.17848","pmcid":"PMC11610460","license":"cc by","oa":true,"pdf":"pdfs/39624135.pdf","cited_by":2,"pub_types":["Clinical Trial Protocol"],"curated":false,"type":"protocol","level":0,"ctx":["populations"],"l1":"We expect this protocol to demonstrate that the use of PFMT and photobiomodulation strategies is feasible and able to potentiate the recovery of women affected by the genitourinary syndrome of menopause. The Ethics Committee of the…","kw":"Low-level light therapy Pelvic floor disorders Sexual dysfunction Adult Female Humans Middle Aged Double-Blind Method Exercise Therapy"},{"pmid":"39766378","title":"The Impact of Low-Level Laser Therapy on Spasticity in Children with Spastic Cerebral Palsy: A Systematic Review.","journal_abbr":"Brain Sci","authors":["Jiménez A","Carrick FR","Hoffman N","et al."],"date":"2024-11-25","year":2024,"doi":"10.3390/brainsci14121179","pmcid":"PMC11674564","license":"cc by","oa":true,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"This review indicates that LLLT shows promise in decreasing spasticity in children with cerebral palsy. Nevertheless, a lack of treatment parameters, heterogeneity in research methods, and a lack of objective outcome measures weaken the…","kw":"cerebral palsy children low-level laser therapy spasticity"},{"pmid":"39543005","title_fr":"PBM et contribution énergétique en normoxie et hypoxie chez le coureur amateur","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser","LED"],"nm":[850],"n":11,"effect":"neutre","theme":"Performance musculaire","l1":"La PBM n'allonge pas le temps d'épuisement en normoxie ni en hypoxie ; en hypoxie, elle augmente la part anaérobie.","l2":"Essai croisé pilote randomisé en simple aveugle, 11 coureurs.","l3":{"points":["Conditions d'altitude."],"limites":["Pilote."],"pratique":"Pas de gain de performance."},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Influence of photobiomodulation on energy contribution in normoxia and hypoxia conditions in amateur runners: a single-blinded and randomized crossover pilot study.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Secarolli LF","Carvalho CD","Girasol CE","et al."],"date":"2024-11-14","year":2024,"week":"2024-S46","doi":"10.1007/s10103-024-04234-5","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"This study aimed to investigate the influence of photobiomodulation therapy (PBMT) in hypoxia (HYP) and normoxia (NOR) on time to exhaustion and the energetic contribution of treadmill running in amateur athletes. Eleven male participants, aged between 18 and 29 years, were submitted to an incremental test to determine the iV̇O2max, and subsequently on separated days, to the PBMT application (irradiation = 720 s; wavelength = 850 nm), followed by four efforts to exhaustion, in treadmill running, under different conditions [NOR + placebo (PLA); NOR + PBMT; HYP + PLA; HYP + PBMT], in random order, to access energy contribution and maximal accumulated oxygen deficit alternative (MAODALT). Time to exhaustion and absolute aerobic contribution were lower in HYP than NOR, for both PLA and PBMT conditions (p < 0.05). In the percentage energy contribution of each metabolism during exhaustion effort, aerobic participation was lower, while MAODALT was higher in HYP than NOR, only in the PLA situation; alactic anaerobic participation was higher in HYP than NOR in the PBMT application situation (p = 0.002). The PBMT does not promote additional benefits over time to exhaustion in NOR and HYP conditions, however PBMT during exhaustive efforts in HYP results in an increase in anaerobiosis."}],"keywords":["Bioenergetic","Hypoxia","Low-level light therapy","Running"]},{"pmid":"39663094","title_fr":"Effet dose de la PBM chez la joueuse de futsal","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["LED"],"nm":[],"n":15,"effect":"neutre","theme":"Performance musculaire","l1":"Chez 15 joueuses de futsal, aucune dose de PBM (300 à 1 260 J) n'améliore l'endurance, la puissance ni la force.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Acute dose-response effect of photobiomodulation therapy on muscle performance in female futsal players: A randomized, double-blind, placebo-controlled, crossover study.","journal":"Journal of bodywork and movement therapies","journal_abbr":"J Bodyw Mov Ther","authors":["Borim JM","Borghi SM","do Nascimento AP","et al."],"date":"2024-11-07","year":2024,"week":"2024-S45","doi":"10.1016/j.jbmt.2024.11.006","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":2,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"BACKGROUND","text":"Photobiomodulation therapy (PBMT) has recently been indicated as a potential therapeutic strategy in diverse health and sports contexts. However, its efficacy on muscle performance in female futsal players remains unknown. The purpose of this study was to investigate the dose-response effect of PBMT on muscle performance in female futsal players."},{"label":"METHODS","text":"In a crossover design, fifteen female futsal athletes (age: 18-30 years) were randomized to receive 1 of 4 PBMT conditions (placebo, 300, 900, and 1260 J [J]) on four occasions, separated by a 2-wk washout period. PBMT treatments were applied on the quadriceps muscle of both legs using a device containing 200 light-emitting diodes (LEDs), immediately before the following tests: countermovement jump (CMJ) (i.e., flight time as indicator of muscle power), maximum voluntary isometric contraction (MVIC) for the leg extension exercise (i.e., muscle strength), and 3 sets of repetitions-to-failure (i.e., local muscular endurance) for the 45° leg press exercise, with recording of rating of perceived exertion (RPE) after each set. The fatigue index was determined by the number of repetitions between sets 1 and 3."},{"label":"RESULTS","text":"No significant differences were found between the PBMT conditions for the maximum number of repetitions (p = 0.899), RPE (time p < 0.0001; interaction p = 0.653), fatigue index (p = 0.835), muscle power (p = 0.789), and isometric peak and mean torque (p = 0.776 and 0.537, respectively)."},{"label":"CONCLUSION","text":"Different doses of acute PBMT with LEDs do not improve muscle performance (endurance, power, and strength) and RPE in female futsal players."}],"keywords":["Futsal","Laser","Light-emitting diodes","Performance","Phototherapy","Power","Strength"]},{"pmid":"40270626","title":"The comparison of the efficacy of extracorporeal shockwave therapy and high-intensity laser therapy in the treatment of de Quervain tenosynovitis.","journal_abbr":"Turk J Phys Med Rehabil","authors":["Karakuzu Güngör Z","Güngör E"],"date":"2024-10-31","year":2024,"doi":"10.5606/tftrd.2024.14671","pmcid":"PMC12012914","license":"cc by-nc","oa":true,"cited_by":3,"curated":false,"type":"autre","level":0,"ctx":[],"l1":"Both ESWT and HILT treatments are safe and effective in DQT treatment. The ESWT is a recent, non-invasive therapeutic modality which is effective, convenient, and safe in DQT. On the other hand, HILT is a non-invasive, reliable method…","kw":"De Quervain tenosynovitis extracorporeal shockwave therapy high-intensity laser therapy."},{"pmid":"39459602","title":"The Effectiveness of High Intensity Laser in Improving Motor Deficits in Patients with Lumbar Disc Herniation.","journal_abbr":"Life (Basel)","authors":["Tache-Codreanu DL","Trăistaru MR"],"date":"2024-10-14","year":2024,"doi":"10.3390/life14101302","pmcid":"PMC11509049","license":"cc by","oa":true,"cited_by":5,"curated":false,"type":"autre","level":0,"ctx":["récupération","populations"],"l1":"The group undergoing a rehabilitation program with integrated HIL therapy displayed significantly greater improvement in motor deficits, affirming the positive impact of HIL therapy on functional parameters among LDH patients.","kw":"assessment disability disk herniation high intensity laser therapy motor deficit neuronal recovery"},{"pmid":"39449475","title":"Photobiomodulation as Medicine: Low-Level Laser Therapy (LLLT) for Acute Tissue Injury or Sport Performance Recovery.","journal_abbr":"J Funct Morphol Kinesiol","authors":["Lawrence J","Sorra K"],"date":"2024-09-27","year":2024,"doi":"10.3390/jfmk9040181","pmcid":"PMC11503318","license":"cc by","oa":true,"cited_by":17,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["performance","récupération","blessures"],"l1":"Technical properties of laser light delivery to the body also differ materially from LED devices. Sport physiotherapists, team physicians, trainers and athletes should understand limitations in the current evidence-base informing…","kw":"acute tissue injury low-level laser therapy photobiomodulation sport performance wound healing"},{"pmid":"39345834","title":"Effects of photobiomodulation therapy associated with motor control exercise for chronic non-specific low back pain: protocol for a randomised placebo-controlled trial.","journal_abbr":"BMJ Open Sport Exerc Med","authors":["de Oliveira MFD","Bjordal JM","Schardong J","et al."],"date":"2024-09-26","year":2024,"doi":"10.1136/bmjsem-2024-002199","pmcid":"PMC11429343","license":"cc by-nc","oa":true,"cited_by":3,"curated":false,"type":"autre","level":0,"ctx":["blessures"],"l1":"The results will be disseminated through scientific publications and presentations at scientific meetings. Trial registration number: NCT05487118.","kw":"Back injuries Exercise Randomised controlled trial"},{"pmid":"39227554","title":"LED therapy modulates M1/M2 macrophage phenotypes and mitigates dystrophic features in treadmill-trained mdx mice.","journal_abbr":"Photochem Photobiol Sci","authors":["Pereira VA","da Silva HNM","Fernandes EM","et al."],"date":"2024-09-03","year":2024,"doi":"10.1007/s43630-024-00626-2","cited_by":1,"curated":false,"type":"preclinical","level":5,"ctx":["populations"],"nm":[850],"pre":"vivo","l1":"Our data also imply that the beneficial effects of LED therapy in the dystrophic muscle correlate with the interplay between calcium, oxidative stress and inflammation signalling pathways. Together, these results suggest that…","kw":"mdx mice Calcium pathways Dystrophic muscle Exercise Inflammatory process Oxidative stress Animals Mice, Inbred mdx Mice Macrophages Muscular Dystrophy, Duchenn"},{"pmid":"39211002","title":"Photobiomodulation use in ophthalmology - an overview of translational research from bench to bedside.","journal_abbr":"Front Ophthalmol (Lausanne)","authors":["Valter K","Tedford SE","Eells JT","et al."],"date":"2024-08-15","year":2024,"doi":"10.3389/fopht.2024.1388602","pmcid":"PMC11358123","license":"cc by","oa":true,"cited_by":14,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["populations"],"l1":"More recently, preclinical findings in ocular models have been translated to the clinic with promising results. This review discusses the preclinical and clinical evidence of the effects of PBM in ophthalmology and provides…","kw":"age-related macular degeneration diabetic retinopathy ophthalmology photobiomodulation retina retinopathy"},{"pmid":"39200194","title":"The Role of Bone Edema in Plantar Fasciitis Treated with Temperature-Controlled High-Energy Adjustable Multi-Mode Emission Laser (THEAL) and Exercise: A Prospective Randomized Clinical Trial.","journal_abbr":"Biomedicines","authors":["Covelli I","De Giorgi S","Di Lorenzo A","et al."],"date":"2024-08-02","year":2024,"doi":"10.3390/biomedicines12081729","pmcid":"PMC11351923","license":"cc by","oa":true,"curated":false,"type":"autre","level":0,"ctx":[],"l1":"The regression analysis showed that a greater reduction in fascia thickness occurred in the laser group (p-value: 0.047). In conclusion, the two conservative treatments were effective in patients suffering from plantar fasciitis, even in…","kw":"bone edema exercise high-intensity laser therapy plantar fasciitis"},{"pmid":"39099702","title":"Use of low-level laser therapy as an adjuvant therapy for phlebostatic lesions.","journal_abbr":"J Vasc Bras","authors":["Rezende LDA","Catabriga DS","Pacheco AO","et al."],"date":"2024-07-08","year":2024,"doi":"10.1590/1677-5449.202301592","pmcid":"PMC11296685","license":"cc by","oa":true,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"nm":[635,780],"l1":"The question was answered: \"What is the effectiveness described in the literature of using low-intensity laser therapy (LILT) in the treatment of venous lesions?\" The wavelength used in studies varied from 635 nm of red ray to 780 nm of…","kw":"terapia com luz de baixa intensidade venous insufficiency venous ulcer"},{"pmid":"38965082","title":"Effect of combined red and infrared wavelengths on inflammation, hemorrhage, and muscle damage caused by Bothrops leucurus snake venom.","journal_abbr":"Lasers Med Sci","authors":["da Silva GD","Silva FL","da Paixão Sevá A","et al."],"date":"2024-07-04","year":2024,"doi":"10.1007/s10103-024-04116-w","cited_by":2,"curated":false,"type":"preclinical","level":5,"ctx":["récupération"],"nm":[660,808],"em":["cw"],"pre":"vivo","l1":"leucurus venom and stimulated collagen deposition. Better results were obtained with the combined wavelengths.","kw":"Inflammatory infiltrate Photobiomodulation Skeletal muscle Tissue repair Animals Mice Bothrops Low-Level Light Therapy Muscle, Skeletal Inflammation"},{"pmid":"39040733","title":"Effectiveness of Low-Level Laser Therapy Combined With Eccentric Exercise in Treating Midportion Achilles Tendinopathy: A Randomized Controlled Trial.","journal_abbr":"Cureus","authors":["Shriya S","Arya RK","Kushwaha S","et al."],"date":"2024-06-22","year":2024,"doi":"10.7759/cureus.62919","pmcid":"PMC11262780","license":"cc by","oa":true,"cited_by":3,"curated":false,"type":"autre","level":0,"ctx":["blessures"],"l1":"Practitioners should prioritize evidence-based interventions, such as eccentric exercises, as the primary treatment modality while considering alternative therapies for adjunctive purposes. Further research is needed to explore additional…","kw":"achilles tendon eccentric exercises laser therapy overuse injuries tendinopathy"},{"pmid":"38819613","title_fr":"Effet dose de la PBM sur la performance au 5 km","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["LED"],"nm":[],"n":null,"effect":"neutre","theme":"Performance musculaire","l1":"Chez des coureurs entraînés, la PBM jusqu'à 1 260 J n'améliore pas la performance au 5 km.","l2":"Double aveugle, croisé.","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Acute dose-response effect of photobiomodulation therapy on 5-km running performance in trained runners: a randomized, double-blind, placebo-controlled, crossover study.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["do Nascimento AP","de Oliveira GA","Bressanin JPB","et al."],"date":"2024-05-31","year":2024,"week":"2024-S22","doi":"10.1007/s10103-024-04099-8","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Photobiomodulation therapy (PBMT) has been advocated as a potential intervention to improve muscle performance and recovery in the health and sports context. However, the short- and long-term effects of PBMT on endurance running performance remain under-researched and controversial. The purpose of this study was to investigate the acute dose-response effect of PBMT with light-emitting diodes (LEDs) on endurance performance and rating of perceived exertion (RPE; 6-20 Borg) during a 5-km running trial in recreational runners. In a crossover design, eighteen young adult runners (28.7 ± 7.8 years) were randomized to receive 1 of 4 PBMT conditions (placebo, 300, 900, and 1260 Joules [J]) 60 min before the 5-km running trial on four occasions, separated by a 2-wk washout period. The treatments were applied to the quadriceps, hamstrings, and gastrocnemius muscles of both legs using a device containing 200 LEDs (100 red and 100 infrared). The following variables were assessed: endurance performance (i.e. total time, mean velocity, and velocity in the split distances at the initial 200 m and every 400 m lap) and RPE in the split distances at the initial 200 m and every 400 m lap. Data normality and homogeneity were tested using Shapiro-Wilk's and Levene's tests, respectively. Differences between treatment conditions were assessed using the analysis of variance tests (one- or two-way ANOVA, depending on the comparisons), complemented by the Bonferroni post hoc test. There were significant time effects for the running velocity and RPE in the split distances (p < 0.0001), with no significant treatment-by-time interaction (running velocity, p = 0.59; RPE, p = 0.95). The mean velocity (p = 0.997), total time (p = 0.998), and total mean of the RPE (p = 0.91) were similar between treatment conditions. In conclusion, acute PBMT with LEDs at doses of 300, 900, and 1260 J is not recommended for improving endurance performance and RPE in the 5-km running trial in recreational runners."}],"keywords":["Endurance performance","Light emitting diodes","Low-level light therapy","Phototherapy","Running"]},{"pmid":"38823506","title":"Study and optimization of the photobiomodulation effects induced on mitochondrial metabolic activity of human cardiomyocytes for different radiometric and spectral conditions.","journal_abbr":"Life Sci","authors":["Joniová J","Gerelli E","Wagnières G"],"date":"2024-05-31","year":2024,"doi":"10.1016/j.lfs.2024.122760","license":"cc by-nc","cited_by":9,"curated":false,"type":"autre","level":0,"ctx":[],"l1":"This conclusion is important since many approved therapeutics and cancer detection approaches are based on the use of PpIX. Finally, this correlation strongly suggests that the PBM effects mentioned above have a common \"fundamental\"…","kw":"Cardiomyocytes Metabolism Mitochondria PBM Photobiomodulation PpIX Humans Myocytes, Cardiac Low-Level Light Therapy Mitochondria Oxygen Consumption Protoporphyr"},{"pmid":"38781474","title_fr":"PBM, douleur et retour au jeu chez le sportif blessé : méta-analyse","type":"ma","level":1,"pop":"adulte","ctx":["blessures"],"aim":"traitement","mode":["laser","LED"],"nm":[],"n":null,"effect":"mitigé","theme":"Blessures sportives","l1":"La PBM réduit la douleur des sportifs blessés, mais n'accélère pas le retour au jeu.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Effects of Photobiomodulation on Pain and Return to Play of Injured Athletes: A Systematic Review and Meta-analysis.","journal":"Journal of strength and conditioning research","journal_abbr":"J Strength Cond Res","authors":["Morgan RM","Wheeler TD","Poolman MA","et al."],"date":"2024-05-23","year":2024,"week":"2024-S21","doi":"10.1519/JSC.0000000000004752","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":5,"pub_types":["Systematic Review","Meta-Analysis"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Morgan, RM, Wheeler, TD, Poolman, MA, Haugen, ENJ, LeMire, SD, and Fitzgerald, JS. Effects of photobiomodulation on pain and return to play of injured athletes: A systematic review and meta-analysis. J Strength Cond Res 38(6): e310-e319, 2024-The aims of this systematic review and meta-analysis were to evaluate the effect of photobiomodulation (PBM) on musculoskeletal pain in injured athletes and to determine if the effects of PBM allowed injured athletes to return to play faster. Electronic databases (MEDLINE Complete, CINAHL, and SPORTDiscus, PubMed, Web of Science, and Embase) were systematically searched (up to and including November 7, 2023) for peer-reviewed randomized controlled trials (RCTs) meeting criteria. Six RCTs, representing 205 competitive and recreational athletes with a mean age of 24 years, were included in the analysis. There were 6 intervention groups using standard physical therapy (n = 1), placebo PBM (n = 4), and aloe gel (n = 1) lasting between 10 minutes and 8 weeks in duration. The level of significance set for the study was p < 0.05. Overall, the use of PBM indicated a positive effect on pain reduction for PBM vs. control groups, standardized mean differences = 1.03, SE = 0.22, 95% confidence intervals = [0.43-1.63], p = 0.0089, but the 2 RCTs found evaluating the effect of PBM on time to return to play after injury in athletes do not support a benefit. Allied healthcare professionals may use PBM to reduce pain, thus allowing an athlete to return to their normal biomechanical movement faster; however, limited evidence suggests that PBM does not reduce time to return to play after an injury."}],"keywords":[]},{"pmid":"38758297","title_fr":"PBM avant l'effort, endurance et récupération selon le niveau d'activité : méta-analyse","type":"ma","level":1,"pop":"adulte","ctx":["blessures"],"aim":"prévention","mode":["laser","LED"],"nm":[],"n":null,"effect":"mitigé","theme":"Blessures sportives","l1":"La PBM avant l'effort améliore l'endurance musculaire chez les sujets peu entraînés, moins chez les sportifs entraînés en résistance.","l2":"—","l3":{"points":["Effet selon le profil."],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Can pre-exercise photobiomodulation improve muscle endurance and promote recovery from muscle strength and injuries in people with different activity levels? A meta-analysis of randomized controlled trials.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Li BM","Qiu DY","Ni PS","et al."],"date":"2024-05-17","year":2024,"week":"2024-S20","doi":"10.1007/s10103-024-04079-y","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":9,"pub_types":["Meta-Analysis","Review"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Photobiomodulation therapy (PBMT) was introduced as an ergogenic aid for sport performance in healthy individuals is still controversial. The main aim of this study is to assess the potential enhancements in muscle endurance and recovery from muscle strength and injuries mediated by PBMT among individuals exhibiting diverse activity levels. Randomized controlled trials (RCT) of PBMT interventions for healthy people (both trained and untrained individuals) exercising were searched (up to January 16, 2024) in four electronic databases: Web of Science, PubMed, Scopus and Embase. Primary outcome measures included muscle endurance, muscle strength and creatine kinase (CK) levels; secondary outcome measure included Lactate dehydrogenase (LDH) levels. Subgroup analyses based on physical activity levels were conducted for each outcome measure. Thirty-four RCTs were included based on the article inclusion and exclusion criteria. Statistical results showed that PBMT significantly improved muscle endurance (standardized mean difference [SMD] = 0.31, 95%CI 0.11, 0.51, p < 0.01), indicating a moderate effect size. It also facilitated the recovery of muscle strength (SMD = 0.24, 95%CI 0.10, 0.39, p < 0.01) and CK (mean difference [MD] = -77.56, 95%CI -112.67, -42.44, p < 0.01), indicating moderate and large effect sizes, respectively. Furthermore, pre-application of PBMT significantly improved muscle endurance, recovery of muscle strength and injuries in physically inactive individuals and athletes (p < 0.05), while there was no significant benefit for physically active individuals. Pre-application of PBMT improves muscle endurance and promotes recovery from muscle strength and injury (includes CK and LDH) in athletes and sedentary populations, indicating moderate to large effect sizes, but is ineffective in physically active populations. This may be due to the fact that physically active people engage in more resistance training, which leads to a decrease in the proportion of red muscle fibres, thus affecting photobiomodulation."}],"keywords":["Exercise tolerance","Low-level light therapy","Meta-analysis","Muscle strength","Recovery of function"]},{"pmid":"38689440","title_fr":"Laser avant électrostimulation ischémique et fatigue musculaire","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser"],"nm":[850],"n":36,"effect":"favorable","theme":"Performance musculaire","l1":"Chez 36 adultes, 60 J de laser 850 nm avant électrostimulation avec restriction de flux réduisent la fatigue et préservent la force.","l2":"Med Sci Sports Exerc 2024.","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Fatigue Alleviation by Low-Level Laser Preexposure in Ischemic Neuromuscular Electrical Stimulation.","journal":"Medicine and science in sports and exercise","journal_abbr":"Med Sci Sports Exerc","authors":["Wu CC","Lin YT","Hu CL","et al."],"date":"2024-05-01","year":2024,"week":"2024-S18","doi":"10.1249/MSS.0000000000003472","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":5,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"PURPOSE","text":"Despite its susceptibility to muscle fatigue, combined neuromuscular electrical stimulation (NMES) and blood flow restriction (BFR) are effective regimens for managing muscle atrophy when traditional resistance exercises are not feasible. This study investigated the potential of low-level laser therapy (LLLT) in reducing muscle fatigue after the application of combined NMES and BFR."},{"label":"METHODS","text":"Thirty-six healthy adults were divided into control and LLLT groups. The LLLT group received 60 J of 850-nm wavelength LLLT before a training program of combined NMES and BFR of the nondominant extensor carpi radialis longus (ECRL). The control group followed the same protocol but received sham laser therapy. Assessments included maximal voluntary contraction, ECRL mechanical properties, and isometric force tracking for wrist extension."},{"label":"RESULTS","text":"The LLLT group exhibited a smaller normalized difference in maximal voluntary contraction decrement (-4.01 ± 4.88%) than the control group (-23.85 ± 7.12%) ( P < 0.001). The LLLT group demonstrated a smaller decrease in muscle stiffness of the ECRL compared with the control group, characterized by the smaller normalized changes in frequency ( P = 0.002), stiffness ( P = 0.002), and relaxation measures ( P = 0.011) of mechanical oscillation waves. Unlike the control group, the LLLT group exhibited a smaller posttest increase in force fluctuations during force tracking ( P = 0.014), linked to the predominant recruitment of low-threshold MU ( P < 0.001) without fatigue-related increases in the discharge variability of high-threshold MU ( P > 0.05)."},{"label":"CONCLUSIONS","text":"LLLT preexposure reduces fatigue after combined NMES and BFR, preserving force generation, muscle stiffness, and force scaling. The functional benefits are achieved through fatigue-resistant activation strategies of motor unit recruitment and rate coding."}],"keywords":[]},{"pmid":"38668764","title_fr":"PBM dans l'entorse de cheville : méta-analyse","type":"ma","level":3,"pop":"adulte","ctx":["blessures"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"mitigé","theme":"Blessures sportives","l1":"Dans l'entorse de cheville, la PBM réduit fortement la douleur (preuve modérée), sans effet démontré sur la fonction ni l'œdème.","l2":"Revue systématique avec méta-analyse.","l3":{"points":["Effet antalgique."],"limites":["Preuve faible sur l'œdème."],"pratique":"Antalgie, pas de récupération plus rapide."},"em":[],"pre":"","topic":"sport","title":"Effectiveness of photobiomodulation therapy in the treatment of patients with an ankle sprain: a systematic review and meta-analysis.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Alayat MS","Takaroni A","Elsodany AM","et al."],"date":"2024-04-26","year":2024,"week":"2024-S17","doi":"10.1007/s10103-024-04063-6","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":1,"pub_types":["Systematic Review","Meta-Analysis"],"curated":true,"depth":1,"abstract":[{"label":"BACKGROUND","text":"Photobiomodulation therapy (PBMT) is widely used in the treatment of patients with musculoskeletal and sports disorders with a lack of significance in patients with sprain ankle."},{"label":"PURPOSE","text":"This review investigated the effect of PBMT on pain, oedema, and function in patients with an ankle sprain."},{"label":"METHODS","text":"A systematic search of the databases (MEDLINE, PubMed, EBSCO, Web of Science, Wiley Online Library, Science Direct, Physiotherapy Evidence (PEDro), and the Cochrane Databases) was performed from inception to the end of 2023 to identify any clinical study investigating the effect of PBMT on ankle sprain. PBMT parameters and measured outcomes were extracted. The primary measured outcome was pain and function, and oedema were secondary measured outcomes. Methodological quality was assessed using the PEDro scale. The level of evidence was determined by the Grading of Recommendations Assessment, Development, and Evaluation (GRADE) system. A random effect meta-analysis with forest plot was used to calculate standardized mean difference (SMD) at a 95% confidence interval and the overall effect size (ES)."},{"label":"RESULTS","text":"Six studies (598 patients) were included in the review and five studies in the meta-analysis. There were two fair-quality and four good-quality studies, with a moderate level of evidence on pain, and a low level of evidence on oedema and function. The meta-analysis revealed a significant overall effect of PBMT on pain with high ES [SMD - 0.88 (-1.76, -0.00), p = 0.05], with a non-significant effect on oedema and function with a medium ES [SMD - 0.70 (-1.64, 0.24), p = 0.14] on oedema and low ES on function [SMD - 0.22 (-0.69, 0.24), p = 0.35]. Significant heterogeneity was observed in all measured outcomes with high heterogeneity (I2 > 75%) in pain and oedema and moderate heterogeneity in function."},{"label":"CONCLUSION","text":"PBMT is quite effective for patients with an ankle sprain. PBMT showed high effect size with a moderate level of evidence on pain intensity. The lack of significant effects of PBMT on function and edema with low level of evidence limit the confidence to the current results and recommend further large high-quality studies with higher PBMT intensity and fluency for standardisation of the irradiation parameters and treatment protocol."},{"label":"REGISTRATION","text":"PROSPERO registration number (CRD42021292930)."}],"keywords":["Ankle and foot function","Ankle sprain","Meta-analysis","Oedema","Pain","Photobiomodulation","Systematic review"]},{"pmid":"38714002","title":"Preventive and therapeutic vascular photobiomodulation decreases the inflammatory markers and enhances the muscle repair process in an animal model.","journal_abbr":"J Photochem Photobiol B","authors":["Malavazzi TCDS","Andreo L","Martinelli A","et al."],"date":"2024-04-24","year":2024,"doi":"10.1016/j.jphotobiol.2024.112921","cited_by":9,"curated":false,"type":"preclinical","level":5,"ctx":["blessures","populations"],"nm":[780],"pre":"vivo","l1":"In conclusion, VPBM effectively modulated hematological parameters, circulating leukocytes, the protein expression of the chemokine MCP-1, and the proinflammatory cytokines TNF-α and IL-1β, ultimately influencing the inflammatory process.…","kw":"Cryoinjury Low-level laser Modified ILIB Muscle repair Systemic vascular photobiomodulation Animals Rats, Wistar Low-Level Light Therapy Rats Muscle, Skeletal M"},{"pmid":"38614054","title_fr":"PBM et fonction musculaire dans la sclérose en plaques : essai croisé","type":"rct","level":2,"pop":"adulte","ctx":["populations"],"aim":"traitement","mode":["laser","LED"],"nm":[600,1100],"n":17,"effect":"mitigé","theme":"Sujets âgés & malades chroniques","l1":"Dans la SEP légère à modérée, une dose individualisée de PBM améliore la force et sa récupération, sans effet sur l'endurance.","l2":"Essai croisé randomisé en double aveugle, 17 patients.","l3":{"points":["Dose individualisée."],"limites":["Effet aigu."],"pratique":"Piste en rééducation."},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Effects of photobiomodulation therapy on muscle function in individuals with multiple sclerosis.","journal":"Multiple sclerosis and related disorders","journal_abbr":"Mult Scler Relat Disord","authors":["Rouhani M","Tolentino M","Lyons JA","et al."],"date":"2024-04-01","year":2024,"week":"2024-S14","doi":"10.1016/j.msard.2024.105598","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":8,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"BACKGROUND","text":"In people with multiple sclerosis (pwMS), muscle fatigue and weakness are common issues that can interfere with daily activities. Photobiomodulation therapy (PBMT), comprising light in a 600-1100 nm bandwidth, is a low-level laser therapy thought to improve muscle performance in non-disease populations, in part, by improving mitochondrial function and thus, might be beneficial in pwMS. Given this potential, we aimed to investigate the effects of PBMT on muscle performance in pwMS, both in the short-term and over an extended period."},{"label":"METHODS","text":"This study consisted of two parts with a randomized double-blind crossover design. In study I, muscle function was assessed in four sessions before and after PBMT in ambulatory pwMS (N = 17, F = 14) as follows: maximal voluntary contraction (MVC) and muscle fatigue of the right tibialis anterior (TA) muscle was compared at baseline and following a two-min submaximal fatiguing contraction. Then, PBMT was administered to the belly of TA muscle at different doses of energy of an active device (40 J, 80 J, 120 J) or placebo. The muscle function assessment was then repeated."},{"label":"OUTCOME VARIABLES","text":"muscle force recovery (%), muscle fatigue (%). Statistical tests included McNemar's exact test, Wilcoxon signed-rank test, and the Friedman test. In study II, a subgroup from study I (N = 12, F = 11) received individualized doses (i.e., best dose-effect observed in study I) of active, or placebo PBMT, which was administered on the TA muscle for two weeks. Muscle function assessments were performed pre- and post-PBMT in four sessions similar to study I."},{"label":"OUTCOME VARIABLES","text":"Baseline strength (N), endurance time (s), and muscle fatigue (%). The Wilcoxon signed-rank test was used for statistical analysis. Values are reported as mean (SD)."},{"label":"RESULTS","text":"In study I, participants who received a high dose of PBMT showed significant improvement in force recovery (101.89 % (13.55 %)) compared to the placebo group (96.3 % (18.48 %); p = 0.03). Muscle fatigue did not significantly improve with either active PBMT or placebo. In study II, active PBMT resulted in a significant improvement in muscle strength compared to both the baseline (pre-PBMT = 162.70 N (37.52 N); post-PBMT = 185.56 N (33.95 N); p = 0.01) and the placebo group (active PBMT: mean-change = 22.87 N (23.67 N); placebo: mean-change = -4.12 N (31.95 N); p = 0.02). Endurance time and muscle fatigue did not show significant improvement with either active PBMT or placebo."},{"label":"CONCLUSION","text":"Our findings suggest that an individualized dose of PBMT might improve muscle performance, including force recovery and strength in individuals with mild-moderate MS. Therefore, PBMT might be a novel therapeutic modality, either as a standalone treatment or in combination with other interventions, to improve muscle performance in pwMS."}],"keywords":["Endurance","Low-level laser therapy","Multiple sclerosis","Muscle fatigue","Strength"]},{"pmid":"38610771","title":"Physical Therapies for Delayed Onset Muscle Soreness: A Protocol for an Umbrella and Mapping Systematic Review with Meta-Meta-Analysis.","journal_abbr":"J Clin Med","authors":["Wiecha S","Posadzki P","Prill R","et al."],"date":"2024-03-29","year":2024,"doi":"10.3390/jcm13072006","pmcid":"PMC11012564","license":"cc by","oa":true,"cited_by":5,"curated":false,"type":"autre","level":0,"ctx":["récupération"],"l1":"This umbrella review has the potential to identify gaps in the existing evidence base that would inform future research. The protocol has been registered at PROSPERO (CRD42024485501].","kw":"DOMS evidence-based meta-research muscle soreness physical exercise physiotherapy"},{"pmid":"38606230","title":"Unveiling the Efficacy of Physiotherapy Strategies in Alleviating Low Back Pain: A Comprehensive Review of Interventions and Outcomes.","journal_abbr":"Cureus","authors":["Tikhile P","Patil DS"],"date":"2024-03-12","year":2024,"doi":"10.7759/cureus.56013","pmcid":"PMC11008921","license":"cc by","oa":true,"cited_by":6,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["performance"],"l1":"To get more information about the optimal dosage, therapeutic modalities and long-term effects of these treatments, more admirable research is required. This paper aims to expand the scientific discourse by exploring non-traditional…","kw":"chronic non-specific low-back pain core stability core strengthening low-back pain (lbp) postural balance therapeutic intervention"},{"pmid":"38665862","title":"A Meta-Analysis of Randomized Controlled Trials on the Effects of Photobiomodulation Therapy on Running Performance.","journal_abbr":"Int J Exerc Sci","authors":["Nascimento APD","Silva AVD","Casonatto J","et al."],"date":"2024-03-01","year":2024,"doi":"10.70252/BUWB9550","pmcid":"PMC11042871","license":"cc by-nd","oa":true,"cited_by":1,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["performance"],"l1":"Our findings indicate that PBM alone or combined with a training program does not improve running performance in terms of time-trial and time-to-exhaustion testing. More studies involving PBM plus training and doses higher than 1000 J are…","kw":"LED therapy Phototherapy light-emitting diodes low-level laser therapy physical performance time-to-exhaustion"},{"pmid":"38262071","title_fr":"PBM par LED rouge et proche infrarouge en réanimation : durée de séjour et fonction musculaire","type":"rct","level":2,"pop":"adulte","ctx":["populations"],"aim":"prévention","mode":["LED"],"nm":[635,880],"n":60,"effect":"favorable","theme":"Sujets âgés & malades chroniques","l1":"Chez 60 patients de réanimation, la PBM quotidienne réduit la durée de séjour d'environ 30 % et augmente la force et la mobilité par rapport à la simulation.","l2":"Triple aveugle ; scores de gravité similaires.","l3":{"points":["Critère dur : durée de séjour."],"limites":["Un seul centre."],"pratique":"—"},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Photobiomodulation therapy (red/NIR LEDs) reduced the length of stay in intensive care unit and improved muscle function: A randomized, triple-blind, and sham-controlled trial.","journal":"Journal of biophotonics","journal_abbr":"J Biophotonics","authors":["Neto RPM","Espósito LMB","da Rocha FC","et al."],"date":"2024-01-23","year":2024,"week":"2024-S04","doi":"10.1002/jbio.202300501","pmcid":"PMC11065604","license":null,"oa":false,"pdf":null,"cited_by":8,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't","Research Support, N.I.H., Extramural"],"curated":true,"depth":1,"abstract":[{"label":"CONTEXT","text":"Photobiomodulation therapy (PBMT) has been widely used to improve strength, fatigue resistance and increase muscle mass in healthy individuals. These effects could help critically ill patients admitted to intensive care units (ICUs) who show reduced mobility and muscle strength. ICU-acquired weakness lessens overall health and increases the patient's length of stay in the ICU."},{"label":"OBJECTIVE","text":"This study evaluated the effects of PBMT using low intensity light-emitting diodes (LEDs) on the mobility and muscle strength (functional capacity) and length of stay of patients admitted to hospital ICU."},{"label":"METHODS","text":"This randomized, triple-blind, sham-controlled trial was conducted in a hospital ICU. Sixty patients were randomly assigned to two equal groups: (a) PBMT and (b) Sham. PBMT was applied daily to patients until their discharge from the ICU, using a flexible neoprene array of 264 LEDs (120 at 635 nm, 1.2 mW each; 144 at 880 nm, 15 mW each) for 90s (207.36 Joules) at each site. Ten sites were located bilaterally on the thighs, legs, arms, and forearms ventrally and dorsally, 15 min totaling 2,073.6 Joules per session. Outcomes were length of stay (in h) until discharge from the ICU, muscle strength by the Medical Research Council (MRC) score and handgrip dynamometry (HGD), patient mobility by Intensive Care Unit Mobility Scale (IMS) and the Simplified Acute Physiology Score 3 (SAPS 3) for predicting mortality of patients admitted to the ICU."},{"label":"RESULTS","text":"PBMT reduced the average length of stay in the ICU by ~30% (p = 0.028); increased mobility (IMS: 255% vs. 110% p = 0.007), increased muscle strength (MRC: 12% vs. -9% p = 0.001) and HGD (34% vs. -13% p < 0.001), and the SAPS3 score was similar (p > 0.05)."},{"label":"CONCLUSION","text":"The results suggest that daily PBMT can reduce the length of stay of ICU patients and increase muscle strength and mobility."}],"keywords":["handgrip","intensive care unit","light‐emitting diode","low‐level laser therapy","medical research council"]},{"pmid":"38304418","title":"Innovative integration: optimizing performance through warm-up and photobiomodulation in high-intensity test.","journal_abbr":"Front Sports Act Living","authors":["Santos IA","Lemos MP","Puggina EF","et al."],"date":"2024-01-18","year":2024,"doi":"10.3389/fspor.2024.1341106","pmcid":"PMC10830741","license":"cc by","oa":true,"curated":false,"type":"autre","level":0,"ctx":["performance"],"l1":"The performance in YYIIR1 was superior (p = 0.02) in the WU + PBMT condition (440.0 ± 59.0 m) compared to the WU + Placebo (353.3 ± 94.7 m), and placebo alone (no warm-up) (325.0 ± 67.2 m). We conclude that a combination of a specific…","kw":"ergogenic aids female futsal laser therapy performance running"},{"pmid":"38160343","title":"Effectiveness of cryo plus ultrasound therapy versus diathermy in combination with high-intensity laser therapy for pain relief in footballers with muscle injuries: A prospective study.","journal_abbr":"J Back Musculoskelet Rehabil","authors":["Scaturro D","de Sire A","Vitagliani F","et al."],"date":"2023-12-31","year":2023,"doi":"10.3233/BMR-230265","cited_by":4,"pub_types":["Comparative Study"],"curated":false,"type":"nrct","level":3,"ctx":["performance","blessures"],"l1":"HILT and cryo plus ultrasound therapy, in combination with therapeutic exercise, rep-resent a valid strategy in the treatment of muscle injuries in professional footballers.","kw":"Athletic injuries football muscle performance physical therapies rehabilitation Humans Diathermy Prospective Studies Male Ultrasonic Therapy Case-Control Studie"},{"pmid":"38150056","title_fr":"PBM et performance fonctionnelle du sujet sain : méta-analyse","type":"ma","level":1,"pop":"adulte","ctx":["récupération"],"aim":"prévention","mode":["laser","LED"],"nm":[655,905],"n":null,"effect":"mitigé","theme":"Récupération & courbatures","l1":"La PBM réduit la fatigue et aide la récupération du sujet sain, sans preuve d'augmentation de la force ou de la capacité fonctionnelle.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Effects of photobiomodulation therapy on the functional performance of healthy individuals: a systematic review with meta-analysis.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Bezerra LO","de Macedo LES","da Silva MLA","et al."],"date":"2023-12-27","year":2023,"week":"2023-S52","doi":"10.1007/s10103-023-03956-2","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":8,"pub_types":["Meta-Analysis","Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"","text":"The aim of this study is to assess the effect of photobiomodulation therapy (PBMT) on functional performance concerning strength, fatigue, and functional capacity in healthy individuals. This systematic review with meta-analysis involved searches on data platforms and active searches of randomized clinical trials, focusing on PBMT as the sole intervention. Primary outcomes assessed included strength, fatigue, and functional capacity. Three reviewers screened studies by title and abstract using Rayyan, and data were extracted using a specific form. Bias risk was assessed using RoB2, and confidence in the evidence was evaluated using the Grading of Recommendations Assessment, Development, and Evaluation (GRADE). The RevMan was used for meta-analysis. Sixteen studies were included, totaling 340 individuals (183 males and 157 women). Most articles presented a low risk of bias. Variability was observed in device types and application domains, including wavelengths (655-905 nm), power (10-200 nW), energy (0.6-30 J per point), and time (30-100 s per point). PBMT improved fatigue recovery (mean difference: 5.87; 95% CI 3.83, 7.91). There was no enhancement in strength (peak torque: mean difference 12.40; 95% CI -5.55, 30.55; one-repetition maximum test: mean difference 39.97, 95% CI -2.44, 82.38; isometric and isokinetic strength: mean difference 2.77, 95% CI -14.90, 20.44) nor improvement in short-term (mean difference 0.67, 95% CI -0.58, 1.91) and long-term (mean difference 18.44, 95% CI -55.65, 92.54) functional capacity. PBMT may aid in favoring fatigue recovery in healthy individuals; however, there's no evidence to support PBMT enhancing strength or improving functional capacity."}],"keywords":["Functional performance","Laser therapy","Low-level light therapy","Muscle fatigue","Muscle strength","Young adult"]},{"pmid":"38219522","title":"Physical therapy interventions used to treat individuals with biceps tendinopathy: a scoping review.","journal_abbr":"Braz J Phys Ther","authors":["McDevitt AW","Young JL","Cleland JA","et al."],"date":"2023-12-27","year":2023,"doi":"10.1016/j.bjpt.2023.100586","pmcid":"PMC10825607","cited_by":5,"pub_types":["Scoping Review"],"curated":false,"type":"review","level":5,"ctx":["blessures"],"l1":"This scoping review reported interventions primarily based on therapeutic modalities in quantitative studies while literature reviews, clinical commentaries, and a Delphi study described the addition of manual therapy, patient education,…","kw":"Biceps tendinopathy Intervention Physical therapy Scoping review Sports physical therapy Humans Muscle, Skeletal Physical Therapy Modalities Tendons Shoulder Pa"},{"pmid":"38763575","title_fr":"Moment d'application de la PBM chez le joueur de rugby","type":"rct","level":2,"pop":"adulte","ctx":["blessures"],"aim":"prévention","mode":["laser","LED"],"nm":[850],"n":18,"effect":"mitigé","theme":"Blessures sportives","l1":"Chez 18 rugbymen, la PBM avant l'exercice améliore la performance, mais pas les marqueurs de lésion musculaire.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Effects of photobiomodulation applied at different times on functional performance and ergogenic response of rugby athletes: Randomized clinical trial.","journal":"Journal of bodywork and movement therapies","journal_abbr":"J Bodyw Mov Ther","authors":["da Costa Santos VB","Alvares AM","Chierotti P","et al."],"date":"2023-12-26","year":2023,"week":"2023-S52","doi":"10.1016/j.jbmt.2023.11.052","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":1,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"BACKGROUND","text":"Photobiomodulation (PBM) is indicated to accelerate the recovery of athletes and reduce muscle damage caused by physical exercise. The objective of this study was to establish the best time to apply photobiomodulation to increase the functional performance and ergogenic response of rugby athletes."},{"label":"METHODS","text":"Randomized crossover clinical trial with 18 rugby athletes of both sexes. The interventions were carried out from January to May 2019. The blood levels of creatine kinase (CK) and lactate, and performance in the Modified Star Excursion Balance Test, Single Hop Test, Triple Hop Test, Bangsbo Sprint test (BST), and Yo-Yo intermittent recovery level 1 (YoyoIR1) were evaluated. The athletes underwent two blocks of exercises with the BST and Yoyo-IR1, as well as the random application of four interventions: without application of photobiomodulation (CO), pre-exercise photobiomodulation (PBpre), PBM during the exercise interval (PBint), or post-exercise photobiomodulation (PBpos). The photobiomodulation using light-emitting diodes (850 nm, 8 J/cm2) lasted 10 min and was applied to the quadriceps, hamstrings, and triceps surae muscles. The results were compared between groups and times, and the effect size for the interventions was established."},{"label":"RESULTS","text":"No differences were found between groups in CK, lactate, and performance in the functional tests between groups and times. Only the PBpre presented improved performance in the first Yoyo-1R1 test (p < 0.01), while the PBint improved in the second Yoyo-IR1 test and BST (p < 0.05)."},{"label":"CONCLUSION","text":"The PBM did not change muscle damage markers or performance in the functional tests. For an ergogenic response, photobiomodulation applied before exercise improves performance, which can be maintained when PBM is performed in the exercise interval."}],"keywords":["Athletic performance","Phototherapy","Physical therapy modalities","Prevention","Recovery"]},{"pmid":"38048090","title_fr":"PBM dans les morsures de serpent Bothrops atrox (JAMA Intern Med 2023)","type":"rct","level":2,"pop":"adulte","ctx":["blessures"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"favorable","theme":"Blessures sportives","l1":"Dans un essai en double aveugle publié dans JAMA Internal Medicine, le laser réduit les lésions musculaires et l'inflammation locale après morsure de Bothrops atrox, sans effet indésirable.","l2":"Antalgiques comparables dans les deux groupes.","l3":{"points":["Publication de haut niveau."],"limites":["Indication très particulière."],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Photobiomodulation Therapy to Treat Snakebites Caused by Bothrops atrox: A Randomized Clinical Trial.","journal":"JAMA internal medicine","journal_abbr":"JAMA Intern Med","authors":["Carvalho ÉDS","Souza ARDN","Melo DFC","et al."],"date":"2023-12-04","year":2023,"week":"2023-S49","doi":"10.1001/jamainternmed.2023.6538","pmcid":"PMC10696517","license":"cc by","oa":true,"pdf":null,"cited_by":11,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"IMPORTANCE","text":"Bothrops venom acts almost immediately at the bite site and causes tissue damage."},{"label":"OBJECTIVE","text":"To investigate the feasibility and explore the safety and efficacy of low-level laser therapy (LLLT) in reducing the local manifestations of B atrox envenomations."},{"label":"DESIGN, SETTING, AND PARTICIPANTS","text":"This was a double-blind randomized clinical trial conducted at Fundação de Medicina Tropical Doutor Heitor Vieira Dourado, in Manaus, Brazil. A total of 60 adult participants were included from November 2020 to March 2022, with 30 in each group. Baseline characteristics on admission were similarly distributed between groups. Data analysis was performed from August to December 2022."},{"label":"INTERVENTION","text":"The intervention group received LLLT combined with regular antivenom treatment. The laser used was a gallium arsenide laser with 4 infrared laser emitters and 4 red laser emitters, 4 J/cm2 for 40 seconds at each application point."},{"label":"MAIN OUTCOMES AND MEASURES","text":"Feasibility was assessed by eligibility, recruitment, and retention rates; protocol fidelity; and patients' acceptability. The primary efficacy outcome of this study was myolysis estimated by the value of creatine kinase (U/L) on the third day of follow-up. Secondary efficacy outcomes were (1) pain intensity, (2) circumference measurement ratio, (3) extent of edema, (4) difference between the bite site temperature and that of the contralateral limb, (5) need for the use of analgesics, (6) frequency of secondary infections, and (7) necrosis. These outcomes were measured 48 hours after admission. Disability assessment was carried out from 4 to 6 months after patients' discharge. P values for outcomes were adjusted with Bonferroni correction."},{"label":"RESULTS","text":"A total of 60 patients (mean [SD] age, 43.2 [15.3] years; 8 female individuals [13%] and 52 male individuals [87%]) were included. The study was feasible, and patient retention and acceptability were high. Creatine kinase was significantly lower in the LLLT group (mean [SD], 163.7 [160.0] U/L) 48 hours after admission in relation to the comparator (412.4 [441.3] U/L) (P = .03). Mean (SD) pain intensity (2.9 [2.7] vs 5.0 [2.4]; P = .004), circumference measurement ratio (6.6% [6.6%] vs 17.1% [11.6%]; P < .001), and edema extent (25.8 [15.0] vs 40.1 [22.7] cm; P = .002) were significantly lower in the LLLT group in relation to the comparator. No difference was observed between the groups regarding the mean difference between the bite site temperature and the contralateral limb. Secondary infections, necrosis, disability outcomes, and the frequency of need for analgesics were similar in both groups. No adverse event was observed."},{"label":"CONCLUSIONS AND RELEVANCE","text":"The data from this randomized clinical trial suggest that the use of LLLT was feasible and safe in a hospital setting and effective in reducing muscle damage and the local inflammatory process caused by B atrox envenomations."},{"label":"TRIAL REGISTRATION","text":"Brazilian Registry of Clinical Trials Identifier: RBR-4qw4vf."}],"keywords":[]},{"pmid":"38015822","title":"Therapeutic Photobiomodulation Before Strenuous Exercise Attenuates Shoulder Muscle Fatigue.","journal_abbr":"J Athl Train","authors":["Crow JA","Stauffer JW","Levine D","et al."],"date":"2023-11-28","year":2023,"doi":"10.4085/1062-6050-0171.23","pmcid":"PMC11277280","cited_by":2,"curated":false,"type":"autre","level":0,"ctx":["récupération"],"l1":"Photobiomodulation therapy attenuated fatigue and improved muscular performance of the shoulder external rotators in the latter stages of strenuous resistance exercise.","kw":"isokinetic near-infrared skeletal muscle Humans Male Muscle Fatigue Low-Level Light Therapy Adult Female"},{"pmid":"38432848","title_fr":"PBM, force et endurance du quadriceps chez l'adulte sain","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser","LED"],"nm":[],"n":28,"effect":"neutre","theme":"Performance musculaire","l1":"Chez 28 adultes sains, la PBM n'améliore ni la force ni l'endurance du quadriceps.","l2":"Double aveugle.","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Can photobiomodulation improve quadriceps strength and endurance outcomes in asymptomatic adults? A double-blind randomized controlled trial.","journal":"Journal of bodywork and movement therapies","journal_abbr":"J Bodyw Mov Ther","authors":["Serighelli F","De Oliveira Silva D","Reginato GA","et al."],"date":"2023-11-22","year":2023,"week":"2023-S47","doi":"10.1016/j.jbmt.2023.11.025","pmcid":null,"license":"cc by","oa":false,"pdf":null,"cited_by":2,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"AIM","text":"To explore the effect of photobiomodulation on quadriceps strength and endurance torques in asymptomatic adults."},{"label":"METHODS","text":"Twenty-eight asymptomatic adults were randomized to one of two interventions: photobiomodulation (n = 14) or sham (n = 14). Quadriceps strength was evaluated by maximum voluntary isometric contraction test (60°) and endurance by an elastic resistance in multiple-set knee extension/flexion repetitions using a traction dynamometer. The outcomes were measured at three time points: pre-baseline; baseline and; final assessment. The photobiomodulation was applied to the quadriceps and triceps surae muscles of each participant's dominant lower limb, using a cluster with 1 infrared laser diode and 3 led amber of 170 mW for 240 s over four consecutive days. The sham group went through the same procedures, but the equipment was off, and patients and assessors were blinded to the intervention. Reliability and minimal detectable change of the measures were obtained from the pre-baseline and baseline time points. Differences between interventions were tested by an analysis of covariance."},{"label":"RESULTS AND DISCUSSION","text":"There was no difference between photobiomodulation compared to sham in maximum isometric torque (mean difference (95% CI) = 0.008 (-0.29 to 0.31) and endurance torques (mean difference (95% CI) = 0.04 (-0.03 to 0.12). The mean difference was lower than the minimal detectable change for the maximum isometric torque (1.02 Nm.kg-1) and endurance torque (0.49 Nm.kg-1)."},{"label":"CONCLUSION","text":"Photobiomodulation does not improve quadriceps strength and endurance outcomes in asymptomatic adults."}],"keywords":["Knee","Light-emitting diodes therapy","Low-level laser therapy","Muscle strength","Quadriceps femoris muscle"]},{"pmid":"37999430","title":"Fundamentals or Icing on Top of the Cake? A Narrative Review of Recovery Strategies and Devices for Athletes.","journal_abbr":"Sports (Basel)","authors":["Driller M","Leabeater A"],"date":"2023-11-03","year":2023,"doi":"10.3390/sports11110213","pmcid":"PMC10674277","license":"cc by","oa":true,"cited_by":5,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["performance","récupération"],"l1":"We report that foam rolling, compression garments, cryotherapy, photobiomodulation, hydrotherapy, and active recovery have a high level of positive evidence for improved recovery outcomes, while sauna, recovery boots/sleeves, occlusion…","kw":"cold water immersion compression ice baths massage guns sport performance"},{"pmid":"37918103","title":"Synthesis of surgeon and rehabilitation therapist treatment methods of bicipital tenosynovitis in dogs allows development of an initial consensus therapeutic protocol.","journal_abbr":"J Am Vet Med Assoc","authors":["Lane DM","Pfeil DV","Kowaleski MP"],"date":"2023-11-01","year":2023,"doi":"10.2460/javma.23.08.0461","cited_by":1,"curated":false,"type":"preclinical","level":5,"ctx":["populations"],"pre":"vivo","l1":"Consensus agreement, combined with existing research, was used to create a treatment algorithm suggesting how to best address multiple manifestations of bicipital tendinopathy. Such guidelines can be considered to direct therapeutic…","kw":"bicipital tenosynovitis canine conservative therapy rehabilitation tenotomy Humans Dogs Animals Tenosynovitis Consensus Tendons"},{"pmid":"37917978","title_fr":"Patch lumineux rouge et bleu pulsé dans les contusions de la cuisse","type":"rct","level":2,"pop":"adulte","ctx":["blessures"],"aim":"traitement","mode":["LED"],"nm":[],"n":46,"effect":"favorable","theme":"Blessures sportives","l1":"Chez 46 volontaires, le patch lumineux rouge et bleu améliore la force et la puissance du quadriceps pendant la phase aiguë d'une contusion.","l2":"—","l3":{"points":["Modèle de contusion."],"limites":["Simple aveugle."],"pratique":"—"},"em":["pulse"],"pre":"","topic":"sport","title":"Pulsed Red and Blue Photobiomodulation for the Treatment of Thigh Contusions and Soft Tissue Injury: A Randomized Controlled Trial.","journal":"Journal of sport rehabilitation","journal_abbr":"J Sport Rehabil","authors":["Wells A","Rigby J","Castel C","et al."],"date":"2023-10-13","year":2023,"week":"2023-S41","doi":"10.1123/jsr.2022-0334","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":3,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"CONTEXT","text":"Contusion and soft tissue injuries are common in sports. Photobiomodultion, light and laser therapy, is an effective aid to increase healing rates and improve function after various injury mechanisms. However, it is unclear how well photobiomodulation improves function after a contusion soft tissue injury. This study aimed to determine the effects of a pulsed red and blue photobiomodulation light patch on muscle function following a human thigh contusion injury."},{"label":"DESIGN","text":"Single-blinded randomized control trial design."},{"label":"METHODS","text":"We enrolled 46 healthy participants. Participants completed 5 visits on consecutive days. On the first visit, participants completed a baseline isokinetic quadriceps strength testing protocol at 60°/s and 180°/s. On the second visit, participants were struck in the rectus femoris of the anterior thigh with a tennis ball from a serving machine. Immediately following, participants were treated for 30 minutes with an active or placebo photobiomodulation patch (CareWear light patch system, CareWear Corp). Following the treatment, participants completed the same isokinetic quadriceps strength testing protocol. Participants completed the treatment and isokinetic quadriceps strength test during the following daily visits. We normalized the data by calculating the percent change from baseline. We used a mixed model analysis of covariance, with sex as a covariate, to determine the difference between treatment groups throughout the acute recovery process."},{"label":"RESULTS","text":"We found the active photobiomodulation treatment significantly increased over the placebo group, quadriceps peak torque during the 180°/s test (P = .030), and average power during both the 60°/s (P = .041) and 180°/s (P ≤ .001) assessments. The mean peak torque and average power of 180°/s, at day 4, exceeded the baseline levels by 8.9% and 16.8%, respectively."},{"label":"CONCLUSIONS","text":"The red and blue photobiomodulation light patch improved muscle strength and power during the acute healing phase of a human thigh contusion injury model."}],"keywords":["bruise","light therapy","recovery"]},{"pmid":"38028882","title":"The Effect of Photobiomodulation on the Treatment of Hereditary Mitochondrial Diseases.","journal_abbr":"J Lasers Med Sci","authors":["Baskerville R","Krijgsveld N","Esser P","et al."],"date":"2023-10-10","year":2023,"doi":"10.34172/jlms.2023.41","pmcid":"PMC10658120","cited_by":7,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["récupération","populations"],"l1":"Conclusion: There is emerging evidence of efficacy for PBMT for diseases involving acquired mitochondrial insufficiency. We identified no published research on PBMT in hereditary mitochondrial disease, but this review confirms a…","kw":"Cytochrome oxidase Fatigue Mitochondrial disease Muscle Near-infrared Photobiomodulation"},{"pmid":"37915879","title":"Physiotherapy Rehabilitation Following Lower Extremity Split Skin Grafting in Necrotizing Fasciitis.","journal_abbr":"Cureus","authors":["Hatwar V","Phansopkar P"],"date":"2023-09-30","year":2023,"doi":"10.7759/cureus.46295","pmcid":"PMC10616995","license":"cc by","oa":true,"cited_by":2,"pub_types":["Case Reports"],"curated":false,"type":"cases","level":4,"ctx":[],"l1":"There was an improvement in all the outcome measures taken. The treatment protocol proved to be beneficial for the patient.","kw":"necrotizing fasciitis physiotherapy intervention physiotherapy management rehabilitation skin grafting"},{"pmid":"37842301","title":"Psychophysical therapy and underlying neuroendocrine mechanisms for the rehabilitation of long COVID-19.","journal_abbr":"Front Endocrinol (Lausanne)","authors":["Meng QT","Song WQ","Churilov LP","et al."],"date":"2023-09-29","year":2023,"doi":"10.3389/fendo.2023.1120475","pmcid":"PMC10570751","license":"cc by","oa":true,"cited_by":3,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["populations"],"l1":"Neuroendocrine regulation plays a significant role in repairing damage after viral infection, regulating immune homeostasis, and improving metabolic activity in patients with long COVID-19. This review uses oxytocin as an example to…","kw":"hormone long COVID-19 psychophysical therapies rehabilitation sequelae Humans Post-Acute COVID-19 Syndrome COVID-19 SARS-CoV-2 Neurosecretory Systems Disease Pr"},{"pmid":"38288386","title":"Effects of Photobiomodulation on High-Intensity Intermittent Anaerobic Performance of Lower Limbs in Brazilian Jiu-Jitsu Athletes: A Randomized, Crossover, Double-Blind Clinical Trial.","journal_abbr":"Int J Exerc Sci","authors":["Dos Santos Junior RB","Branco BHM","Andreato LV","et al."],"date":"2023-09-01","year":2023,"doi":"10.70252/ZCGJ4357","pmcid":"PMC10824299","license":"cc by-nd","oa":true,"cited_by":1,"curated":false,"type":"autre","level":0,"ctx":["performance"],"l1":"Treatment with PBM did not produce a dose-dependent ergogenic response in high-intensity intermittent performance in BJJ athletes.","kw":"Low-intensity light therapy martial arts sports performance stress test"},{"pmid":"37586862","title":"Biomodulating healing after arthroscopic rotator cuff repair: the protocol of a randomised proof of concept trial (BIOHACK).","journal_abbr":"BMJ Open","authors":["Allaart LJH","Lech J","Macken AA","et al."],"date":"2023-08-16","year":2023,"doi":"10.1136/bmjopen-2022-071078","pmcid":"PMC10432644","license":"cc by-nc","oa":true,"cited_by":1,"pub_types":["Clinical Trial Protocol","Research Support, Non-U.S. Gov't"],"curated":false,"type":"protocol","level":0,"ctx":["blessures"],"l1":"The results of this study will be published in a peer-reviewed journal. NCT04618484.","kw":"ORTHOPAEDIC & TRAUMA SURGERY Orthopaedic sports trauma REHABILITATION MEDICINE Humans Arthroplasty Biological Products Consensus Randomized Controlled Trials as"},{"pmid":"37580518","title_fr":"PBM et muscle squelettique du diabétique : revue des études animales","type":"sr","level":5,"pop":"—","ctx":["populations"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"favorable","theme":"Sujets âgés & malades chroniques","l1":"Chez l'animal diabétique, la PBM améliore la santé musculaire ; des modèles plus proches des patients sont nécessaires.","l2":"—","l3":{"points":["—"],"limites":["Animal."],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Photobiomodulation therapy on skeletal muscles exposed to diabetes mellitus: a systematic review of animal studies.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Dos Santos Soares F","de Souza Pinto M","Kruger A","et al."],"date":"2023-08-14","year":2023,"week":"2023-S33","doi":"10.1007/s10103-023-03853-8","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":3,"pub_types":["Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Diabetes-related muscle damage has been overlooked despite its known association with increased morbidity and mortality in DM individuals. PBMT is a recognized alternative to improve skeletal muscle health in other populations, but its effectiveness in DM is still unclear. To address this issue, we reviewed preclinical studies, available in any language and period, in ten sources of information. The methods were previously registered at PROSPERO (CRD42021271041), based on PRISMA recommendations. Studies in murine models of T1DM or T2DM that reported quantitative analyses of skeletal muscles treated with low-level light therapy could be included after a blind selection process. Most of the seven included studies focus on decompensated T1DM rats with acute muscle injury (cryoinjury or contusion). In these five studies, PBMT improved muscle regeneration, by reducing inflammation and stimulating factors pro-angiogenesis and pro-myogenesis. Some positive effects could also be observed in two studies on muscles without acute injury: control of oxidative stress (T1DM) and reduction of myosteatosis (T2DM). Although infrared laser applied locally appears to be a promising approach, optimal parameters are undefined due to the heterogeneity of outcomes and high risk of bias, which prevented a quantitative synthesis. Several aspects of this growing field have yet to be investigated, particularly regarding the DM model (e.g., aged animals, T2DM), intervention (e.g., comparison with LED), and outcomes (e.g., muscle mass, strength, and function). Future research should aim to improve the internal validity by following guidelines for animal studies and enhance the translatability to clinical trials by using animal models that closely mimic patients with DM in rehabilitation settings."}],"keywords":["Glucose metabolism disorders","Low-level light therapy","Skeletal muscle"]},{"pmid":"37530880","title_fr":"PBM et performance physique de la femme en phase folliculaire","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser","LED"],"nm":[],"n":27,"effect":"neutre","theme":"Performance musculaire","l1":"Chez 27 femmes actives, la PBM ne modifie pas la performance ni les lactates lors d'un test anaérobie en phase folliculaire.","l2":"—","l3":{"points":["Double aveugle."],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Influence of photobiomodulation therapy on the physical performance of women during the follicular phase of the menstrual cycle: A double-blind Sham-controlled randomized clinical trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["de Carvalho Rotoly G","Papoti M","Foresti YF","et al."],"date":"2023-08-02","year":2023,"week":"2023-S31","doi":"10.1007/s10103-023-03840-z","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":2,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"To evaluate the effects of photobiomodulation on the physical performance of healthy women, considering the menstrual cycle. 27 physically active healthy women (age 25.68 ± 3.99 years; mass 63.76 ± 12.77 kg; height 1.65 ± 0.59 cm) during the initial follicular phase (FF1 and FF2) of the menstrual cycle underwent performance evaluations, through a supramaximal test, subjective perception of exertion, blood lactate, and evaluations in the isokinetic dynamometer. Photobiomodulation (PBM) (200J) and Sham (0J) therapy were applied 10 min before the performance evaluations on the quadriceps femoris, hamstrings, and triceps surae muscles. A significance level of 5% was adopted and the effect size was calculated by Cohen's d. It was not possible to observe a significant difference (p > 0.05) in any of the performance variables evaluated in the comparison between groups, only small effects for total distance, final subjective perception of exertion, lactate peak and lactate delta in the PBM group. PBM did not improve muscle performance, resistance to fatigue, perceived exertion, and blood lactate concentrations during a predominantly anaerobic test in healthy women during the FF of the menstrual cycle."}],"keywords":["Fatigue","Light-emitting diode","Menstrual cycle","Performance","Women"]},{"pmid":"37419235","title_fr":"PBM, fonction du genou et tolérance à l'effort chez le sujet âgé : méta-analyse","type":"ma","level":1,"pop":"adulte","ctx":["populations"],"aim":"traitement","mode":["laser","LED"],"nm":[],"n":null,"effect":"favorable","theme":"Sujets âgés & malades chroniques","l1":"Chez les plus de 60 ans qui font de l'exercice, la PBM soulage davantage la douleur et améliore la fonction et l'amplitude du genou.","l2":"Méta-analyse d'essais randomisés (Arch Phys Med Rehabil).","l3":{"points":["Sujets âgés actifs."],"limites":["Hétérogénéité."],"pratique":"Complément de l'exercice."},"em":[],"pre":"","topic":"sport","title":"The Effects of Photobiomodulation on Knee Function, Pain, and Exercise Tolerance in Older Adults: A Meta-analysis of Randomized Controlled Trials.","journal":"Archives of physical medicine and rehabilitation","journal_abbr":"Arch Phys Med Rehabil","authors":["Li BM","Zhang CK","He JH","et al."],"date":"2023-07-05","year":2023,"week":"2023-S27","doi":"10.1016/j.apmr.2023.06.016","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":6,"pub_types":["Meta-Analysis","Review","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"OBJECTIVE","text":"To assess whether photobiomodulation therapy (PBMT) enhances the benefits of exercise in older adults."},{"label":"DATA SOURCES","text":"PubMed, Scopus, Medline, and Web of Science, dated to February 2023."},{"label":"STUDY SELECTION","text":"All included studies were randomized controlled trials of PBMT combined with exercise co-intervention in persons 60 years and older."},{"label":"OUTCOME MEASURES","text":"Western Ontario and McMaster University Osteoarthritis Index (WOMAC-total, pain, stiffness and function), perceived pain intensity, timed Up and Go (TUG) Test, 6-min walk test (6MWT), muscle strength, and knee range of motion were included."},{"label":"DATA EXTRACTION","text":"Two researchers independently performed data extraction. Article data were extracted in Excel and summarized by a third researcher."},{"label":"DATA SYNTHESIS","text":"The meta-analysis included 14 of the 1864 studies searched in the database. No statistical differences were found between the treatment and control groups in terms of WOMAC-stiffness (mean difference [MD]=-0.31, 95% confidence interval [CI] -0.64 to 0.03), TUG (MD=-0.17, 95% CI -0.71 to 0.38), 6MWT (MD=32.2, 95% CI -44.62 to 109.01), or muscle strength (standardized mean difference=0.24, 95% CI -0.02 to 0.50). However, statistically significant differences were found for WOMAC-total (MD=-6.83, 95% CI -12.3 to -1.37), WOMAC-pain (MD=-2.03, 95% CI -4.06 to -0.01), WOMAC-function (MD=-5.03, 95% CI -9.11 to -0.96), visual analog scale/numeric pain rating scale (MD=-1.24, 95% CI -2.43 to -0.06), and knee range of motion (MD=1.47, 95% CI 0.07 to 2.88)."},{"label":"CONCLUSIONS","text":"In older adults who exercise regularly, PBMT can potentially provide additional pain relief, improve knee joint function, and increase knee joint range of motion."}],"keywords":["Exercise","Osteoarthritis of knee","Pain","Photobiomodulation therapy","Rehabilitation"]},{"pmid":"37310556","title":"Photobiomodulation at molecular, cellular, and systemic levels.","journal_abbr":"Lasers Med Sci","authors":["da Silva TG","Ribeiro RS","Mencalha AL","et al."],"date":"2023-06-13","year":2023,"doi":"10.1007/s10103-023-03801-6","cited_by":58,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"These molecules and factors are responsible for cellular effects, such as cell proliferation, migration, differentiation, and apoptosis, which feature PBM at the cellular level. Finally, molecular and cellular effects are responsible for…","kw":"Laser Light-emitting diodes Photobiomodulation Phototherapy Apoptosis Cell Differentiation Cell Proliferation Signal Transduction Muscles"},{"pmid":"37294341","title_fr":"PBM et performance anaérobie du cycliste entraîné","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["LED"],"nm":[630],"n":15,"effect":"neutre","theme":"Performance musculaire","l1":"Chez 15 cyclistes entraînés, la PBM rouge à faible dose n'a pas d'effet ergogène sur la performance anaérobie.","l2":"—","l3":{"points":["Double aveugle."],"limites":["—"],"pratique":"—"},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Photobiomodulation does not improve anaerobic performance in well-trained cyclists.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Flores LJF","de Souza Campos F","Baumann L","et al."],"date":"2023-06-09","year":2023,"week":"2023-S23","doi":"10.1007/s10103-023-03803-4","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":2,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"To determine if photobiomodulation (PBM) has ergogenic effects on the anaerobic performance of well-trained cyclists. Fifteen healthy male road or mountain bike cyclists participated in this randomized, double-blinded, placebo-controlled, crossover study. Athletes were randomly assigned to receive photobiomodulation (630 nm, 4.6 J/cm2, 6 J per point, 16 points, PBM session) or placebo intervention (PLA session) in the first session. The athletes then performed a 30-s Wingate test to determine mean and peak average power, relative power, mean and peak velocity, mean and peak RPM, fatigue index, total distance, time to peak power, explosive strength, and power drop. After 48 h, athletes returned to the laboratory for the crossover intervention. The repeated-measures ANOVA test followed by Bonferroni post hoc test or Friedman test with Dunn's post hoc test (p < 0.05), and Cohen's d statistic were used for comparisons. Performance in the Wingate test was not significantly different (p > 0.05) between PBM and PLA sessions for any variable. Only a small effect size was detected for time to peak power (-0.40; 1.11 to 0.31) and explosive strength (0.38; -0.34 to 1.09). We conclude that irradiation with red light, under a low energy density, does not promote ergogenic effects on the anaerobic performance of cycling athletes."}],"keywords":["Low-Level Light Therapy","Muscle Strength","Performance-enhancing effects","Physical fitness"]},{"pmid":"37214754","title":"Low-level laser therapy in the management of muscle fatigue caused after long Endodontic procedure.","journal_abbr":"J Clin Exp Dent","authors":["Gaikwad TV","Maini AP","Das S","et al."],"date":"2023-05-01","year":2023,"doi":"10.4317/jced.60369","pmcid":"PMC10198691","license":"cc by","oa":true,"cited_by":1,"curated":false,"type":"autre","level":0,"ctx":["récupération"],"l1":"The low-level laser can be a useful procedure immediately post long endodontic procedure causing masticatory muscle fatigue. Hence, this therapy can be considered as an add-on therapeutic procedure along with prolonged endodontic…","kw":""},{"pmid":"37099210","title_fr":"PBM corps entier et récupération après cyclisme anaérobie","type":"rct","level":2,"pop":"adulte","ctx":["récupération"],"aim":"les deux","mode":["LED"],"nm":[],"n":48,"effect":"mitigé","theme":"Récupération & courbatures","l1":"Chez 48 sportifs, la PBM corps entier ne change pas la performance au Wingate, mais améliore la récupération le lendemain.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Whole-body photobiomodulation improves post-exercise recovery but does not affect performance or physiological response during maximal anaerobic cycling.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Forsey JD","Merrigan JJ","Stone JD","et al."],"date":"2023-04-26","year":2023,"week":"2023-S17","doi":"10.1007/s10103-023-03759-5","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":2,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"This study aims to examine the effects of acute whole-body photobiomodulation (wbPBM), applied pre-exercise, on bouts of anaerobic cycling (Wingate) performances. Forty-eight healthy, active males and females participated in this single-blind, randomized, crossover study. Participants visited the laboratory three times to complete repeat (4 ×) Wingate testing, with one week between each visit. All participants completed baseline testing during their first visit and randomly received either the wbPBM or placebo condition before testing on the second visit, followed by the opposite condition on the third visit. There were no significant condition × time interactions for any variable (peak power, average power, power decrement, lactate, heart rate, ratings of perceived exertion, heart rate variability (HRV), root-mean square of differences between R-R intervals (rMSSD), power in the high-frequency range (HF) average, power in the low-frequency range (LF) average, total power, LF/HF, or power in the very-low-frequency range average). A main condition effect was only noted for heart rate, where peak heart rate was significantly higher for wbPBM (145, 141-148 bpm) than placebo (143, 139-146 bpm; p = 0.006) and baseline testing (143, 140-146; p = 0.049) throughout the entire testing session (i.e., collapsed across all timepoints). Furthermore, HRV (rMSSD) the following morning after testing was significantly higher for the wbPBM session compared to placebo (p = 0.043). There were no differences in perceived recovery (p = 0.713) or stress (p = 0.978) scores between wbPBM and placebo. Implementing 20 min of wbPBM immediately prior to maximal bouts of anaerobic cycling did not improve performance (i.e., power output) or physiological responses (e.g., lactate). However, wbPBM elicited the ability to work at a higher heart rate throughout testing and seemed to enhance recovery through improved HRV the following morning."}],"keywords":["Fatigue","Heart rate variability","Muscle soreness","Power output","Red and near-infrared light therapy","Wingate test"]},{"pmid":"36964028","title":"Photobiomodulation (Therapeutic Lasers): An Update and Review of Current Literature.","journal_abbr":"Vet Clin North Am Small Anim Pract","authors":["Bunch J"],"date":"2023-03-22","year":2023,"doi":"10.1016/j.cvsm.2023.02.010","cited_by":11,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"The potential variety of conditions for which it can be used as an adjunctive, non-invasive modality has propelled its use in both veterinary rehabilitation, sports medicine, and general practice. In the last decade, clinical research has…","kw":"Laser therapy Low-level laser therapy Photobiomodulation Therapeutic laser Low-Level Light Therapy Lasers"},{"pmid":"36878185","title":"Low-Level Laser Therapy Facilitates Postcontraction Recovery with Ischemic Preconditioning.","journal_abbr":"Med Sci Sports Exerc","authors":["Chen YC","Lin YT","Hu CL","et al."],"date":"2023-02-24","year":2023,"doi":"10.1249/MSS.0000000000003149","cited_by":7,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"autre","level":0,"ctx":["performance","récupération"],"nm":[808],"l1":"LLL expedites postcontraction recovery with ischemic preconditioning, manifesting as superior force generation capacity and force precision control for activation of MU with a higher recruitment threshold and lower discharge variability.","kw":"Adult Male Humans Female Muscle, Skeletal Electromyography"},{"pmid":"36818359","title":"Recognition and conservative management for a spectrum of sport-related scapholunate interosseous ligament injuries: a case series.","journal_abbr":"J Can Chiropr Assoc","authors":["Parks A","Lee AD","Billham J"],"date":"2023-02-23","year":2023,"pmcid":"PMC9914831","cited_by":2,"curated":false,"type":"autre","level":0,"ctx":["blessures"],"l1":"Management strategies included early wrist immobilization, soft tissue manual therapy, low-level laser therapy, proprioceptive and strengthening exercises, and early orthopedic referral. This case series highlights: (1) the spectrum of SL…","kw":"chiropractic chiropratique conservative management dissociation scapho-lunaire gestion conservatrice instabilité scapho-lunaire"},{"pmid":"36793565","title":"A Clinically-Reasoned Approach to Manual Therapy in Sports Physical Therapy.","journal_abbr":"Int J Sports Phys Ther","authors":["Short S","Tuttle M","Youngman D"],"date":"2023-02-01","year":2023,"doi":"10.26603/001c.67936","pmcid":"PMC9897024","license":"cc by-nc","oa":true,"cited_by":8,"curated":false,"type":"autre","level":0,"ctx":[],"l1":"Given the risks associated with pharmacological pain management, the cost of passive modalities like biophysical agents (electrical stimulation, photobiomodulation, ultrasound, etc), and the indications from the evidence-base when…","kw":"Manual Therapy Pain Sports Physical Therapy Symptom-Modification"},{"pmid":"36769752","title":"Pilates Method and/or Photobiomodulation Therapy Combined to Static Magnetic Field in Women with Stress Urinary Incontinence: A Randomized, Double-Blind, Placebo-Controlled Clinical Trial.","journal_abbr":"J Clin Med","authors":["De Marchi T","Ferlito JV","Turra AC","et al."],"date":"2023-01-31","year":2023,"doi":"10.3390/jcm12031104","pmcid":"PMC9917687","license":"cc by","oa":true,"pdf":"pdfs/36769752.pdf","cited_by":5,"curated":false,"type":"autre","level":0,"ctx":[],"l1":"We observed an increase in strength (p < 0.01), tone (p < 0.01), and quality of life (p < 0.01), in addition to a decrease in urinary lost (p < 0.01) for all groups comparing the pre and post-intervention. The PBMT/sMF alone, the Pilates,…","kw":"Photobiomodulation therapy Pilates method stress urinary incontinence women’s health"},{"pmid":"36622557","title_fr":"Traitements conservateurs après lésion aiguë des ischio-jambiers chez l'athlète : revue évolutive","type":"sr","level":3,"pop":"adulte","ctx":["blessures"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"neutre","theme":"Blessures sportives","l1":"Après lésion des ischio-jambiers, les données ne soutiennent ni le PRP ni le laser en pratique clinique.","l2":"Revue systématique évolutive (Sports Med).","l3":{"points":["Négatif pour le laser."],"limites":["Peu d'essais."],"pratique":"Non recommandé."},"em":[],"pre":"","topic":"sport","title":"Effectiveness of Conservative Interventions After Acute Hamstrings Injuries in Athletes: A Living Systematic Review.","journal":"Sports medicine (Auckland, N.Z.)","journal_abbr":"Sports Med","authors":["Afonso J","Olivares-Jabalera J","Fernandes RJ","et al."],"date":"2023-01-09","year":2023,"week":"2023-S02","doi":"10.1007/s40279-022-01783-z","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":17,"pub_types":["Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"BACKGROUND","text":"Hamstrings injuries are common in sports and the reinjury risk is high. Despite the extensive literature on hamstrings injuries, the effectiveness of the different conservative (i.e., non-surgical) interventions (i.e., modalities and doses) for the rehabilitation of athletes with acute hamstrings injuries is unclear."},{"label":"OBJECTIVE","text":"We aimed to compare the effects of different conservative interventions in time to return to sport (TRTS) and/or time to return to full training (TRFT) and reinjury-related outcomes after acute hamstrings injuries in athletes."},{"label":"DATA SOURCES","text":"We searched CINAHL, Cochrane Library, EMBASE, PubMed, Scopus, SPORTDiscus, and Web of Science databases up to 1 January, 2022, complemented with manual searches, prospective citation tracking, and consultation of external experts."},{"label":"ELIGIBILITY CRITERIA","text":"The eligibility criteria were multi-arm studies (randomized and non-randomized) that compared conservative treatments of acute hamstrings injuries in athletes."},{"label":"DATA ANALYSIS","text":"We summarized the characteristics of included studies and conservative interventions and analyzed data for main outcomes (TRTS, TRFT, and rate of reinjuries). The risk of bias was judged using the Cochrane tools. Quality and completeness of reporting of therapeutic exercise programs were appraised with the i-CONTENT tool and the certainty of evidence was judged using the GRADE framework. TRTS and TRFT were analyzed using mean differences and the risk of reinjury with relative risks."},{"label":"RESULTS","text":"Fourteen studies (12 randomized and two non-randomized) comprising 730 athletes (mostly men with ages between 14 and 49 years) from different sports were included. Nine randomized studies were judged at high risk and three at low risk of bias, and the two non-randomized studies were judged at critical risk of bias. Seven randomized studies compared exercise-based interventions (e.g., L-protocol vs C-protocol), one randomized study compared the use of low-level laser therapy, and three randomized and two non-randomized studies compared injections of platelet-rich plasma to placebo or no injection. These low-level laser therapy and platelet-rich plasma studies complemented their interventions with an exercise program. Only three studies were judged at low overall risk of ineffectiveness (i-CONTENT). No single intervention or combination of interventions proved superior in achieving a faster TRTS/TRFT or reducing the risk of reinjury. Only eccentric lengthening exercises showed limited evidence in allowing a shorter TRFT. The platelet-rich plasma treatment did not consistently reduce the TRFT or have any effect on the risk of new hamstrings injuries. The certainty of evidence was very low for all outcomes and comparisons."},{"label":"CONCLUSIONS","text":"Available evidence precludes the prioritization of a particular exercise-based intervention for athletes with acute hamstrings injuries, as different exercise-based interventions showed comparable effects on TRTS/TRFT and the risk of reinjuries. Available evidence also does not support the use of platelet-rich plasma or low-level laser therapy in clinical practice. The currently available literature is limited because of the risk of bias, risk of ineffectiveness of exercise protocols (as assessed with the i-CONTENT), and the lack of comparability across existing studies."},{"label":"CLINICAL TRIAL REGISTRATION","text":"PROSPERO CRD42021268499 and OSF ( https://osf.io/3k4u2/ )."}],"keywords":[]},{"pmid":"36310376","title":"Resistance exercise and low-level laser therapy improves grip strength and morphological aspects in the ankle joint of Wistar rats with experimental arthritis.","journal_abbr":"Anat Rec (Hoboken)","authors":["Retameiro ACB","Neves M","Tavares ALF","et al."],"date":"2022-10-31","year":2022,"doi":"10.1002/ar.25112","cited_by":6,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"preclinical","level":5,"ctx":["performance","blessures"],"nm":[660],"pre":"vivo","l1":"The treated groups exhibited morphological characteristics similar to those of the control group. LLLT and resistance exercise restored muscle strength and morphological aspects of the ankle joint in rats with experimentally induced RA.","kw":"ankle injuries comparative exercise histology laser therapy muscle strength Humans Rats Male Animals Rats, Wistar Low-Level Light Therapy"},{"pmid":"36301306","title_fr":"PBM et étirements dans les courbatures","type":"rct","level":2,"pop":"adulte","ctx":["récupération"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"neutre","theme":"Récupération & courbatures","l1":"Chez des sujets non entraînés, la PBM et les étirements ne soulagent pas les courbatures.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Effects of Photobiomodulation and Low-Intensity Stretching on Delayed-Onset Muscle Soreness: A Randomized Control Trial.","journal":"Photobiomodulation, photomedicine, and laser surgery","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Ma F","Li Y","Chen Q","et al."],"date":"2022-10-26","year":2022,"week":"2022-S43","doi":"10.1089/photob.2022.0055","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":4,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Objective: This study aimed to investigate the effects of photobiomodulation (PBM), low-intensity stretching, and their combination on delayed-onset muscle soreness (DOMS) in the untrained population. The relationships between DOMS and muscle function and functional performance were also tested. Methods: Fifty-four participants were randomized into four groups. Eccentric exercise was used to induce DOMS. Each group received either no treatment, PBM, stretching or PBM combined with stretching at 24, 48, and 72 h postexercise. Pressure pain threshold (PPT), numerical rating scale (NRS), single-leg forward jump (SLFJ), and maximum isometric voluntary contraction (MIVC) were measured at baseline, 24, 48, 72, and 96 h after eccentric exercise. Between-group differences were tested using two-way repeated measures analysis of variance and the relationships between DOMS and MIVC, and SLFJ were examined using Pearson's correlation analysis. Results: The PPT at the vastus medialis and vastus lateral in the PBM combined with stretching group was significantly lower than that in control group at 72 h (p = 0.045) and 48 h (p = 0.037) postexercise. No significant between-group difference in PPT was found for the rest occasions. There was no significant between-group difference in NRS, MVIC, and SLFJ on any occasion (p ≥ 0.052). DOMS was not correlated with MIVC and SLFJ (p ≥ 0.09). Conclusions: PBM or low-intensity stretching did not affect DOMS and functional performance in untrained individuals. The combination of PBM and low-intensity stretching increased pain sensitivity and did not relieve soreness. The DOMS was not associated with either muscle function or functional performance."}],"keywords":["delayed-onset muscle soreness","maximum isometric voluntary contraction","photobiomodulation","pressure pain threshold","stretching"]},{"pmid":"36294470","title":"TECAR Therapy Associated with High-Intensity Laser Therapy (Hilt) and Manual Therapy in the Treatment of Muscle Disorders: A Literature Review on the Theorised Effects Supporting Their Use.","journal_abbr":"J Clin Med","authors":["Szabo DA","Neagu N","Teodorescu S","et al."],"date":"2022-10-19","year":2022,"doi":"10.3390/jcm11206149","pmcid":"PMC9604865","license":"cc by","oa":true,"cited_by":25,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"TECAR therapy, combined with manual therapy and High-Intensity Laser therapy in treating muscle diseases, presented optimal collaboration in the recovery process of all muscle diseases.","kw":"TECAR therapy high-intensity laser therapy manual therapy muscle disorders"},{"pmid":"36187084","title":"Research protocol to evaluate the effectiveness of shockwave therapy, photobiomodulation and physical therapy in the management of non-insertional Achilles tendinopathy in runners: a randomised control trial with elective cross-over design.","journal_abbr":"BMJ Open Sport Exerc Med","authors":["Tenforde AS","Vogel KEL","Tam J","et al."],"date":"2022-09-27","year":2022,"doi":"10.1136/bmjsem-2022-001397","pmcid":"PMC9516084","license":"cc by-nc","oa":true,"cited_by":4,"curated":false,"type":"autre","level":0,"ctx":["blessures"],"l1":"The elective cross-over phase will be an exploratory study and will inform us whether patient preference for treatment will impact the treatment response. NCT04725513.","kw":"Achilles exercises shockwave"},{"pmid":"36157830","title":"Effects of intravascular photobiomodulation on motor deficits and brain perfusion images in intractable myasthenia gravis: A case report.","journal_abbr":"World J Clin Cases","authors":["Lan CH","Wu YC","Chiang CC","et al."],"date":"2022-09-26","year":2022,"doi":"10.12998/wjcc.v10.i24.8718","pmcid":"PMC9453358","license":"cc by-nc","oa":true,"cited_by":3,"pub_types":["Case Reports"],"curated":false,"type":"cases","level":4,"ctx":[],"l1":"ILIB might have beneficial effects on MG, and brain SPECT images provided direct evidence of a positive correlation between ILIB and clinical performance.","kw":"Case report Intravascular laser irradiation of blood Myasthenia gravis Myasthenia gravisactivities of daily living scale Quantitative myasthenia gravis scale Si"},{"pmid":"36233361","title":"Effectiveness of High-Intensity Laser Therapy Plus Ultrasound-Guided Peritendinous Hyaluronic Acid Compared to Therapeutic Exercise for Patients with Lateral Elbow Tendinopathy.","journal_abbr":"J Clin Med","authors":["Pellegrino R","Paolucci T","Brindisino F","et al."],"date":"2022-09-20","year":2022,"doi":"10.3390/jcm11195492","pmcid":"PMC9572841","license":"cc by","oa":true,"cited_by":18,"curated":false,"type":"autre","level":0,"ctx":["performance","blessures","populations"],"l1":"No serious adverse events occurred. Our findings suggest that Hy-A associated with HILT might be more effective than TE for people with LET in the short−medium term.","kw":"Patient-Rated Tennis Elbow Evaluation disability high-intensity laser therapy hyaluronic acid lateral elbow tendinopathy muscle strength"},{"pmid":"36139746","title":"Can Photobiomodulation Therapy (PBMT) Minimize Exercise-Induced Oxidative Stress? A Systematic Review and Meta-Analysis.","journal_abbr":"Antioxidants (Basel)","authors":["De Marchi T","Ferlito JV","Ferlito MV","et al."],"date":"2022-08-27","year":2022,"doi":"10.3390/antiox11091671","pmcid":"PMC9495825","license":"cc by","oa":true,"cited_by":25,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"Low to moderate certainty evidence shows that PBMT is a resource that can reduce oxidative damage and increase enzymatic antioxidant activity post exercise. We found evidence to support that one session of PBMT can modulate the redox…","kw":"exercise laser therapy oxidative damage phototherapy reactive species"},{"pmid":"36110255","title":"Recovery in water polo: how much do we have to know? A systematic review.","journal_abbr":"J Exerc Rehabil","authors":["Barrenetxea-Garcia J","Murua-Ruiz A","Mielgo-Ayuso J","et al."],"date":"2022-08-26","year":2022,"doi":"10.12965/jer.2244306.153","pmcid":"PMC9449089","license":"cc by-nc","oa":true,"cited_by":10,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["performance","récupération"],"l1":"The results show that supplementation with cherry juice before training does not imply improvements in recovery; the full-body photobiomodulation therapy reduces muscle damage; reducing training load during the season increased the…","kw":"Performance Recovery Systematic review Water polo"},{"pmid":"36051417","title":"Chronic Supraspinatus Tendonitis Pain: An Integrative Approach for Treatment with Cross-Fiber Massage, Electroacupuncture, Far-Infrared Heat, and Photobiomodulation.","journal_abbr":"Med Acupunct","authors":["Liu S"],"date":"2022-08-17","year":2022,"doi":"10.1089/acu.2022.0041","pmcid":"PMC9419923","cited_by":2,"curated":false,"type":"autre","level":0,"ctx":["blessures"],"l1":"More clinical and research studies are recommended to validate this approach for this condition and other soft-tissue traumata.","kw":"Ashi acupuncture Traditional Chinese Medicine chronic soft-tissue injury chronic sports injury cross-fiber massage microcurrent electroacupuncture"},{"pmid":"36006085","title":"Full-Body Photobiomodulation Therapy Is Associated with Reduced Sleep Durations and Augmented Cardiorespiratory Indicators of Recovery.","journal_abbr":"Sports (Basel)","authors":["Rentz LE","Bryner RW","Ramadan J","et al."],"date":"2022-07-31","year":2022,"doi":"10.3390/sports10080119","pmcid":"PMC9414854","license":"cc by","oa":true,"cited_by":6,"curated":false,"type":"autre","level":0,"ctx":["récupération"],"l1":"Sleep durations were still lower following PBMT, even when controlling for daily and accumulated training loads. Enhanced cardiorespiratory indicators of recovery following PBMT, despite significant reductions in sleep duration, suggest…","kw":"athlete monitoring exercise training red light therapy soccer wearable device"},{"pmid":"35910832","title_fr":"PBM avec champ magnétique statique chez l'athlète de CrossFit","type":"rct","level":2,"pop":"adulte","ctx":["récupération"],"aim":"les deux","mode":["laser","LED"],"nm":[],"n":null,"effect":"favorable","theme":"Récupération & courbatures","l1":"Avant ou après la séance, la PBM avec champ magnétique améliore la performance et accélère la récupération chez l'athlète de CrossFit.","l2":"Triple aveugle, croisé.","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Photobiomodulation Therapy Combined with a Static Magnetic Field Applied in Different Moments Enhances Performance and Accelerates Muscle Recovery in CrossFit® Athletes: A Randomized, Triple-Blind, Placebo-Controlled Crossover Trial.","journal":"Oxidative medicine and cellular longevity","journal_abbr":"Oxid Med Cell Longev","authors":["Pinto HD","Casalechi HL","de Marchi T","et al."],"date":"2022-07-19","year":2022,"week":"2022-S29","doi":"10.1155/2022/9968428","pmcid":"PMC9325605","license":"cc by","oa":true,"pdf":"pdfs/35910832.pdf","cited_by":12,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"The ergogenic effects of photobiomodulation therapy combined with a static magnetic field (PBMT-sMF) on exercises with characteristics similar to those of CrossFit® are unknown. This study was aimed at investigating the effects of PBMT-sMF applied at different times on recovery and physical performance in CrossFit® athletes by analyzing functional aspects, muscle damage, inflammatory processes, and oxidative stress. This was a prospectively registered, triple-blinded, placebo-controlled, crossover trial. CrossFit® athletes were recruited and assigned to receive one of the four possible interventions. Each intervention included protocols before and after the exercise (referred to as the workout of the day (WOD)). The four possibilities of intervention were as follows: placebo before and after WOD (placebo), PBMT-sMF before and placebo after WOD (PBMT-sMF before), placebo before and PBMT-sMF after WOD (PBMT-sMF after), and PBMT-sMF before and after WOD (PBMT-sMF before and after). The order of possibilities for the interventions was randomized. The primary outcome was the functional test performance. The secondary outcomes were the subjective perception of exertion, muscle damage, inflammation, and oxidative stress. The outcomes were measured before the WOD; immediately after the intervention; and 1, 24, and 48 hours after the WOD. Statistical analysis was performed using repeated measures ANOVA followed by the Bonferroni post hoc test to examine the differences between the interventions at each time point. Twelve participants were randomized and analyzed for each sequence. PBMT-sMF enhanced the performance on functional tests (calculated as a percentage of change) when applied before or after WOD in the assessment performed immediately post-WOD and at 24 and 48 hours later (p < 0.05) compared to placebo and PBMT-sMF before and after WOD. In terms of the secondary outcomes, PBMT-sMF applied before or after WOD significantly decreased the creatine kinase, catalase, and superoxide dismutase activities and interleukin-6, thiobarbituric acid, and carbonylated protein levels (all p < 0.05) compared to the other possibilities of intervention. In addition, PBMT-sMF applied before and after WOD decreased creatine kinase activity at 24 hours and IL-6 levels at 24 and 48 hours compared to placebo (p < 0.05). None of the participants reported any adverse events. PBMT-sMF enhanced the performance of functional tests, decreased the levels of biochemical markers of muscle damage and inflammation, decreased oxidative stress, and increased antioxidant activity in CrossFit® athletes when applied before or after WOD."}],"keywords":[]},{"pmid":"35802348","title_fr":"Effets ergogéniques de la PBM selon le type d'exercice : méta-analyse","type":"ma","level":1,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser","LED"],"nm":[],"n":null,"effect":"mitigé","theme":"Performance musculaire","l1":"La PBM améliore l'endurance musculaire mono-articulaire et le temps jusqu'à épuisement en cyclisme, mais pas la force, la course ni la natation.","l2":"Sports Medicine 2022.","l3":{"points":["Effets selon le type d'effort."],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Deconstructing the Ergogenic Effects of Photobiomodulation: A Systematic Review and Meta-analysis of its Efficacy in Improving Mode-Specific Exercise Performance in Humans.","journal":"Sports medicine (Auckland, N.Z.)","journal_abbr":"Sports Med","authors":["Dutra YM","Malta ES","Elias AS","et al."],"date":"2022-07-08","year":2022,"week":"2022-S27","doi":"10.1007/s40279-022-01714-y","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":20,"pub_types":["Meta-Analysis","Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"BACKGROUND","text":"Photobiomodulation therapy (PBMT) is defined as non-thermal electromagnetic irradiation through laser or light-emitting diode sources. In recent decades, PBMT has attracted attention as a potential preconditioning method. The current meta-analysis was conducted to assess the effectiveness of PBMT in improving mode-specific exercise performance in healthy young adults."},{"label":"METHODS","text":"A computerized literature search was conducted, ending on 15 May 2022. The databases searched were PubMed, Cochrane Central Register of Controlled Trials, Embase, SPORTDiscus, and the Physiotherapy Evidence Database. Inclusion/exclusion criteria limited articles to crossover, double-blind, placebo-controlled studies investigating the PBMT effects as a preconditioning method. The included trials were synthesized according to exercise mode (single-joint, cycling, running, and swimming). All results were combined using the standardized mean differences (SMDs) method and the 95% confidence intervals (CIs) were described."},{"label":"RESULTS","text":"A total of 37 individual studies, employing 78 exercise performance measurements in 586 participants, were included in the analyses. In single-joint exercises, PBMT improved muscle endurance performance (SMD 0.27, 95% CI 0.12-0.41; p < 0.01) but not muscle strength performance (p = 0.92). In cycling, PBMT improved time to exhaustion performance (SMD 0.35, 95% CI 0.10-0.59; p < 0.01) but had no effect on all-out sprint performance (p = 0.96). Similarly, PBMT had no effect on time to exhaustion (p = 0.10), time-trial (p = 0.61), or repeated-sprint (p = 0.37) performance in running and no effect on time-trial performance in swimming (p = 0.81)."},{"label":"CONCLUSION","text":"PBMT improves muscle endurance performance in single-joint exercises and time to exhaustion performance in cycling but is not effective for muscle strength performance in single-joint exercises, running, or swimming performance metrics."}],"keywords":[]},{"pmid":"35757272","title":"Application of Low-Intensity Laser in the Treatment of Skeletal Muscle Injury in Runners.","journal_abbr":"Emerg Med Int","authors":["Chen Y","Li Q"],"date":"2022-06-17","year":2022,"doi":"10.1155/2022/1211602","pmcid":"PMC9232341","license":"cc by","oa":true,"cited_by":2,"pub_types":["Retracted Publication"],"curated":false,"type":"autre","level":0,"ctx":["blessures"],"l1":"The experimental results showed that a low-intensity laser can effectively alleviate muscle inflammation, reduce the number of cell damage, bring the mean and integral optical density of protein to the normal level significantly, and…","kw":""},{"pmid":"35648258","title":"Analysis of pain relief and functional recovery in patients with rotator cuff tendinopathy through therapeutic ultrasound and photobiomodulation therapy: a comparative study.","journal_abbr":"Lasers Med Sci","authors":["Martins JPS","de Lima CJ","Fernandes AB","et al."],"date":"2022-06-01","year":2022,"doi":"10.1007/s10103-022-03584-2","cited_by":7,"curated":false,"type":"autre","level":0,"ctx":["performance","récupération","blessures","populations"],"nm":[640,850],"em":["pulse"],"l1":"In conclusion, improvements in quality of life, pain intensity relief, shoulder amplitude motion, and muscle strength force obtained with ultrasound therapy are enhanced by adding infrared LED irradiation to ultrasound for patients…","kw":"LED photomodulation Pain and quality of life Rotator cuff tendinopathy Shoulder motion amplitude and strength force Therapeutic ultrasound Humans Low-Level Ligh"},{"pmid":"35693867","title":"The Influence of Phototherapy on Recovery From Exercise-Induced Muscle Damage.","journal_abbr":"Int J Sports Phys Ther","authors":["D'Amico A","Silva K","Rubero A","et al."],"date":"2022-06-01","year":2022,"doi":"10.26603/001c.34422","pmcid":"PMC9159724","license":"cc by-nc","oa":true,"cited_by":3,"curated":false,"type":"autre","level":0,"ctx":["récupération"],"l1":"Phototherapy may not be a useful recovery tool for those participating in explosive, short-duration activities.","kw":"exercise recovery low-level laser therapy muscular soreness photobiomodulation"},{"pmid":"35441320","title":"Effects of moderate aerobic exercise, low-level laser therapy, or their combination on muscles pathology, oxidative stress and irisin levels in the mdx mouse model of Duchenne muscular dystrophy.","journal_abbr":"Lasers Med Sci","authors":["Arıkan S","Alaca N","Özbeyli D","et al."],"date":"2022-04-19","year":2022,"doi":"10.1007/s10103-022-03562-8","cited_by":11,"curated":false,"type":"preclinical","level":5,"ctx":["populations"],"pre":"vivo","l1":"When LLLT was applied in addition to exercise, muscle strength, skeletal muscle utrophin levels increased, and skeletal and diaphragmatic muscle degeneration and inflammation decreased. In addition, it was determined that only LLLT…","kw":"Duchenne Exercise Heart Irisin Low-level laser therapy Mdx mice Animals Disease Models, Animal Fibronectins Inflammation Low-Level Light Therapy Mice"},{"pmid":"35235082","title":"Effects of light-emitting diode therapy on cardiovascular and salivary nitrite responses in postmenopausal women submitted to a single bout of high-intensity interval training.","journal_abbr":"Lasers Med Sci","authors":["de Freitas VH","Mariano IM","Amaral AL","et al."],"date":"2022-03-02","year":2022,"doi":"10.1007/s10103-022-03533-z","cited_by":2,"curated":false,"type":"autre","level":0,"ctx":[],"l1":"HRV was impaired post- compared to pre-exercise (p < 0.05). LEDT did not improve physiological performance during HIIT and did not accelerate the recovery of BP and autonomic modulation or change the NO release after exercise in…","kw":"Aerobic Exercise Autonomic Function Double product Heart Rate Menopause Female Heart Rate High-Intensity Interval Training Humans Nitrites Oxygen Consumption"},{"pmid":"35242050","title":"The Functions and Mechanisms of Low-Level Laser Therapy in Tendon Repair (Review).","journal_abbr":"Front Physiol","authors":["Lyu K","Liu X","Jiang L","et al."],"date":"2022-02-15","year":2022,"doi":"10.3389/fphys.2022.808374","pmcid":"PMC8886125","license":"cc by","oa":true,"cited_by":26,"curated":false,"type":"autre","level":0,"ctx":["blessures"],"l1":"However, it should also be noted that in the final phase of tendon repair, the use of LLLT causes excessive upregulation of some growth factors, which will lead to tendon fibrosis. In summary, we need to further investigate the functions…","kw":"function low-level laser therapy mechanism tendinopathy tendon repair"},{"pmid":"35151026","title_fr":"PBM pendant un programme d'entraînement chez des sujets entraînés : essai contre placebo","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser","LED"],"nm":[],"n":null,"effect":"neutre","theme":"Performance musculaire","l1":"Chez des sujets déjà entraînés, ajouter la PBM (30 J par site) à 6 semaines d'entraînement n'apporte aucun bénéfice supplémentaire.","l2":"Essai randomisé contre placebo (Braz J Phys Ther).","l3":{"points":["Essai rigoureux négatif."],"limites":["Une dose."],"pratique":"Pas d'intérêt en entraînement chronique."},"em":[],"pre":"","topic":"sport","title":"Photobiomodulation therapy applied during an exercise-training program does not promote additional effects in trained individuals: A randomized placebo-controlled trial.","journal":"Brazilian journal of physical therapy","journal_abbr":"Braz J Phys Ther","authors":["Machado AF","Leal-Junior ECP","Batista NP","et al."],"date":"2022-01-02","year":2022,"week":"2021-S52","doi":"10.1016/j.bjpt.2021.100388","pmcid":"PMC8843995","license":null,"oa":false,"pdf":null,"cited_by":5,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"BACKGROUND","text":"Previous studies have shown positive results of photobiomodulation (PBM) for improving performance and accelerating post-exercise recovery. However, the effects of PBM in healthy individuals who underwent a neuromuscular adaptation training remain unclear."},{"label":"OBJECTIVE","text":"To investigate the effects of PBM during a training program combining sprints and explosive squats exercises on clinical, functional, and systemic outcomes in trained healthy individuals compared to a placebo intervention and a control."},{"label":"METHODS","text":"We conducted a randomized placebo-controlled trial. Healthy males were randomly assigned to three groups: active PBM (30 J per site), placebo, or control (passive recovery). The participants performed a six-week (12 sessions) of a training program consisting of a combination of sprints and squats with recovery applied between sprints and squats. To prevent the influence of the primary neuromuscular adaptation to exercise on the results, all participants had to participate in a period of six weeks of exercise training program. Functional, clinical, and psychological outcomes and vascular endothelial growth factor (VEGF) were assessed at baseline and after six weeks. Results are expressed as mean difference (MD) and 95% confidence intervals (CI)."},{"label":"RESULTS","text":"Thirty-nine healthy male volunteers (aged 18-30 years; body mass index 23.9 ± 3 kg/m²) were recruited. There was no significant time by group interaction, and no significant effect of group, but there was a significant effect of time for maximal voluntary isometric contraction (primary outcome) (MD=22 Nm/kg; 95%CI: 3.9, 40) and for squat jump (MD=1.6 cm; 95CI%: 0.7, 2.5). There was no significant interaction (time*group), time, or group effect for the other outcomes."},{"label":"CONCLUSION","text":"The addition of PBM to a combined training performed for six weeks in previously trained individuals did not result in additional benefits compared to placebo or no additional intervention."}],"keywords":["Athletic performance","Phototherapy","Recovery of function"]},{"pmid":"34876217","title":"Low-level laser prevents doxorubicin-induced skeletal muscle atrophy by modulating AMPK/SIRT1/PCG-1α-mediated mitochondrial function, apoptosis and up-regulation of pro-inflammatory responses.","journal_abbr":"Cell Biosci","authors":["Ou HC","Chu PM","Huang YT","et al."],"date":"2021-12-07","year":2021,"doi":"10.1186/s13578-021-00719-w","pmcid":"PMC8650328","license":"cc by","oa":true,"cited_by":28,"curated":false,"type":"autre","level":0,"ctx":[],"l1":"Our findings may provide a novel adjuvant intervention that can potentially benefit cancer patients from Dox-induced muscle wasting.","kw":"AMPK Doxorubicin Low-level laser Myopathy ROS"},{"pmid":"34947870","title":"Photobiomodulation and Sports: Results of a Narrative Review.","journal_abbr":"Life (Basel)","authors":["Ailioaie LM","Litscher G"],"date":"2021-12-03","year":2021,"doi":"10.3390/life11121339","pmcid":"PMC8706093","license":"cc by","oa":true,"cited_by":17,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["performance","récupération"],"l1":"There is an urgent need to continuously improve PBM devices, delivery methods, and protocols in new ingenious future sports trials. Latest innovations and nanotechnologies applied to perform intracellular signaling analysis, while…","kw":"fatigue light emitting diodes low-level laser therapy muscle damage performance photobiomodulation"},{"pmid":"34751510","title":"Low-level light pre-conditioning promotes C2C12 myoblast differentiation under hypoxic conditions.","journal_abbr":"J Biophotonics","authors":["Yan M","Wu MX"],"date":"2021-11-09","year":2021,"doi":"10.1002/jbio.202100246","cited_by":8,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"autre","level":0,"ctx":[],"nm":[980],"l1":"Moreover, LLL pre-treatment appeared to enhance glucose uptake, prevent energy metabolic switch from oxidative phosphorylation to glycolysis, and diminish lactate production under hypoxic conditions. The observation provides valuable…","kw":"hypoxia low-level light mitochondria myoblast differentiation photobiomodulation Cell Differentiation Humans Hypoxia Low-Level Light Therapy Muscle Fibers, Skel"},{"pmid":"34669081","title_fr":"Cryothérapie contre PBM pour la récupération musculaire : méta-analyse","type":"ma","level":1,"pop":"adulte","ctx":["récupération"],"aim":"traitement","mode":["laser","LED"],"nm":[],"n":null,"effect":"favorable","theme":"Récupération & courbatures","l1":"Après un effort intense, la PBM apporte un effet cliniquement important sur la récupération et semble meilleure que la cryothérapie.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Comparison between cryotherapy and photobiomodulation in muscle recovery: a systematic review and meta-analysis.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Ferlito JV","Ferlito MV","Leal-Junior ECP","et al."],"date":"2021-10-20","year":2021,"week":"2021-S42","doi":"10.1007/s10103-021-03442-7","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":14,"pub_types":["Meta-Analysis","Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"","text":"The purpose of this study is to compare the effect of photobiomodulation therapy (PBMT) and cryotherapy (CRT) on muscle recovery outcomes. These searches were performed in PubMed, PEDro, CENTRAL, and VHL (which includes the Lilacs, Medline, and SciELO database) from inception to June 2021. We included randomized clinical trials involved healthy human volunteers (> 18 years) underwent an intervention of PBMT and CRT, when used in both isolated form post-exercise. Standardized mean differences (SMD) or mean difference (MD) with 95% confidence interval were calculated and pooled in a meta-analysis for synthesis. The risk of bias and quality of evidence were assessed through Cochrane risk-of-bias tool and GRADE system. Four articles (66 participants) with a high to low risk of bias were included. The certainty of evidence was classified as moderate to very low. PBMT was estimated to improve the muscle strength (SMD = 1.73, CI 95% 1.33 to 2.13, I2 = 27%, p < 0.00001), reduce delayed onset muscle soreness (MD: - 25.69%, CI 95% - 34.42 to - 16.97, I2 = 89%, p < 0.00001), and lower the concentration of biomarkers of muscle damage (SMD =  - 1.48, CI 95% - 1.93 to - 1.03, I2 = 76%, p < 0,00,001) when compared with CRT. There was no difference in oxidative stress and inflammatory levels. Based on our findings, the use of PBMT in muscle recovery after high-intensity exercise appears to be beneficial, provides a clinically important effect, and seems to be the best option when compared to CRT."}],"keywords":["Cold therapy","Exercise-induced muscle damage","Muscle performance","Muscle recovery","Phototherapy"]},{"pmid":"34858690","title":"Immediate effects of photobiomodulation therapy combined with a static magnetic field on the subsequent performance: a preliminary randomized crossover triple-blinded placebo-controlled trial.","journal_abbr":"Biomed Opt Express","authors":["Aleixo-Junior IO","Leal-Junior ECP","Casalechi HL","et al."],"date":"2021-10-15","year":2021,"doi":"10.1364/BOE.442075","pmcid":"PMC8606121","cited_by":3,"curated":false,"type":"autre","level":0,"ctx":["performance"],"l1":"Volunteers did not report adverse events. Our results suggest that PBMT-sMF is able to decrease skeletal muscle fatigue, accelerating post-exercise recovery and, consequently, increasing subsequent physical performance when applied…","kw":""},{"pmid":"34520536","title":"Response of Aerobic Capacity to Low-Level Laser Therapy in Burned Patients.","journal_abbr":"J Burn Care Res","authors":["Kamel NM","Toson RA","Elsayeh SM"],"date":"2021-09-14","year":2021,"doi":"10.1093/jbcr/irab173","cited_by":1,"curated":false,"type":"autre","level":0,"ctx":["récupération","populations"],"l1":"However, after comparison, the improvements in the study group were statistically significant than those in the control group with P < .01 and P < .05, respectively. Low-level laser therapy has a beneficial therapeutic impact on promoting…","kw":"Adult Burns Exercise Therapy Exercise Tolerance Fatigue Humans"},{"pmid":"34428975","title_fr":"Laser, performance musculaire et récupération chez l'athlète : méta-analyse","type":"ma","level":1,"pop":"adulte","ctx":["récupération"],"aim":"prévention","mode":["laser"],"nm":[],"n":null,"effect":"favorable","theme":"Récupération & courbatures","l1":"Le laser améliore la performance musculaire de l'athlète, même si son effet thérapeutique n'est pas encore établi avec certitude.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Effects of Low-Level Laser Therapy on Muscular Performance and Soreness Recovery in Athletes: A Meta-analysis of Randomized Controlled Trials.","journal":"Sports health","journal_abbr":"Sports Health","authors":["Luo WT","Lee CJ","Tam KW","et al."],"date":"2021-08-25","year":2021,"week":"2021-S34","doi":"10.1177/19417381211039766","pmcid":"PMC9460079","license":null,"oa":false,"pdf":null,"cited_by":11,"pub_types":["Meta-Analysis","Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"CONTEXT","text":"Athletes must maintain their peak state of strength. Previous studies have investigated the effect of low-level laser therapy (LLLT) on muscular performance. A previous systematic review and meta-analysis has investigated this issue in healthy participants but not in physically active athletes."},{"label":"OBJECTIVE","text":"To investigate whether LLLT can improve muscular performance and soreness recovery in athletes."},{"label":"DATA SOURCES","text":"PubMed, EMBASE, and Cochrane Library."},{"label":"STUDY SELECTION","text":"Published randomized controlled trials and crossover studies till December 2020."},{"label":"STUDY DESIGN","text":"Systematic review and meta-analysis."},{"label":"LEVEL OF EVIDENCE","text":"Level 3."},{"label":"DATA EXTRACTION","text":"Assessment of study quality was rated using the risk of bias assessment method for randomized trials (Cochrane Handbook for Systematic Reviews of Interventions)."},{"label":"RESULTS","text":"A total of 24 studies were included. LLLT application before exercise significantly improved lower-limb muscle strength in 24-hour, 48-hour, 96-hour, and 8-week follow-up groups. Furthermore, decreased soreness index, serum creatine kinase concentrations, interleukin-6, and thiobarbituric acid reactive substance concentrations and a trend toward the improvement of contract repetition number and VO2 kinetic outcomes were observed."},{"label":"CONCLUSION","text":"Although a definite therapeutic effect of LLLT is yet to be established, the current evidence supports that LLLT use improves muscular performance in physically active athletes. Additional trials with large sample sizes and robust design should be conducted before strong recommendations are made."}],"keywords":["athlete","low-level laser therapy","meta-analysis","muscular performance"]},{"pmid":"34391447","title":"The effect of low-level red and near-infrared photobiomodulation on pain and function in tendinopathy: a systematic review and meta-analysis of randomized control trials.","journal_abbr":"BMC Sports Sci Med Rehabil","authors":["Tripodi N","Feehan J","Husaric M","et al."],"date":"2021-08-14","year":2021,"doi":"10.1186/s13102-021-00306-z","pmcid":"PMC8364035","license":"cc by","oa":true,"cited_by":17,"curated":false,"type":"autre","level":0,"ctx":["blessures"],"l1":"There is very-low-to-moderate quality evidence demonstrating that PBM has utility as a standalone and/or adjunctive therapy for tendinopathy disorders.","kw":"Low-level laser therapy Meta-analysis Pain Photobiomodulation Systematic review Tendinopathy"},{"pmid":"34341968","title":"Benefits of Sebastiania hispida (Euphorbiaceae) extract and photobiomodulation therapy as potentially adjunctive strategies to be explored against snake envenoming.","journal_abbr":"Photochem Photobiol Sci","authors":["Dourado DM","Matias R","da Silva BAK","et al."],"date":"2021-08-02","year":2021,"doi":"10.1007/s43630-021-00081-3","cited_by":3,"curated":false,"type":"preclinical","level":5,"ctx":["récupération"],"nm":[904],"pre":"vivo","l1":"hispida richness in phenolic compounds and flavonoids, such as the light modulatory ability to triggering a multitude of cell signalings likely underlie the positive outcomes. Our findings suggest both treatments as potential auxiliary…","kw":"Complementary therapies Gallium-arsenide (GaAs) laser Photobiomodulation Skeletal muscle regeneration Snake envenomation Animals Plant Extracts Rats, Wistar Rat"},{"pmid":"34255219","title":"The influence of photobiomodulation on the temperature of the brachial biceps during muscle fatigue protocol.","journal_abbr":"Lasers Med Sci","authors":["Stamborowski SF","de Oliveira Spinelli BM","Lima FPS","et al."],"date":"2021-07-13","year":2021,"doi":"10.1007/s10103-021-03360-8","cited_by":6,"pub_types":["Clinical Trial"],"curated":false,"type":"nrct","level":3,"ctx":["récupération"],"l1":"In the temperature analysis, the control group exhibited the highest average temperature, with a significant difference only for the placebo. The results indicate that the control displayed the greatest physical degeneration and the PMB…","kw":"Dynamometer Low-level laser therapy Muscle fatigue Photobiomodulation Thermography Cross-Over Studies Electromyography Humans Isometric Contraction Muscle Fatig"},{"pmid":"34776149","title_fr":"Dose unique de PBM (laser + LED) et performance des membres inférieurs","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser","LED"],"nm":[],"n":60,"effect":"favorable","theme":"Performance musculaire","l1":"Chez 60 volontaires, une seule séance de PBM sur les extenseurs du genou et les fléchisseurs plantaires améliore la performance motrice.","l2":"L'effet dépend du muscle irradié.","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Using a single dose of photobiomodulation (laser + LED) to improve performance of lower limbs in functional test: Randomized clinical trial.","journal":"Journal of bodywork and movement therapies","journal_abbr":"J Bodyw Mov Ther","authors":["Carvalho AR","Caovilla AR","Ficagna A","et al."],"date":"2021-06-23","year":2021,"week":"2021-S25","doi":"10.1016/j.jbmt.2021.06.024","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":5,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"BACKGROUND","text":"Photobiomodulation (PBM) improves motor performance despite doubts whether it occurs immediately or late after a single dose. We evaluated the effect of a cluster PMB (laser + LED) single dose on muscle fatigue recovery in young sedentary adults, both immediately and in the short term (period between 24 and 48 h) after the fatiguing event."},{"label":"METHODS","text":"Randomized clinical trial with 60 volunteers randomized in 5 groups (n = 12 in each): control/(CG); placebo/(SG); PBM in knee extensor/(KE_G); plantar-flexor/(PF_G); knee extensor + plantar-flexor/(KE + FP_G). Before the intervention (pre) a fatiguing event (FE) was applied, which consisted in going up and down one step until exhaustion. Repetition number (RN) and time to exhaustion (TTE) were recorded. Then each group received its respective intervention and immediately after that, the FE was performed again (immediate post). In the period between 24 and 48 h after irradiation, a new FE was performed (late post). In addition to the comparative statistics, complementary metrics (if the mean difference [Diff] between the comparison pairs was higher or lower than minimum detectable change [MDC] and effect size [ES]) were calculated."},{"label":"RESULTS","text":"Through the integrated analysis of inferential statistics and complementary metrics, it was observed that although there was no time of evaluation effect, there was a group effect. PBM improved performance in KE + FP_G (p-value<0.05; Diff>MDC; ES = moderate) and PF_G (p-value>0.05; but Diff > MDC; ES = moderate) regarding CG for both RN and TTE."},{"label":"CONCLUSION","text":"A PBM single dose irradiation may improve motor performance and there is specificity of the irradiated muscle group, although it does not depend on the moment."}],"keywords":["Exercise tolerance","Low-level light therapies","Muscle fatigue"]},{"pmid":"34177615","title":"Photobiomodulation Therapy at 808 nm Does Not Improve Biceps Brachii Performance to Exhaustion and Delayed-Onset Muscle Soreness in Young Adult Women: A Randomized, Controlled, Crossover Trial.","journal_abbr":"Front Physiol","authors":["Azuma RHE","Merlo JK","Jacinto JL","et al."],"date":"2021-06-10","year":2021,"doi":"10.3389/fphys.2021.664582","pmcid":"PMC8222918","license":"cc by","oa":true,"cited_by":13,"curated":false,"type":"autre","level":0,"ctx":["performance","récupération"],"nm":[808],"l1":"Our results indicate that acute laser PBM at 808 nm does not improve biceps brachii performance to exhaustion, RPE, and DOMS in untrained women.","kw":"exercise fatigue low-level light therapy pain physical functional performance resistance training"},{"pmid":"33844675","title":"Acute Photobiomodulation by LED Does Not Alter Muscle Fatigue and Cycling Performance-Corrigendum.","journal_abbr":"Med Sci Sports Exerc","authors":[],"date":"2021-04-12","year":2021,"doi":"10.1249/MSS.0000000000002644","pub_types":["Published Erratum"],"curated":false,"type":"autre","level":0,"ctx":["performance","récupération"],"l1":"","kw":""},{"pmid":"33761459","title_fr":"PBM et vitesse critique en natation : essai croisé","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser","LED"],"nm":[],"n":15,"effect":"neutre","theme":"Performance musculaire","l1":"Chez des nageurs fédérés, la PBM avant l'effort ne modifie ni la vitesse critique ni les marqueurs de fatigue.","l2":"Essai croisé randomisé en double aveugle contre placebo, 15 nageurs.","l3":{"points":["Résultat négatif."],"limites":["Petit effectif."],"pratique":"Pas d'effet en natation."},"em":[],"pre":"","topic":"sport","title":"Effect of Photobiomodulation on Critical Swimming Velocity: A Randomized, Crossover, Double-Blind, and Placebo-Controlled Study.","journal":"International journal of sports physiology and performance","journal_abbr":"Int J Sports Physiol Perform","authors":["Teixeira CL","Mezzaroba PV","Machado FA"],"date":"2021-03-23","year":2021,"week":"2021-S12","doi":"10.1123/ijspp.2020-0264","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":3,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"PURPOSE","text":"To analyze the acute effect of photobiomodulation (PBM) on swimming critical velocity (CV)."},{"label":"METHODS","text":"A total of 15 male federated swimmers (20.9 [2.4] y old) participated in this study. Three sets of front crawl were performed at distances of 100, 200, and 400 m to determine the CV under 3 experimental conditions: PBM (420 J), placebo (PLA), and control (C) in this randomized, crossover, double-blind, and placebo-controlled study. One-way analysis of variance for repeated measurements was used for statistical analyses."},{"label":"RESULTS","text":"The results showed that the prior application of PBM did not have ergogenic effects on CV and front crawl swimming performance: CV (PBM = 1.15 [0.15]; PLA = 1.20 [0.25]; C = 1.15 [0.14] m·s-1), swim time (ST) 100 m (PBM = 65.5 [6.3]; PLA = 65.2 [5.6]; C = 66.0 [5.9] s), ST 200 m (PBM = 148.5 [17.9]; PLA = 149.4 [16.4]; C = 150.1 [17.9] s), and ST 400 m (PBM = 327.7 [38.2]; PLA = 321.6 [47.7]; C = 329.5 [41.2] s)."},{"label":"CONCLUSIONS","text":"A PBM application prior to front crawl swimming test did not significantly modify the CV, ST, physiological factors of metabolic fatigue, perceptual, and front crawl stroke efficiency parameters in competition swimmers covering distances of 100, 200, and 400 m."}],"keywords":["athletic performance","endurance test","ergogenic","front crawl","low-level light therapy"]},{"pmid":"33622119","title":"Effects of photobiomodulation on sport performance in swimming para-athletes - a case series.","journal_abbr":"Res Sports Med","authors":["Garcez A","Nunez SC","Garcez AS","et al."],"date":"2021-02-23","year":2021,"doi":"10.1080/15438627.2021.1888101","curated":false,"type":"autre","level":0,"ctx":["performance"],"l1":"Also, the peak heartbeat was 10% lower after PBM. A muscular pre-conditioning using PBM with an infrared LED could modulate upper musculature and cardio-respiratory function, leading tobetter swimming performance in parathletes.","kw":"Lasertherapy cardio-respiratory function ledtherapy Athletes Cross-Over Studies Humans Muscle, Skeletal Para-Athletes Swimming"},{"pmid":"33558014","title":"Rehabilitation of the Canine Forelimb.","journal_abbr":"Vet Clin North Am Small Anim Pract","authors":["Brown JA","Tomlinson J"],"date":"2021-02-09","year":2021,"doi":"10.1016/j.cvsm.2020.12.005","cited_by":3,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["populations"],"l1":"Although there is a dearth of evidence-based veterinary medical studies in rehabilitation therapy and modalities for forelimb injuries in dogs, some extrapolation from human medicine can be made and applied. When developing a…","kw":"Extracorporal shockwave therapy Hydrotherapy Photobiomodulation (laser therapy) Therapeutic exercise Therapeutic ultrasound Tissue healing Animals Dog Diseases "},{"pmid":"33459175","title_fr":"PBM, performance et économie de course sur 3 000 m : essai en double aveugle","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser","LED"],"nm":[],"n":null,"effect":"favorable","theme":"Performance musculaire","l1":"Chez des coureurs, la PBM améliore la performance sur 3 000 m et l'économie de course à 24 h.","l2":"Essai randomisé en double aveugle contre placebo (J Sports Sci).","l3":{"points":["Endurance."],"limites":["Pas d'effet sur l'effort perçu."],"pratique":"Préconditionnement possible."},"em":[],"pre":"","topic":"sport","title":"Effect of photobiomodulation therapy on performance and running economy in runners: A randomized double-blinded placebo-controlled trial.","journal":"Journal of sports sciences","journal_abbr":"J Sports Sci","authors":["Lanferdini FJ","Silva ES","Boeno FP","et al."],"date":"2021-01-17","year":2021,"week":"2021-S02","doi":"10.1080/02640414.2021.1872930","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":8,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"The objective of this study was to evaluate effects of photobiomodulation therapy (PBMT) on the 3000 m running performance (primary outcome), running economy (RE), metabolic cost and ratings of perceived exertion during running (secondary outcomes). Twenty male endurance athletes performed 4-min treadmill rectangular test at 12 km.h-1 monitored by a gas analyser. After that, PBMT or placebo in each lower limb was applied, followed performed a maximum test of 3000 m. Immediately after 3000 m test, the athletes repeated the treadmill test. Another application of PBMT/placebo was done after the treadmill test, and athletes went back to the laboratory 24 h later to repeat the treadmill test. After a 72 h interval, athletes repeated all procedures with another treatment intervention (PBMT/placebo). Athletes performed the 3000 m running test ~7s faster when treated with PBMT with similar effort score compared placebo condition. The RE remains unchanged immediately post 3000 m running test, nonetheless RE measured post-24 h improved by 5% with PBMT application without changes in metabolic cost. The PBMT pre- and post-conditioning enhanced the 3000 m running performance and improved RE 24 h following the 3000 m test. However, no changes on ratings of perceived exertion and metabolic cost with the application of PBMT."}],"keywords":["Photobiomodulation therapy","distance running","metabolic economy","performance"]},{"pmid":"33519511","title":"Photobiomodulation 30 min or 6 h Prior to Cycling Does Not Alter Resting Blood Flow Velocity, Exercise-Induced Physiological Responses or Time to Exhaustion in Healthy Men.","journal_abbr":"Front Physiol","authors":["Dutra YM","Claus GM","Malta ES","et al."],"date":"2021-01-15","year":2021,"doi":"10.3389/fphys.2020.607302","pmcid":"PMC7844325","license":"cc by","oa":true,"cited_by":2,"curated":false,"type":"autre","level":0,"ctx":["performance"],"l1":"PBMT at 152 J applied 30 min or 6 h before cycling at severe-intensity did not alter resting plasma nitrite and blood flow velocity in the femoral artery, exercise-induced physiological responses, or time to exhaustion in healthy…","kw":"cardiorespiratory fitness ergogenic effects exercise tests low-level laser therapy regional blood flow"},{"pmid":"33332232","title_fr":"PBM corps entier et récupération chez le joueur de water-polo","type":"rct","level":2,"pop":"adulte","ctx":["récupération"],"aim":"traitement","mode":["LED"],"nm":[],"n":null,"effect":"neutre","theme":"Récupération & courbatures","l1":"La PBM corps entier n'améliore pas la récupération des joueurs de water-polo lors de matchs répétés.","l2":"Résultats préliminaires.","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Full Body Photobiomodulation Therapy to Induce Faster Muscle Recovery in Water Polo Athletes: Preliminary Results.","journal":"Photobiomodulation, photomedicine, and laser surgery","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Zagatto AM","Dutra YM","Lira FS","et al."],"date":"2020-12-17","year":2020,"week":"2020-S51","doi":"10.1089/photob.2020.4803","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":12,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Objective: To investigate the recovery of male water polo athletes applying full body photobiomodulation therapy (PBMT) regarding inflammation and muscle damage markers, testosterone and cortisol hormonal responses, heart rate variability (HRV), maximal voluntary contraction, and squat jump (SJ) after official water polo matches. Background: PBMT has been applied locally on specific muscle groups to induce faster recovery and improve the performance of athletes and nonathletes. However, many sports modalities require movement of the whole body, and a full body PBMT could be more adequate to irradiate large muscle areas homogeneously and faster. Methods: In a randomized, parallel, and double-blinded design, 13 athletes (whole team) aged 18 years attended the study and were allocated into two groups: PBMT (dose of 6.9 J/cm2, irradiance of 46.17 mW/cm2, 5 min irradiation) and placebo treatment. The study was conducted during the 2019 Brazilian under 20 water polo championship. All athletes were assessed by blood samples and neuromuscular evaluation. Immediately after each match, all athletes received PBMT (effective or placebo). Results: No significant interactions (raw values and percentage related to baseline) were observed for testosterone and cortisol, tumor necrosis factor-alpha, interleukin-6, creatine kinase concentration, maximal isometric voluntary contraction, SJ test, and HRV. Only an isolated interaction (decrease) was found for lactate dehydrogenase (LDH) response after the first match (p = 0.004, post-hoc p = 0.038). Conclusions: The parameters of the full body PBMT of this study did not induce faster recovery of inflammatory, muscle damage (excepting LDH), testosterone, cortisol, HRV, and neuromuscular responses during repeated days of water polo matches."}],"keywords":["cortisol","inflammation","light-emitting diode","low-level laser therapy","testosterone"]},{"pmid":"33332234","title_fr":"PBM rouge ou infrarouge et fatigue du biceps","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["LED"],"nm":[630,850],"n":null,"effect":"mitigé","theme":"Performance musculaire","l1":"L'infrarouge semble plus efficace que le rouge pour réduire la fatigue du biceps.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Acute Photobiomodulation Effects Through a Cluster Device on Skeletal Muscle Fatigue of Biceps Brachii in Young and Healthy Males: A Randomized Double-Blind Session.","journal":"Photobiomodulation, photomedicine, and laser surgery","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Vassão PG","Baldini GS","Vieira KVSG","et al."],"date":"2020-12-17","year":2020,"week":"2020-S51","doi":"10.1089/photob.2019.4786","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":2,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Objective: The aim of this study was to investigate and compare the acute effects of red and infrared photobiomodulation (PBM) using a cluster device on biceps brachii muscle fatigue in young and healthy males. Background: Vigorous physical activity could lead to muscle fatigue, which compromises motor control and muscle strength and consequently impairs performance. The positive effects of PBM in reducing fatigue onset have been highlighted. However, the better wavelength with cluster devices is not yet established. Methods: A randomized double-blind session was used. Thirty-two young and healthy males were randomized into the control group (CG), red PBM group (RPG), and infrared PBM group (IPG). A PBM cluster device [7 visible diodes (630 nm), 7 infrared diodes (850 nm), 100 mW/diode, 2 W/cm2 power density, 91 J/cm2 energy density, 4 J per point, 28 J total energy, and 40 sec] was applied after muscle fatigue. Muscle fatigue was analyzed by surface electromyography (EMG) recorded from the long head of biceps brachii, blood lactate concentration, and evaluation of the rate of perceived exertion (RPE) using the Borg Scale. The fatigue protocol consisted of a maximum voluntary isotonic contraction of elbow flexion-extension with 75% of one-repetition maximum until exhaustion. The Borg Scale was applied before and at the end of the experiment to measure the RPE. The electromyography fatigue index (EMGFI) was calculated by windows of median frequency from EMG data. Results: EMGFI, blood lactate concentration, and RPE showed no intergroup statistical difference, except the EMGFI delta value that showed a difference between IPG and CG, with a greater value in the CG. However, intragroup comparisons showed that EMGFI decreased in the CG and RPE and lactate concentration increased significantly in all groups. Conclusions: There was no difference between red and infrared PBM in reduction of biceps brachii fatigue. However, the EMGFI delta value was greater in the IPG compared with the CG, suggesting that infrared can be more effective in reducing biceps brachii fatigue."}],"keywords":["electromyography","lactate","muscle fatigue","photobiomodulation"]},{"pmid":"33332233","title":"Photobiomodulation Before Eccentric Fatigue Protocol in the Control of Pain and Muscle Damage Markers: A Double-Blind, Randomized Controlled Study.","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Palma H","Pinfildi CE","Lambertucci RH","et al."],"date":"2020-12-17","year":2020,"doi":"10.1089/photob.2020.4866","cited_by":1,"pub_types":["Clinical Trial Protocol"],"curated":false,"type":"protocol","level":0,"ctx":["récupération"],"l1":"Conclusions: The PBM applied before eccentric fatigue protocol showed no significant results on DOMS, although there was a positive effect to control muscle damage. Brazilian Registry of Clinical Trials (RBR-7qhddz).","kw":"muscle damage muscular fatigue photobiomodulation recovery Cross-Over Studies Fatigue Humans Low-Level Light Therapy Male Muscle, Skeletal"},{"pmid":"33273302","title_fr":"LED et récupération après exercice pliométrique","type":"rct","level":2,"pop":"adulte","ctx":["blessures"],"aim":"prévention","mode":["LED"],"nm":[630,940],"n":null,"effect":"favorable","theme":"Blessures sportives","l1":"La LED 630 ou 940 nm avant un exercice excentrique limite les lésions musculaires sans compromettre l'adaptation à l'exercice répété.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Phototherapy Improves Muscle Recovery and Does Not Impair Repeated Bout Effect in Plyometric Exercise.","journal":"Journal of strength and conditioning research","journal_abbr":"J Strength Cond Res","authors":["Padoin S","Zeffa AC","Molina Corrêa JC","et al."],"date":"2020-12-02","year":2020,"week":"2020-S49","doi":"10.1519/JSC.0000000000003895","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":5,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Padoin, S, Zeffa, AC, Molina Corrêa, JC, de Angelis, TR, Moreira, TB, Barazetti, LK, and de Paula Ramos, S. Phototherapy improves muscle recovery and does not impair repeated bout effect in plyometric exercise. J Strength Cond Res 36(12): 3301-3310, 2022-The effects of photobiomodulation with red (630 nm) and near-infrared (940 nm) light wavelengths were investigated on the inhibition of exercise-induced muscle damage (EIMD) and adaptation to the repeated bout effect (RBE). Twenty-eight healthy men were randomized to receive light-emitting diode therapy (LEDT) at 630 nm (4.6 J·cm -2 , 97 J energy), LEDT at 940 nm (4.6 J·cm -2 , 114 J), or placebo. After LEDT or placebo treatment, subjects performed 100 drop-jumps (5 sets of 20 repetitions). Creatine kinase, delayed-onset muscle soreness (DOMS), countermovement jump (CMJ), and squat jump (SJ) were assessed before, immediately after, and 24, 48, and 72 hours after the bout. After 14 days, the subjects were submitted to the same plyometric exercise, without LEDT, and were evaluated again. Creatine kinase levels increased significantly 72 hours after the first bout in the placebo group in relation to the LEDT 940-nm group ( P < 0.01). The LEDT 630-nm group showed a significant increase in SJ at 24 hours ( P < 0.05), whereas, at 48 hours, the LEDT 940 nm showed a significant increase compared with the placebo group ( P < 0.05). The 2-way analysis of variance revealed an effect for treatment in the SJ ( F = 7.12; P = 0.001). No differences were found between groups for DOMS and CMJ after the first bout. After the second bout of exercise, there was no effect of treatment. The results suggest that treatment with LEDT 630 nm and LEDT 940 nm before eccentric exercise attenuates EIMD without impairing RBE."}],"keywords":[]},{"pmid":"33269093","title":"A Potential Role for Photobiomodulation Therapy in Disease Treatment and Prevention in the Era of COVID-19.","journal_abbr":"Aging Dis","authors":["Liebert A","Bicknell B","Markman W","et al."],"date":"2020-12-01","year":2020,"doi":"10.14336/AD.2020.0901","pmcid":"PMC7673843","license":"cc by","oa":true,"cited_by":13,"curated":false,"type":"autre","level":0,"ctx":["populations"],"l1":"PBM therapy is worthy of consideration as a potential treatment for those most vulnerable to COVID-19, such as the elderly and those with comorbidities. The treatment may potentially be advantageous for those infected with the virus,…","kw":"COVID-19 immunomodulation microbiome mitochondrial dysfunction photobiomodulation"},{"pmid":"33232629","title_fr":"Effet dose de la PBM sur la performance en extension du genou","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser","LED"],"nm":[],"n":8,"effect":"favorable","theme":"Performance musculaire","l1":"Chez 8 hommes, la bonne dose de PBM permet le même travail avec moins de fatigue lors de séries d'extension du genou.","l2":"—","l3":{"points":["—"],"limites":["8 sujets."],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Dose-Response Effect of Photobiomodulation Therapy on Muscle Performance and Fatigue During a Multiple-Set Knee Extension Exercise: A Randomized, Crossover, Double-Blind Placebo-Controlled Trial.","journal":"Photobiomodulation, photomedicine, and laser surgery","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Rossato M","Dellagrana RA","Sakugawa RL","et al."],"date":"2020-11-24","year":2020,"week":"2020-S48","doi":"10.1089/photob.2020.4820","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":18,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Objective: The aim of this study was to identify the best energy dose of photobiomodulation therapy (PBMT) able to improve muscle performance and reduce fatigue during multiple-set knee extension exercise. Methods: Eighteen physically active men participated in this study. Each participant performed an isokinetic exercise protocol (5 sets of 10 knee extension repetitions, maximum contractions at 60°·s-1) in 6 sessions, 1 week apart. Control condition (no PBMT/placebo treatments) was applied at the first and sixth sessions. Placebo or PBMT with 135, 270, or 540 J/quadriceps was randomly applied from the second to fifth sessions. Placebo/PBMT treatments were always applied at two moments: 6 h before and immediately before exercise. The isometric and isokinetic concentric peak torques were assessed before and after the exercise protocol. Results: The knee extension exercise performance (total work performed during exercise) was not affected by PBMT (135, 270, and 540 J) compared with placebo treatment. However, all PBMT treatments (135, 270, and 540 J) led to lower percentage drop compared with placebo and control conditions on isometric peak torque (IPT), concentric peak torque (CPT), and concentric work (W). All PBMT doses led to possibly positive or likely positive effects on IPT, CPT, and W compared with placebo. Conclusions: Our findings demonstrate that PBMT with 135, 270, and 540 J applied at two moments (6 h before and immediately before exercise) was able to produce the same total work with lower fatigue, which may facilitate the performance of additional sets (i.e., higher training volume)."}],"keywords":["ergogenic effect","light-emitting diodes therapy","low-level laser therapy","strength training"]},{"pmid":"33227220","title_fr":"Moment d'application de la LED et performance musculaire chez le jeune homme","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["LED"],"nm":[],"n":null,"effect":"neutre","theme":"Performance musculaire","l1":"La LED n'augmente ni la performance musculaire ni la résistance à la fatigue chez le jeune homme, quel que soit le délai d'application.","l2":"—","l3":{"points":["Double aveugle."],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Time-Response of Photobiomodulation Therapy by Light-Emitting Diodes on Muscle Torque and Fatigue Resistance in Young Men: Randomized, Double-Blind, Crossover and Placebo-Controlled Study.","journal":"Photobiomodulation, photomedicine, and laser surgery","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Abreu JSS","Dos Santos GV","Fonsati L","et al."],"date":"2020-11-23","year":2020,"week":"2020-S48","doi":"10.1089/photob.2020.4813","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":6,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Background: Photobiomodulation therapy (PBMT) by lasers or light-emitting diodes (LEDs) has been used in the last two decades to increase muscle performance in humans. The main findings of PBMT on muscle performance are increment in torque and number of muscle contractions, and fatigue resistance in high-intensity exercises. Although there are suggested light energies to be followed, the literature has also pointed out to a possible time-response of PBMT to increase exercise performance and recovery in humans. Objective: To investigate the possible time-response of PBMT by LEDs to increase muscle performance in young men regarding peak torque (PT), rate of torque development (RTD), fatigue resistance, and subjective perception of effort in maximal voluntary isometric contractions (MVIC) of elbow flexion. Methods: This randomized, double-blind, placebo-controlled, crossover trial with two arms enrolled 34 healthy and physically active young men, but 30 (21.10 ± 2.25 years old) completed all procedures. All volunteers were allocated into two equal arms (groups): PBMT (60 J; 1152 mW; 52 sec; and 166.75 cm2) applied on biceps brachii by a flexible array of LEDs, and placebo treatment. Each arm (n = 15) investigated the time-response (5 min, 1 h, 3 h, and 6 h) of PBMT in a randomized, double-blind, and crossover manner on the PT, RTD, fatigue resistance, and subjective perception of effort. Results: There were no significant results (p > 0.05) for all comparisons within and between groups regarding PT, RTD, fatigue resistance, and subjective perception of effort in MVIC of the elbow flexion in all time-response tested (5 min, 1 h, 3 h, and 6 h) before or after fatigue test. Only RTD did not decay significantly after fatigue test at all time-responses for PBMT group. Conclusions: PBMT was not effective to increase muscle performance and decrease fatigue to demonstrate the possible time-response in humans."}],"keywords":["dose–response","fatigue","light-emitting diode","low-level laser therapy","torque"]},{"pmid":"33227224","title_fr":"PBM et performance au 1 500 m : réponse individuelle","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser","LED"],"nm":[670,850,880,950],"n":null,"effect":"neutre","theme":"Performance musculaire","l1":"La PBM n'améliore pas le temps au 1 500 m de coureurs amateurs ; les répondeurs ont une meilleure capacité aérobie.","l2":"Essai randomisé contre placebo.","l3":{"points":["Variabilité individuelle."],"limites":["Coureurs récréatifs."],"pratique":"Effet inconstant."},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Effect of Photobiomodulation Therapy in the 1500 m Run: An Analysis of Performance and Individual Responsiveness.","journal":"Photobiomodulation, photomedicine, and laser surgery","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Dellagrana RA","Rossato M","Orssatto LBR","et al."],"date":"2020-11-23","year":2020,"week":"2020-S48","doi":"10.1089/photob.2019.4785","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":10,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Objective: The aims of this study were to verify the effects of photobiomodulation therapy (PBMT) on time trial run performance over 1500 m, as well as on individual responsiveness of recreative runners. Materials and methods: Nineteen recreationally trained runners participated in a randomized, crossover, double-blind placebo-controlled trial. The study was divided in four sessions: (1) incremental maximal running test; (2) 1500 m run control (without placebo or PBMT); and (3, 4) PBMT or placebo before 1500 m run. PBMT or placebo was applied over 14 sites per lower limb immediately before time trial run using a mixed wavelength device (33 diodes: 5 LASERs of 850 nm, 12 LEDs of 670 nm, 8 LEDs of 880 nm, and 8 LEDs with 950 nm). PBMT delivered 30 J per site, with a total energy dose of 840 J. Physiological variables [maximal oxygen uptake (VO2MAX), velocity associated to VO2MAX (vVO2MAX), peak of velocity, and respiratory compensation point (RCP)] were assessed during incremental maximal test. During 1500 m races we accessed the following: time, heart rate, and lower limb rate perception exertion per lap, total time, and blood lactate concentration ([Lac]). Results: PBMT had no significant difference and likely trivial effect for performance in the total time trial run over 1500 m compared to placebo. In the responsiveness analyses, 10 participants positively responded to PBMT, whereas total time reduced for responders (-10.6 sec; -3.18%) and increased for nonresponders (+6.0 sec; +1.73%). Responders presented higher aerobic parameters (VO2MAX and RCP) than nonresponders. Moreover, responders had lower time per lap and [Lac] (1 and 3 min) when PBMT was applied. Conclusions: PBMT applied immediately before running in noncontrolled environment was not able to improve the 1500 m performance of recreationally trained runners. However, responders to PBMT presented higher aerobic capacity than nonresponders."}],"keywords":["athletics","ergogenic aid","light-emitting diode therapy","low-level laser therapy","running performance"]},{"pmid":"33216681","title":"Use of Photobiomodulation Therapy in Exercise Performance Enhancement and Postexercise Recovery: True or Myth?","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Ferraresi C"],"date":"2020-11-18","year":2020,"doi":"10.1089/photob.2020.4948","cited_by":8,"pub_types":["Editorial"],"curated":false,"type":"letter","level":0,"ctx":["performance","récupération"],"l1":"","kw":"Exercise Low-Level Light Therapy Recovery of Function"},{"pmid":"33313457","title":"The effectiveness of low-level laser therapy combined with facial expression exercises in patients with moderate-to-severe Bell's palsy: A study protocol for a randomised controlled trial.","journal_abbr":"Int J Surg Protoc","authors":["Kandakurti PK","Shanmugam S","Basha SA","et al."],"date":"2020-11-14","year":2020,"doi":"10.1016/j.isjp.2020.11.001","pmcid":"PMC7720090","license":"cc by-nc-nd","oa":true,"cited_by":11,"curated":false,"type":"autre","level":0,"ctx":["populations"],"l1":"We plan to publish this review in a peer-reviewed journal. We may also present this review at local and/or national conferences.","kw":"Antiviral therapy Bell’s palsy Corticosteroids therapy Electrical muscle stimulation Facial exercises Facial paralysis"},{"pmid":"33092328","title":"Evidence-based post exercise recovery in combat sports: a narrative review.","journal_abbr":"J Sports Med Phys Fitness","authors":["LÓpez-Laval I","Mielgo-Ayuso J","Terrados N","et al."],"date":"2020-10-22","year":2020,"doi":"10.23736/S0022-4707.20.11341-0","cited_by":11,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["performance","récupération"],"l1":"To optimize CS performance, adequate recovery is required during training and competition processes. Traditional ergo nutritional supplementation of carbohydrates and proteins combined. Besides, the consumption of evidence supported…","kw":"Athletic Performance Dietary Supplements Humans Martial Arts Massage Rest"},{"pmid":"33088573","title":"What is the optimal time-response window for the use of photobiomodulation therapy combined with static magnetic field (PBMT-sMF) for the improvement of exercise performance and recovery, and for how long the effects last? A randomized, triple-blinded, placebo-controlled trial.","journal_abbr":"BMC Sports Sci Med Rehabil","authors":["Leal-Junior ECP","de Oliveira MFD","Joensen J","et al."],"date":"2020-10-19","year":2020,"doi":"10.1186/s13102-020-00214-8","pmcid":"PMC7574416","license":"cc by","oa":true,"cited_by":13,"curated":false,"type":"autre","level":0,"ctx":["performance","récupération"],"l1":"PBMT-sMF can be used from 5 min to 6 h before exercise, and the effects can last up to 54 h after treatment. However, the effects start to decrease when a 1-day (24 h) time-response window is used.","kw":"Light emitting diodes Low-level laser therapy Performance Phototherapy Post-exercise recovery"},{"pmid":"33020394","title_fr":"PBM et performance intermittente chez la joueuse de futsal","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser","LED"],"nm":[],"n":null,"effect":"neutre","theme":"Performance musculaire","l1":"La PBM n'améliore pas la performance aux efforts intenses et intermittents chez des joueuses de futsal amateurs.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Acute Photobiomodulation Does Not Influence Specific High-Intensity and Intermittent Performance in Female Futsal Players.","journal":"International journal of environmental research and public health","journal_abbr":"Int J Environ Res Public Health","authors":["Santos IAD","Lemos MP","Coelho VHM","et al."],"date":"2020-10-04","year":2020,"week":"2020-S40","doi":"10.3390/ijerph17197253","pmcid":"PMC7579062","license":"cc by","oa":true,"pdf":"pdfs/33020394.pdf","cited_by":10,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"","text":"The acute improvement of performance after photobiomodulation therapy (PBMT) has been reported in different types of exercise. However, the effect on high-intensity and intermittent exercises that are relevant for team sports is unknown. Thus, we evaluated the effect of prior acute application of PBMT on high-intensity and intermittent exercise performance, muscle oxygenation, and physiological/perceptual indicators in amateur female futsal players. Thirteen players (24.1 ± 3.7 years) performed a testing battery (countermovement jump (CMJ), Illinois agility and YoYo intermittent recovery test level 1 (YYIR1)) preceded by 15 min of PBMT (1 min 30 s each muscular point; five muscular points in each lower limbs) or 15 min of placebo (SHAM), in a counterbalanced randomized cross-over design (one-week in-between PBMT/SHAM). All test performance did not differ (p > 0.05) between PBMT and SHAM, as well as blood lactate, rating of perceived exertion, heart rate, and muscle oxygenation (via near infrared spectroscopy) responses. The acute application of PBMT prior to a physical testing battery does not influence high-intensity and intermittent exercises performance, neither physiological nor perceptual responses in amateur female futsal players."}],"keywords":["ergogenic aids","fatigue","gender","laser","soccer","team-sports"]},{"pmid":"32990506","title":"Photobiomodulation Therapy Modulates Muscle Gene Expression and Improves Performance of Rats Subjected to a Chronic Resistance Exercise Protocol.","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Macedo MM","Mafra FFP","Teixeira CB","et al."],"date":"2020-09-28","year":2020,"doi":"10.1089/photob.2019.4792","cited_by":3,"curated":false,"type":"preclinical","level":5,"ctx":["performance"],"nm":[904],"pre":"vivo","l1":"PBM promoted increased expression of lactate dehydrogenase enzyme, mammalian target of rapamycin protein, and androgen receptor (p < 0.05) but not the myosin heavy chain (p = 0.43). Conclusions: PBM therapy increases the expression of…","kw":"laser therapy performance photobiomodulation skeletal muscle Animals Gene Expression Humans Low-Level Light Therapy Male Muscle, Skeletal"},{"pmid":"33992253","title":"Effects of the infrared laser on classical ballerinas' feet: Analysis of plantar foot and static balance.","journal_abbr":"J Bodyw Mov Ther","authors":["Paolillo FR","Lobo da Costa PH","Mendes PVB","et al."],"date":"2020-09-28","year":2020,"doi":"10.1016/j.jbmt.2020.09.007","cited_by":3,"curated":false,"type":"autre","level":0,"ctx":["performance"],"nm":[808],"l1":"Then, there were pain relief and improvement of functional performance in ballerinas. The possible mechanism of laser action in reducing pain and thus enhancing performance, like higher blood flow of foot due to an increase of cutaneous…","kw":"Classical ballet training Pain Performance Photobiomodulation Thermography Adult Female Foot Humans Pain Pain Management"},{"pmid":"32925378","title":"Concussions in Ice Hockey - Moving Toward Objective Diagnoses and Point-of-care Treatment: A Review.","journal_abbr":"Curr Sports Med Rep","authors":["Pender SC","Smith AM","Finnoff JT","et al."],"date":"2020-09-14","year":2020,"doi":"10.1249/JSR.0000000000000752","cited_by":4,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["blessures"],"l1":"An estimated US $1.1 billion has been spent on unsuccessful traumatic brain injury clinical trials. As our ability to accurately diagnose concussion improves, dimethyl fumarate, memantine, thioredoxin-mimetic peptides, transcranial…","kw":"Animals Athletic Injuries Brain Concussion Hockey Humans Neuropsychological Tests"},{"pmid":"32903997","title":"The Effect on Muscle Hardness of Acupuncture Stimulation Using Low-reactive Level Laser Therapy and Silver Spike Point Therapy, along with Stretching.","journal_abbr":"Laser Ther","authors":["Sawada T","Tateyama N","Ikeda T","et al."],"date":"2020-09-09","year":2020,"doi":"10.5978/islsm.20-OR-04","pmcid":"PMC7447822","license":"cc by-nc","curated":false,"type":"autre","level":0,"ctx":[],"l1":"This is because an improved local blood flow due to SSP therapy is considered to have relaxed muscle tonus, which boosted metabolism and removed algogenic substances. This became more effective through a combined use of stretching and…","kw":"laser acupuncture low-reactive level laser therapy muscle hardness silver spike point therapy stretching"},{"pmid":"33013635","title":"Changes in Brain Function and Structure After Self-Administered Home Photobiomodulation Treatment in a Concussion Case.","journal_abbr":"Front Neurol","authors":["Chao LL","Barlow C","Karimpoor M","et al."],"date":"2020-09-08","year":2020,"doi":"10.3389/fneur.2020.00952","pmcid":"PMC7509409","license":"cc by","oa":true,"cited_by":39,"pub_types":["Case Reports"],"curated":false,"type":"cases","level":4,"ctx":["blessures"],"em":["pulse"],"l1":"After 8 weeks of PBM treatments, increased brain volumes, improved functional connectivity, and increased cerebral perfusion and improvements on neuropsychological test scores were observed. Although this is a single, sport-related case…","kw":"cognition home treatment neuroimaging photobiomodulation traumatic brain injury (TBI)"},{"pmid":"32862403","title_fr":"PBM aiguë et performance musculaire du diabétique","type":"rct","level":2,"pop":"adulte","ctx":["populations"],"aim":"—","mode":["LED"],"nm":[],"n":null,"effect":"neutre","theme":"Sujets âgés & malades chroniques","l1":"Appliquée sur une courte période, la PBM n'apporte pas de gain important de performance musculaire ni de fonction chez le diabétique.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Acute application of photobiomodulation does not bring important gains for the muscular performance and functionality of diabetic individuals.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Gobbi A","de Carvalho G","Sapalo AT","et al."],"date":"2020-08-29","year":2020,"week":"2020-S35","doi":"10.1007/s10103-020-03135-7","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":5,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Photobiomodulation therapy (PBMT) has been used to improve the physical performance of individuals with advanced age; however, there are no studies in the literature that support the application of light-emitting diode (LED) therapy for the muscular performance of individuals with diabetes mellitus who show a decline in functionality. The aim of the study was to analyze the acute effects of PBMT on strength and functional performance in type 2 diabetic individuals. Sixty-three volunteers were recruited and randomized into five groups: control (C), sham (S), red LED (R), infrared LED (IR), and red LED + infrared LED (R + IR). On the first day, the volunteers were evaluated using the time up and go (TUG), the 6-min walk test (6MWT), and isokinetic dynamometer of the ankle. In the following 3 days, groups R, IR, R + IR, and S returned for application of PBMT bilaterally, with 180 J of energy on each leg. On the fifth day, a reassessment was performed. There was no statistical difference between groups for the variables of the isokinetic dynamometer, TUG, and 6MWT. Analysis of the size of the clinical effect for the isokinetic variables showed that there was no pattern among the effects observed. There is a moderate effect in favor of R, IR, and R + IR in relation to C for the TUG and a moderate effect of R + IR in relation to C for the 6MWT. The PBMT applied for a short period does not bring important gains for the muscular performance and functionality of diabetic individuals."}],"keywords":["Diabetes mellitus","Muscle strength","Photobiomodulation","Physiotherapy"]},{"pmid":"32864144","title":"Does photobiomodulation therapy combined to static magnetic field (PBMT-sMF) promote ergogenic effects even when the exercised muscle group is not irradiated? A randomized, triple-blind, placebo-controlled trial.","journal_abbr":"BMC Sports Sci Med Rehabil","authors":["Machado CDSM","Casalechi HL","Vanin AA","et al."],"date":"2020-08-26","year":2020,"doi":"10.1186/s13102-020-00197-6","pmcid":"PMC7448464","license":"cc by","oa":true,"cited_by":4,"curated":false,"type":"autre","level":0,"ctx":["performance","récupération"],"l1":"Our results support the current evidence that local irradiation of all exercised muscles promotes ergogenic effects. PBMT-sMF improved performance and reduced muscle fatigue only when applied locally to muscles involved in physical…","kw":"Exercise performance Muscle performance Muscle recovery Photobiomodulation therapy Physiotherapy Rehabilitation"},{"pmid":"32796413","title_fr":"Effet ergogénique de la PBM au test de Wingate : essai croisé","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser","LED"],"nm":[630],"n":null,"effect":"favorable","theme":"Performance musculaire","l1":"La PBM améliore la performance au test anaérobie de Wingate de 30 secondes, probablement via le métabolisme anaérobie alactique.","l2":"Essai croisé randomisé en double aveugle contre placebo.","l3":{"points":["Effort anaérobie."],"limites":["Petit effectif."],"pratique":"Effet ergogénique."},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Ergogenic Effects of Photobiomodulation on Performance in the 30-Second Wingate Test: A Randomized, Double-Blind, Placebo-Controlled, Crossover Study.","journal":"Journal of strength and conditioning research","journal_abbr":"J Strength Cond Res","authors":["Molina Correa JC","Padoin S","Varoni PR","et al."],"date":"2020-08-12","year":2020,"week":"2020-S33","doi":"10.1519/JSC.0000000000003734","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":5,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Molina Correa, JC, Padoin, S, Varoni, PR, Demarchi, MC, Flores, LJ, Nampo, FK, and de Paula Ramos, S. Ergogenic effects of photobiomodulation on performance in the 30-second Wingate test: A randomized, double-blind, placebo-controlled, crossover study. J Strength Cond Res 36(7): 1901-1908, 2022-The purpose of this study was to evaluate the ergogenic effects of red light (630 nm) photobiomodulation on anaerobic capacity in the Wingate test. Sixteen healthy and physically active male volunteers (21.71 ± 2.49 years of age, body mass index between 18.5 and 24.9 kg/m2) participated in this randomized, double-blind, placebo-controlled, crossover study. The subjects performed 3 Wingate test sessions, with a 48-hour interval between tests. In the first session (baseline session, BS), a Wingate test was performed to evaluate the initial performance. Subjects were paired by performance in the BS and allocated through a draw to receive either the phototherapy (630 nm, 4.6 J/cm2, 6 J per point, 16 points, light-emitting diode [LED] session) or placebo intervention (PLA session) in the second test session. In the third test session, a crossover intervention was performed. The repeated-measures analysis of variance test, followed by Bonferroni post hoc test or Friedman test with Dunn's post hoc test (p < 0.05) and Cohen's d statistic were used for comparisons. The LED session with phototherapy promoted an increase in performance in peak power (p < 0.05), relative power (p < 0.05), RPMpeak (p < 0.05), and peak velocity (p < 0.05), as well as total displacement (p < 0.01) compared with PLA. The mean power (p < 0.05), relative power (p < 0.05), RPMmean (p < 0.01), and mean velocity (p < 0.01) were higher in the LED session than those of BS. We concluded that phototherapy improves performance in Wingate anaerobic exercise, possibly due to large effects on the anaerobic alactic metabolism."}],"keywords":[]},{"pmid":"32744919","title_fr":"PBM et restriction du flux sanguin des extenseurs du poignet","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"—","mode":["laser"],"nm":[660,830],"n":null,"effect":"favorable","theme":"Performance musculaire","l1":"L'association PBM 660 nm et entraînement avec restriction de flux augmente la force de préhension des extenseurs du poignet.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Effects of Photobiomodulation Therapy and Restriction of Wrist Extensor Blood Flow on Grip: Randomized Clinical Trial.","journal":"Photobiomodulation, photomedicine, and laser surgery","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Florianovicz VC","Ferraresi C","Kuriki HU","et al."],"date":"2020-07-28","year":2020,"week":"2020-S31","doi":"10.1089/photob.2019.4800","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":6,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Objective: To evaluate the influence of two different photobiomodulation therapy (PBMT) protocols (red 660 nm vs. infrared 830 nm) combined with a blood flow restriction (BFR) training protocol in wrist extensor muscles on handgrip, wrist extension force, and electromyographic behavior [root mean square (RMS)]. Background: PBMT has been widely used to increase muscle performance and recovery in recent clinical trials. However, there is no evidence whether PBMT (red and/or infrared) can promote better results when combined with BFR, a known method to induce better strength gains. Methods: This study was a randomized controlled trial including 58 volunteers allocated into four groups: (1) control (conventional strengthening), (2) BFR (strengthening with BFR), (3) 660 nm (BFR strengthening with 660 nm PBMT-35 mW; 0.05 cm2; 2.10 J, total energy 18.9 J), and (4) 830 nm (BFR strengthening with 830 nm PBMT-32 mW; 0.101 cm2; 1.92 J, total energy 17.2 J). Data were analyzed by using a mixed-effects model, with a 5% significance index. Results: A statistically significant increase was obtained for handgrip strength for the 660 nm group [27.36 ± 2.61 kilogram force (kgF)] compared with the 830 nm group (23.04 ± 3.06 kgF) (p = 0.010) and for wrist extensor strength in the 660 nm (7.77 ± 0.58 kgF) and BFR (7.54 ± 0.92 kgF) groups compared with the control group (5.33 ± 0.61 kgF) (p = 0.001 and p = 0.004, respectively). The RMS value for the 660 nm group was significantly higher than control (p < 0.0001), BFR (p < 0.0001), and the 830 nm group (p = 0.0009). Conclusions: The association of PBMT (660 nm) and BFR was effective for increasing handgrip strength of the wrist extensors, associated with an increase in RMS."}],"keywords":["RMS","blood flow restriction","electromyography","handgrip","low-level laser therapy"]},{"pmid":"32774545","title":"Does Photobiomodulation Therapy Enhance Maximal Muscle Strength and Muscle Recovery?","journal_abbr":"J Hum Kinet","authors":["Tsuk S","Lev YH","Fox O","et al."],"date":"2020-07-21","year":2020,"doi":"10.2478/hukin-2019-0138","pmcid":"PMC7386143","license":"cc by-nc-nd","oa":true,"cited_by":12,"curated":false,"type":"autre","level":0,"ctx":["performance","récupération"],"nm":[808],"l1":"In addition, there was no effect of photobiomodulation on muscle recovery as measured by the TW (F(1,27) = .16, p = .69) or PT (F(1,29) = .056, p = .814). Applying photobiomodulation for 10 min immediately before exercise did not improve…","kw":"acute exercise anaerobic power fatigue skeletal muscles"},{"pmid":"32598231","title":"Effect of 12 Weeks of Endurance Training Combined with Creatine Supplement, Photobiomodulation Therapy, or Both on Performance and Muscle Damage in Rats.","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Malta ES","Ferraresi C","Monte MG","et al."],"date":"2020-06-26","year":2020,"doi":"10.1089/photob.2019.4793","cited_by":2,"curated":false,"type":"preclinical","level":5,"ctx":["performance","récupération"],"nm":[808],"pre":"vivo","l1":"In addition, CK levels were also significantly lower for the PBMT groups than for the other groups. Conclusions: We conclude that PBMT alone or in conjunction with Cr supplement during a 12-week training program resulted in significantly…","kw":"endurance training ergogenic aids laser irradiation muscle damage muscle performance Animals Creatine Endurance Training Humans Low-Level Light Therapy Male"},{"pmid":"32366796","title":"Acute Photobiomodulation by LED Does Not Alter Muscle Fatigue and Cycling Performance.","journal_abbr":"Med Sci Sports Exerc","authors":["Dutra YM","Claus GM","Malta ES","et al."],"date":"2020-05-06","year":2020,"doi":"10.1249/MSS.0000000000002394","cited_by":20,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"autre","level":0,"ctx":["performance","récupération"],"l1":"Based on our findings, the PBMT at 260- and 130-J doses does not have a beneficial effect on muscle fatigue, cycling performance, metabolic parameters, and muscle activity in male recreational cyclists.","kw":"Adult Athletic Performance Bicycling Biomarkers Cross-Over Studies Electromyography"},{"pmid":"32369763","title":"Does Low-Level Laser Therapy Decrease Muscle-Damaging Mediators After Performance in Soccer Athletes Versus Sham Laser Treatment? A Critically Appraised Topic.","journal_abbr":"J Sport Rehabil","authors":["Bettleyon J","Kaminski TW"],"date":"2020-05-05","year":2020,"doi":"10.1123/jsr.2019-0421","cited_by":7,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["performance","récupération"],"l1":"Clinical Bottom Line: LLLT at 10, 30, or 50 J performed at a minimum of 2 locations on the rectus femoris, vastus lateralis, and vastus medialis bilaterally for 10 seconds each is significant in decreasing blood serum levels of BL and CK…","kw":"blood lactate creatine kinase recovery Biomarkers Creatine Kinase Humans Lactic Acid Low-Level Light Therapy Muscle Fatigue"},{"pmid":"33345040","title":"The Effects of Whole-Body Photobiomodulation Light-Bed Therapy on Creatine Kinase and Salivary Interleukin-6 in a Sample of Trained Males: A Randomized, Crossover Study.","journal_abbr":"Front Sports Act Living","authors":["Ghigiarelli JJ","Fulop AM","Burke AA","et al."],"date":"2020-04-29","year":2020,"doi":"10.3389/fspor.2020.00048","pmcid":"PMC7739664","license":"cc by","oa":true,"cited_by":12,"curated":false,"type":"autre","level":0,"ctx":["récupération"],"l1":"An additional Wilcoxon signed-rank test for CK percentage change from 24 to 72 h showed the PBMT condition (Mdn = -45%) to have a -18% median difference as compared to the control condition (Mdn = -41%). As such, whole-body PBMT does not…","kw":"bed therapy heart rate variability low level laser therapy recovery resistance training"},{"pmid":"32333337","title_fr":"PBM et capacité fonctionnelle de l'insuffisant rénal chronique","type":"rct","level":2,"pop":"adulte","ctx":["populations"],"aim":"—","mode":["laser","LED"],"nm":[810],"n":null,"effect":"favorable","theme":"Sujets âgés & malades chroniques","l1":"Huit semaines de PBM sur les membres inférieurs améliorent la capacité fonctionnelle et la force de l'insuffisant rénal chronique.","l2":"—","l3":{"points":["Population fragile."],"limites":["—"],"pratique":"—"},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Photobiomodulation therapy increases functional capacity of patients with chronic kidney failure: randomized controlled trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Schardong J","Falster M","Sisto IR","et al."],"date":"2020-04-24","year":2020,"week":"2020-S17","doi":"10.1007/s10103-020-03020-3","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":11,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Photobiomodulation (PBM) has been used in different populations as a strategy to attenuate muscle fatigue and improve exercise performance. Recent findings demonstrated that a single session with specific PBM doses during hemodialysis (HD) increased the upper limb muscle strength of chronic kidney failure (CKF) patients. Now, the primary objective of this study was to evaluate the chronic effect of PBM on the functional capacity of this population. Secondarily, we aimed at investigating the effects of PBM on the patients' strength, muscle thickness and echogenicity, perception of pain, fatigue, and quality of life. A randomized controlled trial was conducted in which the intervention group (IG, n = 14) received 24 sessions of PBM (810 nm, 5 diodes × 200 mW, 30 J/application site) on lower limb during HD. The control group (CG, n = 14) did not receive any physical therapy intervention, it only underwent HD sessions. As a result, there was an increase in the functional capacity (assessed through the six-minute walk test) for the IG compared with the CG [50.7 m (CI95% 15.63; 85.72), p = 0.01, large effect size, d = 1.12], as well as an improvement on lower limb muscle strength (assessed through the sit-and-stand test) [- 7.4 s (CI95% - 4.54; - 10.37), p = 0.00, large effect size, d = 1.99]. For other outcomes evaluated, no significant difference between-group was observed. Finally, PBM applied as monotherapy for 8 weeks in the lower limb improves functional capacity and muscle strength of CKF patients."}],"keywords":["Low-level light therapy","Randomized controlled trial","Renal dialysis","Renal insufficiency, chronic"]},{"pmid":"32318813","title":"Acute physiological responses to combined blood flow restriction and low-level laser.","journal_abbr":"Eur J Appl Physiol","authors":["Chen YC","Su YH","Lin YT","et al."],"date":"2020-04-22","year":2020,"doi":"10.1007/s00421-020-04378-6","cited_by":11,"curated":false,"type":"autre","level":0,"ctx":["récupération"],"l1":"LLLT pre-conditioning can minimize the BFR-related decline in muscle oxygen saturation, leading to force gradation and MU discharge in a cost-effective and complex manner.","kw":"Electromyography Force fluctuations Hypoxia Motor unit Myoglobin Photobiomodulation Adult Electromyography Female Hemodynamics Humans Isometric Contraction"},{"pmid":"32308987","title":"Does the combination of photobiomodulation therapy (PBMT) and static magnetic fields (sMF) potentiate the effects of aerobic endurance training and decrease the loss of performance during detraining? A randomised, triple-blinded, placebo-controlled trial.","journal_abbr":"BMC Sports Sci Med Rehabil","authors":["de Paiva PRV","Casalechi HL","Tomazoni SS","et al."],"date":"2020-04-10","year":2020,"doi":"10.1186/s13102-020-00171-2","pmcid":"PMC7147046","license":"cc by","oa":true,"cited_by":15,"curated":false,"type":"autre","level":0,"ctx":["performance"],"nm":[640,875,905],"em":["super"],"l1":"PBMT/sMF can potentiate the effects of aerobic endurance training and decrease performance loss after a 4-week detraining period. Thus, it may prove to be an important tool for both amateur and high-performance athletes as well as people…","kw":"Deconditioning Endurance exercise Light-emitting diode therapy Low-level laser therapy Phototherapy"},{"pmid":"32186975","title":"Pre-Conditioning and Post-Operative Photobiomodulation Therapy by a Novel Light Patch System for Knee Arthroplasty: A Protocol for a Phase 1 Study.","journal_abbr":"Photobiomodul Photomed Laser Surg","authors":["Vassão PG","Renno AC","Smith BN","et al."],"date":"2020-03-18","year":2020,"doi":"10.1089/photob.2019.4751","cited_by":2,"pub_types":["Clinical Trial Protocol"],"curated":false,"type":"protocol","level":0,"ctx":[],"nm":[450,640],"l1":"Conclusions: This study will provide an assessment of feasibility of using PBMT applied using a novel light patch system for management of pain symptoms and swelling, and aiding recovery of patients undergoing TKA. The results of this…","kw":"functional capacity knee arthroplasty pain photobiomodulation therapy Arthroplasty, Replacement, Knee Feasibility Studies Humans Low-Level Light Therapy Osteoar"},{"pmid":"32078062","title":"Photobiomodulation by light emitting diode applied sequentially does not alter performance in cycling athletes.","journal_abbr":"Lasers Med Sci","authors":["de Carvalho G","Gobbi A","Gobbi RB","et al."],"date":"2020-02-20","year":2020,"doi":"10.1007/s10103-020-02973-9","cited_by":7,"curated":false,"type":"autre","level":0,"ctx":["performance","récupération"],"nm":[940],"l1":"However, the association of two wavelengths seems to be better for increased performance. ClinicalTrials.gov Identifier: NCT03225976.","kw":"Athletes Clinical trial Fatigue Performance Photobiomodulation Adult Athletic Performance Bicycling Humans Lactic Acid Low-Level Light Therapy"},{"pmid":"31991284","title_fr":"Laser dans la rééducation des lésions des ischio-jambiers","type":"rct","level":2,"pop":"adulte","ctx":["blessures"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"neutre","theme":"Blessures sportives","l1":"Chez des athlètes amateurs, le laser n'accélère pas le retour au sport après lésion des ischio-jambiers (23 contre 24 jours).","l2":"Aucune récidive à 6 mois dans les deux groupes.","l3":{"points":["Contre placebo."],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Effects of low-level laser therapy on hamstring strain injury rehabilitation: A randomized controlled trial.","journal":"Physical therapy in sport : official journal of the Association of Chartered Physiotherapists in Sports Medicine","journal_abbr":"Phys Ther Sport","authors":["Medeiros DM","Aimi M","Vaz MA","et al."],"date":"2020-01-10","year":2020,"week":"2020-S02","doi":"10.1016/j.ptsp.2020.01.006","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":19,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"OBJECTIVES","text":"To evaluate the effects of low-level laser therapy (LLLT) on functional rehabilitation following hamstring strain injury (HSI) in amateur athletes treated with an exercise-based rehabilitation program."},{"label":"DESIGN","text":"Randomized controlled trial."},{"label":"METHODS","text":"Male athletes (18-40 years old) who sustained HSI were randomized in LLLT or placebo groups. All patients were engaged in the same exercise-based rehabilitation program until they met specific criteria to return to sport. Hamstring muscles were treated with LLLT or placebo immediately after each rehabilitation session. The primary outcome was time-to-return to sport. Secondary outcomes were the number of rehabilitation sessions, hamstring flexibility, hamstring strength, and re-injury rate."},{"label":"RESULTS","text":"Twenty-four athletes began rehabilitation, and 22 (11 per group) completed the study schedule. Participants of LLLT and placebo groups had similar age, body size, injury characteristics, and baseline levels of hamstring flexibility and strength. The two groups increased flexibility and strength similarly throughout the rehabilitation program. Time-to-return to sport was the same for athletes treated with LLLT (23 ± 9 days) and placebo (24 ± 13 days). There were no re-injuries within 6 months after return to sport."},{"label":"CONCLUSION","text":"LLLT, as used in this study, did not optimize functional rehabilitation following HSI in amateur athletes treated with an exercise-based rehabilitation program."}],"keywords":["Electrophysical agents","Muscle injury","Photobiomodulation therapy","Physiotherapy"]},{"pmid":"31925594","title":"Low-level laser therapy prevents muscle oxidative stress in rats subjected to high-intensity resistance exercise in a dose-dependent manner.","journal_abbr":"Lasers Med Sci","authors":["Dos Santos SS","de Oliveira HA","Antonio EL","et al."],"date":"2020-01-10","year":2020,"doi":"10.1007/s10103-020-02951-1","cited_by":5,"curated":false,"type":"preclinical","level":5,"ctx":["performance"],"pre":"vivo","l1":"These data indicate that LLLT prior to RE can prevent muscle oxidative stress. This study is the first to evaluate the impact of dosimetric LLLT parameters on the oxidative stress induced by RE, wherein both 8 J and 12 J of energy…","kw":"Laser Oxidative stress Phototherapy Resistance exercise Strength training Animals Catalase Female Lipid Peroxidation Low-Level Light Therapy Muscle, Skeletal"},{"pmid":"31890228","title":"The effect of low level laser irradiation on oxidative stress, muscle damage and function following neuromuscular electrical stimulation. A double blind, randomised, crossover trial.","journal_abbr":"BMC Sports Sci Med Rehabil","authors":["Jówko E","Płaszewski M","Cieśliński M","et al."],"date":"2019-12-27","year":2019,"doi":"10.1186/s13102-019-0147-3","pmcid":"PMC6933902","license":"cc by","oa":true,"cited_by":21,"curated":false,"type":"autre","level":0,"ctx":["récupération"],"l1":"LLLT may protect from impairments in enzymatic antioxidant system and may shorten inflammation induced by a single NMES session in moderately active, healthy men. However, the effects of LLLT on redox state and inflammatory processes do…","kw":"Biochemistry DOMS Evoked contractions Exercise-induced muscle damage Knee extensors Photobiomodulation"},{"pmid":"31823135","title":"Long-term analyses of spastic muscle behavior in chronic poststroke patients after near-infrared low-level laser therapy (808 nm): a double-blinded placebo-controlled clinical trial.","journal_abbr":"Lasers Med Sci","authors":["das Neves MF","Aleixo DC","Mendes IS","et al."],"date":"2019-12-10","year":2019,"doi":"10.1007/s10103-019-02920-3","cited_by":14,"pub_types":["Controlled Clinical Trial"],"curated":false,"type":"nrct","level":3,"ctx":["récupération","populations"],"nm":[808],"l1":"The root mean square (RMS) values also increased after PBMT + exoskeleton from 23.2 ± 15 to 34.9 ± 21 μV (p = 0.0178). Our results suggest that the application of PBMT may contribute to an increased range of elbow motion and muscle fiber…","kw":"Laser Muscle fatigue PBMT Photobiomodulation therapy Spasticity Stroke Adult Double-Blind Method Electromyography Female Humans Infrared Rays"},{"pmid":"31793464","title":"The impact of high-intensity laser therapy on oxidative stress, lysosomal enzymes, and protease inhibitor in athletes.","journal_abbr":"Chin J Physiol","authors":["Sielski Ł","Sutkowy P","Katarzyna PO","et al."],"date":"2019-12-04","year":2019,"doi":"10.4103/CJP.CJP_40_19","cited_by":1,"curated":false,"type":"autre","level":0,"ctx":[],"l1":"24 h after the HILT intervention, the CTS D and AcP activities were also correlated in the injured athletes (r = 0.8, P = 0.002). The study suggests that one HILT intervention does not significantly influence the redox equilibrium but…","kw":"High-intensity laser therapy lysosomal hydrolases oxidative stress α1-antitrypsin Adolescent Antioxidants Athletes Catalase Female Glutathione Peroxidase"},{"pmid":"31827687","title_fr":"PBM infrarouge avant un test de course chez le footballeur de haut niveau","type":"rct","level":2,"pop":"adulte","ctx":["blessures"],"aim":"prévention","mode":["laser","LED"],"nm":[],"n":null,"effect":"favorable","theme":"Blessures sportives","l1":"Chez des footballeurs de haut niveau, la PBM avant l'effort améliore la performance et réduit lésions musculaires, inflammation et stress oxydatif.","l2":"NCT03803956.","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Infrared Low-Level Laser Therapy (Photobiomodulation Therapy) before Intense Progressive Running Test of High-Level Soccer Players: Effects on Functional, Muscle Damage, Inflammatory, and Oxidative Stress Markers-A Randomized Controlled Trial.","journal":"Oxidative medicine and cellular longevity","journal_abbr":"Oxid Med Cell Longev","authors":["Tomazoni SS","Machado CDSM","De Marchi T","et al."],"date":"2019-11-16","year":2019,"week":"2019-S46","doi":"10.1155/2019/6239058","pmcid":"PMC6885272","license":"cc by","oa":true,"pdf":"pdfs/31827687.pdf","cited_by":46,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"The effects of preexercise photobiomodulation therapy (PBMT) to enhance performance, accelerate recovery, and attenuate exercise-induced oxidative stress were still not fully investigated, especially in high-level athletes. The aim of this study was to evaluate the effects of PBMT (using infrared low-level laser therapy) applied before a progressive running test on functional aspects, muscle damage, and inflammatory and oxidative stress markers in high-level soccer players. A randomized, triple-blind, placebo-controlled crossover trial was performed. Twenty-two high-level male soccer players from the same team were recruited and treated with active PBMT and placebo. The order of interventions was randomized. Immediately after the application of active PBMT or placebo, the volunteers performed a standardized high-intensity progressive running test (ergospirometry test) until exhaustion. We analyzed rates of oxygen uptake (VO2 max), time until exhaustion, and aerobic and anaerobic threshold during the intense progressive running test. Creatine kinase (CK) and lactate dehydrogenase (LDH) activities, levels of interleukin-1β (IL-1-β), interleukin-6 (IL-6), and tumor necrosis factor alpha (TNF-α), levels of thiobarbituric acid (TBARS) and carbonylated proteins, and catalase (CAT) and superoxide dismutase (SOD) activities were measured before and five minutes after the end of the test. PBMT increased the VO2 max (both relative and absolute values-p < 0.0467 and p < 0.0013, respectively), time until exhaustion (p < 0.0043), time (p < 0.0007) and volume (p < 0.0355) in which anaerobic threshold happened, and volume in which aerobic threshold happened (p < 0.0068). Moreover, PBMT decreased CK (p < 0.0001) and LDH (p < 0.0001) activities. Regarding the cytokines, PBMT decreased only IL-6 (p < 0.0001). Finally, PBMT decreased TBARS (p < 0.0001) and carbonylated protein levels (p < 0.01) and increased SOD (p < 0.0001)and CAT (p < 0.0001) activities. The findings of this study demonstrate that preexercise PBMT acts on different functional aspects and biochemical markers. Moreover, preexercise PBMT seems to play an important antioxidant effect, decreasing exercise-induced oxidative stress and consequently enhancing athletic performance and improving postexercise recovery. This trial is registered with Clinicaltrials.gov NCT03803956."}],"keywords":[]},{"pmid":"31729609","title":"Physical exercise and low-level laser therapy on the nociception and leukocyte migration of Wistar rats submitted to a model of rheumatoid arthritis.","journal_abbr":"Lasers Med Sci","authors":["Neves M","Retameiro ACB","Tavares ALF","et al."],"date":"2019-11-15","year":2019,"doi":"10.1007/s10103-019-02905-2","cited_by":14,"curated":false,"type":"preclinical","level":5,"ctx":[],"pre":"vivo","l1":"The treated groups showed recovery of functionality; it is still verified that laser therapy increased the nociceptive threshold of the chronic inflammatory period, and the exercise reflected in significant functional improvement and…","kw":"Exercise Laser therapy Leukocyte count Neurogenic inflammation Rheumatoid arthritis Animals Arthritis, Rheumatoid Cell Movement Edema Inflammation Leukocytes"},{"pmid":"31661369","title":"Conservative treatment of Achilles tendon partial tear in a futsal player: A case report.","journal_abbr":"Physiother Theory Pract","authors":["Medeiros DM"],"date":"2019-10-29","year":2019,"doi":"10.1080/09593985.2019.1683924","cited_by":2,"pub_types":["Case Reports"],"curated":false,"type":"cases","level":4,"ctx":["blessures"],"l1":"Outcomes: Ankle dorsiflexion range of motion and hop tests. Discussion: This case report demonstrated that non-surgical treatment for Achilles tendon partial tear was effective for this patient and enabled the athlete to return to…","kw":"Plantarflexors rehabilitation triceps surae Achilles Tendon Conservative Treatment Humans Range of Motion, Articular Rupture Tendinopathy"},{"pmid":"31662370","title":"Effects of photobiomodulation therapy combined to static magnetic field in strength training and detraining in humans: protocol for a randomised placebo-controlled trial.","journal_abbr":"BMJ Open","authors":["de Paiva PRV","Casalechi HL","Tomazoni SS","et al."],"date":"2019-10-28","year":2019,"doi":"10.1136/bmjopen-2019-030194","pmcid":"PMC6830659","license":"cc by-nc","oa":true,"cited_by":4,"pub_types":["Clinical Trial Protocol","Research Support, Non-U.S. Gov't"],"curated":false,"type":"protocol","level":0,"ctx":["performance"],"l1":"The results from this study will be disseminated through scientific publications in international peer-reviewed journals and presented at national and international scientific meetings. NCT03858179.","kw":"performance phototherapy physical therapy strength training structural properties Adult Humans Low-Level Light Therapy Magnetic Field Therapy Magnetic Fields Ma"},{"pmid":"31654154","title_fr":"PBM des muscles respiratoires dans la BPCO : essai croisé en double aveugle","type":"rct","level":2,"pop":"adulte","ctx":["populations"],"aim":"traitement","mode":["laser","LED"],"nm":[],"n":null,"effect":"mitigé","theme":"Sujets âgés & malades chroniques","l1":"Première étude de la PBM sur les muscles respiratoires dans la BPCO ; les effets sur la fonction et la capacité restent limités.","l2":"Essai croisé randomisé en double aveugle contre placebo.","l3":{"points":["Nouvelle cible."],"limites":["Effet aigu."],"pratique":"Exploratoire."},"em":[],"pre":"","topic":"sport","title":"Acute effects of photobiomodulation therapy applied to respiratory muscles of chronic obstructive pulmonary disease patients: a double-blind, randomized, placebo-controlled crossover trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["de Souza GHM","Ferraresi C","Moreno MA","et al."],"date":"2019-10-26","year":2019,"week":"2019-S43","doi":"10.1007/s10103-019-02885-3","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":16,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"To investigate the effects of photobiomodulation applied to respiratory muscles on lung function, thoracoabdominal mobility, respiratory muscle strength, and functional capacity in COPD patients. This is a randomized double-blind crossover clinical trial. Twelve male COPD patients participated in the study. Participants were randomly allocated to receive two photobiomodulation sessions, 1 week apart: (1) an effective photobiomodulation session applied at the main respiratory muscles by means of a cluster with 69 light-emitting diodes (LEDs), containing 35 red (630 ± 10 nm; 10 mW; 0.2 cm2) and 34 near-infrared (830 ± 20 nm; 10 mW; 0.2 cm2) LEDs and (2) a sham photobiomodulation session, following the same procedures without emitting light. The primary outcomes were pulmonary function (spirometric indexes); thoracoabdominal mobility (cirtometry); respiratory muscle strength (maximal respiratory pressures), assessed at three moments: (1) baseline, (2) 1 h after intervention, and (3) 24 h after intervention; and the functional capacity, assessed by the 6-min walk test (6MWT) at baseline and 24 h after intervention. No significant interactions were found for spirometric variables, maximal respiratory pressures, and cirtometry. However, there was a Time × Condition interaction (F = 18.63; p = 0.001; η2p = 0.62) in the walked distance on the 6MWT, with a significant increase after photobiomodulation intervention (p < 0.01) compared with the baseline. Photobiomodulation applied to respiratory muscles was effective in improving acute functional capacity in COPD patients. To the best of our knowledge, this is the first study assessing the effects of photobiomodulation applied to respiratory muscles in patients with COPD."}],"keywords":["6-min walk test","Low-level light therapy","Phototherapy","Physical therapy","Respiratory function tests"]},{"pmid":"31574822","title":"Analysis of the effects of low-level laser therapy on muscle fatigue of the biceps brachii muscle of healthy individuals and spastic individuals: Study protocol for a single-center, randomized, double-blind, and controlled clinical trial.","journal_abbr":"Medicine (Baltimore)","authors":["da Silva BP","Souza GADS","Filho AADN","et al."],"date":"2019-10-03","year":2019,"doi":"10.1097/MD.0000000000017166","pmcid":"PMC6775413","license":"cc by","oa":true,"cited_by":7,"pub_types":["Clinical Trial Protocol"],"curated":false,"type":"protocol","level":0,"ctx":["récupération"],"l1":"Pain intensity will be evaluated by means of the visual analog scale, and the myoelectric activity by means of surface electromyography associated with the evaluation of muscular strength by means of the dynamometer. The local temperature…","kw":"Adult Aged Aged, 80 and over Arm Cross-Sectional Studies Double-Blind Method"},{"pmid":"31402432","title_fr":"PBM et électrostimulation chez de jeunes volleyeurs","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"—","mode":["laser","LED"],"nm":[850],"n":null,"effect":"mitigé","theme":"Performance musculaire","l1":"L'électrostimulation améliore plus la force et la détente que la PBM chez de jeunes volleyeurs.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":["pulse"],"pre":"","nm_auto":true,"topic":"sport","title":"Photobiomodulation therapy and NMES improve muscle strength and jumping performance in young volleyball athletes: a randomized controlled trial study in Brazil.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["da Cunha RA","Pinfildi CE","de Castro Pochini A","et al."],"date":"2019-08-11","year":2019,"week":"2019-S32","doi":"10.1007/s10103-019-02858-6","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":14,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"The purpose of this study was to investigate the effectiveness of adding photobiomodulation therapy and neuromuscular electrical stimulation (NMES) to volleyball athletes' training, focusing on muscle strength and jumping skills. Thirty-six athletes were randomly placed into three groups: control, photobiomodulation therapy, and NMES. The athletes trained to improve their muscle strength and jumping skills. The athletes in the photobiomodulation therapy group were submitted to photobiomodulation therapy (850 nm, continuous, energy density 0.8 J/cm2, radiant energy per point 6 J, total radiant energy 36 J) before undergoing strength and plyometric training. The NMES group additionally underwent NMES-based quadriceps femoris muscle strength training (base frequency 1 kHz, frequency modulation 70 Hz, intensity maximum tolerable). The variables analyzed were muscle strength, jumping ability, global impression, and jump frequency; they were measured at baseline and during follow-ups at 6 and 8 weeks. The statistical analysis was conducted on an intention-to-treat basis. The between-group differences and their respective 95% CIs were calculated using linear mixed models by using group, time, and group-versus-time interaction terms. Dominant lower limb strength improved the most in the NMES group compared to the control group (mean difference = 1.4, 95% CI = .5 to 2.4). Non-dominant lower limb strength increased in both the photobiomodulation therapy group (mean difference = 1.1, 95% CI = .3 to 2) and the NMES group (mean difference = 1.9, 95% CI = 1.1 to 2.8) compared to the control group, but the NMES group improved more than the photobiomodulation therapy group (mean difference = 0.8, 95% CI = 0.1 to 1.7). The NMES group had the greatest improvement in global perceived effect scale compared to the control group (mean difference = 1.1, 95% CI = 1 to 2.2). Dominant lower limb strength improved in the NMES group compared to the control group. Non-dominant lower limb strength increased in both the photobiomodulation therapy group and the NMES group compared to the control group, but the NMES group improved significantly more than the photobiomodulation therapy group; the NMES group also improved in the global perceived effect scale compared to the control group. This study found that, for volleyball athletes, photobiomodulation therapy and NMES both promoted benefits in terms of muscle-strength gain. In addition, these benefits were maintained for 2 weeks even after training was interrupted. Dominant lower limb strength improved in the NMES group compared to the control group. Non-dominant lower limb strength increased in both the photobiomodulation therapy group and the NMES group compared to the control group, but the NMES group improved significantly more than the photobiomodulation therapy group; the NMES group also improved in global impression of jumps compared to the control group."}],"keywords":["Athletic performance","Muscle strength","Neuromuscular electrical stimulation","Photobiomodulation therapy","Sports"]},{"pmid":"31297066","title":"Photobiomodulation Therapy Does Not Attenuate Fatigue and Muscle Damage in Judo Athletes: A Randomized, Triple-Blind, Placebo-Controlled Trial.","journal_abbr":"Front Physiol","authors":["Orssatto LBDR","Detanico D","Kons RL","et al."],"date":"2019-06-26","year":2019,"doi":"10.3389/fphys.2019.00811","pmcid":"PMC6607399","license":"cc by","oa":true,"cited_by":12,"curated":false,"type":"autre","level":0,"ctx":["performance","récupération"],"l1":"No differences were observed between photobiomodulation therapy and placebo at any time points for any variables (p > 0.05), indicating no positive effect favoring photobiomodulation therapy. In conclusion, our findings suggest no effect…","kw":"combat sports low-level laser therapy performance photobiomodulation recovery stretch shortening cycle"},{"pmid":"31203569","title_fr":"LED et sensibilité du baroréflexe à l'effort dans le diabète de type 2","type":"rct","level":2,"pop":"adulte","ctx":["populations"],"aim":"traitement","mode":["LED"],"nm":[],"n":11,"effect":"neutre","theme":"Sujets âgés & malades chroniques","l1":"Chez des diabétiques de type 2, la PBM par LED (300 J) avant un effort modéré ne modifie pas le contrôle autonome cardiovasculaire.","l2":"Essai randomisé, 11 hommes.","l3":{"points":["Résultat négatif."],"limites":["Très petit effectif."],"pratique":"Pas d'effet cardiovasculaire."},"em":["cw"],"pre":"","topic":"sport","title":"Acute effect of photobiomodulation using light-emitting diodes (LEDs) on baroreflex sensitivity during and after constant loading exercise in patients with type 2 diabetes mellitus.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Milan-Mattos JC","de Oliveira Francisco C","Ferroli-Fabrício AM","et al."],"date":"2019-06-15","year":2019,"week":"2019-S24","doi":"10.1007/s10103-019-02815-3","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":2,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"To evaluate the photobiomodulation (PBM) effect on the cardiovascular autonomic control, analyzed by baroreflex sensitivity (sequence method), during constant load exercise and recovery in diabetic men, we evaluated 11 men with type 2 diabetes (DM2) (40-64 years). The constant workload exercise protocol (TECC) was performed on two different days, 14 days apart from each other, to guarantee PBM washout period. After PBM by light-emitting diode (LED) irradiation (150 J or 300 J or placebo), 10 min of rest (REST) was performed. After this period, the volunteer was positioned on a cycloergometer to start the test (1-min rest, 3-min free-load heating, 6-min constant workload-EXERCISE, 6-min free-load cool-down, 1-min rest) followed by a sitting period of 10 min (RECOVERY). The constant workload corresponded to 80%VO2GET (gas exchange threshold) identified by a previous cardiopulmonary exercise test (CPET). PBM was applied in continuous mode, contact technique, bilaterally, on both femoral quadriceps and gastrocnemius muscle groups. The electrocardiogram R-R intervals (BioAmp FE132) and the peripheral pulse pressure signals (Finometer PRO) were collected continuously throughout the protocol. Stable sequences of 256 points were chosen at REST, EXERCISE, and RECOVERY. The baroreflex sensitivity (BRS) was computed in time domain according to the sequence method (αseq). The comparison between therapies (150 J/300 J/placebo) and condition (REST, EXERCISE, and RECOVERY) was performed using the ANOVA two-way repeated measures test. There was no interaction between therapy and conditions during the TECC. There was only the condition effect (p < 0.001), showing that the behavior of αseq was similar regardless of the therapy. Photobiomodulation with 150 J or 300 J applied previously to a moderate-intensity TECC in DM2 was not able to promote cardiovascular autonomic control changes leading to an improvement in BRS."}],"keywords":["Baroreflex sensitivity","Cardiovascular autonomic control","Phototherapy","Physical exercise","Sequence method","Type 2 diabetes mellitus"]},{"pmid":"31197508","title_fr":"PBM et musculation chez la femme ménopausée","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"—","mode":["laser"],"nm":[630,850],"n":null,"effect":"neutre","theme":"Performance musculaire","l1":"La PBM n'apporte pas de gain supplémentaire de force à un entraînement en résistance chez la femme ménopausée.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Effects of photobiomodulation on muscle strength in post-menopausal women submitted to a resistance training program.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Almeida JN","Prado WL","Terra CM","et al."],"date":"2019-06-14","year":2019,"week":"2019-S24","doi":"10.1007/s10103-019-02822-4","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":8,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"The aim of this study was to compare the effects of resistance training of low volume and high intensity with or without photobiomodulation (PBM) on muscle strength and functional performance in post-menopausal women. Thirty-four post-menopausal women were randomized into resistance training (RTG, n = 17) or resistance training plus PBM (PBMG, n = 17). Individuals from both groups received the same RT protocol consisting of leg-press 45°, front lat pulldown, leg curl, chest press, and squat performed in two sets of 10 repetitions with a workload of 75% of one repetition maximum (1RM), twice per week, during 8 weeks. PBMG individuals also received, prior to the exercise session, PBM through a cluster containing 7 visible diodes (630 nm) and 7 infrared diodes (850 nm) with power of 100 mW each and energy of 4 J per diode, applied to the quadriceps femoris muscle; individuals from RTG received placebo PBM prior to the sessions, applied with the same device switched off. Muscle strength (1RM; isometric dynamometer), functional performance (Time Up and Go; Berg Balance Scale; 6-min walk test), and quality of life (World Health Organization Quality of Life-Bref) were performed before and after 8 weeks. Both groups increased muscle strength (p < 0.001) for all exercises, without group differences (p = 0.651). Quality of life (p = 0.015) and balance (p = 0.006) increased only in the RTG. The results suggest that PBM were not able for inducing additional benefits to RT to improve muscle strength in post-menopausal women."}],"keywords":["Low-level laser therapy","Phototherapy","Physical conditioning","Post-menopause","Sarcopenia","Strength training"]},{"pmid":"31168833","title":"Review of non-invasive body contouring devices for fat reduction, skin tightening and muscle definition.","journal_abbr":"Australas J Dermatol","authors":["Mazzoni D","Lin MJ","Dubin DP","et al."],"date":"2019-06-06","year":2019,"doi":"10.1111/ajd.13090","cited_by":57,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"Although they do not achieve the same results as liposuction, they are an attractive alternative for patients who do not want the risks or costs associated with surgery. When used appropriately and correctly, these devices have…","kw":"body contouring fat reduction lipolysis liposuction skin tightening Body Contouring Cryotherapy Extracorporeal Shockwave Therapy Humans Low-Level Light Therapy "},{"pmid":"31165945","title":"Acute low-level laser therapy effects on peripheral muscle strength and resistance in patients with fibromyalgia.","journal_abbr":"Lasers Med Sci","authors":["Dos Santos RC","Souza Guedes KWHS","de Sousa Pinto JM","et al."],"date":"2019-06-05","year":2019,"doi":"10.1007/s10103-019-02816-2","cited_by":4,"curated":false,"type":"autre","level":0,"ctx":["performance","populations"],"l1":"","kw":""},{"pmid":"31147894","title":"Correction to: Are the ergogenic effects of photobiomodulation therapy age-dependent? A randomized double-blinded placebo-controlled trial.","journal_abbr":"Lasers Med Sci","authors":["Fritsch CG","Folgiarini LA","Gomes NS","et al."],"date":"2019-05-31","year":2019,"doi":"10.1007/s10103-019-02820-6","pub_types":["Published Erratum"],"curated":false,"type":"autre","level":0,"ctx":["performance"],"l1":"The correct author name is Bruno Manfredini Baroni. The original article has been corrected.","kw":""},{"pmid":"31126572","title":"Corrigendum to \"Effects of laser acupuncture in a patient with a 12-year history of facial paralysis: A case report\" [Complement. Ther. Med. 43 (April) (2019) 306-310].","journal_abbr":"Complement Ther Med","authors":["Ton G","Lee LW","Tu CH","et al."],"date":"2019-05-16","year":2019,"doi":"10.1016/j.ctim.2019.04.015","pub_types":["Published Erratum"],"curated":false,"type":"autre","level":0,"ctx":[],"l1":"LAT significantly improved the sequelae of long-term facial paralysis in this patient. Large-scale prospective studies are needed to confirm this observation.","kw":"Case report Laser acupuncture Low-level laser therapy Sequelae of facial palsy"},{"pmid":"31045769","title":"Effects of photobiomodulation therapy in aerobic endurance training and detraining in humans: Protocol for a randomized placebo-controlled trial.","journal_abbr":"Medicine (Baltimore)","authors":["de Paiva PRV","Casalechi HL","Tomazoni SS","et al."],"date":"2019-05-03","year":2019,"doi":"10.1097/MD.0000000000015317","pmcid":"PMC6504339","license":"cc by","oa":true,"cited_by":5,"pub_types":["Clinical Trial Protocol"],"curated":false,"type":"protocol","level":0,"ctx":["performance"],"l1":"The results from this study will be further disseminated through scientific publications in international peer-reviewed journals and presentations at national and international scientific meetings. NCT03879226.","kw":"Adolescent Adult Athletic Performance Body Fat Distribution Endurance Training Exercise Test"},{"pmid":"31025208","title":"Are the ergogenic effects of photobiomodulation therapy age-dependent? A randomized double-blinded placebo-controlled trial.","journal_abbr":"Lasers Med Sci","authors":["Fritsch CG","Folgiarini LA","Gomes NS","et al."],"date":"2019-04-25","year":2019,"doi":"10.1007/s10103-019-02790-9","cited_by":3,"curated":false,"type":"autre","level":0,"ctx":["performance"],"l1":"","kw":""},{"pmid":"30851081","title":"Sex, but not skin tone affects penetration of red-light (660 nm) through sites susceptible to sports injury in lean live and cadaveric tissues.","journal_abbr":"J Biophotonics","authors":["Hu D","van Zeyl M","Valter K","et al."],"date":"2019-03-10","year":2019,"doi":"10.1002/jbio.201900010","cited_by":18,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"autre","level":0,"ctx":["blessures","populations"],"nm":[660],"l1":"Live and cadaveric tissue penetration did not differ statistically for tissues <50 mm but cadavers required more red-light to penetrate >50 mm. These results assist clinicians and researchers in determining red-light treatment intensities…","kw":"LED treatment photobiomodulation red light therapy sports injuries sprain strain Absorption, Physicochemical Adult Athletic Injuries Cadaver Disease Susceptibil"},{"pmid":"30820772","title_fr":"PBM et musculation du quadriceps chez la femme âgée","type":"rct","level":2,"pop":"adulte","ctx":["populations"],"aim":"—","mode":["laser"],"nm":[],"n":null,"effect":"favorable","theme":"Sujets âgés & malades chroniques","l1":"Chez des femmes âgées, la PBM associée à la musculation améliore plus la performance du quadriceps que l'entraînement seul.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Quadriceps femoris performance after resistance training with and without photobiomodulation in elderly women: a randomized clinical trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Tucci HT","Figueiredo DS","de Paula Carvalho R","et al."],"date":"2019-02-28","year":2019,"week":"2019-S09","doi":"10.1007/s10103-019-02748-x","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":12,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"The study assessed if quadriceps femoris muscle performance of older women can be improved by applying photobiomodulation therapy after a resistance training program. This study is a randomized, controlled trial with concealed allocation, intention-to-treat analysis, and blinded outcome evaluators. Forty-five healthy sedentary older women classified as active or insufficiently active were randomized to groups receiving 8 weeks of quadriceps femoris resistance training plus active group or placebo group, or a control group (no training or photobiomodulation). Surface electromyographic fatigue indexes of vastus medialis, rectus femoris, and vastus lateralis; one-maximum repetition (1-MR); and analysis of inflammatory biomarkers (IL-6, IL-8, and TNF-α cytokines, plus CK and LDH enzymes) were measured at baseline and twice in a 24 h-period after 8 weeks. No differences among the three groups were found in fatigue indexes for all three muscles, although in general, the active group presented improved fatigue indexes from baseline to 8-week outcome, while the other groups did not. Both training groups improved in 1-MR over the 8-week period. Inflammatory biomarkers were not different at long- or short-term among the three groups, except differences in groups for long-term IL-8 changes, differences in time for long-term LDH and short-term TNF-α changes, and interactions of time by group for short-term LDH changes. Quadriceps femoris performance of older women was not improved when photobiomodulation was associated to the proposed quadriceps femoris resistance training, when compared to training without photobiomodulation and a sedentary group."}],"keywords":["Electromyography","Fatigue","Photobiomodulation","Quadriceps femoris","Resistance training"]},{"pmid":"30935549","title":"Effects of laser acupuncture in a patient with a 12-year history of facial paralysis: A case report.","journal_abbr":"Complement Ther Med","authors":["Ton G","Lee LW","Chen YH","et al."],"date":"2019-02-27","year":2019,"doi":"10.1016/j.ctim.2019.02.015","license":"cc by-nc-nd","cited_by":7,"pub_types":["Case Reports"],"curated":false,"type":"cases","level":4,"ctx":[],"l1":"LAT significantly improved the sequelae of long-term facial paralysis in this patient. Large-scale prospective studies are needed to confirm this observation [added]","kw":"Acupuncture Points Acupuncture Therapy Facial Nerve Facial Paralysis Humans Male"},{"pmid":"30676234","title":"A Novel Blue-Red Photobiomodulation Therapy Patch Effects on a Repetitive Elbow-Flexion Fatigue Task.","journal_abbr":"J Sport Rehabil","authors":["Rigby JH","Hagan AM"],"date":"2019-01-25","year":2019,"doi":"10.1123/jsr.2018-0339","cited_by":3,"curated":false,"type":"autre","level":0,"ctx":["récupération"],"nm":[450,645],"em":["pulse"],"l1":"Nearly 30% of participants had an increase benefit during a repeated-bout fatigue task due to the blue/red light-emitting diode photobiomodulation light patch.","kw":"exercise recovery laser therapy muscle fatigue muscle function Adolescent Adult Elbow Joint Female Healthy Volunteers Humans"},{"pmid":"30775383","title":"Acute Effects Using Light-Emitting Diode Therapy (LEDT) for Muscle Function during Isometric Exercise in Asthma Patients: A Pilot Study.","journal_abbr":"Biomed Res Int","authors":["Costa IP","Politti F","Cahalin LP","et al."],"date":"2019-01-16","year":2019,"doi":"10.1155/2019/7501870","pmcid":"PMC6354134","license":"cc by","oa":true,"cited_by":2,"curated":false,"type":"autre","level":0,"ctx":["récupération","populations"],"nm":[850],"l1":"A single application of LEDT in the parameters and dose according to the equipment used in the study were not able to promote differences in the time of contraction and the fatigue response in asthmatic patients. However, the chronic…","kw":"Adult Asthma Exercise Female Humans Isometric Contraction"},{"pmid":"30692939","title":"Photobiomodulation by Led Does Not Alter Muscle Recovery Indicators and Presents Similar Outcomes to Cold-Water Immersion and Active Recovery.","journal_abbr":"Front Physiol","authors":["Malta ES","de Lira FS","Machado FA","et al."],"date":"2019-01-14","year":2019,"doi":"10.3389/fphys.2018.01948","pmcid":"PMC6339932","license":"cc by","oa":true,"cited_by":19,"curated":false,"type":"autre","level":0,"ctx":["récupération"],"nm":[660,850],"l1":"However, an effect of time was found with an increase in CK and IL-10 (P = 0.003), while DOMS decreased at 48 and 72-h compared with 24-h (P = 0.001). Conclusion: In summary, PBMT had no effect on inflammation, muscle damage, CMJ…","kw":"L-lactate dehydrogenase creatine kinase high-intensity interval training inflammation interleukin-10 low-level light therapy"},{"pmid":"30755776","title":"Effects of Laser Acupuncture on Delayed Onset Muscle Soreness of the Biceps Brachii Muscle: A Randomized Controlled Trial.","journal_abbr":"Evid Based Complement Alternat Med","authors":["Chang WD","Wu JH","Chang NJ","et al."],"date":"2019-01-13","year":2019,"doi":"10.1155/2019/6568976","pmcid":"PMC6348906","license":"cc by","oa":true,"cited_by":8,"curated":false,"type":"autre","level":0,"ctx":["récupération"],"l1":"Photobiomodulation therapy on Tianquan (PC2) and Chihtseh acupoints (LU5) before the exercise did not significantly decrease DOMS and increase muscle performance. Laser acupuncture as a supplemental therapy seemed to have no effect on…","kw":""},{"pmid":"30607719","title_fr":"PBM pour prévenir la fatigue des ischio-jambiers chez le footballeur","type":"rct","level":2,"pop":"adulte","ctx":["blessures"],"aim":"prévention","mode":["laser","LED"],"nm":[],"n":null,"effect":"favorable","theme":"Blessures sportives","l1":"La PBM limite la fatigue des ischio-jambiers induite par le football, une piste pour prévenir les lésions.","l2":"—","l3":{"points":["Prévention des blessures."],"limites":["Critère indirect."],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Photobiomodulation therapy as a tool to prevent hamstring strain injuries by reducing soccer-induced fatigue on hamstring muscles.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Dornelles MP","Fritsch CG","Sonda FC","et al."],"date":"2019-01-03","year":2019,"week":"2019-S01","doi":"10.1007/s10103-018-02709-w","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":12,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Muscle fatigue is a potential risk factor for hamstring strain injuries in soccer players. The aim of this study was to verify the effect of photobiomodulation therapy (PBMT) on the hamstrings' muscle fatigue of soccer players during a simulated match. Twelve male amateur soccer players (~ 25 years) participated in this randomized, crossover, double-blinded, placebo-controlled trial. The volunteers were evaluated in two sessions, with a minimum 7-day interval. At each session, volunteers received either PBMT (300 J per thigh) or placebo treatment on the hamstrings prior to the simulated soccer match. Muscle strength and functional capacity were evaluated through isokinetic dynamometry and countermovement jump (CMJ) tests, respectively, before and immediately after the simulated soccer match. Players had lower reductions on hamstring eccentric peak torque [4.85% (ES = 0.31) vs. 8.72% (ES = 0.50)], hamstring-to-quadriceps torque ratio [3.60% (ES = 0.24) vs. 7.75% (ES = 0.50)], and CMJ height [1.77% (ES = 0.09) vs. 5.47% (ES = 0.32)] when treated with PBMT compared to placebo. Magnitude-based inference supports that PBMT promoted 75%, 69%, and 53% chances for beneficial effects on hamstring eccentric peak torque, hamstring-to-quadriceps torque ratio, and CMJ height, respectively, compared to placebo treatment. In conclusion, PBMT applied before a simulated soccer match proved to be effective in attenuating the hamstrings' muscle fatigue. These findings support PBMT as a promising tool to prevent hamstring strain injury in soccer players."}],"keywords":["Football","Muscle injury","Phototherapy","Prevention"]},{"pmid":"36817995","title":"Joint SASMA and Bricscess Congress: Cape Town - South Africa, Thursday 10 - Sunday 13 October 2019.","journal_abbr":"S Afr J Sports Med","authors":[],"date":"2019-01-01","year":2019,"pmcid":"PMC9924525","license":"cc by","oa":true,"curated":false,"type":"autre","level":0,"ctx":["blessures","populations"],"l1":"","kw":"Achilles tendon Amputee BMI Gymnastics Muscle strain injury Non-communicable diseases"},{"pmid":"30613078","title":"Effects of Ultrasound, Laser and Exercises on Temporomandibular Joint Pain and Trismus Following Head and Neck Cancer.","journal_abbr":"Ann Rehabil Med","authors":["Elgohary HM","Eladl HM","Soliman AH","et al."],"date":"2018-12-28","year":2018,"doi":"10.5535/arm.2018.42.6.846","pmcid":"PMC6325320","license":"cc by-nc","oa":true,"cited_by":20,"curated":false,"type":"autre","level":0,"ctx":[],"l1":"The LIUS and TET are more effective than LLLT and/or TET in reducing TMJ pain and trismus following HNC.","kw":"Head and neck neoplasms Lasers Temporomandibular joint Trismus Ultrasonics"},{"pmid":"30591412","title":"Clinical and scientific recommendations for the use of photobiomodulation therapy in exercise performance enhancement and post-exercise recovery: current evidence and future directions.","journal_abbr":"Braz J Phys Ther","authors":["Leal-Junior ECP","Lopes-Martins RÁB","Bjordal JM"],"date":"2018-12-23","year":2018,"doi":"10.1016/j.bjpt.2018.12.002","pmcid":"PMC6546960","cited_by":63,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["performance","récupération"],"l1":"It is important to stress that the recommendations of this masterclass article are based on most recent systematic reviews with meta-analysis and RCTs published in this research field. Future guidelines must follow the same direction and…","kw":"Light emitting diodes therapy Low-level laser therapy Phototherapy Rehabilitation Sports Athletic Performance Exercise Humans Low-Level Light Therapy Photothera"},{"pmid":"30506108","title":"Low-Level Laser Therapy Prevents Treadmill Exercise-Induced Progression of Arthrogenic Joint Contracture Via Attenuation of Inflammation and Fibrosis in Remobilized Rat Knees.","journal_abbr":"Inflammation","authors":["Kaneguchi A","Ozawa J","Minamimoto K","et al."],"date":"2018-12-04","year":2018,"doi":"10.1007/s10753-018-0941-1","cited_by":22,"curated":false,"type":"preclinical","level":5,"ctx":["performance","populations"],"pre":"vivo","l1":"Additional LLLT and exercise intervention did not further reduce total contracture, but LLLT suppressed the progression of arthrogenic contracture caused by ambulation and treadmill exercise. Therefore, exercise with LLLT in the early…","kw":"exercise fibrosis inflammation joint contracture low-level laser therapy remobilization Animals Contracture Disease Progression Fibrosis Inflammation Knee Joint"},{"pmid":"30328526","title":"Modulation of exercise-induced muscular damage and hyperalgesia by different 630 nm doses of light-emitting diode therapy (LEDT) in rats.","journal_abbr":"Lasers Med Sci","authors":["Vasconcelos AB","Nampo FK","Molina JC","et al."],"date":"2018-10-17","year":2018,"doi":"10.1007/s10103-018-2655-x","cited_by":6,"curated":false,"type":"preclinical","level":5,"ctx":["récupération"],"nm":[630],"pre":"vivo","l1":"Also, LEDT (4.2 J/cm2) and LEDT (10.0 J/cm2) groups showed less immunostaining for TNF-α in macrophages or areas with necrosis of muscle fibers compared to the PR group. LEDT (4.2 J/cm2, 6.3 J)-reduced muscle inflammation and nociception…","kw":"Inflammation Light-emitting diode Pain Phototherapy Physical exercise Skeletal muscle Animals Creatine Kinase Dose-Response Relationship, Radiation Edema Hypera"},{"pmid":"30264179","title_fr":"Laser et activation électrique du quadriceps dans l'insuffisance cardiaque","type":"rct","level":2,"pop":"adulte","ctx":["populations"],"aim":"prévention","mode":["laser"],"nm":[850],"n":null,"effect":"neutre","theme":"Sujets âgés & malades chroniques","l1":"Une séance de laser ne réduit pas la fatigue du quadriceps chez l'insuffisant cardiaque.","l2":"—","l3":{"points":["—"],"limites":["Séance unique."],"pratique":"—"},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Surface electromyography after lower level laser therapy application on skeletal muscles in individuals with heart failure.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Delacoste FBC","Sonza A","Mochizuki L","et al."],"date":"2018-09-27","year":2018,"week":"2018-S39","doi":"10.1007/s10103-018-2611-9","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":0,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"The purpose of this study was to investigate the effects of low-level laser therapy (LLLT) applied before a fatigue protocol through the effects on the electrical activation in the quadriceps muscle in patients with HF. Fourteen patients with the diagnosis of heart failure (HF) were selected for this double-blind, crossover type clinical trial. These participants have attended to a familiarization, LLLT, and placebo sessions, totaling three visits. The LLLT was applied in the quadriceps muscle (850 nm, 5 J per diode). The fatigue protocol consisted of concentric and eccentric isokinetic contractions (cc/ec) until exhaustion or up to 50 cc/ec. The muscular fatigue was evaluated with surface electromyography, by the analysis of integral, median frequency, and entropy. Only one application of LLLT is not able to decrease skeletal muscle activation in patients with HF. There was no reduction of muscle fatigue among the proposed protocols. Single LLLT session has no effect on the reduction of skeletal muscle fatigue in patients with HF."}],"keywords":["Electromyography","Entropy","Heart failure","Low-level laser therapy"]},{"pmid":"30264178","title_fr":"PBM avant les matchs de futsal : temps de jeu et récupération","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser","LED"],"nm":[640,875,905],"n":null,"effect":"favorable","theme":"Performance musculaire","l1":"Chez des joueurs de futsal de haut niveau, la PBM avant le match augmente le temps passé sur le terrain et accélère la récupération.","l2":"Essai croisé randomisé en triple aveugle contre placebo.","l3":{"points":["Conditions de match réelles."],"limites":["Distance parcourue inchangée."],"pratique":"Préconditionnement utile."},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Photobiomodulation therapy before futsal matches improves the staying time of athletes in the court and accelerates post-exercise recovery.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["De Marchi T","Leal-Junior ECP","Lando KC","et al."],"date":"2018-09-27","year":2018,"week":"2018-S39","doi":"10.1007/s10103-018-2643-1","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":29,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"This study aimed to analyze PBMT effects on futsal player's performance and recovery in a non-controlled field environment. It is a randomized, triple-blinded, placebo-controlled, crossover clinical trial. The research included six professional athletes and in each match phototherapy treatments were performed before matches (40 minutes), blood samples were collected before treatments, and samples immediately after the end of the matches and 48 h after. Furthermore, videos were analyzed to quantify the time athletes spent on the pitch and the distance they covered. PBMT was performed at 17 sites of each lower limb (40 mins before matches), employing a cluster with 12 diodes (4 laser diodes of 905 nm, 4 LEDs of 875 nm, and 4 LEDs of 640 nm, 30 J per site). The performance of the athlete could be quantified considering the time on the pitch and the distance covered; the biochemical markers evaluated were creatine kinase, lactate dehydrogenase, blood lactate, and oxidative damage to lipids and proteins. PBMT significantly increased the time of staying in the pitch and a significant improvement in all the biochemical markers evaluated. No statistically significant difference was found for the distance covered. Pre-exercise PBMT can enhance performance and accelerate recovery of high-level futsal players."}],"keywords":["Exercise","Light-emitting diodes","Low-level laser therapy","Phototherapy","Sport"]},{"pmid":"30255449","title_fr":"PBM associant lasers, LED et champ magnétique et capacité d'effort dans la BPCO","type":"rct","level":2,"pop":"adulte","ctx":["populations"],"aim":"traitement","mode":["laser","LED"],"nm":[640,875,905],"n":null,"effect":"favorable","theme":"Sujets âgés & malades chroniques","l1":"Dans la BPCO, une séance de PBM avant l'effort augmente le nombre de marches au test et réduit l'essoufflement et la fatigue des jambes.","l2":"Essai croisé randomisé en triple aveugle.","l3":{"points":["Maladie respiratoire."],"limites":["Effet aigu."],"pratique":"Piste en réhabilitation respiratoire."},"em":["super"],"pre":"","nm_auto":true,"topic":"sport","title":"Acute effects of photobiomodulation therapy (PBMT) combining laser diodes, light-emitting diodes, and magnetic field in exercise capacity assessed by 6MST in patients with COPD: a crossover, randomized, and triple-blinded clinical trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Miranda EF","Diniz WA","Gomes MVN","et al."],"date":"2018-09-25","year":2018,"week":"2018-S39","doi":"10.1007/s10103-018-2645-z","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":9,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Chronic obstructive pulmonary disease (COPD) is characterized by dyspnea, as well as musculoskeletal and systemic manifestations. Photobiomodulation therapy (PBMT) with use of low-level laser therapy (LLLT) and/or light-emitting diode therapy (LEDT) is an electrophysical intervention that has been found to minimize or delay muscle fatigue. The aim of this study was to evaluate the acute effect of PBMT with combined use of lasers diodes, light-emitting diodes (LEDs), magnetic field on muscle performance, exercise tolerance, and metabolic variables during the 6-minute stepper test (6MST) in patients with COPD. Twenty-one patients with COPD (FEV1 46.3% predicted) completed the 6MST protocol over 2 weeks, with one session per week. PBMT/magnetic field or placebo (PL) was performed before each 6MST (17 sites on each lower limb, with a dose of 30 J per site, using a cluster of 12 diodes 4 × 905 nm super-pulsed laser diodes, 4 × 875 nm infrared LEDs, and 4 × 640 nm red LEDs; Multi Radiance Medical™, Solon, OH, USA). Patients were randomized into two groups before the test according to the treatment they would receive. Assessments were performed before the start of each protocol. The primary outcomes were oxygen uptake and number of steps, and the secondary outcome was perceived exertion (dyspnea and fatigue in the lower limbs). PBMT/magnetic field applied before 6MST significantly increased the number of steps during the cardiopulmonary exercise test when compared to the results with placebo (129.8 ± 10.6 vs 116.1 ± 11.5, p = 0.000). PBMT/magnetic field treatment also led to a lower score for the perception of breathlessness (3.0 [1.0-7.0] vs 4.0 [2.0-8.0], p = 0.000) and lower limb fatigue (2.0 [0.0-5.0] vs 4.0 [0.0-7.0], p = 0.001) compared to that with placebo treatment. This study showed that the combined application of PBMT and magnetic field increased the number of steps during the 6MST and decreased the sensation of dyspnea and lower limb fatigue in patients with COPD."}],"keywords":["6MST","COPD","Light-emitting diode therapy","Low-level laser therapy","Performance","Phototherapy"]},{"pmid":"30765920","title":"Immediate effects of self-myofascial release on latent trigger point sensitivity: a randomized, placebo-controlled trial.","journal_abbr":"Biol Sport","authors":["Wilke J","Vogt L","Banzer W"],"date":"2018-08-31","year":2018,"doi":"10.5114/biolsport.2018.78055","pmcid":"PMC6358529","license":"cc by-nc-nd","oa":true,"cited_by":28,"curated":false,"type":"autre","level":0,"ctx":[],"l1":"Static self_myofascial release using a foam roller might represent an alternative to reduce pressure pain of latent MTrP. Additional research should aim to extend these findings to patients and athletes with myofascial pain syndromes.","kw":"Fascia Foam rolling Myofascial pain Self-massage"},{"pmid":"30096269","title":"Characterization of Skeletal Muscle Strain Lesion Induced by Stretching in Rats: Effects of Laser Photobiomodulation.","journal_abbr":"Photomed Laser Surg","authors":["Ramos L","Marcos RL","Torres-Silva R","et al."],"date":"2018-08-10","year":2018,"doi":"10.1089/pho.2018.4473","cited_by":11,"curated":false,"type":"preclinical","level":5,"ctx":["blessures","populations"],"pre":"vivo","l1":"Laser photobiomodulation reduced skeletal muscle edema as well as cytokines and CRP, leading to a significant reduction in inflammatory markers.","kw":"LLLT inflammation photobiomodulation skeletal muscle strain Animals Disease Models, Animal Low-Level Light Therapy Male Muscle Stretching Exercises Muscle, Skel"},{"pmid":"29992491","title":"PBMT and topical diclofenac as single and combined treatment on skeletal muscle injury in diabetic rats: effects on biochemical and functional aspects.","journal_abbr":"Lasers Med Sci","authors":["Dos Santos LS","Saltorato JC","Monte MG","et al."],"date":"2018-07-10","year":2018,"doi":"10.1007/s10103-018-2580-z","cited_by":9,"curated":false,"type":"preclinical","level":5,"ctx":["blessures","populations"],"nm":[830],"em":["cw"],"pre":"vivo","l1":"In addition, we observed that PBMT + diclofenac and PBMT alone showed significant improvement compared with injury and diclofenac groups in functional analysis at all time points. The results indicate that PBMT alone or in combination…","kw":"Diabetes mellitus Low-level laser therapy Photobiomodulation therapy Rats Skeletal muscle injury Topical nonsteroidal anti-inflammatory drug Administration, Top"},{"pmid":"29952693","title":"The Effectiveness of Photobiomodulation Therapy Versus Cryotherapy for Skeletal Muscle Recovery: A Critically Appraised Topic.","journal_abbr":"J Sport Rehabil","authors":["Fisher SR","Rigby JH","Mettler JA","et al."],"date":"2018-06-29","year":2018,"doi":"10.1123/jsr.2017-0359","cited_by":8,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["récupération"],"l1":"Shorter recovery times and increased muscle performance can be seen 24 to 96 hours following PBMT application. Strength of Recommendation: Based on consistent findings from all 5 studies, there is grade B evidence to support the use of…","kw":"cold therapy cold-water immersion therapy laser therapy light therapy post-exercise Athletes Biomarkers Cryotherapy Exercise Humans Low-Level Light Therapy"},{"pmid":"29933277","title_fr":"Photothérapie et créatine kinase selon le type d'exercice : méta-analyse","type":"ma","level":1,"pop":"adulte","ctx":["récupération"],"aim":"prévention","mode":["laser","LED"],"nm":[],"n":null,"effect":"favorable","theme":"Récupération & courbatures","l1":"La photothérapie réduit l'élévation des CK, surtout après un exercice localisé.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Phototherapy on Management of Creatine Kinase Activity in General Versus Localized Exercise: A Systematic Review and Meta-Analysis.","journal":"Clinical journal of sport medicine : official journal of the Canadian Academy of Sport Medicine","journal_abbr":"Clin J Sport Med","authors":["Machado AF","Micheletti JK","Lopes JSS","et al."],"date":"2018-06-23","year":2018,"week":"2018-S25","doi":"10.1097/JSM.0000000000000606","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":16,"pub_types":["Meta-Analysis","Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"OBJECTIVE","text":"The main focus of this systematic review was to determine the efficacy of phototherapy in the management of creatine kinase (CK) activity after exercise and furthermore to identify for which exercise model protocol phototherapy provides the best results."},{"label":"DESIGN","text":"Meta-analysis comparing phototherapy with a control condition."},{"label":"SETTING","text":"The MEDLINE, EMBASE, SPORTDiscus, PEDro, and CENTRAL databases were searched from their earliest records to October 03, 2016. Data were pooled in a meta-analysis and described as standardized mean difference (SMD) with 95% confidence intervals (CIs) using a random effects model."},{"label":"PARTICIPANTS","text":"Healthy subjects (no restrictions were applied, eg, age, sex, and exercise level)."},{"label":"INTERVENTION","text":"Phototherapy (low-level laser therapy and/or light-emitting diode therapy) before or after exercise and a placebo or control condition."},{"label":"MAIN OUTCOME MEASURES","text":"Creatine kinase activity (no restriction to any analysis, eg, serum, plasma, or capillary blood)."},{"label":"RESULTS","text":"Fourteen studies were included for review. The results revealed that phototherapy has a more positive effect than control condition in management of CK activity [SMD = 0.77, 95% CI (0.32 to 1.22); P = 0.0007; I = 72%]. In exploratory analysis, the results showed that phototherapy was effective only in the exercise protocol with localized exercise with large effect size [localized exercise: SMD = 0.89, 95% CI (0.26 to 1.51); P = 0.0002; I = 76%; general exercise: SMD = 0.61, 95% CI (-0.05 to 1.26); P = 0.07; I = 67%]."},{"label":"CONCLUSIONS","text":"The available evidence suggest that phototherapy has beneficial effects on the management of CK activity and demonstrate a possible relationship based on damage caused by exercise, providing a greater effect in studies that used localized exercise."}],"keywords":[]},{"pmid":"29748911","title":"Patient education and rehabilitation after hip arthroplasty in an Italian spa center: a pilot study on its feasibility.","journal_abbr":"Int J Biometeorol","authors":["Musumeci A","Pranovi G","Masiero S"],"date":"2018-05-11","year":2018,"doi":"10.1007/s00484-018-1548-9","cited_by":17,"pub_types":["Clinical Trial"],"curated":false,"type":"nrct","level":3,"ctx":[],"l1":"After total hip arthroplasty, patients who underwent an intensive post-acute multimodal rehabilitation program showed an improvement in motor and functional recovery and a positive impact on quality of life. Therefore, we believe that the…","kw":"Activity Arthroplasties Educational Exercise Hip replacement Hydrokinesitherapy Aged Aged, 80 and over Arthroplasty, Replacement, Hip Balneology Exercise Therap"},{"pmid":"29707756","title":"Comment on \"Photobiomodulation delays the onset of skeletal muscle fatigue in a dose-dependent manner\".","journal_abbr":"Lasers Med Sci","authors":["De Marchi T"],"date":"2018-04-30","year":2018,"doi":"10.1007/s10103-018-2504-y","pub_types":["Letter","Comment"],"curated":false,"type":"letter","level":0,"ctx":["récupération"],"l1":"","kw":"Muscle Contraction Muscle Fatigue Muscle, Skeletal"},{"pmid":"29696446","title":"Photobiomodulation effects on mRNA levels from genomic and chromosome stabilization genes in injured muscle.","journal_abbr":"Lasers Med Sci","authors":["da Silva Neto Trajano LA","Trajano ETL","da Silva Sergio LP","et al."],"date":"2018-04-26","year":2018,"doi":"10.1007/s10103-018-2510-0","cited_by":8,"curated":false,"type":"preclinical","level":5,"ctx":["blessures"],"nm":[904],"pre":"vivo","l1":"Data show that photobiomodulation reduces the mRNA levels from ATM and p53, as well reduces mRNA levels from TRF1 and TRF2 at 25 and 75 mW in injured skeletal muscle. In conclusion, photobiomodulation alters mRNA relative levels from…","kw":"DNA Laser Muscle Wistar rats Animals Ataxia Telangiectasia Mutated Proteins Chromosomes, Mammalian Genome Low-Level Light Therapy Male"},{"pmid":"29578836","title":"Protective effects of photobiomodulation against resistance exercise-induced muscle damage and inflammation in rats.","journal_abbr":"J Sports Sci","authors":["de Oliveira HA","Antonio EL","Silva FA","et al."],"date":"2018-03-26","year":2018,"doi":"10.1080/02640414.2018.1457419","cited_by":16,"curated":false,"type":"preclinical","level":5,"ctx":["performance","récupération"],"pre":"vivo","l1":"These data indicate that LLLT prior to or post resistance exercise can reduce muscle damage and inflammation, resulting in muscle recovery improvement. We attempted to determine an ideal LLLT dose for suitable results, wherein 4J…","kw":"Inflammation laser muscle recovery phototherapy strength training Animals Biomarkers Creatine Kinase Cytokines Female Inflammation"},{"pmid":"29546618","title":"LED session prior incremental step test enhance VO2max in running.","journal_abbr":"Lasers Med Sci","authors":["Mezzaroba PV","Pessôa Filho DM","Zagatto AM","et al."],"date":"2018-03-15","year":2018,"doi":"10.1007/s10103-018-2475-z","cited_by":16,"pub_types":["Clinical Trial"],"curated":false,"type":"nrct","level":3,"ctx":["performance"],"l1":"It is concluded that LED sessions prior to exercise modify cardiorespiratory response by affecting running tolerance during the incremental step test, metabolite clearance, and RPE. Therefore, LED could be used as a prior exercise…","kw":"Aerobic metabolism Blood lactate Cardiorespiratory Ergogenic Phototherapy Adult Exercise Exercise Test Humans Light Male"},{"pmid":"29455305","title_fr":"PBM 904 nm et fatigue musculaire chez la jeune femme","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser"],"nm":[904],"n":null,"effect":"favorable","theme":"Performance musculaire","l1":"La PBM 904 nm réduit la fatigue et augmente la performance musculaire de jeunes femmes actives, sans effet sur les lactates.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":["pulse"],"pre":"","topic":"sport","title":"Photobiomodulation (PBM) therapy at 904 nm mitigates effects of exercise-induced skeletal muscle fatigue in young women.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Toma RL","Oliveira MX","Renno ACM","et al."],"date":"2018-02-17","year":2018,"week":"2018-S07","doi":"10.1007/s10103-018-2454-4","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":26,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Muscle fatigue is a process influenced by several mechanisms such as concentration of metabolic substrates, changes in blood flow, and increases in reactive oxygen species that impair contractile muscle function. In this context, photobiomodulation has been investigated for preventing muscle fatigue, with reports of positive effects on muscle performance. This study aimed to investigate the effects of 904-nm LASER photobiomodulation on rectus femoris muscle performance in young women. Eighteen young women participated in a randomized, participant and assessor-blinded crossover trial with placebo control. Active LASER (904 nm, 60 mW, 250 Hz, 3.6 J per diode, total dose of 129.6 J) intervention was applied prior to an isokinetic fatigue protocol consisting of a set of 60 concentric quadricep contractions at a constant dynamometer angular velocity of 180°/s. Compared to placebo, LASER photobiomodulation significantly reduced muscle fatigue across a range of indicators including reduced ratings of perceived exertion (P = 0.0139), and increased electromyographic fatigue index (EFI) (P = 0.005). The isokinetic dynamometer performance analysis demonstrated that LASER photobiomodulation increased peak torque (P = 0.04), time to peak torque (P = 0.042), total work (P = 0.032), average power (P = 0.0007), and average peak torque (P = 0.019) between both experimental conditions. No significant difference was observed for work fatigue index (P = 0.29) or for lactate concentration (P > 0.05). Photobiomodulation at 904 nm was effective in reducing fatigue levels and increasing muscle performance in young active women but had no effect on lactate levels."}],"keywords":["Electromyography","Lactate","Laser","Muscle fatigue","Muscle performance","Photobiomodulation therapy"]},{"pmid":"29228289","title":"Clinical Practice Guideline for Physical Therapy Assessment and Treatment in Patients With Nonspecific Neck Pain.","journal_abbr":"Phys Ther","authors":["Bier JD","Scholten-Peeters WGM","Staal JB","et al."],"date":"2017-12-12","year":2017,"doi":"10.1093/ptj/pzx118","cited_by":181,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"autre","level":0,"ctx":["populations"],"l1":"The physical therapist is advised not to use dry needling, low-level laser, electrotherapy, ultrasound, traction, and/or a cervical collar.In case of a delayed/deviant recovery with clear and/or dominant psychosocial prognostic factors…","kw":"Exercise Therapy Humans Manipulation, Spinal Neck Pain Physical Examination Practice Guidelines as Topic"},{"pmid":"29177980","title_fr":"LED sur le membre inférieur homolatéral ou controlatéral : répétitions et réponse cardiaque","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["LED"],"nm":[],"n":null,"effect":"mitigé","theme":"Performance musculaire","l1":"La LED n'améliore la performance que sur le membre irradié, sans effet sur les lactates ni la réponse cardiaque.","l2":"—","l3":{"points":["Effet local."],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Cardiac autonomic responses and number of repetitions maximum after LED irradiation in the ipsilateral and contralateral lower limb.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Ferreira Junior A","Schamne JC","de Moraes SMF","et al."],"date":"2017-11-24","year":2017,"week":"2017-S47","doi":"10.1007/s10103-017-2391-7","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":8,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"The aim of this study was to verify the maximum number of repetitions, fatigue index, blood lactate concentration ([Lac]), and cardiac autonomic responses after LED irradiation (LEDI) in the ipsilateral and contralateral limb. Twelve male subjects (22.0 ± 3.86 years; weight 82.94 ± 12.58 kg; height 1.77 ± 0.05 m), physically active, took part in this study. The subjects underwent a one repetition maximum (1RM) test and performed four randomly experimental sessions in the horizontal leg press exercise, which consisted in four sets of maximum repetitions at 80% of 1RM. The subjects performed two experimental sessions applying LED active or placebo on ipsilateral limb and two experimental sessions applying LED active or placebo on contralateral limb prior exercise and in the interval of sets on quadriceps and hamstrings muscles. A number of repetitions and fatigue index were verified. [Lac] and heart rate variability (HRV) were collected during post-exercise recovery and analyzed. It was observed that active LEDI promoted an increase in maximal number of repetitions (LEDI = 44.4 ± 9.0 vs placebo = 39.9 ± 11.4; p < 0.05) and decreases the fatigue index (LEDI = 34.3 ± 21.8% vs placebo = 50.0 ± 26.6%; p < 0.05) comparing to placebo situation, only in the ipsilateral application. There were no differences on [Lac] and in HRV parameters comparing LEDI vs placebo on post-exercise recovery in both applications (p > 0.05). The LEDI improves performance only in the ipsilateral application, but there were no differences on [Lac] and cardiac autonomic responses after exercise for both the applications."}],"keywords":["Heart rate variability","Muscle fatigue","Performance","Photobiomodulation"]},{"pmid":"29119418","title_fr":"Laser et cinétique de la VO2 chez le cycliste de compétition","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser"],"nm":[],"n":null,"effect":"favorable","theme":"Performance musculaire","l1":"Le laser accélère la cinétique de la VO2 chez le cycliste, un mécanisme possible de son effet ergogène.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Low-level laser therapy improves the VO2 kinetics in competitive cyclists.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Lanferdini FJ","Krüger RL","Baroni BM","et al."],"date":"2017-11-09","year":2017,"week":"2017-S45","doi":"10.1007/s10103-017-2347-y","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":23,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Some evidence supports that low-level laser therapy (LLLT) reduces neuromuscular fatigue, so incrementing sports performance. A previous randomized controlled trial of our group showed increased exercise tolerance in male competitive cyclists treated with three different LLLT doses (3, 6, and 9 J/diode; or 135, 270, and 405 J/thigh) before time-to-exhaustion cycling tests. Now, the present study was designed to evaluate the effects of these LLLT doses on the VO2 kinetics of athletes during cycling tests. Twenty male competitive cyclists (29 years) participated in a crossover, randomized, double-blind, and placebo-controlled trial. On the first day, the participants performed an incremental cycling test to exhaustion to determine maximal oxygen uptake (VO2MAX) and maximal power output (POMAX), as well as a familiarization with the time-to-exhaustion test. In the following days (2 to 5), all participants performed time-to-exhaustion tests at POMAX. Before the exhaustion test, different doses of LLLT (3, 6, and 9 J/diode; or 135, 270, and 405 J/thigh, respectively) or placebo were applied bilaterally to the quadriceps muscle. All exhaustion tests were monitored online by an open-circuit spirometry system in order to analyze the VO2 amplitude, VO2 delay time, time constant (tau), and O2 deficit. Tau and O2 deficit were decreased with LLLT applications compared to the placebo condition (p < 0.05). No differences (p > 0.05) were found between the experimental conditions for VO2 amplitude and VO2 delay time. In conclusion, LLLT decreases tau and O2 deficit during time-to-exhaustion tests in competitive cyclists, and these changes in VO2 kinetics response can be one of the possible mechanisms to explain the ergogenic effect induced by LLLT."}],"keywords":["Cycling","Phototherapy","Sport performance","Time-to-exhaustion","VO2 kinetics"]},{"pmid":"29099680","title_fr":"PBM 810 nm avant l'effort : quelle puissance optimale ?","type":"rct","level":2,"pop":"adulte","ctx":["récupération"],"aim":"prévention","mode":["laser"],"nm":[810],"n":28,"effect":"favorable","theme":"Récupération & courbatures","l1":"Chez 28 footballeurs, 100 mW par diode donnent les meilleurs résultats sur la performance et la récupération ; plus de puissance n'est pas mieux.","l2":"—","l3":{"points":["Puissance optimale."],"limites":["—"],"pratique":"100 mW par diode."},"em":[],"pre":"","topic":"sport","title":"Pre-Exercise Infrared Photobiomodulation Therapy (810 nm) in Skeletal Muscle Performance and Postexercise Recovery in Humans: What Is the Optimal Power Output?","journal":"Photomedicine and laser surgery","journal_abbr":"Photomed Laser Surg","authors":["de Oliveira AR","Vanin AA","Tomazoni SS","et al."],"date":"2017-11-04","year":2017,"week":"2017-S44","doi":"10.1089/pho.2017.4343","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":40,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"BACKGROUND","text":"Photobiomodulation therapy (PBMT) has recently been used to alleviate postexercise muscle fatigue and enhance recovery, demonstrating positive results. A previous study by our research group demonstrated the optimal dose for an infrared wavelength (810 nm), but the outcomes could be optimized further with the determination of the optimal output power."},{"label":"OBJECTIVE","text":"The aim of the present study was to evaluate the effects of PBMT (through low-level laser therapy) on postexercise skeletal muscle recovery and identify the best output power."},{"label":"MATERIALS AND METHODS","text":"A randomized, placebo-controlled double-blind clinical trial was conducted with the participation of 28 high-level soccer players. PBMT was applied before the eccentric contraction protocol with a cluster with five diodes, 810 nm, dose of 10 J, and output power of 100, 200, 400 mW per diode or placebo at six sites of knee extensors. Maximum isometric voluntary contraction (MIVC), delayed onset muscle soreness (DOMS) and biochemical markers related to muscle damage (creatine kinase and lactate dehydrogenase), inflammation (IL-1β, IL-6, and TNF-α), and oxidative stress (catalase, superoxide dismutase, carbonylated proteins, and thiobarbituric acid) were evaluated before isokinetic exercise, as well as at 1 min and at 1, 24, 48, 72, and 96 h, after the eccentric contraction protocol."},{"label":"RESULTS","text":"PBMT increased MIVC and decreased DOMS and levels of biochemical markers (p < 0.05) with the power output of 100 and 200 mW, with better results for the power output of 100 mW."},{"label":"CONCLUSIONS","text":"PBMT with 100 mW power output per diode (500 mW total) before exercise achieves best outcomes in enhancing muscular performance and postexercise recovery. Another time it has been demonstrated that more power output is not necessarily better."}],"keywords":["exercise performance","parameter optimization","photobiomodulation therapy","phototherapy","postexercise recovery"]},{"pmid":"29101708","title_fr":"Effet dose de la PBM sur l'économie neuromusculaire en course","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser","LED"],"nm":[670,850,880,950],"n":18,"effect":"favorable","theme":"Performance musculaire","l1":"Chez 18 coureurs, la PBM améliore l'économie neuromusculaire ; la meilleure dose est 15 J par site (420 J au total).","l2":"—","l3":{"points":["Dose optimale."],"limites":["—"],"pratique":"—"},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Dose-response effect of photobiomodulation therapy on neuromuscular economy during submaximal running.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Dellagrana RA","Rossato M","Sakugawa RL","et al."],"date":"2017-11-03","year":2017,"week":"2017-S44","doi":"10.1007/s10103-017-2378-4","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":19,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"The purpose of this study was to verify the photobiomodulation therapy (PBMT) effects with different doses on neuromuscular economy during submaximal running tests. Eighteen male recreational runners participate in a randomized, double-blind, and placebo-controlled trial, which each participant was submitted to the same testing protocol in five conditions: control, placebo, and PBMT with doses of 15, 30, and 60 J per site (14 sites in each lower limb). The submaximal running was performed at 8 and 9 km h-1 during 5 min for each velocity. Muscle activation of the vastus lateralis (VL), vastus medialis (VM), rectus femoris (RF), biceps femoris (BF), and gastrocnemius lateralis (GL) was collected during the last minute of each running test. The root mean square (RMS) was normalized by maximal isometric voluntary contraction (MIVC) performed a priori in an isokinetic dynamometer. The RMS sum of all muscles (RMSLEG) was considered as main neuromuscular economy parameter. PBMT with doses of 15, 30, and 60 J per site [33 diodes = 5 lasers (850 nm), 12 LEDs (670 nm), 8 LEDs (880 nm), and 8 LEDs (950 nm)] or placebo applications occurred before running tests. For the statistical analysis, the effect size was calculated. Moreover, a qualitative inference was used to determine the magnitude of differences between groups. Peak torque and RMS during MIVCs showed small effect sizes. According to magnitude-based inference, PBMT with dose of 15 J per site showed possibly and likely beneficial effects on neuromuscular economy during running at 8 and 9 km h-1, respectively. On other hand, PBMT with doses of 30 and 60 J per site showed possible beneficial effects only during running at 9 km h-1. We concluded that PBMT improve neuromuscular economy and the best PBMT dose was 15 J per site (total dose of 420 J)."}],"keywords":["Electromyography","Ergogenic aid","Light-emitting diodes therapy","Low-level laser therapy"]},{"pmid":"29090398","title_fr":"PBM, performance et fatigue musculaire chez le sujet sain : méta-analyse","type":"ma","level":3,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser","LED"],"nm":[655,950],"n":null,"effect":"favorable","theme":"Performance musculaire","l1":"La PBM améliore la performance et réduit la fatigue ; doses efficaces : 20 à 60 J pour les petits groupes musculaires, 60 à 300 J pour les grands, jusqu'à 200 mW par diode.","l2":"Revue systématique avec méta-analyse.","l3":{"points":["Repères de dose précis."],"limites":["Paramètres hétérogènes."],"pratique":"Référence de dosage."},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Photobiomodulation therapy for the improvement of muscular performance and reduction of muscular fatigue associated with exercise in healthy people: a systematic review and meta-analysis.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Vanin AA","Verhagen E","Barboza SD","et al."],"date":"2017-10-31","year":2017,"week":"2017-S44","doi":"10.1007/s10103-017-2368-6","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":129,"pub_types":["Meta-Analysis","Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Researches have been performed to investigate the effects of phototherapy on improving performance and reduction of muscular fatigue. However, a great variability in the light parameters and protocols of the trials are a concern to establish the efficacy of this therapy to be used in sports or clinic. The aim of this study is to investigate the effectiveness, moment of application of phototherapy within an exercise protocol, and which are the parameters optimally effective for the improvement of muscular performance and the reduction of muscular fatigue in healthy people. Systematic searches of PubMed, PEDro, Cochrane Library, EMBASE, and Web of Science databases were conducted for randomized clinical trials to March 2017. Analyses of risk of bias and quality of evidence of the included trials were performed, and authors were contacted to obtain any missing or unclear information. We included 39 trials (861 participants). Data were reported descriptively through tables, and 28 trials were included in meta-analysis comparing outcomes to placebo. Meta-analysis was performed for the variables: time until reach exhaustion, number of repetitions, isometric peak torque, and blood lactate levels showing a very low to moderate quality of evidence and some effect in favor to phototherapy. Further investigation is required due the lack of methodological quality, small sample size, great variability of exercise protocols, and phototherapy parameters. In general, positive results were found using both low-level laser therapy and light-emitting diode therapy or combination of both in a wavelength range from 655 to 950 nm. Most of positive results were observed with an energy dose range from 20 to 60 J for small muscular groups and 60 to 300 J for large muscular groups and maximal power output of 200 mW per diode."}],"keywords":["Exercise","Fatigue","Light emitting diode","Low-level light therapy","Performance","Phototherapy"]},{"pmid":"29023221","title":"Evaluation of the Effect of Phototherapy in Patients with Mandibular Fracture on Mandibular Dynamics, Pain, Edema, and Bite Force: A Pilot Study.","journal_abbr":"Photomed Laser Surg","authors":["Lauriti L","de Cerqueira Luz JG","Agnelli Mesquita-Ferrari R","et al."],"date":"2017-10-12","year":2017,"doi":"10.1089/pho.2017.4334","cited_by":12,"pub_types":["Evaluation Study"],"curated":false,"type":"autre","level":0,"ctx":["récupération","populations"],"nm":[660],"l1":"The findings suggest improvements in the laser group in comparison with the sham group with regard to mandibular dynamics, a reduction in postoperative facial swelling, a reduction in pain, and an increase in bite force.","kw":"mandibular dynamics mandibular fracture muscle fatigue phototherapy Adolescent Adult Bite Force Cohort Studies Edema Female"},{"pmid":"28980210","title":"Photobiomodulation Therapy Improves Acute Inflammatory Response in Mice: the Role of Cannabinoid Receptors/ATP-Sensitive K+ Channel/p38-MAPK Signalling Pathway.","journal_abbr":"Mol Neurobiol","authors":["Neves LMS","Gonçalves ECD","Cavalli J","et al."],"date":"2017-10-04","year":2017,"doi":"10.1007/s12035-017-0792-z","cited_by":34,"curated":false,"type":"preclinical","level":5,"ctx":[],"nm":[660],"pre":"vivo","l1":"Thus, cannabinoid receptors and, possibly, the endocannabinoid system, represent an important site of action of PBM that opens the possibility of complementary and nonpsychotropic therapeutic interventions in clinical practice. Graphical…","kw":"Cannabinoid receptors Inflammation Laser Phototherapy Animals Carrageenan Cytokines Edema Hyperalgesia Immunomodulation"},{"pmid":"28931981","title":"Immunomodulatory effects of two different physical therapy modalities in patients with chronic obstructive pulmonary disease.","journal_abbr":"J Phys Ther Sci","authors":["Mehani SHM"],"date":"2017-09-15","year":2017,"doi":"10.1589/jpts.29.1527","pmcid":"PMC5599814","license":"cc by-nc-nd","oa":true,"cited_by":13,"curated":false,"type":"autre","level":0,"ctx":["populations"],"l1":"[Conclusion] Both inspiratory muscle training and low level laser therapy are effective physical therapy modalities in promoting immune disturbances. The results also supported the superior role of LLLT over IMT in managing immune…","kw":"Immunity Inspiratory muscle training Low level laser therapy"},{"pmid":"28979160","title":"Preconditioning by light-load eccentric exercise is equally effective as low-level laser therapy in attenuating exercise-induced muscle damage in collegiate men.","journal_abbr":"J Pain Res","authors":["Nausheen S","Moiz JA","Raza S","et al."],"date":"2017-09-11","year":2017,"doi":"10.2147/JPR.S139615","pmcid":"PMC5602376","license":"cc by-nc","oa":true,"cited_by":9,"curated":false,"type":"autre","level":0,"ctx":["performance","récupération"],"l1":"This study indicated that light-load eccentric exercise confers similar protective effect against subsequent maximal eccentric exercise as LLLT. Both the treatments could be used reciprocally based on the patient preference, costs, and…","kw":"creatine kinase delayed onset muscle soreness elbow flexors isometric strength lactate dehydrogenase repeated bout effect"},{"pmid":"28986000","title":"The effect of light-emitting diode (590/830 nm)-based low-level laser therapy on posttraumatic edema of facial bone fracture patients.","journal_abbr":"J Craniomaxillofac Surg","authors":["Baek WY","Byun IH","Yun IS","et al."],"date":"2017-09-02","year":2017,"doi":"10.1016/j.jcms.2017.08.027","cited_by":14,"curated":false,"type":"autre","level":0,"ctx":["populations"],"nm":[590,830],"l1":"LED-based LLLT is recently receiving attention worldwide for its cost-effectiveness and large coverage area compared to traditional laser therapy. Recent studies support its effectiveness in various areas such as wound healing, skin…","kw":"Edema Laser Trauma Cost-Benefit Analysis Edema Facial Bones Female Humans Low-Level Light Therapy"},{"pmid":"28665818","title":"Effects of Light-Emitting Diode Therapy on Muscle Hypertrophy, Gene Expression, Performance, Damage, and Delayed-Onset Muscle Soreness: A Case-Control Study With a Pair of Identical Twins.","journal_abbr":"Am J Phys Med Rehabil","authors":["Soares-Caldeira LF","de Paula Ramos S"],"date":"2017-07-01","year":2017,"doi":"10.1097/PHM.0000000000000789","cited_by":1,"pub_types":["Letter","Research Support, Non-U.S. Gov't","Comment"],"curated":false,"type":"letter","level":0,"ctx":["performance","récupération"],"l1":"","kw":"Case-Control Studies Humans Hypertrophy Muscle, Skeletal Myalgia Twins, Monozygotic"},{"pmid":"28644245","title":"Reply to the Letter to the Editor on \"Effects of Light-Emitting Diode Therapy on Muscle Hypertrophy, Gene Expression, Performance, Damage, and Delayed-Onset Muscle Soreness: Case-Control Study With a Pair of Identical Twins\".","journal_abbr":"Am J Phys Med Rehabil","authors":["Ferraresi C","Bertucci D","Schiavinato J","et al."],"date":"2017-06-24","year":2017,"doi":"10.1097/PHM.0000000000000777","pmcid":"PMC5736411","pub_types":["Letter","Comment"],"curated":false,"type":"letter","level":0,"ctx":["performance","récupération"],"l1":"","kw":"Case-Control Studies Humans Hypertrophy Muscle, Skeletal Myalgia Twins, Monozygotic"},{"pmid":"28579190","title":"Effect of low-level laser therapy (LLLT) and light-emitting diodes (LEDT) applied during combined training on performance and post-exercise recovery: protocol for a randomized placebo-controlled trial.","journal_abbr":"Braz J Phys Ther","authors":["Machado AF","Micheletti JK","Vanderlei FM","et al."],"date":"2017-05-20","year":2017,"doi":"10.1016/j.bjpt.2017.05.010","pmcid":"PMC5537481","oa":true,"cited_by":7,"curated":false,"type":"autre","level":0,"ctx":["performance","récupération"],"l1":"This will be the first trial to include phototherapy during training. We believe that this strategy will combine the ergogenic and prophylactic effects in the same session. Furthermore, an application protocol performed after primary…","kw":"Athletic performance Phototherapy Recovery of function Exercise Humans Low-Level Light Therapy Muscle, Skeletal Phototherapy Randomized Controlled Trials as Top"},{"pmid":"28466181","title":"[Low level laser therapy : A narrative literature review on the efficacy in the treatment of rheumatic orthopaedic conditions].","journal_abbr":"Z Rheumatol","authors":["Baltzer AWA","Stosch D","Seidel F","et al."],"date":"2017-05-04","year":2017,"doi":"10.1007/s00393-017-0309-1","cited_by":5,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["performance","blessures"],"l1":"LLLT shows potential as an effective, noninvasive, safe and cost-efficient means to treat and prevent a variety of acute and chronic musculoskeletal conditions. Further randomized controlled studies, however, are required to confirm this…","kw":"Low level laser therapy Muscle regeneration Muscle strength Osteoarthritis Tendinopathy Arthritis, Rheumatoid Fibromyalgia Humans Low-Level Light Therapy Muscle"},{"pmid":"28422520","title_fr":"Laser, performance et fatigue chez le cycliste de compétition","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser"],"nm":[],"n":null,"effect":"favorable","theme":"Performance musculaire","l1":"Le laser améliore la performance et réduit la fatigue chez le cycliste ; 135 J donne les meilleurs résultats.","l2":"—","l3":{"points":["Dose optimale."],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Improvement of Performance and Reduction of Fatigue With Low-Level Laser Therapy in Competitive Cyclists.","journal":"International journal of sports physiology and performance","journal_abbr":"Int J Sports Physiol Perform","authors":["Lanferdini FJ","Bini RR","Baroni BM","et al."],"date":"2017-04-20","year":2017,"week":"2017-S16","doi":"10.1123/ijspp.2016-0187","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":34,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Evidence indicates that low-level laser therapy (LLLT) minimizes fatigue effects on muscle performance. However, the ideal LLLT dosage to improve athletes'performance during sports activities such as cycling is still unclear. Therefore, the goal of this study was to investigate the effects of different LLLT dosages on cyclists'performance in time-to-exhaustion tests. In addition, the effects of LLLT on the frequency content of the EMG signals to assess fatigue mechanisms were examined. Twenty male competitive cyclists participated in a crossover, randomized, double-blind, placebo-controlled trial. They performed an incremental cycling test to exhaustion (on day 1) followed by 4 time-to-exhaustion tests (on days 2-5) at their individual maximal power output. Before each time-to-exhaustion test, different dosages of LLLT (135, 270, and 405 J/thigh, respectively) or placebo were applied at the quadriceps muscle bilaterally. Power output and muscle activation from both lower limbs were recorded throughout the tests. Increased performance in time-to-exhaustion tests was observed with the LLLT-135 J (∼22 s; P < .01), LLLT-270 J (∼13 s; P = .03), and LLLT-405 J (∼13 s; P = .02) compared to placebo (149 ± 23 s). Although LLLT-270 J and LLLT-405 J did not show significant differences in muscle activation compared with placebo, LLLT-135 J led to an increased high-frequency content compared with placebo in both limbs at the end of the exhaustion test (P ≤ .03). In conclusion, LLLT increased time to exhaustion in competitive cyclists, suggesting this intervention as a possible nonpharmacological ergogenic agent in cycling. Among the different dosages, LLLT-135 J seems to promote the best effects."}],"keywords":["athletes","cycling","exhaustion time","phototherapy","spectral properties"]},{"pmid":"28319422","title_fr":"Photothérapie pour la performance et la récupération : comparaison de trois appareils","type":"rct","level":2,"pop":"adulte","ctx":["récupération"],"aim":"prévention","mode":["laser","LED"],"nm":[],"n":40,"effect":"favorable","theme":"Récupération & courbatures","l1":"Chez 40 hommes, l'appareil pulsé de faible puissance donne les meilleurs résultats ; l'appareil continu de forte puissance augmente même les CK.","l2":"Double aveugle contre placebo.","l3":{"points":["Tous les appareils ne se valent pas."],"limites":["—"],"pratique":"—"},"em":["pulse"],"pre":"","topic":"sport","title":"Phototherapy for Improvement of Performance and Exercise Recovery: Comparison of 3 Commercially Available Devices.","journal":"Journal of athletic training","journal_abbr":"J Athl Train","authors":["De Marchi T","Schmitt VM","Danúbia da Silva Fabro C","et al."],"date":"2017-03-20","year":2017,"week":"2017-S12","doi":"10.4085/1062-6050-52.2.09","pmcid":"PMC5455246","license":null,"oa":false,"pdf":null,"cited_by":37,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"CONTEXT","text":"Recent studies suggest the prophylactic use of low-powered laser/light has ergogenic effects on athletic performance and postactivity recovery. Manufacturers of high-powered lasers/light devices claim that these can produce the same clinical benefits with increased power and decreased irradiation time; however, research with high-powered lasers is lacking."},{"label":"OBJECTIVE","text":"To evaluate the magnitude of observed phototherapeutic effects with 3 commercially available devices."},{"label":"DESIGN","text":"Randomized double-blind placebo-controlled study."},{"label":"SETTING","text":"Laboratory."},{"label":"PATIENTS OR OTHER PARTICIPANTS","text":"Forty healthy untrained male participants."},{"label":"INTERVENTION(S)","text":"Participants were randomized into 4 groups: placebo, high-powered continuous laser/light, low-powered continuous laser/light, or low-powered pulsed laser/light (comprising both lasers and light-emitting diodes). A single dose of 180 J or placebo was applied to the quadriceps."},{"label":"MAIN OUTCOME MEASURE(S)","text":"Maximum voluntary contraction, delayed-onset muscle soreness (DOMS), and creatine kinase (CK) activity from baseline to 96 hours after the eccentric exercise protocol."},{"label":"RESULTS","text":"Maximum voluntary contraction was maintained in the low-powered pulsed laser/light group compared with placebo and high-powered continuous laser/light groups in all time points (P < .05). Low-powered pulsed laser/light demonstrated less DOMS than all groups at all time points (P < .05). High-powered continuous laser/light did not demonstrate any positive effects on maximum voluntary contraction, CK activity, or DOMS compared with any group at any time point. Creatine kinase activity was decreased in low-powered pulsed laser/light compared with placebo (P < .05) and high-powered continuous laser/light (P < .05) at all time points. High-powered continuous laser/light resulted in increased CK activity compared with placebo from 1 to 24 hours (P < .05)."},{"label":"CONCLUSIONS","text":"Low-powered pulsed laser/light demonstrated better results than either low-powered continuous laser/light or high-powered continuous laser/light in all outcome measures when compared with placebo. The increase in CK activity using the high-powered continuous laser/light compared with placebo warrants further research to investigate its effect on other factors related to muscle damage."}],"keywords":["high-intensity laser therapy","light-emitting diode therapy","low-level laser therapy","photobiomodulation therapy","skeletal muscle performance"]},{"pmid":"28054262","title_fr":"PBM contre cryothérapie pour la récupération après un effort intense","type":"rct","level":2,"pop":"adulte","ctx":["récupération"],"aim":"traitement","mode":["laser","LED"],"nm":[],"n":40,"effect":"favorable","theme":"Récupération & courbatures","l1":"Chez 40 volontaires, la PBM récupère mieux que la cryothérapie, et la cryothérapie réduit même l'efficacité de la PBM.","l2":"—","l3":{"points":["Double aveugle."],"limites":["—"],"pratique":"Ne pas associer cryothérapie et PBM."},"em":[],"pre":"","topic":"sport","title":"Does photobiomodulation therapy is better than cryotherapy in muscle recovery after a high-intensity exercise? A randomized, double-blind, placebo-controlled clinical trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["De Marchi T","Schmitt VM","Machado GP","et al."],"date":"2017-01-05","year":2017,"week":"2017-S01","doi":"10.1007/s10103-016-2139-9","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":31,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"This study aimed to determine the effectiveness of photobiomodulation therapy (PBMT) and cryotherapy, in isolated and combined forms, as muscle recovery techniques after muscle fatigue-inducing protocol. Forty volunteers were randomly divided into five groups: a placebo group (PG); a PBMT group (PBMT); a cryotherapy group (CG); a cryotherapy-PBMT group (CPG); and a PBMT-cryotherapy group (PCG). All subjects performed four sessions at 24-h intervals, during which they submitted to isometric assessment (MVC) and blood collection in the pre-exercise period, and 5 and 60 min post-exercise, while the muscle fatigue induction protocol occurred after the pre-exercise collections. In the remaining sessions performed 24, 48, and 72 h later, only blood collections and MVCs were performed. A single treatment with PBMT and/or cryotherapy was applied after only 2 min of completing the post-5-min MVC test at the first session. In the intragroup comparison, it was found that exercise led to a significant decrease (p < 0.05) in the production of MVC in all groups. Comparing the results of MVCs between groups, we observed significant increases in the MVC capacity of the PBMT, CPG, and PCG volunteers in comparison with both PG and CG (p < 0.05). We observed a significant decrease in the concentrations of the biochemical markers of oxidative damage (TBARS and PC) in all groups and muscle damage (creatine kinase-CK) in the PBMT, PCG, and CPG compared with the PG (p < 0.01). The clinical impact of these findings is clear because they demonstrate that the use of phototherapy is more effective than the use of cryotherapy for muscle recovery, additionally cryotherapy decreases PBMT efficacy."}],"keywords":["Cryotherapy","High-intensity exercise","Muscle damage","Oxidative stress","Phototherapy"]},{"pmid":"29975834","title":"[MUSCLE FATIGUE: FACTORS OF DEVELOPMENT AND WAYS OF CORRECTION].","journal_abbr":"Fiziol Zh (1994)","authors":["Matvienko TY","Zavodovskyi DA","Nozdrenko DN","et al."],"date":"2017-01-01","year":2017,"doi":"10.15407/fz63.01.095","pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["récupération"],"l1":"The effect of the most common endogenous and exogenous antioxidants in the biochemical processes in muscle fatigue was analyzed. It is shown that biocompatible, non-toxic water-soluble C(60) fullerenes, which possess powerful…","kw":"Acetylcysteine Allopurinol Antioxidants Fullerenes Humans Low-Level Light Therapy"},{"pmid":"28035444","title":"Multimodal vaginal toning for bladder symptoms and quality of life in stress urinary incontinence.","journal_abbr":"Int Urogynecol J","authors":["de la Torre S","Miller LE"],"date":"2016-12-29","year":2016,"doi":"10.1007/s00192-016-3248-5","pmcid":"PMC5514206","license":"cc by","oa":true,"cited_by":10,"pub_types":["Evaluation Study"],"curated":false,"type":"autre","level":0,"ctx":["performance"],"l1":"Multimodal vaginal toning therapy yields clinically meaningful improvements in bladder symptoms, pelvic floor muscle strength, and quality of life in women with SUI.","kw":"Female sexual dysfunction Low-level light Postpartum Stress urinary incontinence Vaginal toning Adult Combined Modality Therapy Female Humans Low-Level Light Th"},{"pmid":"28001756","title":"Transcranial, Red/Near-Infrared Light-Emitting Diode Therapy to Improve Cognition in Chronic Traumatic Brain Injury.","journal_abbr":"Photomed Laser Surg","authors":["Naeser MA","Martin PI","Ho MD","et al."],"date":"2016-12-22","year":2016,"doi":"10.1089/pho.2015.4037","cited_by":62,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["blessures"],"nm":[633,810],"l1":"LED treatments may be performed in the home. Sham-controlled studies with veterans who have cognitive dysfunction from Gulf War Illness, blast TBI, and TBI/PTSD are currently ongoing.","kw":"LED LLLT PBM PTSD TBI TBI treatment Brain Injuries, Traumatic Brain Injury, Chronic Cognition Disorders Humans Low-Level Light Therapy"},{"pmid":"27904977","title":"Erratum to: Effects of low-level laser therapy applied before or after plyometric exercise on muscle damage markers: randomized, double-blind, placebo-controlled trial.","journal_abbr":"Lasers Med Sci","authors":["Fritsch CG","Dornelles MP","Severo-Silveira L","et al."],"date":"2016-12-02","year":2016,"doi":"10.1007/s10103-016-2113-6","cited_by":1,"pub_types":["Published Erratum"],"curated":false,"type":"autre","level":0,"ctx":["récupération"],"l1":"","kw":""},{"pmid":"27874264","title":"Photobiomodulation in human muscle tissue: an advantage in sports performance?","journal_abbr":"J Biophotonics","authors":["Ferraresi C","Huang YY","Hamblin MR"],"date":"2016-11-22","year":2016,"doi":"10.1002/jbio.201600176","pmcid":"PMC5167494","cited_by":105,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["performance","récupération"],"l1":"PBM can increase muscle mass gained after training, and decrease inflammation and oxidative stress in muscle biopsies. We raise the question of whether PBM should be permitted in athletic competition by international regulatory authorities.","kw":"LEDT LLLT creatine kinase delayed onset muscle soreness fatigue photobiomodulation Athletes Athletic Performance Double-Blind Method Humans Inflammation Low-Lev"},{"pmid":"27655326","title_fr":"Laser avant ou après un exercice pliométrique et lésions musculaires","type":"rct","level":2,"pop":"adulte","ctx":["blessures"],"aim":"les deux","mode":["laser"],"nm":[810],"n":null,"effect":"mitigé","theme":"Blessures sportives","l1":"Le laser après un exercice pliométrique réduit l'échogénicité musculaire et peut-être les courbatures, sans limiter la perte de force.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Effects of low-level laser therapy applied before or after plyometric exercise on muscle damage markers: randomized, double-blind, placebo-controlled trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Fritsch CG","Dornelles MP","Severo-Silveira L","et al."],"date":"2016-09-21","year":2016,"week":"2016-S38","doi":"10.1007/s10103-016-2072-y","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":24,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Promising effects of phototherapy on markers of exercise-induced muscle damage has been already demonstrated in constant load or isokinetic protocols. However, its effects on more functional situations, such as plyometric exercises, and when is the best moment to apply this treatment (pre- or post-exercise) remain unclear. Therefore, the purpose of this study was to investigate the effect of low-level laser therapy (LLLT) before or after plyometric exercise on quadriceps muscle damage markers. A randomized, double-blinded, placebo-controlled trial was conducted with 24 healthy men, 12 at pre-exercise treatment group and 12 at post-exercise treatment group. Placebo and LLLT (810 nm, 200 mW per diode, 6 J per diode, 240 J per leg) were randomly applied on right/left knee extensor muscles of each volunteer before/after a plyometric exercise protocol. Muscular echo intensity (ultrasonography images), soreness (visual analogue scale - VAS), and strength impairment (maximal voluntary contraction - MVC) were assessed at baseline, 24, 48, and 72 h post-exercise. Legs treated with LLLT before or after exercise presented significantly smaller increments of echo intensity (values up to 1 %) compared to placebo treatments (increased up to ∼7 %). No significant treatment effect was found for VAS and MVC, although a trend toward better results on LLLT legs have been found for VAS (mean values up to 30 % lesser than placebo leg). In conclusion, LLLT applied before or after plyometric exercise reduces the muscle echo intensity response and possibly attenuates the muscle soreness. However, these positive results were not observed on strength impairment."}],"keywords":["Exercise recovery","Muscle damage","Phototherapy","Quadriceps muscle"]},{"pmid":"27649962","title":"Analysis of photobiomodulation associated or not with platelet-rich plasma on repair of muscle tissue by Raman spectroscopy.","journal_abbr":"Lasers Med Sci","authors":["Ozaki GA","Camargo RC","Koike TE","et al."],"date":"2016-09-20","year":2016,"doi":"10.1007/s10103-016-2067-8","cited_by":4,"curated":false,"type":"preclinical","level":5,"ctx":["blessures"],"pre":"vivo","l1":"It is concluded that either PBM or PRP, and the association of both, was able to reduce the oxidative stress promoted by injury and modulate collagen production at the site of the injury. Furthermore, although both treatments individually…","kw":"Injury Low-level laser therapy Platelet-rich plasma Raman spectroscopy Skeletal muscle Animals Collagen Low-Level Light Therapy Male Muscle, Skeletal Oxidative "},{"pmid":"27638148","title_fr":"Laser et indice de fatigue des fléchisseurs plantaires","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser"],"nm":[],"n":null,"effect":"favorable","theme":"Performance musculaire","l1":"Appliqué avant l'exercice, le laser réduit l'indice de fatigue des muscles du mollet chez le sujet sain.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Low-level laser therapy reduces the fatigue index in the ankle plantar flexors of healthy subjects.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["de Souza CG","Borges DT","de Brito Macedo L","et al."],"date":"2016-09-17","year":2016,"week":"2016-S37","doi":"10.1007/s10103-016-2074-9","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":10,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Low-level laser therapy (LLLT) has been suggested as a resource capable of increasing resistance to fatigue and enhancing muscle performance through its metabolic and photochemical effects. This study evaluated the immediate effects of the application of LLLT on neuromuscular performance of the plantar ankle flexors in healthy subjects through a fatigue-induced protocol. This is a randomized controlled clinical trial, attended by 60 young and physically active volunteers of both genders. The subjects were randomly assigned into three groups, control, placebo, and laser, and underwent a preliminary evaluation of the isokinetic performance of plantar flexors and electromyographic activity of the soleus muscle to ensure homogeneity between groups. After the application of the respective intervention protocols, participants were induced to fatigue by performing 100 isokinetic concentric contractions of ankle plantar flexors at a speed of 90°/s. The dynamometric fatigue index (DFI) and median frequency were recorded during the fatigue protocol for comparison between groups. The group receiving the laser application showed significantly lower dynamometric fatigue index (p = 0.036) when compared to control and placebo groups. In relation to the median frequency during the fatigue test, there was a decrease in all groups, however with no differences between them. We suggest that LLLT being applied prior to exercise can reduce the fatigue index in the ankle plantar flexors of healthy subjects."}],"keywords":["Electromyography","Muscle fatigue","Muscle strength dynamometer"]},{"pmid":"27624781","title_fr":"PBM et/ou cryothérapie pour la récupération musculaire","type":"rct","level":2,"pop":"adulte","ctx":["récupération"],"aim":"traitement","mode":["laser","LED"],"nm":[905],"n":null,"effect":"favorable","theme":"Récupération & courbatures","l1":"La PBM seule est la meilleure modalité de récupération après un effort excentrique intense, avec un retour à l'état de base dès 24 heures.","l2":"La cryothérapie n'apporte rien.","l3":{"points":["Double aveugle."],"limites":["—"],"pratique":"Préférer la PBM à la cryothérapie."},"em":["super"],"pre":"","nm_auto":true,"topic":"sport","title":"Photobiomodulation therapy (PBMT) and/or cryotherapy in skeletal muscle restitution, what is better? A randomized, double-blinded, placebo-controlled clinical trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["de Paiva PR","Tomazoni SS","Johnson DS","et al."],"date":"2016-09-13","year":2016,"week":"2016-S37","doi":"10.1007/s10103-016-2071-z","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":41,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Cryotherapy for post-exercise recovery remains widely used despite the lack of quality evidence. Photobiomodulation therapy (PBMT) studies (with both low-level laser therapy and light-emitting diode therapy) have demonstrated positive scientific evidence to suggest its use. The study aims to evaluate PBMT and cryotherapy as a single or combined treatment on skeletal muscle recovery after eccentric contractions of knee extensors. Fifty healthy male volunteers were recruited and randomized into five groups (PBMT, cryotherapy, cryotherapy + PBMT, PMBT + cryotherapy, or placebo) for a randomized, double-blinded, placebo-controlled trial that evaluated exercise performance (maximum voluntary contraction (MVC)), delayed onset muscle soreness (DOMS), and muscle damage (creatine kinase (CK)). Assessments were performed at baseline; immediately after; and at 1, 24, 48, 72, and 96 h. Comparator treatments was performed 3 min after exercise and repeated at 24, 48, and 72 h. PBMT was applied employing a cordless, portable GameDay™ device (combination of 905 nm super-pulsed laser and 875- and 640-nm light-emitting diodes (LEDs); manufactured by Multi Radiance Medical™, Solon - OH, USA), and cryotherapy by flexible rubber ice packs. PBMT alone was optimal for post-exercise recovery with improved MVC, decreased DOMS, and CK activity (p < 0.05) from 24 to 96 h compared to placebo, cryotherapy, and cryotherapy + PBMT. In the PBMT + cryotherapy group, the effect of PBMT was decreased (p > 0.05) but demonstrated significant improvement in MVC, decreased DOMS, and CK activity (p < 0.05). Cryotherapy as single treatment and cryotherapy + PBMT were similar to placebo (p > 0.05). We conclude that PBMT used as single treatment is the best modality for enhancement of post-exercise restitution, leading to complete recovery to baseline levels from 24 h after high-intensity eccentric contractions."}],"keywords":["Exercise recovery","Light-emitting diodes","Low-level laser therapy","Performance","Phototherapy"]},{"pmid":"27575834","title_fr":"Laser 810 nm avant l'effort chez le footballeur : quelle dose ?","type":"rct","level":2,"pop":"adulte","ctx":["récupération"],"aim":"prévention","mode":["laser"],"nm":[810],"n":28,"effect":"favorable","theme":"Récupération & courbatures","l1":"Chez 28 footballeurs, le laser avant l'effort à 50 J par site augmente la performance et réduit CK et IL-6 ; 30 J est sans effet.","l2":"Pas d'effet sur les courbatures.","l3":{"points":["Dose optimale identifiée."],"limites":["—"],"pratique":"50 J par site avant l'effort."},"em":[],"pre":"","topic":"sport","title":"Pre-Exercise Infrared Low-Level Laser Therapy (810 nm) in Skeletal Muscle Performance and Postexercise Recovery in Humans, What Is the Optimal Dose? A Randomized, Double-Blind, Placebo-Controlled Clinical Trial.","journal":"Photomedicine and laser surgery","journal_abbr":"Photomed Laser Surg","authors":["Aver Vanin A","De Marchi T","Tomazoni SS","et al."],"date":"2016-08-29","year":2016,"week":"2016-S35","doi":"10.1089/pho.2015.3992","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":59,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"AIM","text":"This study aimed to evaluate the medium-term effects of low-level laser therapy (LLLT or photobiomodulation) in postexercise skeletal muscle recovery and performance enhancement and to identify the optimal dose of 810 nm LLLT."},{"label":"MATERIALS AND METHODS","text":"A randomized, double-blind, placebo-controlled trial was performed, with voluntary participation of 28 high-level soccer athletes. We analyzed maximum voluntary contraction (MVC), delayed onset muscle soreness (DOMS), creatine kinase (CK) activity, and interleukin-6 (IL-6) expression. The assessments were performed before exercise protocols, after 1 min, and 1, 24, 48, 72, and 96 h after the end of eccentric exercise protocol used to induce fatigue. LLLT was applied before eccentric exercise protocol with a cluster with five diodes, and dose of 10, 30, or 50 J (200 mW and 810 nm) in six sites of quadriceps."},{"label":"RESULTS","text":"LLLT increased (p < 0.05) MVC from immediately after exercise to 24 h with 50 J dose, and from 24 to 96 h with 10 J dose. Both 10 J then 50 J dose decreased (p < 0.05) CK and IL-6 with better results in favor of 50 J dose. However, LLLT had no effect in decreasing DOMS. No differences (p > 0.05) were found for 30 J dose in any of the outcomes measured."},{"label":"CONCLUSIONS","text":"Pre-exercise LLLT, mainly with 50 J dose, significantly increases performance and improves biochemical markers related to skeletal muscle damage and inflammation."}],"keywords":[]},{"pmid":"27592534","title":"Light-emitting diode therapy in exercise-trained mice increases muscle performance, cytochrome c oxidase activity, ATP and cell proliferation [J. Biophotonics 8, No. 9, 740-754 (2015)].","journal_abbr":"J Biophotonics","authors":["Ferraresi C","Parizotto NA","Pires de Sousa MV","et al."],"date":"2016-07-07","year":2016,"doi":"10.1002/jbio.201680087","cited_by":9,"pub_types":["Published Erratum"],"curated":false,"type":"preclinical","level":5,"ctx":["performance","récupération"],"pre":"vivo","l1":"Biophotonics 8, 740-754 (2015), a statement regarding the approval of some data the authors used is incorrect. This erratum is published to rectify this.","kw":"ATP LEDT LLLT muscle performance muscle recovery"},{"pmid":"27371449","title_fr":"Moment optimal de la photothérapie associée à un programme de musculation","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"—","mode":["laser","LED"],"nm":[640,875,905],"n":null,"effect":"favorable","theme":"Performance musculaire","l1":"La photothérapie appliquée avant l'exercice augmente davantage les gains de force que si elle est appliquée après.","l2":"Double aveugle contre placebo.","l3":{"points":["Timing défini."],"limites":["—"],"pratique":"Avant la séance de musculation."},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"What is the best moment to apply phototherapy when associated to a strength training program? A randomized, double-blinded, placebo-controlled trial : Phototherapy in association to strength training.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Vanin AA","Miranda EF","Machado CS","et al."],"date":"2016-07-01","year":2016,"week":"2016-S26","doi":"10.1007/s10103-016-2015-7","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":58,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"The effects of phototherapy (or photobiomodulation therapy) with low-level laser therapy (LLLT) and/or light-emitting diodes (LEDs) on human performance improvement have been widely studied. Few studies have examined its effect on muscular training and no studies have explored the necessary moment of phototherapy irradiations (i.e., before and/or after training sessions). The aim of this study was to determine the optimal moment to apply phototherapy irradiation when used in association with strength training. Forty-eight male volunteers (age between 18 to 35 years old) completed all procedures in this study. Volunteers performed the strength training protocol where either a phototherapy and/or placebo before and/or after each training session was performed using cluster probes with four laser diodes of 905 nm, four LEDs of 875 nm, and four LEDs of 640 nm-manufactured by Multi Radiance Medical™. The training protocol duration was 12 weeks with assessments of peak torque reached in maximum voluntary contraction test (MVC), load in 1-repetition maximum test (1-RM) and thigh circumference (perimetry) at larger cross-sectional area (CSA) at baseline, 4 weeks, 8 weeks, and 12 weeks. Volunteers from group treated with phototherapy before and placebo after training sessions showed significant (p < 0.05) changes in MVC and 1-RM tests for both exercises (leg extension and leg press) when compared to other groups. With an apparent lack of side effects and safety due to no thermal damage to the tissue, we conclude that the application of phototherapy yields enhanced strength gains when it is applied before exercise. The application may have additional beneficial value in post-injury rehabilitation where strength improvements are needed."}],"keywords":["Light-emitting diode","Low-level laser therapy","Muscle adaptation","Muscle fatigue","Photobiomodulation therapy","Phototherapy"]},{"pmid":"27359205","title":"Identifying Dosage Effect of Light-Emitting Diode Therapy on Muscular Fatigue in Quadriceps.","journal_abbr":"J Strength Cond Res","authors":["Hemmings TJ","Kendall KL","Dobson JL"],"date":"2016-07-01","year":2016,"doi":"10.1519/JSC.0000000000001523","cited_by":19,"pub_types":["Clinical Trial"],"curated":false,"type":"nrct","level":3,"ctx":["récupération"],"l1":"There were no significant differences in blood lactate levels between any of the 4 trials. In conclusion, LEDT had a positive effect on performance when irradiating 6 points on the superficial quadriceps for 60 and 120 seconds before an…","kw":"Adolescent Adult Athletes Double-Blind Method Exercise Female"},{"pmid":"27347569","title":"[The application of electrolaser myostimulation and laserophoresis of biologically active compounds in sports medicine (a review)].","journal_abbr":"Vopr Kurortol Fizioter Lech Fiz Kult","authors":["Khadartsev AA","Fudin NA","Moskvin SV"],"date":"2016-06-28","year":2016,"doi":"10.17116/kurort2016259-67","cited_by":1,"pub_types":["English Abstract","Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"A number of phyto-extracts used for the purpose of laser electrophoresis are characterized. The authors demonstrate the application of the optional versions of this technique in various sports during the training and competition periods.","kw":"Electric Stimulation Therapy Electrochemotherapy Humans Low-Level Light Therapy Sports Medicine"},{"pmid":"27305924","title":"Photobiomodulation delays the onset of skeletal muscle fatigue in a dose-dependent manner.","journal_abbr":"Lasers Med Sci","authors":["Larkin-Kaiser KA","Borsa PA","Baweja HS","et al."],"date":"2016-06-15","year":2016,"doi":"10.1007/s10103-016-1979-7","cited_by":8,"pub_types":["Clinical Trial"],"curated":false,"type":"nrct","level":3,"ctx":["performance","récupération"],"l1":"Our findings show that a 240-J dose of NIR light therapy is efficacious in delaying the onset and extent of muscle fatigue during submaximal isometric positioning tasks. Our findings suggest that NIR light therapy may be used as an…","kw":"Ergogenic Motor output variability Near-infrared Surface electromyography Task failure Adult Cross-Over Studies Double-Blind Method Electromyography Female Huma"},{"pmid":"27272746","title_fr":"Photothérapie pour améliorer la capacité d'effort : méta-analyse","type":"ma","level":1,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser","LED"],"nm":[],"n":null,"effect":"mitigé","theme":"Performance musculaire","l1":"Le laser avant l'effort semble améliorer la capacité d'exercice (répétitions, temps jusqu'à épuisement), mais la qualité des preuves est limitée.","l2":"—","l3":{"points":["—"],"limites":["Preuves limitées."],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Low-level phototherapy to improve exercise capacity and muscle performance: a systematic review and meta-analysis.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Nampo FK","Cavalheri V","Dos Santos Soares F","et al."],"date":"2016-06-07","year":2016,"week":"2016-S23","doi":"10.1007/s10103-016-1977-9","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":36,"pub_types":["Meta-Analysis","Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"","text":"The aim of this study was to evaluate the effectiveness of pre-exercise low-level phototherapy (Light-Emitting Diode therapy [LEDtherapy] or Light Amplification by Stimulate Emission of Radiation therapy [LASERtherapy]) in increasing exercise capacity and muscle performance of people undergoing exercise when compared to placebo treatment. Randomized controlled trials and crossover studies were sought on CENTRAL, MEDLINE, EMBASE, SciELO, PEDro and LILACS from its inception up to February 2015. References lists of included studies were sought for additional relevant research. Two authors independently extracted data on study design, treatment parameters, exercise capacity (number of repetitions, time to exhaustion, blood lactate concentration and lactate dehydrogenase activity) and muscle performance (torque, power and strength) using an structured table. Agreement should be reached by consensus or by a third reviewer. Sixteen studies involving 297 participants were included. Improvement of number of repetitions (mean difference [MD] [95 % confidence interval] = 3.51 repetitions [0.65-6.37]; P = 0.02), delay in time to exhaustion (MD = 4.01 s [2.10-5.91]; P < 0.0001), reduction in lactate levels (MD = 0.34 mmol/L [0.19-0.48]; P < 0.00001) and increased peak torque (MD = 21.51 Nm [10.01-33.01]; P < 0.00001) were observed when LASERtherapy was applied. LEDtherapy meta-analyses were performed with two studies and retrieved no between-group statistically significant difference in power, lactate levels or time to exhaustion. Although our results suggest that LASERtherapy is effective in improving skeletal muscle exercise capacity, the quality of the current evidence is limited."}],"keywords":["Exercise","Low-level laser therapy","Muscle fatigue","Phototherapy"]},{"pmid":"27272518","title_fr":"Photothérapie avant l'effort avec des sondes de tailles différentes","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser","LED"],"nm":[670,850,880,950],"n":null,"effect":"favorable","theme":"Performance musculaire","l1":"Grandes et petites sondes multi-diodes réduisent autant la fatigue des fléchisseurs du coude.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Effect of pre-exercise phototherapy applied with different cluster probe sizes on elbow flexor muscle fatigue.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Rossato M","Dellagrana RA","Lanferdini FJ","et al."],"date":"2016-06-06","year":2016,"week":"2016-S23","doi":"10.1007/s10103-016-1973-0","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":28,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Phototherapy has been used for reducing muscle fatigue. In view of the various types of phototherapy cluster probes available in the market, the purpose of this study was to compare the effects of a similar phototherapy dosage with two different cluster probes on elbow flexor muscle fatigue: small cluster probe (SC = 9 diodes; 7.5 cm(2)) vs. large cluster probe (LC = 33 diodes; 30.2 cm(2)). Ten physically active male aged 18-35 years participate in a randomized, crossover, double-blind, placebo-controlled trial, which each participant was submitted to the same testing protocol in four sessions (separated by at least 48 h) with different treatments: LC-phototherapy, SC-phototherapy, LC-placebo, and SC-placebo. The elbow flexion maximal isometric voluntary contraction (MIVC) was performed before and after a fatigue protocol (60 % of MIVC until exhaustion). Electromyography (EMG) of the biceps brachii muscle was collected during all testing procedure. Phototherapy with dose of 60 J per muscle [LC: 33 diodes = 5 lasers (850 nm), 12 LEDs (670 nm), 8 LEDs (880 nm), and 8 LEDs (950 nm); SC: 9 diodes = 5 lasers (850 nm) and 4 LEDs (670 nm)] or placebo applications occurred before fatigue protocol. Two-way ANOVA (treatment and time factors) and one-way ANOVA were used, followed by LSD post hoc. Time to exhaustion was significantly higher in active LC (15 %; p = 0.031) and SC (14 %; p = 0.038) in comparison with their respective placebo treatments, without differences between LC and SC (p > 0.05) or between placebo conditions (p > 0.05). This larger exercise tolerance in phototherapy conditions was not accompanied by a higher decrement in the volunteers' maximal strength capacity (11-15 %; p > 0.05 for all). EMG signals presented no difference between the four condition tested here. In both large and small cluster probes (according parameters tested in this study) led to reduced fatigue in elbow flexor muscles, without difference between them."}],"keywords":["Ergogenic effect and electromyography","Light-emitting diodes therapy","Low-level laser therapy","Neuromuscular economy"]},{"pmid":"27250713","title_fr":"Laser, lactates et fatigue chez des patients hospitalisés pour insuffisance cardiaque","type":"rct","level":2,"pop":"adulte","ctx":["populations"],"aim":"—","mode":["laser"],"nm":[],"n":null,"effect":"mitigé","theme":"Sujets âgés & malades chroniques","l1":"Chez des insuffisants cardiaques hospitalisés, le laser n'améliore pas la capacité fonctionnelle mais module les lactates et réduit la fatigue perçue.","l2":"Étude pilote.","l3":{"points":["Population fragile."],"limites":["Pilote."],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Acute effects of low-level laser therapy irradiation on blood lactate and muscle fatigue perception in hospitalized patients with heart failure-a pilot study.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Bublitz C","Renno AC","Ramos RS","et al."],"date":"2016-06-01","year":2016,"week":"2016-S22","doi":"10.1007/s10103-016-1965-0","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":17,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"The objective of the present study is to evaluate the acute effects of low-level laser therapy (LLLT) on functional capacity, perceived exertion, and blood lactate in hospitalized patients with heart failure (HF). Patients diagnosed with systolic HF (left ventricular ejection fraction <45 %) were randomized and allocated prospectively into two groups: placebo LLLT group (n = 10)-subjects who were submitted to placebo laser and active LLLT group (n = 10)-subjects who were submitted to active laser. The 6-min walk test (6MWT) was performed, and blood lactate was determined at rest (before LLLT application and 6MWT), immediately after the exercise test (time 0) and recovery (3, 6, and 30 min). A multi-diode LLLT cluster probe (DMC, São Carlos, Brazil) was used. Both groups increased 6MWT distance after active or placebo LLLT application compared to baseline values (p = 0.03 and p = 0.01, respectively); however, no difference was observed during intergroup comparison. The active LLLT group showed a significant reduction in the perceived exertion Borg (PEB) scale compared to the placebo LLLT group (p = 0.006). In addition, the group that received active LLLT showed no statistically significant difference for the blood lactate level through the times analyzed. The placebo LLLT group demonstrated a significant increase in blood lactate between the rest and recovery phase (p < 0.05). Acute effects of LLLT irradiation on skeletal musculature were not able to improve the functional capacity of hospitalized patients with HF, although it may favorably modulate blood lactate metabolism and reduce perceived muscle fatigue."}],"keywords":["6-min walk test","Functional capacity","Heart failure","Lactate","Low-level laser therapy (LLLT)"]},{"pmid":"27250715","title_fr":"Laser et entraînement en force chez la femme âgée : essai en double aveugle","type":"rct","level":2,"pop":"adulte","ctx":["populations"],"aim":"—","mode":["laser"],"nm":[808],"n":null,"effect":"favorable","theme":"Sujets âgés & malades chroniques","l1":"Associé à l'entraînement en force, le laser améliore la performance musculaire de femmes âgées.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Low level laser therapy associated with a strength training program on muscle performance in elderly women: a randomized double blind control study.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Toma RL","Vassão PG","Assis L","et al."],"date":"2016-06-01","year":2016,"week":"2016-S22","doi":"10.1007/s10103-016-1967-y","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":28,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"The aging process leads to a gradual loss of muscle mass and muscle performance, leading to a higher functional dependence. Within this context, many studies have demonstrated the benefits of a combination of physical exercise and low level laser therapy (LLLT) as an intervention that enhances muscle performance in young people and athletes. The aim of this study was to evaluate the effects of combination of LLLT and strength training on muscle performance in elderly women. For this, a hundred elderly women were screened, and 48 met all inclusion criteria to participate in this double-blind placebo-controlled trial. Volunteers were divided in three groups: control (CG = 15), strength training associated with placebo LLLT (TG = 17), and strength training associated with active LLLT (808 nm, 100 mW, 7 J) (TLG = 16). The strength training consisted of knee flexion-extension performed with 80 % of 1-repetition maximum (1-RM) during 8 weeks. Several outcomes related to muscle performance were analyzed through the 6-min walk test (6-MWT), isokinetic dynamometry, surface electromyography (SEMG), lactate concentration, and 1-RM. The results revealed that a higher work (p = 0.0162), peak torque (p = 0.0309), and power (p = 0.0223) were observed in TLG compared to CG. Furthermore, both trained groups increased the 1-RM load (TG vs CG: p = 0.0067 and TLG vs CG: p < 0.0001) and decreased the lactate concentration in the third minute after isokinetic protocol (CG vs TLG: p = 0.0289 and CG vs TG: p = 0.0085). No difference in 6-MWT and in fatigue levels were observed among the groups. The present findings suggested that LLLT in combination with strength training was able to improve muscle performance in elderly people."}],"keywords":["Elderly people","Isokinetic dynamometer","Low level laser therapy","SEMG","Sarcopenia","Strength training"]},{"pmid":"27299571","title":"Effects of low-level laser therapy (LLLT 808 nm) on lower limb spastic muscle activity in chronic stroke patients.","journal_abbr":"Lasers Med Sci","authors":["das Neves MF","Dos Reis MC","de Andrade EA","et al."],"date":"2016-05-31","year":2016,"doi":"10.1007/s10103-016-1968-x","cited_by":23,"pub_types":["Clinical Trial"],"curated":false,"type":"nrct","level":3,"ctx":["récupération","populations"],"nm":[808],"l1":"After the real LLLT intervention, we observed significant reduction in the visual analogue scale for pain intensity (p = 0.0038), increased time to onset of muscle fatigue (p = 0.0063), and increased torque peak (p = 0.0076), but no…","kw":"Cerebrovascular accident Fatigue Low-level laser therapy Pain Spasticity Adult Aged Chronic Disease Cross-Over Studies Cross-Sectional Studies Double-Blind Meth"},{"pmid":"27141153","title":"830 nm light-emitting diode (led) phototherapy significantly reduced return-to-play in injured university athletes: a pilot study.","journal_abbr":"Laser Ther","authors":["Foley J","Vasily DB","Bradle J","et al."],"date":"2016-05-04","year":2016,"doi":"10.5978/islsm.16-OR-03","pmcid":"PMC4846838","cited_by":12,"curated":false,"type":"autre","level":0,"ctx":["blessures"],"nm":[830],"l1":"For any motivated athlete, RTP may be the most important factor postinjury based on the resolution of pain and inflammation and repair to tissue trauma. 830 nm LED phototherapy significantly and safely reduced the RTP in dedicated…","kw":"LED Low level light therapy (LLLT) inflammatory facilitators inflammatory mediators musculoskeletal injury pain"},{"pmid":"27088469","title":"Effects of Light-Emitting Diode Therapy on Muscle Hypertrophy, Gene Expression, Performance, Damage, and Delayed-Onset Muscle Soreness: Case-control Study with a Pair of Identical Twins.","journal_abbr":"Am J Phys Med Rehabil","authors":["Ferraresi C","Bertucci D","Schiavinato J","et al."],"date":"2016-04-19","year":2016,"doi":"10.1097/PHM.0000000000000490","pmcid":"PMC5026559","cited_by":21,"pub_types":["Twin Study"],"curated":false,"type":"autre","level":0,"ctx":["performance","récupération"],"nm":[850],"l1":"Light-emitting diode therapy can be useful to reduce muscle damage, pain, and atrophy, as well as to increase muscle mass, recovery, and athletic performance in rehabilitation programs and sports medicine.","kw":"Case-Control Studies Creatine Kinase Exercise Exercise Tolerance Humans Hypertrophy"},{"pmid":"27082964","title":"Red and Infrared Low-Level Laser Therapy Prior to Injury with or without Administration after Injury Modulate Oxidative Stress during the Muscle Repair Process.","journal_abbr":"PLoS One","authors":["Ribeiro BG","Alves AN","Dos Santos LA","et al."],"date":"2016-04-15","year":2016,"doi":"10.1371/journal.pone.0153618","pmcid":"PMC4833286","license":"cc by","oa":true,"cited_by":19,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"preclinical","level":5,"ctx":["blessures"],"nm":[660,780],"pre":"vivo","l1":"The administration of red and infrared laser therapy at different times positively modulates the activity of antioxidant enzymes and reduces stress markers during the muscle repair process.","kw":"Animals Antioxidants Catalase Glutathione Peroxidase Infrared Rays Lipid Peroxidation"},{"pmid":"27058781","title":"Effects of Low-Level Laser Therapy Applied Before Treadmill Training on Recovery of Injured Skeletal Muscle in Wistar Rats.","journal_abbr":"Photomed Laser Surg","authors":["Adabbo M","Paolillo FR","Bossini PS","et al."],"date":"2016-04-08","year":2016,"doi":"10.1089/pho.2015.4031","pmcid":"PMC4860654","cited_by":14,"curated":false,"type":"preclinical","level":5,"ctx":["récupération","blessures"],"nm":[780],"pre":"vivo","l1":"The LLLT applied before the physical exercise on the treadmill stimulated the angiogenesis and accelerated the process of muscle recovery.","kw":"Animals Low-Level Light Therapy Male Muscle, Skeletal Physical Conditioning, Animal Rats"},{"pmid":"27059227","title":"Light-emitting diode therapy (LEDT) improves functional capacity in rats with heart failure.","journal_abbr":"Lasers Med Sci","authors":["Capalonga L","Karsten M","Hentschke VS","et al."],"date":"2016-04-08","year":2016,"doi":"10.1007/s10103-016-1922-y","cited_by":16,"curated":false,"type":"preclinical","level":5,"ctx":["populations"],"pre":"vivo","l1":"However, Sham and LEDT-HF groups showed higher relative values than the Control-HF group, respectively, for distance covered (27.7 and 32.5 %), time of exercise test (17.7 and 20.5 %), and speed (13.6 and 12.2 %). In conclusion, LEDT was…","kw":"Exercise test Hemodynamic function Maximal oxygen uptake Phototherapy Animals Exercise Test Exercise Tolerance Heart Failure Low-Level Light Therapy Male"},{"pmid":"27050245","title_fr":"PBM et performance de joueurs de rugby de haut niveau : essai croisé contre placebo","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser","LED"],"nm":[640,875,905],"n":null,"effect":"favorable","theme":"Performance musculaire","l1":"Chez des rugbymen de haut niveau, la PBM avant l'effort améliore la performance et accélère la récupération en test de terrain.","l2":"Essai croisé randomisé en double aveugle contre placebo (J Strength Cond Res).","l3":{"points":["Conditions réelles."],"limites":["Petit effectif."],"pratique":"Préconditionnement sur le terrain."},"em":["super"],"pre":"","nm_auto":true,"topic":"sport","title":"Photobiomodulation Therapy Improves Performance and Accelerates Recovery of High-Level Rugby Players in Field Test: A Randomized, Crossover, Double-Blind, Placebo-Controlled Clinical Study.","journal":"Journal of strength and conditioning research","journal_abbr":"J Strength Cond Res","authors":["Pinto HD","Vanin AA","Miranda EF","et al."],"date":"2016-04-07","year":2016,"week":"2016-S14","doi":"10.1519/JSC.0000000000001439","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":63,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Pinto, HD, Vanin, AA, Miranda, EF, Tomazoni, SS, Johnson, DS, Albuquerque-Pontes, GM, de Oliveira Aleixo Junior, I, Grandinetti, VdS, Casalechi, HL, de Tarso Camillo de Carvalho, P, and Pinto Leal Junior. Photobiomodulation therapy improves performance and accelerates recovery of high-level rugby players in field test: A randomized, crossover, double-blind, placebo-controlled clinical study. J Strength Cond Res 30(12): 3329-3338, 2016-Although growing evidence supports the use of photobiomodulation therapy (PBMT) for performance and recovery enhancement, there have only been laboratory-controlled studies. Therefore, the aim of this study was to analyze the effects of PBMT in performance and recovery of high-level rugby players during an anaerobic field test. Twelve male high-level rugby athletes were recruited in this randomized, crossover, double-blinded, placebo-controlled trial. No interventions were performed before the Bangsbo sprint test (BST) at familiarization phase (week 1); at weeks 2 and 3, pre-exercise PBMT or placebo were randomly applied to each athlete. Photobiomodulation therapy irradiation was performed at 17 sites of each lower limb, employing a cluster with 12 diodes (4 laser diodes of 905 nm, 4 light emitting diodes [LEDs] of 875 nm, and 4 LEDs of 640 nm, 30 J per site, manufactured by Multi Radiance Medical). Average time of sprints, best time of sprints, and fatigue index were obtained from BST. Blood lactate levels were assessed at baseline, and at 3, 10, 30, and 60 minutes after BST. Athletes' perceived fatigue was also assessed through a questionnaire. Photobiomodulation therapy significantly (p ≤ 0.05) improved the average time of sprints and fatigue index in BST. Photobiomodulation therapy significantly decreased percentage of change in blood lactate levels (p ≤ 0.05) and perceived fatigue (p ≤ 0.05). Pre-exercise PBMT with the combination of super-pulsed laser (low-level laser), red LEDs, and infrared LEDs can enhance performance and accelerate recovery of high-level rugby players in field test. This opens a new avenue for wide use of PBMT in real clinical practice in sports settings."}],"keywords":[]},{"pmid":"27330707","title":"Effect of Laser Therapy on Chronic Osteoarthritis of the Knee in Older Subjects.","journal_abbr":"J Lasers Med Sci","authors":["Youssef EF","Muaidi QI","Shanb AA"],"date":"2016-03-27","year":2016,"doi":"10.15171/jlms.2016.19","pmcid":"PMC4909009","cited_by":31,"curated":false,"type":"autre","level":0,"ctx":["populations"],"l1":"It can be concluded that addition of LLLT to exercise training program is more effective than exercise training alone in the treatment of older patients with chronic knee OA and the rate of improvement may be dose dependent, as with 6…","kw":"Laser therapy Life Quality Osteoarthritis"},{"pmid":"27034111","title_fr":"Soulagement immédiat de la douleur des blessures sportives par laser : essai en double aveugle","type":"rct","level":2,"pop":"adulte","ctx":["blessures"],"aim":"traitement","mode":["laser"],"nm":[],"n":32,"effect":"favorable","theme":"Blessures sportives","l1":"Chez des sportifs universitaires blessés, une séance de laser réduit immédiatement la douleur de 37 % (contre 8 % sous placebo), efficace chez 75 % d'entre eux.","l2":"Essai randomisé en double aveugle contre placebo, 32 athlètes (J Sci Med Sport).","l3":{"points":["Effet immédiat."],"limites":["Court terme."],"pratique":"Antalgie rapide au bord du terrain."},"em":[],"pre":"","topic":"sport","title":"Immediate pain relief effect of low level laser therapy for sports injuries: Randomized, double-blind placebo clinical trial.","journal":"Journal of science and medicine in sport","journal_abbr":"J Sci Med Sport","authors":["Takenori A","Ikuhiro M","Shogo U","et al."],"date":"2016-03-24","year":2016,"week":"2016-S12","doi":"10.1016/j.jsams.2016.03.006","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":16,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"OBJECTIVES","text":"To determine the immediate pain relief effect of low-level laser therapy on sports injuries in athletes and degree of pain relief by the therapy."},{"label":"DESIGN","text":"Double-blind, randomized, comparative clinical study."},{"label":"METHODS","text":"Participants were 32 college athletes with motion pain at a defined site. Participants were randomized into two groups in which the tested or placebo laser therapy was administered to determine pain intensity from painful action before and after laser irradiation, using the Modified Numerical Rating Scale. The post-therapeutic Modified Numerical Rating Scale score was subtracted from the pre-therapeutic Modified Numerical Rating Scale score to determine pain intensity difference, and the rate of pain intensity difference to pre-therapeutic Modified Numerical Rating Scale was calculated as pain relief rate."},{"label":"RESULTS","text":"Low-level laser therapy was effective in 75% of the laser group, whereas it was not effective in the placebo group, indicating a significant difference in favor of the laser group (p<0.001). Pain relief rate was significantly higher in the laser group than in the placebo group (36.94% vs. 8.20%, respectively, p<0.001), with the difference in pain relief rate being 28.74%."},{"label":"CONCLUSIONS","text":"Low-level laser therapy provided an immediate pain relief effect, reducing pain by 28.74%. It was effective for pain relief in 75% of participants."}],"keywords":["Athletes","Motion pain","Pain relief rate","Physical therapies"]},{"pmid":"26942660","title":"Using Pre-Exercise Photobiomodulation Therapy Combining Super-Pulsed Lasers and Light-Emitting Diodes to Improve Performance in Progressive Cardiopulmonary Exercise Tests.","journal_abbr":"J Athl Train","authors":["Miranda EF","Vanin AA","Tomazoni SS","et al."],"date":"2016-03-04","year":2016,"doi":"10.4085/1062-6050-51.3.10","pmcid":"PMC4852318","cited_by":48,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"autre","level":0,"ctx":["performance","récupération"],"em":["super","pulse"],"l1":"The combination of lasers and LEDs increased the time, distance, and pulmonary ventilation and decreased the score of dyspnea during a cardiopulmonary test.","kw":"fatigue light-emitting diode therapy low-level laser therapy progressive-intensity exercise Adult Cross-Over Studies Double-Blind Method Exercise Test Exercise "},{"pmid":"26873498","title_fr":"Laser 810 nm chez de jeunes joueurs de water-polo : essai en double aveugle","type":"rct","level":2,"pop":"adulte","ctx":["récupération"],"aim":"prévention","mode":["laser"],"nm":[810],"n":20,"effect":"neutre","theme":"Récupération & courbatures","l1":"Chez 20 joueurs de water-polo, 5 jours de laser n'améliorent ni la performance ni les marqueurs inflammatoires et musculaires.","l2":"Surface irradiée peut-être trop petite.","l3":{"points":["Double aveugle."],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Effects of low-level laser therapy on performance, inflammatory markers, and muscle damage in young water polo athletes: a double-blind, randomized, placebo-controlled study.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Zagatto AM","de Paula Ramos S","Nakamura FY","et al."],"date":"2016-02-12","year":2016,"week":"2016-S06","doi":"10.1007/s10103-016-1875-1","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":25,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"This study aimed to evaluate the effects of 5 days of 810-nm low-level laser therapy (LLLT) intervention on inflammatory and muscle damage markers and performance in young water polo players. Twenty young male water polo players participated in the study, which was designed as a randomized, double-blinded, placebo-controlled trial. Active LLLT or an identical placebo LLLT were delivered to eight points on the adductor muscle region immediately after each training day. Performance was measured by a 200-m maximal swimming (P200) and a 30-s crossbar jump test (30CJ) which was performed every day before training, and blood samples were drawn pre and post the final LLLT intervention to measure interleukins (IL) and muscle damage markers. There was no significant change in the P200 exercise in the LLLT group compared with the placebo group but there was a moderate improvement in the 30CJ (8.7 ± 2.6 %). IL-1β and tumor necrosis factor-alpha presented increased (P < 0.016) concentration within group 48 h after the last LLLT intervention compared to pre, 0, and 24 h, but did not differ between groups. IL-10 increased over time in the placebo group and reached a moderate effect compared to the LLLT group. The creatine kinase decreased significantly (P = 0.049) over the time within the LLLT treatment group, but there was no significant change in lactate dehydrogenase (P = 0.150). In conclusion, LLLT resulted in a non-significant, but small to moderate effect on inflammatory and muscle damage markers and a moderate effect on performance in water polo players. In addition, the lack of positive results could be due to the small area covered by irradiation and this should be considered in future studies."}],"keywords":["Cytokines","Laser","Muscle injuries","Water polo"]},{"pmid":"26714981","title_fr":"PBM et fatigue chez la femme âgée : évaluation isocinétique","type":"rct","level":2,"pop":"adulte","ctx":["populations"],"aim":"prévention","mode":["laser"],"nm":[808],"n":null,"effect":"mitigé","theme":"Sujets âgés & malades chroniques","l1":"Chez des femmes âgées, la PBM réduit la fatigue musculaire sans améliorer la performance.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Effects of photobiomodulation on the fatigue level in elderly women: an isokinetic dynamometry evaluation.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Vassão PG","Toma RL","Antunes HK","et al."],"date":"2015-12-29","year":2015,"week":"2015-S53","doi":"10.1007/s10103-015-1858-7","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":27,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Aging is responsible by a series of morphological and functional modifications that lead to a decline of muscle function, particularly in females. Muscle tissue in elderly people is more susceptible to fatigue and, consequently, to an increased inability to maintain strength and motor control. In this context, therapeutic approaches able of attenuating muscle fatigue have been investigated. Among these, the photobiomodulation demonstrate positive results to interacts with biological tissues, promoting the increase in cell energy production. Thus, the aim of this study was to investigate the effects of photobiomodulation (808 nm, 250 J/cm(2), 100 mW, 7 J each point) in the fatigue level and muscle performance in elderly women. Thirty subjects entered a crossover randomized double-blinded placebo-controlled trial. Photobiomodulation was delivered on the rectus femoris muscle of the dominant limb immediately before the fatigue protocol. In both sessions, peripheral muscle fatigue was analyzed by surface electromyography (EMG) and blood lactate analysis. Muscle performance was evaluated using an isokinetic dynamometer. The results showed that photobiomodulation was able of reducing muscle fatigue by a significant increase of electromyographic fatigue index (EFI) (p = 0.047) and decreasing significantly lactate concentration 6 min after the performance of the fatigue protocol (p = 0. 0006) compared the placebo laser session. However, the photobiomodulation was not able of increasing muscle performance measured by the isokinetic dynamometer. Thus, it can be conclude that the photobiomodulation was effective in reducing fatigue levels. However, no effects of photobiomodulation on muscle performance was observed."}],"keywords":["Aged","Electromyography","Muscle changes","Muscle fatigue","Muscle strength dynamometer","Photobiomodulation","Surface electromyography"]},{"pmid":"26714977","title":"Long-term low-level laser therapy promotes an increase in maximal oxygen uptake and exercise performance in a dose-dependent manner in Wistar rats.","journal_abbr":"Lasers Med Sci","authors":["Perini JL","Hentschke VS","Sonza A","et al."],"date":"2015-12-29","year":2015,"doi":"10.1007/s10103-015-1849-8","cited_by":5,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"preclinical","level":5,"ctx":["performance"],"nm":[850],"pre":"vivo","l1":"No significant results were found comparing before and after conditions for the studied variables considering P-LLLT and 8.7 J/cm(2)-LLLT groups. The LLLT promoted in a dose-dependent manner an increase in oxygen consumption uptake and a…","kw":"Exercise performance Functional capacity Maximal exercise test Maximal oxygen consumption Phototherapy Skeletal muscle Animals Biological Transport Dose-Respons"},{"pmid":"26666977","title":"Achilles Tendon Vascularization of Proximal, Medial, and Distal Portion Before and After Partial Lesion in Rats Treated with Phototherapy.","journal_abbr":"Photomed Laser Surg","authors":["Ferreira R","Silva R","Folha RA","et al."],"date":"2015-12-16","year":2015,"doi":"10.1089/pho.2015.3974","cited_by":4,"curated":false,"type":"preclinical","level":5,"ctx":[],"nm":[660,830],"pre":"vivo","l1":"Low-level laser therapy (LLLT) had no effect on the studied parameters. The vascularization of rat tendon is similar to that of humans, which contributes to the studies of therapies that have been applied in humans.","kw":"Achilles Tendon Animals Low-Level Light Therapy Rats"},{"pmid":"26563953","title_fr":"Photothérapie et courbatures : méta-analyse","type":"ma","level":1,"pop":"adulte","ctx":["blessures"],"aim":"les deux","mode":["laser","LED"],"nm":[],"n":null,"effect":"mitigé","theme":"Blessures sportives","l1":"La photothérapie pourrait réduire la douleur et les marqueurs de lésion des courbatures, mais trop peu d'études permettent de conclure.","l2":"—","l3":{"points":["—"],"limites":["Peu d'études."],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Effect of low-level phototherapy on delayed onset muscle soreness: a systematic review and meta-analysis.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Nampo FK","Cavalheri V","Ramos Sde P","et al."],"date":"2015-11-12","year":2015,"week":"2015-S46","doi":"10.1007/s10103-015-1832-4","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":26,"pub_types":["Meta-Analysis","Research Support, Non-U.S. Gov't","Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"","text":"To determine the effectiveness of low-level phototherapy (i.e. light-emitting diode therapy [LEDtherapy] or light amplification by stimulated emission of radiation therapy [LASERtherapy]) on pain, skeletal muscle injury (creatine kinase [CK] levels and edema) and skeletal muscle function (range of movement and strength) in people undergoing an exercise protocol. (Cochrane Central Register of Controlled Trials, MEDLINE, EMBASE, PEDro, SciELO and LILACS up to May 2014), we included randomized controlled trials, quasi-randomized controlled trials and crossover studies in which study participants were allocated to receive either low-level phototherapy or placebo treatment. Phototherapy should have been applied in a single treatment session, either before or after an exercise protocol. We identified 15 studies involving 317 participants. Meta-analyses were limited by substantial heterogeneity. Compared to the placebo group, reduction in CK levels was only observed when LASERtherapy was applied before an exercise protocol (standardized mean difference = -0.66; 95 % CI = -1.30, -0.02). No between-group difference in edema, range of movement and strength were detected when phototherapy was applied before or after exercise. Evidence from this review suggests that low-level phototherapy may not have substantial effect in the treatment of skeletal muscle injury and pain caused by exercise. Definitive conclusions are limited due to the small number of included studies in each meta-analysis, disparities across the included studies and small sample sizes."}],"keywords":["Exercise","Low-level laser therapy","Muscle soreness","Phototherapy","Skeletal muscle"]},{"pmid":"26647747","title":"Effect of low-level laser therapy (808 nm) on skeletal muscle after endurance exercise training in rats.","journal_abbr":"Braz J Phys Ther","authors":["Assis L","Yamashita F","Magri AM","et al."],"date":"2015-09-01","year":2015,"doi":"10.1590/bjpt-rbf.2014.0113","pmcid":"PMC4668339","license":"cc by","oa":true,"cited_by":11,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"preclinical","level":5,"ctx":["performance"],"nm":[808],"pre":"vivo","l1":"These results suggest that LLLT could be an effective therapeutic approach for stimulating recovery during an endurance exercise protocol.","kw":"Animals Exercise Therapy Low-Level Light Therapy Muscle, Skeletal Rats Rats, Wistar"},{"pmid":"26150082","title":"The effect of low-level laser therapy (LLLT) applied prior to muscle injury.","journal_abbr":"Lasers Surg Med","authors":["Ribeiro BG","Alves AN","Santos LADD","et al."],"date":"2015-07-06","year":2015,"doi":"10.1002/lsm.22381","cited_by":18,"curated":false,"type":"autre","level":0,"ctx":["blessures"],"nm":[780],"l1":"LLLT applied immediately prior to injury had positive effects during the muscle regeneration process. Therefore, this resource may have considerable therapeutic value, especially for athletes who practice sports in which there is a…","kw":"low-level laser therapy matrix metalloproteinase 2 muscle regeneration collagen skeletal"},{"pmid":"26083527","title":"Low-Level Laser Therapy (LLLT) in Dystrophin-Deficient Muscle Cells: Effects on Regeneration Capacity, Inflammation Response and Oxidative Stress.","journal_abbr":"PLoS One","authors":["Macedo AB","Moraes LH","Mizobuti DS","et al."],"date":"2015-06-17","year":2015,"doi":"10.1371/journal.pone.0128567","pmcid":"PMC4470633","license":"cc by","oa":true,"cited_by":29,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"preclinical","level":5,"ctx":[],"nm":[830],"pre":"both","l1":"The mdx group showed significant increase in the TNF-α and NF-κB levels, which in turn was reduced by the LLLT treatment. Together, these results suggest that the laser treatment improved regenerative capacity and decreased inflammatory…","kw":"Animals Calcium Cells, Cultured Dystrophin Hydrogen Peroxide Inflammation"},{"pmid":"26076829","title":"Pre-exercise low-level laser therapy improves performance and levels of oxidative stress markers in mdx mice subjected to muscle fatigue by high-intensity exercise.","journal_abbr":"Lasers Med Sci","authors":["Silva AA","Leal-Junior EC","D'Avila Kde A","et al."],"date":"2015-06-16","year":2015,"doi":"10.1007/s10103-015-1777-7","cited_by":21,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"preclinical","level":5,"ctx":["performance","récupération"],"pre":"vivo","l1":"LLLT had a beneficial effect also on the skeletal muscle performance of mdx mice. However, the single application of LLLT and the dose parameters used in this study were not able to change the morphology of a dystrophic muscle.","kw":"Animals Biomarkers Creatine Kinase Exercise Test Low-Level Light Therapy Mice, Inbred C57BL"},{"pmid":"25993067","title":"Influence of low-level laser therapy on vertical jump in sedentary individuals.","journal_abbr":"Einstein (Sao Paulo)","authors":["Kakihata CM","Malanotte JA","Higa JY","et al."],"date":"2015-05-21","year":2015,"doi":"10.1590/S1679-45082015AO3243","pmcid":"PMC4977600","license":"cc by-nc","oa":true,"cited_by":6,"pub_types":["Evaluation Study"],"curated":false,"type":"autre","level":0,"ctx":["performance","récupération"],"nm":[660],"l1":"The low intensity laser on the triceps surae, in sedentary individuals, had no significant effects on the variables evaluated.","kw":"Adult Analysis of Variance Exercise Female Humans Low-Level Light Therapy"},{"pmid":"25751667","title":"Effect of MLS(®) laser therapy with different dose regimes for the treatment of experimentally induced tendinopathy in sheep: pilot study.","journal_abbr":"Photomed Laser Surg","authors":["Iacopetti I","Perazzi A","Maniero V","et al."],"date":"2015-03-10","year":2015,"doi":"10.1089/pho.2014.3775","cited_by":7,"curated":false,"type":"preclinical","level":5,"ctx":["blessures"],"pre":"both","l1":"In this study, clinical and histological evaluation demonstrated that a therapeutic dose <5 J/cm(2) furnished an anti-inflammatory effect, and induced a decrease of fibroblasts and vessel area. Overall, our results suggest that MLS laser…","kw":"Animals Female Low-Level Light Therapy Pilot Projects Sheep Tendinopathy"},{"pmid":"25722067","title_fr":"LED avant les matchs et créatine kinase chez le volleyeur : effet dose","type":"rct","level":2,"pop":"adulte","ctx":["récupération"],"aim":"prévention","mode":["LED"],"nm":[],"n":null,"effect":"favorable","theme":"Récupération & courbatures","l1":"Appliquée avant des matchs officiels, la LED à 210–315 J empêche la hausse des CK chez le volleyeur.","l2":"Effet dose-dépendant.","l3":{"points":["Conditions réelles de compétition."],"limites":["—"],"pratique":"210–315 J avant le match."},"em":[],"pre":"","topic":"sport","title":"Light-emitting diode therapy (LEDT) before matches prevents increase in creatine kinase with a light dose response in volleyball players.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Ferraresi C","Dos Santos RV","Marques G","et al."],"date":"2015-02-27","year":2015,"week":"2015-S09","doi":"10.1007/s10103-015-1728-3","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":35,"pub_types":["Randomized Controlled Trial","Research Support, N.I.H., Extramural","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Low-level laser (light) therapy (LLLT) has been applied over skeletal muscles before intense exercise (muscular pre-conditioning) in order to reduce fatigue and muscle damage (measured by creatine kinase, CK) in clinical trials. However, previous exercise protocols do not exactly simulate the real muscle demand required in sports. For this reason, the aim of this randomized and double-blind placebo-controlled trial was to investigate whether light-emitting diode therapy (LEDT) applied over the quadriceps femoris muscles, hamstrings, and triceps surae of volleyball players before official matches could prevent muscle damage (CK) with a dose response, establishing a therapeutic window. A professional male volleyball team (12 athletes) was enrolled in this study, and LEDT was applied before 4 matches during a national championship. LEDT used an array of 200 light-emitting diodes (LEDs) arranged in 25 clusters of 4 infrared LEDs (850 ± 20 nm; 130 mW) and 25 clusters of 4 red LEDs (630 ± 10 nm; 80 mW). Athletes were randomized to receive one of four different total doses over each muscle group in a double-blind protocol: 105 J (20 s), 210 J (40 s), 315 J (60 s), and placebo (no light for 30 s). CK in blood was assessed 1 h before and 24 h after each match. LEDT at 210 J avoided significant increases in CK (+10 %; P = 0.993) as well as 315 J (+31 %, P = 0.407). Placebo (0 J) allowed a significant increase in CK (+53 %; P = 0.012) as well as LEDT at 105 J (+59 %; P = 0.001). LEDT prevented significant increases of CK in blood in athletes when applied before official matches with a light dose response of 210-315 J, suggesting athletes might consider applying LEDT before competition."}],"keywords":[]},{"pmid":"25700769","title":"Time response of increases in ATP and muscle resistance to fatigue after low-level laser (light) therapy (LLLT) in mice.","journal_abbr":"Lasers Med Sci","authors":["Ferraresi C","de Sousa MV","Huang YY","et al."],"date":"2015-02-21","year":2015,"doi":"10.1007/s10103-015-1723-8","cited_by":69,"pub_types":["Research Support, N.I.H., Extramural","Research Support, Non-U.S. Gov't"],"curated":false,"type":"preclinical","level":5,"ctx":["récupération"],"pre":"vivo","l1":"LEDT increased ATP content in muscles and fatigue resistance in mice with a peak at 6 h. Although the time response in mice and humans is not the same, athletes might consider applying LEDT at 6 h before competition.","kw":"Adenosine Triphosphate Animals Low-Level Light Therapy Male Mice Mice, Inbred BALB C"},{"pmid":"25654277","title":"Photobiomodulation therapy in skeletal muscle: from exercise performance to muscular dystrophies.","journal_abbr":"Photomed Laser Surg","authors":["Leal-Junior EC"],"date":"2015-02-05","year":2015,"doi":"10.1089/pho.2015.9851","pmcid":"PMC4340643","cited_by":15,"pub_types":["Editorial","Research Support, Non-U.S. Gov't"],"curated":false,"type":"letter","level":0,"ctx":["performance"],"l1":"","kw":"Exercise Humans Low-Level Light Therapy Muscle, Skeletal Muscular Dystrophies"},{"pmid":"25614133","title":"Immediate effects of low-intensity laser (808 nm) on fatigue and strength of spastic muscle.","journal_abbr":"Lasers Med Sci","authors":["dos Reis MC","de Andrade EA","Borges AC","et al."],"date":"2015-01-23","year":2015,"doi":"10.1007/s10103-014-1702-5","cited_by":13,"pub_types":["Clinical Trial","Research Support, Non-U.S. Gov't"],"curated":false,"type":"nrct","level":3,"ctx":["performance","récupération"],"nm":[808],"l1":"The LILT (diode laser, l100 mW 808 nm, 4.77 J/cm(2)/point, 40 s/AP) can be employed during and after spastic muscle-strengthening exercises, contributing to the improvement of motor function of the patient. After application of LILT, we…","kw":"Adult Aged Aged, 80 and over Cross-Sectional Studies Double-Blind Method Female"},{"pmid":"25585514","title_fr":"Préconditionnement musculaire par LED chez un coureur d'élite","type":"rct","level":4,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["LED"],"nm":[850],"n":1,"effect":"favorable","theme":"Performance musculaire","l1":"Chez un coureur d'élite, la LED proche infrarouge avant l'effort améliore la performance et module le métabolisme.","l2":"Essai sur un seul sujet.","l3":{"points":["—"],"limites":["Un seul sujet."],"pratique":"—"},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Muscular pre-conditioning using light-emitting diode therapy (LEDT) for high-intensity exercise: a randomized double-blind placebo-controlled trial with a single elite runner.","journal":"Physiotherapy theory and practice","journal_abbr":"Physiother Theory Pract","authors":["Ferraresi C","Beltrame T","Fabrizzi F","et al."],"date":"2015-01-14","year":2015,"week":"2015-S03","doi":"10.3109/09593985.2014.1003118","pmcid":"PMC4470717","license":null,"oa":false,"pdf":null,"cited_by":33,"pub_types":["Randomized Controlled Trial","Research Support, N.I.H., Extramural","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Recently, low-level laser (light) therapy (LLLT) has been used to improve muscle performance. This study aimed to evaluate the effectiveness of near-infrared light-emitting diode therapy (LEDT) and its mechanisms of action to improve muscle performance in an elite athlete. The kinetics of oxygen uptake (VO2), blood and urine markers of muscle damage (creatine kinase--CK and alanine), and fatigue (lactate) were analyzed. Additionally, some metabolic parameters were assessed in urine using proton nuclear magnetic resonance spectroscopy ((1)H NMR). A LED cluster with 50 LEDs (λ = 850 nm; 50 mW 15 s; 37.5 J) was applied on legs, arms and trunk muscles of a single runner athlete 5 min before a high-intense constant workload running exercise on treadmill. The athlete received either Placebo-1-LEDT; Placebo-2-LEDT; or Effective-LEDT in a randomized double-blind placebo-controlled trial with washout period of 7 d between each test. LEDT improved the speed of the muscular VO2 adaptation (∼-9 s), decreased O2 deficit (∼-10 L), increased the VO2 from the slow component phase (∼+348 ml min(-1)), and increased the time limit of exercise (∼+589 s). LEDT decreased blood and urine markers of muscle damage and fatigue (CK, alanine and lactate levels). The results suggest that a muscular pre-conditioning regimen using LEDT before intense exercises could modulate metabolic and renal function to achieve better performance."}],"keywords":["Fatigue","LEDT","LLLT","NMR","muscle damage","oxygen uptake","photobiomodulation"]},{"pmid":"25559198","title":"The Effects of Low-Level Laser Therapy on Pain Associated With Tendinopathy: A Critically Appraised Topic.","journal_abbr":"J Sport Rehabil","authors":["Doyle AT","Lauber C","Sabine K"],"date":"2015-01-05","year":2015,"doi":"10.1123/jsr.2014-0219","cited_by":5,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["blessures"],"l1":"Although LLLT significantly decreases pain from baseline, its use may be no better than placebo or traditional treatments such as ultrasound, moist heat packs, electrical stimulation, or therapeutic exercise to reduce pain associated with…","kw":"Evidence-Based Medicine Low-Level Light Therapy Musculoskeletal Pain Tendinopathy"},{"pmid":"25496083","title_fr":"Laser 808 nm et résistance à la fatigue musculaire","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser"],"nm":[808],"n":7,"effect":"favorable","theme":"Performance musculaire","l1":"Chez 7 jeunes hommes, le laser pendant les pauses augmente de 52 % les répétitions maximales.","l2":"Essai croisé en double aveugle.","l3":{"points":["—"],"limites":["7 sujets."],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Use of low-level laser therapy (808 nm) to muscle fatigue resistance: a randomized double-blind crossover trial.","journal":"Photomedicine and laser surgery","journal_abbr":"Photomed Laser Surg","authors":["de Brito Vieira WH","Bezerra RM","Queiroz RA","et al."],"date":"2014-12-16","year":2014,"week":"2014-S51","doi":"10.1089/pho.2014.3812","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":33,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"OBJECTIVE","text":"The purpose of this study was to investigate whether low-level laser (light) therapy (LLLT) can provide fatigue resistance via maximum repetitions (RM) with an isokinetic dynamometer, and decrease electromyography fatigue index (EFI)."},{"label":"BACKGROUND DATA","text":"LLLT has been used to increase muscle performance when applied before or after intense exercises."},{"label":"MATERIALS AND METHODS","text":"This study was a randomized, double-blind, crossover trial with placebo. Seven young men (21±3 years of age) who were clinically healthy, were allocated into two groups: active laser (LLLT) and placebo laser (Placebo). Both groups were assessed at baseline, at one training session, and at the end of this study. Baseline and final assessments recorded the number of RM of knee flexion-extensions using an isokinetic dynamometer at 60 degrees/sec in conjunction with EFI recorded by median frequency. The training sessions consisted of three sets of 20 RM of knee flexion-extensions using an isokinetic dynamometer at 60 degrees/sec plus LLLT (808 nm, 100 mW, 4 J), or placebo, applied to quadriceps femoris muscles between sets, and after the last series of this exercise. After 1 week (washout period), all volunteers were exchanged among groups and then all assessments were repeated."},{"label":"RESULTS","text":"LLLT group increased RM (52%; p=0.002) with a small EFI for the vastus medialis (p=0.004) and rectus femoris (p=0.004)."},{"label":"CONCLUSIONS","text":"These results suggest an increased muscle fatigue resistance when LLLT is applied during rest intervals, and after the last series of intense exercises."}],"keywords":[]},{"pmid":"25443662","title":"Low-level laser (light) therapy increases mitochondrial membrane potential and ATP synthesis in C2C12 myotubes with a peak response at 3-6 h.","journal_abbr":"Photochem Photobiol","authors":["Ferraresi C","Kaippert B","Avci P","et al."],"date":"2014-12-03","year":2014,"doi":"10.1111/php.12397","pmcid":"PMC4355185","cited_by":145,"pub_types":["Research Support, N.I.H., Extramural","Research Support, Non-U.S. Gov't"],"curated":false,"type":"preclinical","level":5,"ctx":[],"pre":"vivo","l1":"A good correlation was found (r = 0.89) between MMP and ATP. These data suggest an optimum time window of 3-6 h for LEDT stimulate muscle cells.","kw":"Adenosine Triphosphate Animals Cell Line Infrared Rays Low-Level Light Therapy Membrane Potential, Mitochondrial"},{"pmid":"25417170","title_fr":"Laser et adaptation musculaire à l'entraînement excentrique du quadriceps","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"—","mode":["laser"],"nm":[810],"n":30,"effect":"favorable","theme":"Performance musculaire","l1":"Chez 30 hommes, le laser avant chaque séance d'entraînement excentrique augmente l'hypertrophie (+15,4 contre +9,4 %) et le gain de force.","l2":"Huit semaines d'entraînement.","l3":{"points":["Effet sur l'entraînement à long terme."],"limites":["—"],"pratique":"—"},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Effect of low-level laser therapy on muscle adaptation to knee extensor eccentric training.","journal":"European journal of applied physiology","journal_abbr":"Eur J Appl Physiol","authors":["Baroni BM","Rodrigues R","Freire BB","et al."],"date":"2014-11-23","year":2014,"week":"2014-S47","doi":"10.1007/s00421-014-3055-y","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":55,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"PURPOSE","text":"Eccentric training has been popularized for physical conditioning and prevention/rehabilitation of musculoskeletal disorders, especially due to the expressive responses in terms of muscular strength gain. In view of evidence that low-level laser therapy (LLLT) is able to increase exercise performance and accelerate post-exercise recovery, the aim of this study was to verify the effect of LLLT on hypertrophy and strengthening of knee extensor muscles submitted to eccentric training."},{"label":"METHOD","text":"Thirty healthy male subjects were randomized into three groups: Control Group (CG), Training Group (TG) and Training + LLLT Group (TLG). CG received no intervention, while TG and TLG were engaged on an 8-week knee extensor isokinetic eccentric training program. Only subjects from TLG were treated with LLLT (wavelength = 810 nm; power output = 200 mW; total dosage = 240 J) before each training session. Knee extensor muscle thickness and peak torque were assessed through ultrasonography and isokinetic dynamometry, respectively."},{"label":"RESULTS","text":"CG presented no changes in any variable throughout the study, while eccentric training led to significant increases in muscle thickness and peak torque in TG and TLG. Subjects from TLG reached significantly higher percent changes compared to subjects from TG for sum of muscles' thicknesses (15.4 vs. 9.4%), isometric peak torque (20.5 vs. 13.7%), and eccentric peak torque (32.2 vs. 20.0%)."},{"label":"CONCLUSION","text":"LLLT applied before eccentric training sessions seems to improve the hypertrophic response and muscular strength gain in healthy subjects."}],"keywords":[]},{"pmid":"25397864","title_fr":"Proche infrarouge pour limiter la perte de force après un exercice intense","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["LED"],"nm":[],"n":39,"effect":"favorable","theme":"Performance musculaire","l1":"Chez 39 jeunes adultes, le proche infrarouge avant un exercice de résistance limite un peu la perte de force.","l2":"Doses plus élevées à tester.","l3":{"points":["—"],"limites":["Effet modeste."],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Near-infrared light therapy to attenuate strength loss after strenuous resistance exercise.","journal":"Journal of athletic training","journal_abbr":"J Athl Train","authors":["Larkin-Kaiser KA","Christou E","Tillman M","et al."],"date":"2014-11-14","year":2014,"week":"2014-S46","doi":"10.4085/1062-6050-49.3.82","pmcid":"PMC4299734","license":null,"oa":false,"pdf":null,"cited_by":19,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"CONTEXT","text":"Near-infrared (NIR) light therapy is purported to act as an ergogenic aid by enhancing the contractile function of skeletal muscle. Improving muscle function is a new avenue for research in the area of laser therapy; however, very few researchers have examined the ergogenic effects of NIR light therapy and the influence it may have on the recovery process during rehabilitation."},{"label":"OBJECTIVE","text":"To evaluate the ergogenic effect of NIR light therapy on skeletal muscle function."},{"label":"DESIGN","text":"Crossover study."},{"label":"SETTING","text":"Controlled laboratory."},{"label":"PATIENTS OR OTHER PARTICIPANTS","text":"Thirty-nine healthy men (n = 21) and women (n = 18; age = 20.0 ± 0.2 years, height = 169 ± 2 cm, mass = 68.4 ± 1.8 kg, body mass index = 23.8 ± 0.4 kg/m(2))."},{"label":"INTERVENTION(S)","text":"Each participant received active and sham treatments on the biceps brachii muscle on 2 separate days. The order of treatment was randomized. A class 4 laser with a cumulative dose of 360 J was used for the active treatment. After receiving the treatment on each day, participants completed an elbow-flexion resistance-exercise protocol."},{"label":"MAIN OUTCOME MEASURE(S)","text":"The dependent variables were elbow range of motion, muscle point tenderness, and strength (peak torque). Analysis of variance with repeated measures was used to assess changes in these measures between treatments at baseline and at follow-up, 48 hours postexercise. Additionally, immediate strength loss postexercise was compared between treatments using a paired t test."},{"label":"RESULTS","text":"Preexercise to postexercise strength loss for the active laser treatment, although small, was less than with the sham treatment (P = .05)."},{"label":"CONCLUSIONS","text":"Applied to skeletal muscle before resistance exercise, NIR light therapy effectively attenuated strength loss. Therefore, NIR light therapy may be a beneficial, noninvasive modality for improving muscle function during rehabilitation after musculoskeletal injury. However, future studies using higher treatment doses are warranted."}],"keywords":["biceps brachii muscle","contractile function","ergogenic aids","lasers","photobiomodulation"]},{"pmid":"25378263","title":"Light-emitting diode therapy in exercise-trained mice increases muscle performance, cytochrome c oxidase activity, ATP and cell proliferation.","journal_abbr":"J Biophotonics","authors":["Ferraresi C","Parizotto NA","Pires de Sousa MV","et al."],"date":"2014-11-06","year":2014,"doi":"10.1002/jbio.201400087","pmcid":"PMC4422786","cited_by":55,"pub_types":["Research Support, N.I.H., Extramural","Research Support, Non-U.S. Gov't"],"curated":false,"type":"preclinical","level":5,"ctx":["performance","récupération"],"nm":[630,850],"pre":"vivo","l1":"The effectiveness of LEDT on improving muscle performance and recovery suggest applicability for high performance sports and in training programs. Positioning of the mice and light-emitting diode therapy (LEDT) applied on mouse legs,…","kw":"ATP LEDT LLLT muscle performance muscle recovery Adenosine Triphosphate Animals Biomarkers Catalase Cell Proliferation Electron Transport Complex IV"},{"pmid":"25274196","title":"Effects of light-emitting diode (LED) therapy on skeletal muscle ischemia reperfusion in rats.","journal_abbr":"Lasers Med Sci","authors":["Takhtfooladi MA","Shahzamani M","Takhtfooladi HA","et al."],"date":"2014-10-02","year":2014,"doi":"10.1007/s10103-014-1670-9","cited_by":16,"curated":false,"type":"preclinical","level":5,"ctx":["blessures"],"nm":[904],"pre":"vivo","l1":"The muscle tissue glutathione (GSH), superoxide dismutases (SOD), and catalase (CAT) levels in the IR group were significantly lower than those in the subjects in other groups. From the histological and histochemical perspective, the LED…","kw":"Animals Antioxidants Body Weight Catalase Cell Membrane Femoral Artery"},{"pmid":"25143643","title":"Platelet rich plasma versus laser therapy in lateral epicondylitis of elbow.","journal_abbr":"Indian J Orthop","authors":["Tonk G","Kumar A","Gupta A"],"date":"2014-08-22","year":2014,"doi":"10.4103/0019-5413.136260","pmcid":"PMC4137517","license":"cc by-nc-sa","oa":true,"cited_by":9,"curated":false,"type":"autre","level":0,"ctx":["blessures"],"l1":"Treatment of patients with chronic lateral epicondylitis with PRP extract reduced pain and significantly increased function, exceeding the effect of low level laser therapy on long term followup. Low-level laser therapy is better in the…","kw":"Elbow Lateral epicondylitis Nirschl pain score laser therapy low level laser therapy plasma"},{"pmid":"24957189","title":"Effect of pre-irradiation with different doses, wavelengths, and application intervals of low-level laser therapy on cytochrome c oxidase activity in intact skeletal muscle of rats.","journal_abbr":"Lasers Med Sci","authors":["Albuquerque-Pontes GM","Vieira RP","Tomazoni SS","et al."],"date":"2014-06-24","year":2014,"doi":"10.1007/s10103-014-1616-2","cited_by":84,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"preclinical","level":5,"ctx":[],"nm":[660,830,905],"pre":"vivo","l1":"We conclude that LLLT can increase cytochrome c oxidase activity in intact skeletal muscle and that it contributes to our understanding of how LLLT can enhance performance and protect skeletal muscles against fatigue development and…","kw":"Animals Dose-Response Relationship, Radiation Electron Transport Complex IV Immunohistochemistry Low-Level Light Therapy Male"},{"pmid":"24942380","title_fr":"Laser superpulsé et LED combinés : performance et récupération musculaires","type":"rct","level":2,"pop":"adulte","ctx":["blessures"],"aim":"prévention","mode":["laser","LED"],"nm":[670,875,905],"n":null,"effect":"favorable","theme":"Blessures sportives","l1":"Avant l'effort, l'association laser + LED, surtout à 30 J, augmente la performance, réduit les courbatures et les marqueurs de lésion musculaire.","l2":"—","l3":{"points":["Fenêtre de dose."],"limites":["—"],"pratique":"—"},"em":["super"],"pre":"","nm_auto":true,"topic":"sport","title":"Phototherapy in skeletal muscle performance and recovery after exercise: effect of combination of super-pulsed laser and light-emitting diodes.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Antonialli FC","De Marchi T","Tomazoni SS","et al."],"date":"2014-06-19","year":2014,"week":"2014-S25","doi":"10.1007/s10103-014-1611-7","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":84,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Recent studies with phototherapy have shown positive results in enhancement of performance and improvement of recovery when applied before exercise. However, several factors still remain unknown such as therapeutic windows, optimal treatment parameters, and effects of combination of different light sources (laser and LEDs). The aim of this study was to evaluate the effects of phototherapy with the combination of different light sources on skeletal muscle performance and post-exercise recovery, and to establish the optimal energy dose. A randomized, double-blinded, placebo-controlled trial with participation of 40 male healthy untrained volunteers was performed. A single phototherapy intervention was performed immediately after pre-exercise (baseline) maximum voluntary contraction (MVC) with a cluster of 12 diodes (4 of 905 nm lasers-0.3125 mW each, 4 of 875 nm LEDs-17.5 mW each, and 4 of 670 nm LEDs-15 mW each- manufactured by Multi Radiance Medical™) and dose of 10, 30, and 50 J or placebo in six sites of quadriceps. MVC, delayed onset muscle soreness (DOMS), and creatine kinase (CK) activity were analyzed. Assessments were performed before, 1 min, 1, 24, 48, 72, and 96 h after eccentric exercise protocol employed to induce fatigue. Phototherapy increased (p < 0.05) MVC was compared to placebo from immediately after to 96 h after exercise with 10 or 30 J doses (better results with 30 J dose). DOMS was significantly decreased compared to placebo (p < 0.05) with 30 J dose from 24 to 96 h after exercise, and with 50 J dose from immediately after to 96 h after exercise. CK activity was significantly decreased (p < 0.05) compared to placebo with all phototherapy doses from 1 to 96 h after exercise (except for 50 J dose at 96 h). Pre-exercise phototherapy with combination of low-level laser and LEDs, mainly with 30 J dose, significantly increases performance, decreases DOMS, and improves biochemical marker related to skeletal muscle damage."}],"keywords":[]},{"pmid":"24925070","title_fr":"Laser et épreuve d'effort cardiorespiratoire chez l'adulte non entraîné","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"—","mode":["laser"],"nm":[850],"n":null,"effect":"favorable","theme":"Performance musculaire","l1":"Le laser augmente la performance à l'épreuve d'effort, probablement par une meilleure extraction d'oxygène musculaire.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Acute effects of low-level laser therapy on physiologic and electromyographic responses to the cardiopulmonary exercise testing in healthy untrained adults.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["da Silva Alves MA","Pinfildi CE","Neto LN","et al."],"date":"2014-06-13","year":2014,"week":"2014-S24","doi":"10.1007/s10103-014-1595-3","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":33,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Despite the positive effects of low-level laser therapy (LLLT) on muscle fatigue before exercises using a single muscle group, the acute effects of LLLT on performance in cardiopulmonary exercise testing (CPET) are poorly understood. We aimed to assess the acute effects of LLLT on physiologic and electromyographic responses to the CPET in healthy adults. A randomized, double-blind, placebo-controlled crossover trial was performed with 18 untrained participants (nine males, 22 ± 2 years). We applied LLLT or placebo on quadriceps and gastrocnemius 10 min before two rapidly incremental CPETs randomly performed in alternate days on a cycle ergometer. Participants received LLLT using a multidiode cluster, 20 s/site (850 nm, 100 mW/diode, 14 J/site). Physiological responses to the CPET were continuously monitored using a gas analyzer. The electromyographic fatigue threshold (EMGth) was assessed through surface electrodes on vastus lateralis. The root mean square (RMS) was plotted every 5 s against the exercise intensity, and its breakpoint values throughout the CPET was identified as EMGth. Compared to placebo, the LLLT significantly increased peak O2 uptake (V'O2 33 ± 10 vs. 31 ± 9 mL/min/kg). We observed a shallower slope of the Δheart rate/ΔV'O2 during the CPET after LLLT compared to placebo, i.e., increased cardiovascular efficiency (56 ± 24 vs. 66 ± 30 bpm/L/min). There were no LLLT-related changes in EMGth. The LLLT acutely increases exercise performance in healthy untrained adults probably due to increased O2 extraction by peripheral muscles without causing a significant impact on muscle fatigue."}],"keywords":[]},{"pmid":"24716713","title_fr":"Laser avant l'effort et performance isocinétique chez le diabétique de type 2 : protocole","type":"protocol","level":0,"pop":"adulte","ctx":["populations"],"aim":"—","mode":["laser"],"nm":[],"n":null,"effect":"—","theme":"Sujets âgés & malades chroniques","l1":"Protocole d'essai sur le laser avant l'effort chez le diabétique de type 2.","l2":"—","l3":{"points":["—"],"limites":["Protocole."],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Efficacy of pre-exercise low-level laser therapy on isokinetic muscle performance in individuals with type 2 diabetes mellitus: study protocol for a randomized controlled trial.","journal":"Trials","journal_abbr":"Trials","authors":["Gomes CA","Leal-Junior EC","Biasotto-Gonzalez DA","et al."],"date":"2014-04-09","year":2014,"week":"2014-S15","doi":"10.1186/1745-6215-15-116","pmcid":"PMC4021637","license":"cc by","oa":true,"pdf":"pdfs/24716713.pdf","cited_by":4,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"BACKGROUND","text":"Type 2 diabetes, also known non-insulin-dependent diabetes, is the most prevalent type of the disease and involves defects in the secretion and action of insulin. The aim of the proposed study is to evaluate the efficacy of pre-exercise low-level laser therapy (LLLT) on muscle performance of the quadriceps femoris in individuals with type 2 diabetes."},{"label":"METHODS/DESIGN","text":"A double-blind, randomized, controlled clinical trial will be carried out in two treatment phases. In the first phase, quadriceps muscle performance will be evaluated using an isokinetic dynamometer and the levels of creatine kinase and lactate dehydrogenase (biochemical markers of muscle damage) will be determined. The participants will then be allocated to four LLLT groups through a randomization process using opaque envelopes: Group A (4 Joules), Group B (6 Joules), Group C (8 Joules) and Group D (0 Joules; placebo). Following the administration of LLLT, the participants will be submitted to an isokinetic eccentric muscle fatigue protocol involving the quadriceps muscle bilaterally. Muscle performance and biochemical markers of muscle damage will be evaluated again immediately after as well as 24 and 48 hours after the experimental protocol. One week after the last evaluation the second phase will begin, during which Groups A, B and C will receive the LLLT protocol that achieved the best muscle performance in phase 1 for a period of 4 weeks. At the end of this period, muscle performance will be evaluated again. The protocol for this study is registered with the World Health Organization under Universal Trial Number U1111-1146-7109."},{"label":"DISCUSSION","text":"The purpose of this randomized clinical trial is to evaluate the efficacy of pre-exercise LLLT on the performance of the quadriceps muscle (peak torque, total muscle work, maximum power and fatigue index - normalized by body mass) in individuals with DM-2. The study will support the practice of evidence-based to the use of LLLT in improving muscle performance in Individuals with DM-2. Data will be published after the study is completed."}],"keywords":[]},{"pmid":"24651950","title":"Effects of pre-irradiation of low-level laser therapy with different doses and wavelengths in skeletal muscle performance, fatigue, and skeletal muscle damage induced by tetanic contractions in rats.","journal_abbr":"Lasers Med Sci","authors":["Santos LA","Marcos RL","Tomazoni SS","et al."],"date":"2014-03-21","year":2014,"doi":"10.1007/s10103-014-1560-1","cited_by":39,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"preclinical","level":5,"ctx":["performance","récupération"],"nm":[660,905],"pre":"vivo","l1":"Our findings also demonstrate that optimal doses are partly wavelength specific and, consequently, must be differentiated to obtain optimal effects on development of skeletal muscle fatigue and tissue preservation. Our findings also lead…","kw":"Animals Biomechanical Phenomena Creatine Kinase Dose-Response Relationship, Radiation Electric Stimulation Low-Level Light Therapy"},{"pmid":"24622816","title_fr":"Laser basse énergie sur cinq jours dans la périostite tibiale du sportif","type":"rct","level":2,"pop":"adulte","ctx":["blessures"],"aim":"traitement","mode":["laser"],"nm":[],"n":null,"effect":"favorable","theme":"Blessures sportives","l1":"Dans la périostite de jambe due au surentraînement, cinq jours de laser améliorent la fonction des membres inférieurs.","l2":"Essai randomisé contrôlé chez l'homme adulte.","l3":{"points":["Récupération fonctionnelle."],"limites":["Mécanisme proprioceptif incertain."],"pratique":"Option en rééducation."},"em":[],"pre":"","topic":"sport","title":"Five-day, low-level laser therapy for sports-related lower extremity periostitis in adult men: a randomized, controlled trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Chang CC","Ku CH","Hsu WC","et al."],"date":"2014-03-13","year":2014,"week":"2014-S11","doi":"10.1007/s10103-014-1554-z","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":4,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Periostitis in the lower leg caused by overexercise is a universal problem in athletes and runners. The purpose of this study was to observe the functional improvement of the lower limbs upon rehabilitation low-level laser therapy (LLLT). All medical data were gathered from enrolled adults with sports-related lower leg pain. A total of 54 patients underwent triple-phase bone scans using skeletal nuclear scintigraphy, which confirmed periostitis in their lower limbs. The patients were then randomly divided into two groups: one group received laser therapy (N = 29) and the other group (N = 25) received an equivalent placebo treatment (a drug or physical therapy). Treatment protocol commenced with rehabilitation intervention and LLLT was performed three times daily for 5 days at a dosage of 1.4 J/cm(2). A Likert-type pain scale was used to evaluate the severity of pain. Balance function, including postural stability testing (PST) and limits of stability (LOS), was also performed to evaluate the function outcome. Patients experienced a significant improvement in pain by day 2 or day 5 after starting LLLT, but here was no significant difference in pain scale between the measurements before (baseline) and after LLLT. Comparing the PST, the group differences of dynamic vs. static testings ranged from -18.54 to -50.22 (compared 12, 8, 4, 3, 2, 1 to 0, all p < 0.0001), and the PST after LLLT were 3.73 units (p = 0.0258) lower than those of before LLLT. Comparing the LOS, the group differences of dynamic vs. static testing were similar to those in PST, and the relationship between LOS and groups only varied with the direction control during dynamic testing in direction at backward/right vs. right (p < 0.0001). LLLT had a positive effect on proprioception in patients with lower limb periostitis. Larger, better controlled studies are needed to determine what specific effects LLLT has on the function of proprioception."}],"keywords":[]},{"pmid":"24599021","title":"Superpulsed low-level laser therapy protects skeletal muscle of mdx mice against damage, inflammation and morphological changes delaying dystrophy progression.","journal_abbr":"PLoS One","authors":["Leal-Junior EC","de Almeida P","Tomazoni SS","et al."],"date":"2014-03-05","year":2014,"doi":"10.1371/journal.pone.0089453","pmcid":"PMC3943729","license":"cc by","oa":true,"cited_by":29,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"preclinical","level":5,"ctx":["récupération","populations"],"nm":[904],"em":["super","pulse"],"pre":"vivo","l1":"Irradiation of superpulsed LLLT on successive days five times per week for 14 weeks decreased morphological changes, skeletal muscle damage and inflammation in mdx mice. This indicates that LLLT has potential to decrease progression of…","kw":"Animals Creatine Kinase Cyclooxygenase 2 Disease Progression Gene Expression Interleukins"},{"pmid":"24576321","title_fr":"Dose et puissance idéales du laser 810 nm sur la performance musculaire : protocole","type":"protocol","level":0,"pop":"adulte","ctx":["récupération"],"aim":"—","mode":["laser"],"nm":[810],"n":28,"effect":"—","theme":"Récupération & courbatures","l1":"Protocole d'essai chez 28 athlètes pour définir la dose et la puissance optimales du laser 810 nm.","l2":"NCT01844271.","l3":{"points":["—"],"limites":["Protocole."],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"What is the ideal dose and power output of low-level laser therapy (810 nm) on muscle performance and post-exercise recovery? Study protocol for a double-blind, randomized, placebo-controlled trial.","journal":"Trials","journal_abbr":"Trials","authors":["de Oliveira AR","Vanin AA","De Marchi T","et al."],"date":"2014-02-27","year":2014,"week":"2014-S09","doi":"10.1186/1745-6215-15-69","pmcid":"PMC3944795","license":"cc by","oa":true,"pdf":"pdfs/24576321.pdf","cited_by":7,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"BACKGROUND","text":"Recent studies involving phototherapy applied prior to exercise have demonstrated positive results regarding the attenuation of muscle fatigue and the expression of biochemical markers associated with recovery. However, a number of factors remain unknown, such as the ideal dose and application parameters, mechanisms of action and long-term effects on muscle recovery. The aims of the proposed project are to evaluate the long-term effects of low-level laser therapy on post-exercise musculoskeletal recovery and identify the best dose andapplication power/irradiation time."},{"label":"DESIGN AND METHODS","text":"A double-blind, randomized, placebo-controlled clinical trial with be conducted. After fulfilling the eligibility criteria, 28 high-performance athletes will be allocated to four groups of seven volunteers each. In phase 1, the laser power will be 200 mW and different doses will be tested: Group A (2 J), Group B (6 J), Group C (10 J) and Group D (0 J). In phase 2, the best dose obtained in phase 1 will be used with the same distribution of the volunteers, but with different powers: Group A (100 mW), Group B (200 mW), Group C (400 mW) and Group D (0 mW). The isokinetic test will be performed based on maximum voluntary contraction prior to the application of the laser and after the eccentric contraction protocol, which will also be performed using the isokinetic dynamometer. The following variables related to physical performance will be analyzed: peak torque/maximum voluntary contraction, delayed onset muscle soreness (algometer), biochemical markers of muscle damage, inflammation and oxidative stress."},{"label":"DISCUSSION","text":"Our intention, is to determine optimal laser therapy application parameters capable of slowing down the physiological muscle fatigue process, reducing injuries or micro-injuries in skeletal muscle stemming from physical exertion and accelerating post-exercise muscle recovery. We believe that, unlike drug therapy, LLLT has a biphasic dose-response pattern."},{"label":"TRIAL REGISTRATION","text":"The protocol for this study is registered with the Protocol Registry System, ClinicalTrials.gov identifier NCT01844271."}],"keywords":[]},{"pmid":"24568233","title":"Significant improvements in cognitive performance post-transcranial, red/near-infrared light-emitting diode treatments in chronic, mild traumatic brain injury: open-protocol study.","journal_abbr":"J Neurotrauma","authors":["Naeser MA","Zafonte R","Krengel MH","et al."],"date":"2014-02-27","year":2014,"doi":"10.1089/neu.2013.3244","pmcid":"PMC4043367","cited_by":181,"pub_types":["Research Support, N.I.H., Extramural","Research Support, Non-U.S. Gov't","Research Support, U.S. Gov't, Non-P.H.S."],"curated":false,"type":"autre","level":0,"ctx":["performance","blessures","populations"],"l1":"Participants and family reported better ability to perform social, interpersonal, and occupational functions. These open-protocol data suggest that placebo-controlled studies are warranted.","kw":"executive function mTBI photobiomodulation treatment for mTBI Adult Brain Concussion Brain Injury, Chronic Chronic Disease Cognition Disability Evaluation"},{"pmid":"24456143","title_fr":"Laser 830 nm avant ou après l'effort : fatigue et marqueurs de récupération","type":"rct","level":2,"pop":"adulte","ctx":["récupération"],"aim":"les deux","mode":["laser"],"nm":[830],"n":27,"effect":"favorable","theme":"Récupération & courbatures","l1":"Chez 27 footballeurs, le laser avant ou après l'effort réduit lactates et CK, surtout appliqué après.","l2":"Double aveugle contre placebo.","l3":{"points":["Timing comparé."],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Effects of pre- or post-exercise low-level laser therapy (830 nm) on skeletal muscle fatigue and biochemical markers of recovery in humans: double-blind placebo-controlled trial.","journal":"Photomedicine and laser surgery","journal_abbr":"Photomed Laser Surg","authors":["Dos Reis FA","da Silva BA","Laraia EM","et al."],"date":"2014-01-23","year":2014,"week":"2014-S04","doi":"10.1089/pho.2013.3617","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":57,"pub_types":["Comparative Study","Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"OBJECTIVES","text":"The purpose of this study was to investigate the effect of low-level laser therapy (LLLT) before and after exercise on quadriceps muscle performance, and to evaluate the changes in serum lactate and creatine kinase (CK) levels."},{"label":"METHODS","text":"The study was randomized, double blind, and placebo controlled."},{"label":"PATIENTS","text":"A sample of 27 healthy volunteers (male soccer players) were divided into three groups: placebo, pre-fatigue laser, and post-fatigue laser. The experiment was performed in two sessions, with a 1 week interval between them. Subjects performed two sessions of stretching followed by blood collection (measurement of lactate and CK) at baseline and after fatigue of the quadriceps by leg extension. LLLT was applied to the femoral quadriceps muscle using an infrared laser device (830 nm), 0.0028 cm(2) beam area, six 60 mW diodes, energy of 0.6 J per diode (total energy to each limb 25.2 J (50.4 J total), energy density 214.28 J/cm(2), 21.42 W/cm(2) power density, 70 sec per leg. We measured the time to fatigue and number and maximum load (RM) of repetitions tolerated. Number of repetitions and time until fatigue were primary outcomes, secondary outcomes included serum lactate levels (measured before and 5, 10, and 15 min after exercise), and CK levels (measured before and 5 min after exercise)."},{"label":"RESULTS","text":"The number of repetitions (p=0.8965), RM (p=0.9915), and duration of fatigue (p=0.8424) were similar among the groups. Post-fatigue laser treatment significantly decreased the serum lactate concentration relative to placebo treatment (p<0.01) and also within the group over time (after 5 min vs. after 10 and 15 min, p<0.05 both). The CK level was lower in the post-fatigue laser group (p<0.01)."},{"label":"CONCLUSIONS","text":"Laser application either before or after fatigue reduced the post-fatigue concentrations of serum lactate and CK. The results were more pronounced in the post-fatigue laser group."}],"keywords":[]},{"pmid":"24320801","title_fr":"Laser et fatigue du biceps chez la jeune femme","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser"],"nm":[808],"n":20,"effect":"neutre","theme":"Performance musculaire","l1":"Chez 20 jeunes femmes, le laser a un effet limité sur la fatigue du biceps, avec seulement une tendance électromyographique.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Effects of low-level laser therapy on biceps braquialis muscle fatigue in young women.","journal":"Photomedicine and laser surgery","journal_abbr":"Photomed Laser Surg","authors":["Higashi RH","Toma RL","Tucci HT","et al."],"date":"2013-12-11","year":2013,"week":"2013-S50","doi":"10.1089/pho.2012.3388","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":37,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"OBJECTIVE","text":"This study aims to investigate the effects of low-level laser therapy (LLLT) on biceps brachi muscular fatigue in 20 young females."},{"label":"BACKGROUND DATA","text":"Exhausting physical activity leads to muscular fatigue, which could decrease muscular strength, and may cause impairment in motor control and muscle pain. Several biochemical and biophysical resources have been studied in an attempt to accelerate the recovery of muscle fatigue. Among these, LLLT is emphasized."},{"label":"METHODS","text":"Twenty subjects were randomized in one laser group and one placebo group in two sessions of a crossover design experimental procedure; the second session taking place within 7 days of the first. In the first session, subjects underwent a collection of surface electromyographic (SEMG) data of the biceps brachii muscle, followed by active or placebo LLLT at the same muscle, followed then by another EMG sample of biceps brachii. Blood samples were collected five times during the experimental procedure. Second session procedures were identical to the first, with exception of LLLT, which was the opposite of the first session. The fatigue protocol consisted of 60 sec of elbow flexion-extension movement performed with 75% of one maximum repetition. Blood lactate, EMG fatigue, and the number of elbow flexion-extension repetitions during the fatigue protocol were used to evaluate the effects of laser therapy (808 nm wavelength, 100 mW output power, power density of 35.7 W/cm(2), 70 sec each point and 7 J/point on eight points)."},{"label":"RESULTS","text":"No statistical differences were found for eletromyographic fatigue and blood lactate values between groups. Mean numbers of elbow flexion-extension repetitions were 22.6 ± 7.58 after placebo, and 25.1 ± 9.89 after active LLLT group, but these differences were not statistically significant (p=0.342)."},{"label":"CONCLUSIONS","text":"LLLT had limited effects on delaying muscle fatigue in a young female sample, although a tendency was observed in the active laser group toward showing lower electromyography fatigue of biceps brachii muscle. No intergroup differences were found in the number of muscle contractions and lactate concentration."}],"keywords":[]},{"pmid":"24288083","title":"Phototherapy effect on the muscular activity of regular physical activity practitioners.","journal_abbr":"Lasers Med Sci","authors":["dos Santos Maciel T","Muñoz IS","Nicolau RA","et al."],"date":"2013-11-28","year":2013,"doi":"10.1007/s10103-013-1481-4","cited_by":20,"pub_types":["Controlled Clinical Trial","Research Support, Non-U.S. Gov't"],"curated":false,"type":"nrct","level":3,"ctx":["performance"],"nm":[780],"l1":"It is concluded that the LLLT increased the muscle torque at the beginning of the exercise and maintained the levels of lactate after resistance exercise. Therefore, the LLLT with the parameters used in this study can be utilized in…","kw":"Double-Blind Method Exercise Female Humans Lactic Acid Motor Activity"},{"pmid":"24258312","title_fr":"LED 630 nm et récupération musculaire après un exercice lésionnel","type":"rct","level":2,"pop":"adulte","ctx":["blessures"],"aim":"traitement","mode":["LED"],"nm":[630],"n":17,"effect":"favorable","theme":"Blessures sportives","l1":"Chez 17 hommes, la LED 630 nm après un exercice excentrique réduit les courbatures et la perte de force et d'amplitude.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Light-emitting diode phototherapy improves muscle recovery after a damaging exercise.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Borges LS","Cerqueira MS","dos Santos Rocha JA","et al."],"date":"2013-11-21","year":2013,"week":"2013-S47","doi":"10.1007/s10103-013-1486-z","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":24,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"The goal of the present study was to determine the effect of light-emitting diode phototherapy (LEDT) at 630 nm on muscle recovery after a damaging eccentric exercise bout. Seventeen healthy young male volunteers, without previous experience with eccentric exercise, were included in a randomized double-blinded placebo-controlled trial. They were divided into a LEDT (n = 8) and a PLACEBO group (n = 9). To induce muscle damage, subjects performed 30 eccentric contractions with a load of 100 % of maximal voluntary isometric contraction strength of the elbow flexors of the non-dominant arm. LEDT group subjects received biceps brachii phototherapy (λ 630 nm; total energy density, 20.4 J/cm2) immediately after the exercise bout. The LEDT in the placebo group was aimed at the muscle, but it remained turned off. Isometric muscle strength, muscle soreness, and elbow range of motion (ROM) were measured before and at 24, 48, 72, and 96 h the after eccentric exercise bout and compared between groups. Our results showed that the muscle soreness, muscle strength loss, and ROM impairments were significantly reduced up to 96 h after a damaging eccentric exercise bout for the LEDT group compared with the PLACEBO group. A single LEDT (630 nm) intervention immediately after a damaging eccentric exercise bout was effective in terms of attenuating the muscle soreness and muscle strength loss and ROM impairments."}],"keywords":[]},{"pmid":"24249354","title_fr":"Photothérapie, performance et récupération à l'effort : méta-analyse","type":"ma","level":1,"pop":"adulte","ctx":["récupération"],"aim":"prévention","mode":["laser","LED"],"nm":[],"n":null,"effect":"favorable","theme":"Récupération & courbatures","l1":"Laser et LED améliorent la performance musculaire et accélèrent la récupération, surtout appliqués avant l'effort, à 5–6 J par point.","l2":"—","l3":{"points":["Doses repères."],"limites":["—"],"pratique":"5–6 J par point avant l'effort."},"em":[],"pre":"","topic":"sport","title":"Effect of phototherapy (low-level laser therapy and light-emitting diode therapy) on exercise performance and markers of exercise recovery: a systematic review with meta-analysis.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Leal-Junior EC","Vanin AA","Miranda EF","et al."],"date":"2013-11-19","year":2013,"week":"2013-S47","doi":"10.1007/s10103-013-1465-4","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":172,"pub_types":["Meta-Analysis","Research Support, Non-U.S. Gov't","Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Recent studies have explored if phototherapy with low-level laser therapy (LLLT) or narrow-band light-emitting diode therapy (LEDT) can modulate activity-induced skeletal muscle fatigue or subsequently protect against muscle injury. We performed a systematic review with meta-analysis to investigate the effects of phototherapy applied before, during and after exercises. A literature search was performed in Pubmed/Medline database for randomized controlled trials (RCTs) published from 2000 through 2012. Trial quality was assessed with the ten-item PEDro scale. Main outcome measures were selected as: number of repetitions and time until exhaustion for muscle performance, and creatine kinase (CK) activity to evaluate risk for exercise-induced muscle damage. The literature search resulted in 16 RCTs, and three articles were excluded due to poor quality assessment scores. From 13 RCTs with acceptable methodological quality (≥6 of 10 items), 12 RCTs irradiated phototherapy before exercise, and 10 RCTs reported significant improvement for the main outcome measures related to performance. The time until exhaustion increased significantly compared to placebo by 4.12 s (95% CI 1.21-7.02, p < 0.005) and the number of repetitions increased by 5.47 (95% CI 2.35-8.59, p < 0.0006) after phototherapy. Heterogeneity in trial design and results precluded meta-analyses for biochemical markers, but a quantitative analysis showed positive results in 13 out of 16 comparisons. The most significant and consistent results were found with red or infrared wavelengths and phototherapy application before exercises, power outputs between 50 and 200 mW and doses of 5 and 6 J per point (spot). We conclude that phototherapy (with lasers and LEDs) improves muscular performance and accelerate recovery mainly when applied before exercise."}],"keywords":[]},{"pmid":"24155545","title":"Low level laser therapy for sports injuries.","journal_abbr":"Laser Ther","authors":["Morimoto Y","Saito A","Tokuhashi Y"],"date":"2013-10-25","year":2013,"doi":"10.5978/islsm.13-or-01","pmcid":"PMC3799051","cited_by":19,"curated":false,"type":"autre","level":0,"ctx":["blessures"],"l1":"LLLT is an effective treatment for sports injuries, particularly jumper's knee, tennis elbow and Achilles tendinitis.","kw":"Low level laser therapy (LLLT) Sports injuries"},{"pmid":"24102167","title":"Effect of low-level laser therapy (808 nm) in skeletal muscle after resistance exercise training in rats.","journal_abbr":"Photomed Laser Surg","authors":["Patrocinio T","Sardim AC","Assis L","et al."],"date":"2013-10-10","year":2013,"doi":"10.1089/pho.2013.3540","cited_by":14,"curated":false,"type":"preclinical","level":5,"ctx":[],"nm":[808],"pre":"vivo","l1":"These results suggest that LLLT could be an effective therapeutic approach in increasing muscle performance during a resistance exercise protocol.","kw":"Animals Glycogen Lactates Low-Level Light Therapy Male Muscle, Skeletal"},{"pmid":"24005882","title_fr":"Laser 808 nm et marqueurs de lésion musculaire : essai en double aveugle","type":"rct","level":2,"pop":"adulte","ctx":["blessures"],"aim":"prévention","mode":["laser"],"nm":[808],"n":null,"effect":"mitigé","theme":"Blessures sportives","l1":"Le laser réduit les CK 72 heures après un exercice lésionnel du biceps, sans accélérer la récupération de force.","l2":"—","l3":{"points":["Double aveugle."],"limites":["Pas d'effet fonctionnel."],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Effect of low-level laser therapy (808 nm) on markers of muscle damage: a randomized double-blind placebo-controlled trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Felismino AS","Costa EC","Aoki MS","et al."],"date":"2013-09-05","year":2013,"week":"2013-S36","doi":"10.1007/s10103-013-1430-2","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":33,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"The aim of this randomized double-blind placebo-controlled study was to investigate the effect of low-level laser therapy (LLLT) on markers of muscle damage (creatine kinase (CK) and strength performance) in the biceps brachii. Twenty-two physically active men were randomized into two groups: placebo and laser. All volunteers were submitted to an exercise-induced muscle damage protocol for biceps brachii (biceps curl, 10 sets of 10 repetitions with load of 50% of one-repetition maximum test (1RM)). Active LLLT (808 nm; 100 mW; 35.7 W/cm(2), 357.14 J/cm(2) per point, energy of 1 J per point applied for 10 s on four points of the biceps brachii belly of each arm) or placebo was applied between the sets of the biceps curl exercise. CK activity and maximum strength performance (1RM) were measured before, immediately after, 24, 48, and 72 h after the exercise-induced muscle damage protocol. There was an increase in CK activity after the muscle damage protocol in both groups; however, this increase was attenuated in the laser group compared to the placebo group at 72 h (placebo = 841 vs. laser = 357%; p < 0.05). Maximum strength performance was decreased immediately after the muscle damage protocol in both groups (p < 0.05), but at 24, 48, and 72 h, and it returned to the baseline level in both groups. In conclusion, the LLLT attenuated CK activity 72 h after the muscle damage protocol but did not have a positive effect on the recovery of strength performance."}],"keywords":[]},{"pmid":"23895414","title_fr":"Photothérapie pendant l'entraînement sur tapis et performance du quadriceps chez la femme ménopausée","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"—","mode":["LED"],"nm":[],"n":30,"effect":"favorable","theme":"Performance musculaire","l1":"Chez 30 femmes ménopausées, la LED infrarouge pendant l'entraînement augmente la puissance du quadriceps et réduit la fatigue mieux que l'exercice seul.","l2":"—","l3":{"points":["Trois groupes."],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Phototherapy during treadmill training improves quadriceps performance in postmenopausal women.","journal":"Climacteric : the journal of the International Menopause Society","journal_abbr":"Climacteric","authors":["Paolillo FR","Corazza AV","Paolillo AR","et al."],"date":"2013-07-31","year":2013,"week":"2013-S31","doi":"10.3109/13697137.2013.828196","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":7,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"OBJECTIVE","text":"To evaluate the effects of infrared-light-emitting diode (LED) during treadmill training on functional performance."},{"label":"METHODS","text":"Thirty postmenopausal women aged 50-60 years were randomly assigned to one of three groups and successfully completed the full study. The three groups were: (1) the LED group, which performed treadmill training associated with phototherapy (n = 10); (2) the exercise group, which carried out treadmill training only (n = 10); and (3) the sedentary group, which neither performed physical training nor underwent phototherapy (n = 10). Training was performed over a period of 6 months, twice a week for 45 min per session at 85-90% of maximal heart rate, which was obtained during progressive exercise testing. The irradiation parameters were 100 mW, 39 mW/cm(2) and 108 J/cm(2) for 45 min. Quadriceps performance was measured during isokinetic exercise testing at 60°/s and 300°/s."},{"label":"RESULTS","text":"Peak torque did not differ amongst the groups. However, the results showed significantly higher values of power and total work for the LED group (∆ = 21 ± 6 W and ∆ = 634 ± 156 J, p < 0.05) when compared to both the exercise group (∆ = 13 ± 10 W and = 410 ± 270 J) and the sedentary group (∆ = 10 ± 9 W and ∆ = 357 ± 327 J). Fatigue was also significantly lower in the LED group (∆ = -7 ± 4%, p < 0.05) compared to both the exercise group (∆ = 3 ± 8%) and the sedentary group (∆ = -2 ± 6%)."},{"label":"CONCLUSIONS","text":"Infrared-LED during treadmill training may improve quadriceps power and reduce peripheral fatigue in postmenopausal women."}],"keywords":["INFRARED","MUSCLE PERFORMANCE","PHOTOTHERAPY","PHYSICAL TRAINING","POSTMENOPAUSE"]},{"pmid":"23878775","title":"Mechanical solution for a mechanical problem: Tennis elbow.","journal_abbr":"World J Orthop","authors":["Rothschild B"],"date":"2013-07-18","year":2013,"doi":"10.5312/wjo.v4.i3.103","pmcid":"PMC3717240","cited_by":5,"curated":false,"type":"autre","level":0,"ctx":[],"l1":"Thin bands are required, as thick bands (e.g., 2-3 inch wide) simply reduce muscle strength, without significantly reducing stress. This approach appears to be associated with a failure rate less than 1%, assuming the afflicted individual…","kw":"Adaptive equipment Elbow Epicondylitis Inflammation Mechanical overload Tennis elbow"},{"pmid":"23780711","title":"LED therapy or cryotherapy between exercise intervals in Wistar rats: anti-inflammatory and ergogenic effects.","journal_abbr":"Lasers Med Sci","authors":["da Costa Santos VB","de Paula Ramos S","Milanez VF","et al."],"date":"2013-06-19","year":2013,"doi":"10.1007/s10103-013-1371-9","cited_by":19,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"preclinical","level":5,"ctx":["performance"],"nm":[940],"pre":"both","l1":"CRP was decreased in LED animals. We conclude that LED therapy and cryotherapy can improve performance, although LED therapy is more efficient in preventing muscle damage and local and systemic inflammation.","kw":"Animals C-Reactive Protein Cryotherapy Inflammation Lasers, Semiconductor Leukocyte Count"},{"pmid":"23672326","title_fr":"La photothérapie améliore-t-elle la contraction musculaire et la récupération ? Revue systématique","type":"sr","level":1,"pop":"adulte","ctx":["récupération"],"aim":"prévention","mode":["laser","LED"],"nm":[],"n":null,"effect":"favorable","theme":"Récupération & courbatures","l1":"Appliquée avant un exercice de résistance, la photothérapie apporte de façon constante des bénéfices ergogéniques et protecteurs pour le muscle.","l2":"—","l3":{"points":["Résultat constant."],"limites":["—"],"pratique":"Appliquer avant l'effort."},"em":[],"pre":"","topic":"sport","title":"Does phototherapy enhance skeletal muscle contractile function and postexercise recovery? A systematic review.","journal":"Journal of athletic training","journal_abbr":"J Athl Train","authors":["Borsa PA","Larkin KA","True JM"],"date":"2013-05-16","year":2013,"week":"2013-S20","doi":"10.4085/1062-6050-48.1.12","pmcid":"PMC3554033","license":null,"oa":false,"pdf":null,"cited_by":87,"pub_types":["Systematic Review"],"curated":true,"depth":1,"abstract":[{"label":"CONTEXT","text":"Recently, researchers have shown that phototherapy administered to skeletal muscle immediately before resistance exercise can enhance contractile function, prevent exercise-induced cell damage, and improve postexercise recovery of strength and function."},{"label":"OBJECTIVE","text":"To critically evaluate original research addressing the ability of phototherapeutic devices, such as lasers and light-emitting diodes (LEDs), to enhance skeletal muscle contractile function, reduce exercise-induced muscle fatigue, and facilitate postexercise recovery."},{"label":"DATA SOURCES","text":"We searched the electronic databases PubMed, SPORTDiscus, Web of Science, Scopus, and Rehabilitation & Physical Medicine without date limitations for the following key words: laser therapy, phototherapy, fatigue, exercise, circulation, microcirculation, and photobiomodulation."},{"label":"STUDY SELECTION","text":"Eligible studies had to be original research published in English as full papers, involve human participants, and receive a minimum score of 7 out of 10 on the Physiotherapy Evidence Database (PEDro) scale."},{"label":"DATA EXTRACTION","text":"Data of interest included elapsed time to fatigue, total number of repetitions to fatigue, total work performed, maximal voluntary isometric contraction (strength), electromyographic activity, and postexercise biomarker levels. We recorded the PEDro scores, beam characteristics, and treatment variables and calculated the therapeutic outcomes and effect sizes for the data sets."},{"label":"DATA SYNTHESIS","text":"In total, 12 randomized controlled trials met the inclusion criteria. However, we excluded data from 2 studies, leaving 32 data sets from 10 studies. Twenty-four of the 32 data sets contained differences between active phototherapy and sham (placebo-control) treatment conditions for the various outcome measures. Exposing skeletal muscle to single-diode and multidiode laser or multidiode LED therapy was shown to positively affect physical performance by delaying the onset of fatigue, reducing the fatigue response, improving postexercise recovery, and protecting cells from exercise-induced damage."},{"label":"CONCLUSIONS","text":"Phototherapy administered before resistance exercise consistently has been found to provide ergogenic and prophylactic benefits to skeletal muscle."}],"keywords":[]},{"pmid":"23626925","title":"Low-level laser (light) therapy (LLLT) on muscle tissue: performance, fatigue and repair benefited by the power of light.","journal_abbr":"Photonics Lasers Med","authors":["Ferraresi C","Hamblin MR","Parizotto NA"],"date":"2013-04-30","year":2013,"doi":"10.1515/plm-2012-0032","pmcid":"PMC3635110","cited_by":139,"curated":false,"type":"autre","level":0,"ctx":["performance","récupération","blessures"],"l1":"This review covers the literature relating to LLLT and muscles in both preclinical animal experiments and human clinical studies. Athletes, people with injured muscles, and patients with Duchenne muscular dystrophy may all benefit.","kw":"ATP low level laser therapy mitochondria muscle fatigue muscle injury reactive oxygen species"},{"pmid":"23602883","title":"Slowed down: response time deficits in well-recovered subjects with incomplete spinal cord injury.","journal_abbr":"Arch Phys Med Rehabil","authors":["Labruyère R","Zimmerli M","van Hedel HJ"],"date":"2013-04-18","year":2013,"doi":"10.1016/j.apmr.2013.04.002","cited_by":9,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"autre","level":0,"ctx":["blessures"],"l1":"Well-recovered patients with incomplete paraplegia still experience difficulties with quick and accurate movements. Furthermore, combining transcranial magnetic stimulation, electromyogram, and a response time task proved useful for…","kw":"ASIA American Spinal Injury Association EMG LED MEP MWUT Electromyography Evoked Potentials, Motor Female Gait Hospitals, University Humans"},{"pmid":"23314262","title":"Physical therapy management of knee osteoarthritis in the middle-aged athlete.","journal_abbr":"Sports Med Arthrosc Rev","authors":["Adams T","Band-Entrup D","Kuhn S","et al."],"date":"2013-01-15","year":2013,"doi":"10.1097/JSA.0b013e318272f530","cited_by":10,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"Modalities [thermal, electrical stimulation (ES), and low-level laser therapy (LLLT)] and orthotic intervention are moderately supported in the literature as indicated management strategies for knee OA. While many strongly supported…","kw":"Athletes Humans Middle Aged Osteoarthritis, Knee Physical Therapy Modalities Treatment Outcome"},{"pmid":"23296713","title_fr":"Laser 808 nm et fatigue musculaire chez la femme âgée","type":"rct","level":2,"pop":"adulte","ctx":["populations"],"aim":"prévention","mode":["laser"],"nm":[808],"n":null,"effect":"mitigé","theme":"Sujets âgés & malades chroniques","l1":"Chez des femmes âgées, le laser augmente le nombre de répétitions de flexion-extension du genou, sans retarder la fatigue électromyographique.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Effect of 808 nm low-level laser therapy in exercise-induced skeletal muscle fatigue in elderly women.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Toma RL","Tucci HT","Antunes HK","et al."],"date":"2013-01-08","year":2013,"week":"2013-S02","doi":"10.1007/s10103-012-1246-5","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":54,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Aging process involves several structural changes in muscle tissue which lead to decrease in musculoskeletal function. One of the most common physiological modifications is the increase in fatigability in elderly people, which leads to inability to maintain strength and motor control. In this context, low-level laser therapy (LLLT) has demonstrated positive results in reducing fatigue during physical exercise. Thus, this study aimed to investigate the effects of LLLT on skeletal muscle fatigue in elderly women. Twenty-four subjects divided in two groups entered a crossover randomized triple-blinded placebo-controlled trial. Active LLLT (808 nm wavelength, 100 mW, energy 7 J) or an identical placebo LLLT was delivered on the rectus femoris muscle immediately before a fatigue protocol. Subjects performed a fatigue protocol which consisted of voluntary isotonic contractions of knee flexion-extension performed with a load corresponding to 75 % of 1-MR (Maximum Repetition) during 60 s. Surface electromyography (SEMG) signals were recorded from rectus femoris muscle of dominant lower limb to evaluate peripheral fatigability using median frequency analysis of SEMG signal. The number of repetitions of flexion-extension during fatigue protocol was also compared between groups. The values of median frequency were used to calculate the slope coefficient. The results showed no difference in the slope comparing placebo LLLT and active LLLT groups (p = 0.293). However, a significant difference was observed in the number of repetitions between groups, after active LLLT, subjects demonstrated significantly higher number of repetitions (p = 0.047). In this study, LLLT was efficient in increasing the mean number of repetitions during knee flexion-extension exercise, although results have not shown delay electromyographic fatigue."}],"keywords":[]},{"pmid":"23182016","title_fr":"Lumière rouge, sommeil et endurance chez des basketteuses de haut niveau","type":"nrct","level":3,"pop":"adulte","ctx":["récupération"],"aim":"traitement","mode":["LED"],"nm":[],"n":null,"effect":"favorable","theme":"Récupération & courbatures","l1":"Quatorze soirs de lumière rouge sur le corps améliorent la qualité du sommeil et l'endurance de joueuses de basket d'élite, avec une hausse de la mélatonine.","l2":"Étude contrôlée contre placebo (J Athl Train).","l3":{"points":["Sommeil du sportif."],"limites":["Petit effectif ; non randomisé."],"pratique":"Piste pour la récupération."},"em":[],"pre":"","topic":"sport","title":"Red light and the sleep quality and endurance performance of Chinese female basketball players.","journal":"Journal of athletic training","journal_abbr":"J Athl Train","authors":["Zhao J","Tian Y","Nie J","et al."],"date":"2012-11-28","year":2012,"week":"2012-S48","doi":"10.4085/1062-6050-47.6.08","pmcid":"PMC3499892","license":null,"oa":false,"pdf":null,"cited_by":51,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"CONTEXT","text":"Good sleep is an important recovery method for prevention and treatment of overtraining in sport practice. Whether sleep is regulated by melatonin after red-light irradiation in athletes is unknown."},{"label":"OBJECTIVE","text":"To determine the effect of red light on sleep quality and endurance performance of Chinese female basketball players."},{"label":"DESIGN","text":"Cohort study."},{"label":"SETTING","text":"Athletic training facility of the Chinese People's Liberation Army and research laboratory of the China Institute of Sport Science. Patients or Other Participants: Twenty athletes of the Chinese People's Liberation Army team (age = 18.60 6 3.60 years) took part in the study. Participants were divided into red-light treatment (n = 10) and placebo (n = 10) groups."},{"label":"INTERVENTION(S)","text":"The red-light treatment participants received 30 minutes of irradiation from a red-light therapy instrument every night for 14 days. The placebo group did not receive light illumination."},{"label":"MAIN OUTCOME MEASURE(S)","text":"The Pittsburgh Sleep Quality Index (PSQI) questionnaire was completed, serum melatonin was assessed, and 12-minute run was performed at preintervention (baseline) and postintervention (14 days)."},{"label":"RESULTS","text":"The 14-day whole-body irradiation with red-light treatment improved the sleep, serum melatonin level, and endurance performance of the elite female basketball players (P < .05). We found a correlation between changes in global Pittsburgh Sleep Quality Index and serum melatonin levels (r = -0.695, P = .006)."},{"label":"CONCLUSIONS","text":"Our study confirmed the effectiveness of body irradiation with red light in improving the quality of sleep of elite female basketball players and offered a nonpharmacologic and noninvasive therapy to prevent sleep disorders after training."}],"keywords":[]},{"pmid":"23053563","title":"Onychomycosis: modern diagnostic and treatment approaches.","journal_abbr":"Wien Med Wochenschr","authors":["Tchernev G","Penev PK","Nenoff P","et al."],"date":"2012-09-30","year":2012,"doi":"10.1007/s10354-012-0139-3","cited_by":39,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"Moreover, detailed information is suggested, about the choice of therapeutic scheme in case whether dermatophytes, moulds, or yeasts have been identified as causative agents. A thorough discussion of the schemes and duration of the…","kw":"Antifungal Agents Candidiasis Combined Modality Therapy DNA, Fungal Dermatomycoses Enzyme-Linked Immunosorbent Assay"},{"pmid":"22989160","title":"Effects of low-level laser therapy (LLLT) and diclofenac (topical and intramuscular) as single and combined therapy in experimental model of controlled muscle strain in rats.","journal_abbr":"Photochem Photobiol","authors":["de Paiva Carvalho RL","Leal-Junior EC","Petrellis MC","et al."],"date":"2012-09-20","year":2012,"doi":"10.1111/j.1751-1097.2012.01236.x","cited_by":15,"curated":false,"type":"preclinical","level":5,"ctx":["blessures"],"nm":[810],"pre":"vivo","l1":"However, LLLT showed better effects than TD and ID regarding PGE2 levels and walking track analysis (P < 0.05). We can conclude that LLLT has more efficacy than topical and intramuscular diclofenac in treatment of muscle strain injury in…","kw":"Animals Anti-Inflammatory Agents, Non-Steroidal Biomarkers Combined Modality Therapy Cyclooxygenase 1 Cyclooxygenase 2"},{"pmid":"23664040","title_fr":"LED après un effort intense chez l'athlète","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"traitement","mode":["LED"],"nm":[],"n":18,"effect":"neutre","theme":"Performance musculaire","l1":"Chez 18 athlètes, la LED après un effort intense ne modifie ni les lactates, ni la puissance, ni la fatigue.","l2":"Essai croisé en simple aveugle.","l3":{"points":["—"],"limites":["Paramètres uniques."],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"The effects of light emitting diode therapy following high intensity exercise.","journal":"Physical therapy in sport : official journal of the Association of Chartered Physiotherapists in Sports Medicine","journal_abbr":"Phys Ther Sport","authors":["Denis R","O'Brien C","Delahunt E"],"date":"2012-08-21","year":2012,"week":"2012-S34","doi":"10.1016/j.ptsp.2012.03.014","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":12,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"OBJECTIVE","text":"To determine the effects of light emitting diode therapy (LEDT) irradiation on blood lactate concentration ([La]) clearance, peak power output and fatigue index (FI) following high intensity fatiguing exercise."},{"label":"DESIGN","text":"Single-blinded randomised cross-over placebo controlled trial."},{"label":"SETTING","text":"University College Dublin, Institute for Sport and Health, Human performance laboratory."},{"label":"PARTICIPANTS","text":"Eighteen healthy male athletes were recruited from field-based sports (including soccer, hockey and rugby union) and participated in the present study."},{"label":"MAIN OUTCOME MEASURES","text":"Dependent variables were the peak power output elicited during the Wingate Anaerobic Test (WAnT), FI and [La] before and after each exercise. WAnT performance was measured prior to high intensity fatiguing exercise (Yo-Yo IR2), prior to LEDT or placebo, and following LEDT or placebo. [La] was measured at baseline, immediately after the Yo-Yo IR2, and in the 3rd, 9th, and 15th min following LEDT or placebo condition."},{"label":"RESULTS","text":"No significant group by treatment interactions were observed for any outcome measures (P > 0.05)."},{"label":"CONCLUSION","text":"We conclude that LEDT irradiation applied following high intensity exercise was not effective and has no immediate effect on [La] clearance, peak power and FI, and thus has no significant effect on muscle recovery in athletes at the intensity and irradiation parameters used in the present study. Further research using different parameters is required to determine how LEDT may contribute to post-exercise recovery."}],"keywords":[]},{"pmid":"22666495","title":"Low-level laser irradiation stimulates tenocyte migration with up-regulation of dynamin II expression.","journal_abbr":"PLoS One","authors":["Tsai WC","Hsu CC","Pang JH","et al."],"date":"2012-05-30","year":2012,"doi":"10.1371/journal.pone.0038235","pmcid":"PMC3364209","license":"cc by","oa":true,"cited_by":33,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"preclinical","level":5,"ctx":[],"nm":[660],"pre":"both","l1":"The stimulation effect of laser on tenocytes migration was suppressed by dynasore. In conclusion, low-level laser irradiation stimulates tenocyte migration in a process that is mediated by up-regulation of dynamin 2, which can be…","kw":"Animals Cell Movement Dose-Response Relationship, Radiation Dynamin II Gene Expression Regulation Lasers"},{"pmid":"22399243","title":"Effects of low-level laser therapy (GaAs) in an animal model of muscular damage induced by trauma.","journal_abbr":"Lasers Med Sci","authors":["Silveira PC","da Silva LA","Pinho CA","et al."],"date":"2012-03-08","year":2012,"doi":"10.1007/s10103-012-1075-6","cited_by":48,"curated":false,"type":"preclinical","level":5,"ctx":["récupération","blessures","populations"],"nm":[904],"pre":"vivo","l1":"LLLT accelerated the muscular healing by significantly decreasing superoxide anion production, TBARS levels, the activity of SOD, and hydroxyproline content. The data strongly indicate that increased ROS production and augmented collagen…","kw":"Animals Antioxidants Cell Respiration Collagen Creatine Kinase Disease Models, Animal"},{"pmid":"22223060","title":"Effects of light emitting diode (LED) therapy and cold water immersion therapy on exercise-induced muscle damage in rats.","journal_abbr":"Lasers Med Sci","authors":["Camargo MZ","Siqueira CP","Preti MC","et al."],"date":"2012-01-06","year":2012,"doi":"10.1007/s10103-011-1039-2","cited_by":29,"pub_types":["Comparative Study","Evaluation Study"],"curated":false,"type":"preclinical","level":5,"ctx":["récupération"],"nm":[940],"pre":"vivo","l1":"Hematological analysis showed no significant effect of either treatment on leukocyte counts. The results suggest that LED therapy is more efficient than CWI in preventing muscle damage and local inflammation after exercise.","kw":"Animals Creatine Kinase Cryotherapy Immersion Leukocytes Male"},{"pmid":"22053933","title":"Infrared (810 nm) low-level laser therapy in experimental model of strain-induced skeletal muscle injury in rats: effects on functional outcomes.","journal_abbr":"Photochem Photobiol","authors":["Ramos L","Leal Junior EC","Pallotta RC","et al."],"date":"2011-11-08","year":2011,"doi":"10.1111/j.1751-1097.2011.01030.x","cited_by":20,"curated":false,"type":"preclinical","level":5,"ctx":["blessures"],"nm":[810],"pre":"vivo","l1":"All treatments significantly improved muscle performance at 6 and 12 h. LLLT dose of 3 J was as effective as the pharmacological agent in improving functional outcomes in the early phase after a muscle strain injury in rats.","kw":"Animals Infrared Rays Laser Therapy Muscle, Skeletal Rats Wounds and Injuries"},{"pmid":"21870127","title_fr":"Laser 808 nm et performance isocinétique pendant l'entraînement d'endurance","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"—","mode":["laser"],"nm":[808],"n":null,"effect":"favorable","theme":"Performance musculaire","l1":"Associé à un entraînement d'endurance, le laser 808 nm réduit davantage la fatigue chez de jeunes femmes.","l2":"—","l3":{"points":["—"],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Effects of low-level laser therapy (808 nm) on isokinetic muscle performance of young women submitted to endurance training: a randomized controlled clinical trial.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Vieira WH","Ferraresi C","Perez SE","et al."],"date":"2011-08-26","year":2011,"week":"2011-S34","doi":"10.1007/s10103-011-0984-0","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":64,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Low-level laser therapy (LLLT) has shown efficacy in muscle bioenergetic activation and its effects could influence the mechanical performance of this tissue during physical exercise. This study tested whether endurance training associated with LLLT could increase human muscle performance in isokinetic dynamometry when compared to the same training without LLLT. The primary objective was to determine the fatigue index of the knee extensor muscles (FIext) and the secondary objective was to determine the total work of the knee extensor muscles (TWext). Included in the study were 45 clinically healthy women (21 ± 1.78 years old) who were randomly distributed into three groups: CG (control group), TG (training group) and TLG (training with LLLT group). The training for the TG and TLG groups involved cycle ergometer exercise with load applied to the ventilatory threshold (VT) for 9 consecutive weeks. Immediately after each training session, LLLT was applied to the femoral quadriceps muscle of both lower limbs of the TLG subjects using an infrared laser device (808 nm) with six 60-mW diodes with an energy of 0.6 J per diode and a total energy applied to each limb of 18 J. VT was determined by ergospirometry during an incremental exercise test and muscle performance was evaluated using an isokinetic dynamometer at 240°/s. Only the TLG showed a decrease in FIext in the nondominant lower limb (P = 0.016) and the dominant lower limb (P = 0.006). Both the TLG and the TG showed an increase in TWext in the nondominant lower limb (P < 0.001 and P = 0.011, respectively) and in the dominant lower limb (P < 0.000 and P < 0.000, respectively). The CG showed no reduction in FIext or TWext in either lower limb. The results suggest that an endurance training program combined with LLLT leads to a greater reduction in fatigue than an endurance training program without LLLT. This is relevant to everyone involved in sport and rehabilitation."}],"keywords":[]},{"pmid":"21814736","title_fr":"Laser rouge 660 nm ou infrarouge 830 nm contre la fatigue musculaire : lequel choisir ?","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser"],"nm":[660,830],"n":null,"effect":"favorable","theme":"Performance musculaire","l1":"Le rouge et l'infrarouge retardent tous deux la fatigue musculaire et améliorent la performance ; les mécanismes de chaque longueur d'onde restent à préciser.","l2":"Double aveugle contre placebo.","l3":{"points":["Comparaison directe."],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Red (660 nm) and infrared (830 nm) low-level laser therapy in skeletal muscle fatigue in humans: what is better?","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["de Almeida P","Lopes-Martins RA","De Marchi T","et al."],"date":"2011-07-22","year":2011,"week":"2011-S29","doi":"10.1007/s10103-011-0957-3","pmcid":"PMC3282894","license":"cc by-nc","oa":true,"pdf":"pdfs/21814736.pdf","cited_by":83,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"","text":"In animal and clinical trials low-level laser therapy (LLLT) using red, infrared and mixed wavelengths has been shown to delay the development of skeletal muscle fatigue. However, the parameters employed in these studies do not allow a conclusion as to which wavelength range is better in delaying the development of skeletal muscle fatigue. With this perspective in mind, we compared the effects of red and infrared LLLT on skeletal muscle fatigue. A randomized double-blind placebo-controlled crossover trial was performed in ten healthy male volunteers. They were treated with active red LLLT, active infrared LLLT (660 or 830 nm, 50 mW, 17.85 W/cm(2), 100 s irradiation per point, 5 J, 1,785 J/cm(2) at each point irradiated, total 20 J irradiated per muscle) or an identical placebo LLLT at four points of the biceps brachii muscle for 3 min before exercise (voluntary isometric elbow flexion for 60 s). The mean peak force was significantly greater (p < 0.05) following red (12.14%) and infrared LLLT (14.49%) than following placebo LLLT, and the mean average force was also significantly greater (p < 0.05) following red (13.09%) and infrared LLLT (13.24%) than following placebo LLLT. There were no significant differences in mean average force or mean peak force between red and infrared LLLT. We conclude that both red than infrared LLLT are effective in delaying the development skeletal muscle fatigue and in enhancement of skeletal muscle performance. Further studies are needed to identify the specific mechanisms through which each wavelength acts."}],"keywords":[]},{"pmid":"21749398","title":"Low-level laser therapy improves skeletal muscle performance, decreases skeletal muscle damage and modulates mRNA expression of COX-1 and COX-2 in a dose-dependent manner.","journal_abbr":"Photochem Photobiol","authors":["de Almeida P","Lopes-Martins RÁ","Tomazoni SS","et al."],"date":"2011-07-14","year":2011,"doi":"10.1111/j.1751-1097.2011.00968.x","cited_by":61,"curated":false,"type":"preclinical","level":5,"ctx":["performance","récupération"],"nm":[904],"pre":"vivo","l1":"Additionally, 1.0 J group showed increased COX-1 and decreased COX-2 mRNA expression compared with control group and 0.1, 0.3 and 3.0 J laser groups (P < 0.01). We conclude that pre-exercise infrared laser irradiation with dose of 1.0 J…","kw":"Animals Creatine Kinase Cyclooxygenase 1 Cyclooxygenase 2 Dose-Response Relationship, Radiation Electric Stimulation"},{"pmid":"21739259","title_fr":"Laser et course d'intensité croissante : performance, muscle et stress oxydatif","type":"rct","level":2,"pop":"adulte","ctx":["blessures"],"aim":"prévention","mode":["laser"],"nm":[810],"n":null,"effect":"favorable","theme":"Blessures sportives","l1":"Le laser avant une course d'intensité croissante améliore la performance et réduit le stress oxydatif et les lésions musculaires.","l2":"Essai croisé en double aveugle contre placebo.","l3":{"points":["Mécanisme redox proposé."],"limites":["—"],"pratique":"—"},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Low-level laser therapy (LLLT) in human progressive-intensity running: effects on exercise performance, skeletal muscle status, and oxidative stress.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["De Marchi T","Leal Junior EC","Bortoli C","et al."],"date":"2011-07-08","year":2011,"week":"2011-S27","doi":"10.1007/s10103-011-0955-5","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":167,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"","text":"The aim of this work was to evaluate the effects of low-level laser therapy (LLLT) on exercise performance, oxidative stress, and muscle status in humans. A randomized double-blind placebo-controlled crossover trial was performed with 22 untrained male volunteers. LLLT (810 nm, 200 mW, 30 J in each site, 30 s of irradiation in each site) using a multi-diode cluster (with five spots - 6 J from each spot) at 12 sites of each lower limb (six in quadriceps, four in hamstrings, and two in gastrocnemius) was performed 5 min before a standardized progressive-intensity running protocol on a motor-drive treadmill until exhaustion. We analyzed exercise performance (VO(2 max), time to exhaustion, aerobic threshold and anaerobic threshold), levels of oxidative damage to lipids and proteins, the activities of the antioxidant enzymes superoxide dismutase (SOD) and catalase (CAT), and the markers of muscle damage creatine kinase (CK) and lactate dehydrogenase (LDH). Compared to placebo, active LLLT significantly increased exercise performance (VO(2 max) p = 0.01; time to exhaustion, p = 0.04) without changing the aerobic and anaerobic thresholds. LLLT also decreased post-exercise lipid (p = 0.0001) and protein (p = 0.0230) damages, as well as the activities of SOD (p = 0.0034), CK (p = 0.0001) and LDH (p = 0.0001) enzymes. LLLT application was not able to modulate CAT activity. The use of LLLT before progressive-intensity running exercise increases exercise performance, decreases exercise-induced oxidative stress and muscle damage, suggesting that the modulation of the redox system by LLLT could be related to the delay in skeletal muscle fatigue observed after the use of LLLT."}],"keywords":[]},{"pmid":"21465779","title":"[New methods of physical therapy and instruments for their application (based on projects developed in Belarus)].","journal_abbr":"Vopr Kurortol Fizioter Lech Fiz Kult","authors":["Ulashchik VS"],"date":"2011-04-07","year":2011,"pub_types":["English Abstract","Review"],"curated":false,"type":"review","level":5,"ctx":[],"l1":"This article was designed to overview new methods (thermomagnetotherapy, photomagnetotherapy, vacuum darsonvalization, low-frequency fonotherapy, etc.) developed in Belarus under the guidance of the author. The information about the…","kw":"Atmospheric Pressure Electric Stimulation Therapy Humans Low-Level Light Therapy Magnetic Field Therapy Physical Therapy Modalities"},{"pmid":"21182447","title":"Improved cognitive function after transcranial, light-emitting diode treatments in chronic, traumatic brain injury: two case reports.","journal_abbr":"Photomed Laser Surg","authors":["Naeser MA","Saltmarche A","Krengel MH","et al."],"date":"2010-12-23","year":2010,"doi":"10.1089/pho.2010.2814","pmcid":"PMC3104287","cited_by":159,"pub_types":["Case Reports","Research Support, N.I.H., Extramural","Research Support, Non-U.S. Gov't","Research Support, U.S. Gov't, Non-P.H.S."],"curated":false,"type":"cases","level":4,"ctx":["blessures"],"nm":[633,870],"l1":"Transcranial LED may improve cognition, reduce costs in TBI treatment, and be applied at home. Controlled studies are warranted.","kw":"Brain Injuries Brain Injury, Chronic Cognition Disorders Female Humans Low-Level Light Therapy"},{"pmid":"21088862","title_fr":"Immersion en eau froide contre LED pour la récupération musculaire","type":"rct","level":2,"pop":"adulte","ctx":["récupération"],"aim":"prévention","mode":["LED"],"nm":[660,850],"n":null,"effect":"favorable","theme":"Récupération & courbatures","l1":"La LED limite mieux la hausse des lactates et des CK après un effort intense que 5 minutes d'immersion en eau froide.","l2":"Résultats préliminaires chez des athlètes.","l3":{"points":["Comparaison à une méthode courante."],"limites":["Préliminaire."],"pratique":"—"},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Comparison between cold water immersion therapy (CWIT) and light emitting diode therapy (LEDT) in short-term skeletal muscle recovery after high-intensity exercise in athletes--preliminary results.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Leal Junior EC","de Godoi V","Mancalossi JL","et al."],"date":"2010-11-19","year":2010,"week":"2010-S46","doi":"10.1007/s10103-010-0866-x","pmcid":"PMC3119799","license":"cc by-nc","oa":true,"pdf":"pdfs/21088862.pdf","cited_by":69,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"In the last years, phototherapy has becoming a promising tool to improve skeletal muscle recovery after exercise, however, it was not compared with other modalities commonly used with this aim. In the present study we compared the short-term effects of cold water immersion therapy (CWIT) and light emitting diode therapy (LEDT) with placebo LEDT on biochemical markers related to skeletal muscle recovery after high-intensity exercise. A randomized double-blind placebo-controlled crossover trial was performed with six male young futsal athletes. They were treated with CWIT (5°C of temperature [SD ±1°]), active LEDT (69 LEDs with wavelengths 660/850 nm, 10/30 mW of output power, 30 s of irradiation time per point, and 41.7 J of total energy irradiated per point, total of ten points irradiated) or an identical placebo LEDT 5 min after each of three Wingate cycle tests. Pre-exercise, post-exercise, and post-treatment measurements were taken of blood lactate levels, creatine kinase (CK) activity, and C-reactive protein (CRP) levels. There were no significant differences in the work performed during the three Wingate tests (p > 0.05). All biochemical parameters increased from baseline values (p < 0.05) after the three exercise tests, but only active LEDT decreased blood lactate levels (p = 0.0065) and CK activity (p = 0.0044) significantly after treatment. There were no significant differences in CRP values after treatments. We concluded that treating the leg muscles with LEDT 5 min after the Wingate cycle test seemed to inhibit the expected post-exercise increase in blood lactate levels and CK activity. This suggests that LEDT has better potential than 5 min of CWIT for improving short-term post-exercise recovery."}],"keywords":[]},{"pmid":"21086010","title_fr":"Laser 808 nm et entraînement en force","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"—","mode":["laser"],"nm":[808],"n":null,"effect":"favorable","theme":"Performance musculaire","l1":"Associé à l'entraînement en force, le laser 808 nm augmente davantage la performance musculaire que l'entraînement seul.","l2":"—","l3":{"points":["Effet sur l'entraînement."],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Effects of low level laser therapy (808 nm) on physical strength training in humans.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Ferraresi C","de Brito Oliveira T","de Oliveira Zafalon L","et al."],"date":"2010-11-18","year":2010,"week":"2010-S46","doi":"10.1007/s10103-010-0855-0","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":97,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Recent studies have investigated whether low level laser therapy (LLLT) can optimize human muscle performance in physical exercise. This study tested the effect of LLLT on muscle performance in physical strength training in humans compared with strength training only. The study involved 36 men (20.8±2.2 years old), clinically healthy, with a beginner and/or moderate physical activity training pattern. The subjects were randomly distributed into three groups: TLG (training with LLLT), TG (training only) and CG (control). The training for TG and TLG subjects involved the leg-press exercise with a load equal to 80% of one repetition maximum (1RM) in the leg-press test over 12 consecutive weeks. The LLLT was applied to the quadriceps muscle of both lower limbs of the TLG subjects immediately after the end of each training session. Using an infrared laser device (808 nm) with six diodes of 60 mW each a total energy of 50.4 J of LLLT was administered over 140 s. Muscle strength was assessed using the 1RM leg-press test and the isokinetic dynamometer test. The muscle volume of the thigh of the dominant limb was assessed by thigh perimetry. The TLG subjects showed an increase of 55% in the 1RM leg-press test, which was significantly higher than the increases in the TG subjects (26%, P = 0.033) and in the CG subjects (0.27%, P < 0.001). The TLG was the only group to show an increase in muscle performance in the isokinetic dynamometry test compared with baseline. The increases in thigh perimeter in the TLG subjects and TG subjects were not significantly different (4.52% and 2.75%, respectively; P = 0.775). Strength training associated with LLLT can increase muscle performance compared with strength training only."}],"keywords":[]},{"pmid":"20976806","title":"Low-level laser therapy for protection against skeletal muscle damage after ischemia-reperfusion injury in rat hindlimbs.","journal_abbr":"Lasers Surg Med","authors":["Lakyová L","Toporcer T","Tomečková V","et al."],"date":"2010-10-27","year":2010,"doi":"10.1002/lsm.20967","cited_by":21,"curated":false,"type":"preclinical","level":5,"ctx":["récupération","blessures","populations"],"nm":[670],"pre":"vivo","l1":"LLLT confers a protective effect against early inflammatory tissue response, further atrophy, and necrosis of the muscle and it stimulates neovascularization after I/R injury.","kw":"Animals Disease Models, Animal Hindlimb Lasers, Semiconductor Low-Level Light Therapy Male"},{"pmid":"20961231","title":"Effect of low-power gallium-aluminum-arsenium noncoherent light (640 nm) on muscle activity: a clinical study.","journal_abbr":"Photomed Laser Surg","authors":["Kelencz CA","Muñoz IS","Amorim CF","et al."],"date":"2010-10-22","year":2010,"doi":"10.1089/pho.2008.2467","cited_by":34,"pub_types":["Comparative Study","Evaluation Study","Research Support, Non-U.S. Gov't"],"curated":false,"type":"nrct","level":3,"ctx":["récupération"],"nm":[640],"em":["cw"],"l1":"It was concluded that LED can be used as a clinical tool to increase muscle activity (1.044 J per point) and to prevent fatigue (2.088 J per point), without change in the muscle force.","kw":"Adult Electromyography Female Humans Lasers, Semiconductor Low-Level Light Therapy"},{"pmid":"20701543","title":"Influence of laser photobiomodulation on collagen IV during skeletal muscle tissue remodeling after injury in rats.","journal_abbr":"Photomed Laser Surg","authors":["Baptista J","Martins MD","Pavesi VC","et al."],"date":"2010-08-11","year":2010,"doi":"10.1089/pho.2009.2737","cited_by":37,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"preclinical","level":5,"ctx":["blessures"],"nm":[660],"pre":"vivo","l1":"The collagen IV content is modulated in regenerating skeletal muscle under LLLT, which might be associated with better tissue outcome, although the histologic analysis did not detect tissue improvement in the LLLT group.","kw":"Animals Collagen Type IV Immunohistochemistry Low-Level Light Therapy Male Muscle, Skeletal"},{"pmid":"20662021","title":"Effect of pulsing in low-level light therapy.","journal_abbr":"Lasers Surg Med","authors":["Hashmi JT","Huang YY","Sharma SK","et al."],"date":"2010-07-28","year":2010,"doi":"10.1002/lsm.20950","pmcid":"PMC2933784","cited_by":207,"pub_types":["Research Support, N.I.H., Extramural","Research Support, Non-U.S. Gov't","Research Support, U.S. Gov't, Non-P.H.S.","Review"],"curated":false,"type":"review","level":5,"ctx":[],"em":["pulse","cw"],"l1":"There is some evidence that pulsed light does have effects that are different from those of continuous wave light. However further work is needed to define these effects for different disease conditions and pulse structures.","kw":"Adenosine Triphosphate Animals Brain Ischemia Cerebral Cortex Humans Lasers"},{"pmid":"20626264","title_fr":"LED et fatigue des extenseurs du genou","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["LED"],"nm":[660,850],"n":17,"effect":"favorable","theme":"Performance musculaire","l1":"Chez 17 volontaires, la LED limite la baisse de couple maximal du quadriceps après un effort isocinétique intense.","l2":"Essai croisé en double aveugle.","l3":{"points":["—"],"limites":["Petit effectif."],"pratique":"—"},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Effect of light-emitting diodes therapy (LEDT) on knee extensor muscle fatigue.","journal":"Photomedicine and laser surgery","journal_abbr":"Photomed Laser Surg","authors":["Baroni BM","Leal Junior EC","Geremia JM","et al."],"date":"2010-07-13","year":2010,"week":"2010-S28","doi":"10.1089/pho.2009.2688","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":74,"pub_types":["Comparative Study","Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"OBJECTIVE","text":"The purpose of this study was to evaluate the effects of light-emitting diodes therapy (LEDT) on quadriceps muscle fatigue by using torque values from the isokinetic dynamometer as an outcome measure."},{"label":"BACKGROUND DATA","text":"Light therapy is considered an innovative way to prevent muscle fatigue. Although positive results have been obtained in animal models and in clinical experiments, no results are available on the effects of this therapeutic modality on human performance studies with isokinetic dynamometry."},{"label":"MATERIALS AND METHODS","text":"Seventeen healthy and physically active male volunteers were included in a crossover randomized double-blinded placebo-controlled trial. They performed two sessions of an isokinetic fatigue test (30 maximal concentric knee flexion-extension contractions; range of motion, 90 degrees; angular velocity, 180 degrees per second) after LEDT or placebo treatment. Maximal knee extensor muscle isokinetic voluntary contractions were performed before (PRE-MVC) and after (POST-MVC) the fatigue test. LEDT treatment was performed with a multidiode cluster probe (34 red diodes of 660 nm, 10 mW; 35 infrared diodes of 850 nm, 30 mW) at three points of the quadriceps muscle, with a total irradiating dose of 125.1 J."},{"label":"RESULTS","text":"No differences were observed in the PRE-MVC between LEDT (284.81 ± 4.52 Nm) and placebo (282.65 ± 52.64 Nm) treatments. However, for the POST-MVC, higher torques (p = 0.034) were observed for LEDT (237.68 ± 48.82 Nm) compared with placebo (225.68 ± 44.14 Nm) treatment."},{"label":"CONCLUSION","text":"LEDT treatment produced a smaller maximal isometric torque decrease after high-intensity concentric isokinetic exercise, which is consistent with an increase in performance."}],"keywords":[]},{"pmid":"20614767","title":"Incorporating modalities into the rehab mix. Exploring pain solutions for athletes and weekend warriors.","journal_abbr":"Rehab Manag","authors":["O'Rourke J"],"date":"2010-07-10","year":2010,"curated":false,"type":"autre","level":0,"ctx":["blessures"],"l1":"","kw":"Athletic Injuries Athletic Tape Electric Stimulation Therapy Humans Iontophoresis Low-Level Light Therapy"},{"pmid":"20602109","title_fr":"Laser avant l'exercice excentrique et marqueurs de lésion musculaire","type":"rct","level":2,"pop":"adulte","ctx":["blessures"],"aim":"prévention","mode":["laser"],"nm":[],"n":36,"effect":"favorable","theme":"Blessures sportives","l1":"Chez 36 hommes, le laser avant un exercice excentrique limite la hausse des protéines musculaires sanguines et la perte de force.","l2":"Contre placebo.","l3":{"points":["Prévention des lésions."],"limites":["—"],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Low level laser therapy before eccentric exercise reduces muscle damage markers in humans.","journal":"European journal of applied physiology","journal_abbr":"Eur J Appl Physiol","authors":["Baroni BM","Leal Junior EC","De Marchi T","et al."],"date":"2010-07-03","year":2010,"week":"2010-S26","doi":"10.1007/s00421-010-1562-z","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":122,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"","text":"The purpose of the present study was to determine the effect of low level laser therapy (LLLT) treatment before knee extensor eccentric exercise on indirect markers of muscle damage. Thirty-six healthy men were randomized in LLLT group (n = 18) and placebo group (n = 18). After LLLT or placebo treatment, subjects performed 75 maximal knee extensors eccentric contractions (five sets of 15 repetitions; velocity = 60° seg(-1); range of motion = 60°). Muscle soreness (visual analogue scale--VAS), lactate dehydrogenase (LDH) and creatine kinase (CK) levels were measured prior to exercise, and 24 and 48 h after exercise. Muscle function (maximal voluntary contraction--MVC) was measured before exercise, immediately after, and 24 and 48 h post-exercise. Groups had no difference on kineanthropometric characteristics and on eccentric exercise performance. They also presented similar baseline values of VAS (0.00 mm for LLLT and placebo groups), LDH (LLLT = 186 IU/l; placebo = 183 IU/l), CK (LLLT = 145 IU/l; placebo = 155 IU/l) and MVC (LLLT = 293 Nm; placebo = 284 Nm). VAS data did not show group by time interaction (P = 0.066). In the other outcomes, LLLT group presented (1) smaller increase on LDH values 48 h post-exercise (LLLT = 366 IU/l; placebo = 484 IU/l; P = 0.017); (2) smaller increase on CK values 24 h (LLLT = 272 IU/l; placebo = 498 IU/l; P = 0.020) and 48 h (LLLT = 436 IU/l; placebo = 1328 IU/l; P < 0.001) post-exercise; (3) smaller decrease on MVC immediately after exercise (LLLT = 189 Nm; placebo = 154 Nm; P = 0.011), and 24 h (LLLT = 249 Nm; placebo = 205 Nm; P = 0.004) and 48 h (LLLT = 267 Nm; placebo = 216 Nm; P = 0.001) post-exercise compared with the placebo group. In conclusion, LLLT treatment before eccentric exercise was effective in terms of attenuating the increase of muscle proteins in the blood serum and the decrease in muscle force."}],"keywords":[]},{"pmid":"20436237","title_fr":"Laser 810 nm avant l'effort : fatigue et marqueurs de récupération","type":"rct","level":2,"pop":"adulte","ctx":["récupération"],"aim":"prévention","mode":["laser"],"nm":[810],"n":9,"effect":"favorable","theme":"Récupération & courbatures","l1":"Chez 9 volleyeurs, 6 J de laser sur le biceps avant l'effort augmentent l'endurance et réduisent lactates, CK et CRP.","l2":"Essai croisé en double aveugle (JOSPT 2010).","l3":{"points":["Dose précise."],"limites":["9 sujets."],"pratique":"6 J par point, 2 points sur le biceps."},"em":[],"pre":"","topic":"sport","title":"Effects of low-level laser therapy (LLLT) in the development of exercise-induced skeletal muscle fatigue and changes in biochemical markers related to postexercise recovery.","journal":"The Journal of orthopaedic and sports physical therapy","journal_abbr":"J Orthop Sports Phys Ther","authors":["Leal Junior EC","Lopes-Martins RA","Frigo L","et al."],"date":"2010-05-04","year":2010,"week":"2010-S18","doi":"10.2519/jospt.2010.3294","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":136,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"STUDY DESIGN","text":"Randomized crossover double-blinded placebo-controlled trial."},{"label":"OBJECTIVE","text":"To investigate if low-level laser therapy (LLLT) can affect biceps muscle performance, fatigue development, and biochemical markers of postexercise recovery."},{"label":"BACKGROUND","text":"Cell and animal studies have suggested that LLLT can reduce oxidative stress and inflammatory responses in muscle tissue. But it remains uncertain whether these findings can translate into humans in sport and exercise situations."},{"label":"METHODS","text":"Nine healthy male volleyball players participated in the study. They received either active LLLT (cluster probe with 5 laser diodes; lambda = 810 nm; 200 mW power output; 30 seconds of irradiation, applied in 2 locations over the biceps of the nondominant arm; 60 J of total energy) or placebo LLLT using an identical cluster probe. The intervention or placebo were applied 3 minutes before the performance of exercise. All subjects performed voluntary elbow flexion repetitions with a workload of 75% of their maximal voluntary contraction force until exhaustion."},{"label":"RESULTS","text":"Active LLLT increased the number of repetitions by 14.5% (mean +/- SD, 39.6 +/- 4.3 versus 34.6 +/- 5.6; P = .037) and the elapsed time before exhaustion by 8.0% (P = .034), when compared to the placebo treatment. The biochemical markers also indicated that recovery may be positively affected by LLLT, as indicated by postexercise blood lactate levels (P<.01), creatine kinase activity (P = .017), and C-reactive protein levels (P = .047), showing a faster recovery with LLLT application prior to the exercise."},{"label":"CONCLUSION","text":"We conclude that pre-exercise irradiation of the biceps with an LLLT dose of 6 J per application location, applied in 2 locations, increased endurance for repeated elbow flexion against resistance and decreased postexercise levels of blood lactate, creatine kinase, and C-reactiveprotein."},{"label":"LEVEL OF EVIDENCE","text":"Performance enhancement, level 1b."}],"keywords":[]},{"pmid":"20037695","title":"Conservative management of posterior interosseous neuropathy in an elite baseball pitcher's return to play: a case report and review of the literature.","journal_abbr":"J Can Chiropr Assoc","authors":["Robb A","Sajko S"],"date":"2009-12-29","year":2009,"pmcid":"PMC2796949","cited_by":9,"curated":false,"type":"autre","level":0,"ctx":["blessures"],"l1":"Successful resolution of symptomatology and return to pre-injury status was achieved in 5 weeks. A review of literature and an evidence-based discussion for the differential diagnoses, clinical examination, diagnosis, management and…","kw":"arm injury baseball posterior interosseous nerve radial nerve radial neuropathy"},{"pmid":"20024577","title":"Effect of low-level laser therapy (GaAs 904 nm) in skeletal muscle fatigue and biochemical markers of muscle damage in rats.","journal_abbr":"Eur J Appl Physiol","authors":["Leal Junior EC","Lopes-Martins RA","de Almeida P","et al."],"date":"2009-12-19","year":2009,"doi":"10.1007/s00421-009-1321-1","cited_by":71,"curated":false,"type":"preclinical","level":5,"ctx":["récupération"],"nm":[904],"pre":"vivo","l1":"All irradiated groups except the 3.0 J group had significantly lower post-exercise CK activity than the control group. We conclude that pre-exercise irradiation with a laser dose of 1.0 J and 904 nm wavelength significantly delays muscle…","kw":"Animals Dose-Response Relationship, Radiation Lactic Acid Low-Level Light Therapy Male Muscle Fatigue"},{"pmid":"19731300","title_fr":"LED multi-diodes 660/850 nm, fatigue et récupération musculaires","type":"rct","level":2,"pop":"adulte","ctx":["récupération"],"aim":"prévention","mode":["LED"],"nm":[660,850],"n":10,"effect":"favorable","theme":"Récupération & courbatures","l1":"Chez 10 volleyeurs, la LED appliquée avant l'effort retarde un peu la fatigue et réduit lactates, CK et CRP après l'exercice.","l2":"Essai croisé en double aveugle.","l3":{"points":["Marqueurs biologiques concordants."],"limites":["10 sujets."],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Effect of cluster multi-diode light emitting diode therapy (LEDT) on exercise-induced skeletal muscle fatigue and skeletal muscle recovery in humans.","journal":"Lasers in surgery and medicine","journal_abbr":"Lasers Surg Med","authors":["Leal Junior EC","Lopes-Martins RA","Rossi RP","et al."],"date":"2009-09-05","year":2009,"week":"2009-S36","doi":"10.1002/lsm.20810","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":111,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"BACKGROUND AND OBJECTIVES","text":"There are some indications that low-level laser therapy (LLLT) may delay the development of skeletal muscle fatigue during high-intensity exercise. There have also been claims that LED cluster probes may be effective for this application however there are differences between LED and laser sources like spot size, spectral width, power output, etc. In this study we wanted to test if light emitting diode therapy (LEDT) can alter muscle performance, fatigue development and biochemical markers for skeletal muscle recovery in an experimental model of biceps humeri muscle contractions."},{"label":"STUDY DESIGN/MATERIALS AND METHODS","text":"Ten male professional volleyball players (23.6 [SD +/-5.6] years old) entered a randomized double-blinded placebo-controlled crossover trial. Active cluster LEDT (69 LEDs with wavelengths 660/850 nm, 10/30 mW, 30 seconds total irradiation time, 41.7 J of total energy irradiated) or an identical placebo LEDT was delivered under double-blinded conditions to the middle of biceps humeri muscle immediately before exercise. All subjects performed voluntary biceps humeri contractions with a workload of 75% of their maximal voluntary contraction force (MVC) until exhaustion."},{"label":"RESULTS","text":"Active LEDT increased the number of biceps humeri contractions by 12.9% (38.60 [SD +/-9.03] vs. 34.20 [SD +/-8.68], P = 0.021) and extended the elapsed time to perform contractions by 11.6% (P = 0.036) versus placebo. In addition, post-exercise levels of biochemical markers decreased significantly with active LEDT: Blood Lactate (P = 0.042), Creatine Kinase (P = 0.035), and C-Reative Protein levels (P = 0.030), when compared to placebo LEDT."},{"label":"CONCLUSION","text":"We conclude that this particular procedure and dose of LEDT immediately before exhaustive biceps humeri contractions, causes a slight delay in the development of skeletal muscle fatigue, decreases post-exercise blood lactate levels and inhibits the release of Creatine Kinase and C-Reative Protein. Lasers Surg. Med. 41:572-577, 2009. (c) 2009 Wiley-Liss, Inc."}],"keywords":[]},{"pmid":"19697999","title":"Effects of low-level laser irradiation on rat skeletal muscle injury after eccentric exercise.","journal_abbr":"Photomed Laser Surg","authors":["Liu XG","Zhou YJ","Liu TC","et al."],"date":"2009-08-25","year":2009,"doi":"10.1089/pho.2008.2443","cited_by":56,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"preclinical","level":5,"ctx":["récupération","blessures"],"pre":"vivo","l1":"Low-level He-Ne laser therapy could exert therapeutic effects on eccentric exercise-induced rat muscle injury through enhancing muscle anti-oxidative capacity and reducing the inflammatory reaction. The photobiomodulation was…","kw":"Analysis of Variance Animals Creatine Kinase Dose-Response Relationship, Radiation Female Inflammation"},{"pmid":"19302015","title_fr":"Laser à diode unique contre LED multi-diodes avant un effort intense","type":"rct","level":2,"pop":"adulte","ctx":["récupération"],"aim":"prévention","mode":["laser","LED"],"nm":[660,850],"n":8,"effect":"mitigé","theme":"Récupération & courbatures","l1":"Chez 8 volleyeurs, seule la LED multi-diodes réduit les CK après le test de Wingate ; ni la performance ni les lactates ne changent.","l2":"Essai croisé en double aveugle.","l3":{"points":["Comparaison laser–LED."],"limites":["8 sujets."],"pratique":"—"},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"Comparison between single-diode low-level laser therapy (LLLT) and LED multi-diode (cluster) therapy (LEDT) applications before high-intensity exercise.","journal":"Photomedicine and laser surgery","journal_abbr":"Photomed Laser Surg","authors":["Leal Junior EC","Lopes-Martins RA","Baroni BM","et al."],"date":"2009-03-24","year":2009,"week":"2009-S13","doi":"10.1089/pho.2008.2350","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":88,"pub_types":["Comparative Study","Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"BACKGROUND DATA AND OBJECTIVE","text":"There is anecdotal evidence that low-level laser therapy (LLLT) may affect the development of muscular fatigue, minor muscle damage, and recovery after heavy exercises. Although manufacturers claim that cluster probes (LEDT) maybe more effective than single-diode lasers in clinical settings, there is a lack of head-to-head comparisons in controlled trials. This study was designed to compare the effect of single-diode LLLT and cluster LEDT before heavy exercise."},{"label":"MATERIALS AND METHODS","text":"This was a randomized, placebo-controlled, double-blind cross-over study. Young male volleyball players (n = 8) were enrolled and asked to perform three Wingate cycle tests after 4 x 30 sec LLLT or LEDT pretreatment of the rectus femoris muscle with either (1) an active LEDT cluster-probe (660/850 nm, 10/30 mW), (2) a placebo cluster-probe with no output, and (3) a single-diode 810-nm 200-mW laser."},{"label":"RESULTS","text":"The active LEDT group had significantly decreased post-exercise creatine kinase (CK) levels (-18.88 +/- 41.48 U/L), compared to the placebo cluster group (26.88 +/- 15.18 U/L) (p < 0.05) and the active single-diode laser group (43.38 +/- 32.90 U/L) (p < 0.01). None of the pre-exercise LLLT or LEDT protocols enhanced performance on the Wingate tests or reduced post-exercise blood lactate levels. However, a non-significant tendency toward lower post-exercise blood lactate levels in the treated groups should be explored further."},{"label":"CONCLUSION","text":"In this experimental set-up, only the active LEDT probe decreased post-exercise CK levels after the Wingate cycle test. Neither performance nor blood lactate levels were significantly affected by this protocol of pre-exercise LEDT or LLLT."}],"keywords":[]},{"pmid":"19057981","title_fr":"Laser 830 nm avant l'effort et récupération musculaire chez l'athlète","type":"rct","level":2,"pop":"adulte","ctx":["récupération"],"aim":"prévention","mode":["laser"],"nm":[830],"n":null,"effect":"favorable","theme":"Récupération & courbatures","l1":"Appliqué avant un effort intense, le laser 830 nm limite la hausse des CK et accélère l'élimination des lactates, sans changer la performance.","l2":"Double aveugle contre placebo.","l3":{"points":["Marqueurs de récupération."],"limites":["Critères biologiques."],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Effect of 830 nm low-level laser therapy applied before high-intensity exercises on skeletal muscle recovery in athletes.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Leal Junior EC","Lopes-Martins RA","Baroni BM","et al."],"date":"2008-12-05","year":2008,"week":"2008-S49","doi":"10.1007/s10103-008-0633-4","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":95,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"Our aim was to investigate the immediate effects of bilateral, 830 nm, low-level laser therapy (LLLT) on high-intensity exercise and biochemical markers of skeletal muscle recovery, in a randomised, double-blind, placebo-controlled, crossover trial set in a sports physiotherapy clinic. Twenty male athletes (nine professional volleyball players and eleven adolescent soccer players) participated. Active LLLT (830 nm wavelength, 100 mW, spot size 0.0028 cm(2), 3-4 J per point) or an identical placebo LLLT was delivered to five points in the rectus femoris muscle (bilaterally). The main outcome measures were the work performed in the Wingate test: 30 s of maximum cycling with a load of 7.5% of body weight, and the measurement of blood lactate (BL) and creatine kinase (CK) levels before and after exercise. There was no significant difference in the work performed during the Wingate test (P > 0.05) between subjects given active LLLT and those given placebo LLLT. For volleyball athletes, the change in CK levels from before to after the exercise test was significantly lower (P = 0.0133) for those given active LLLT (2.52 U l(-1) +/- 7.04 U l(-1)) than for those given placebo LLLT (28.49 U l(-1) +/- 22.62 U l(-1)). For the soccer athletes, the change in blood lactate levels from before exercise to 15 min after exercise was significantly lower (P < 0.01) in the group subjected to active LLLT (8.55 mmol l(-1) +/- 2.14 mmol l(-1)) than in the group subjected to placebo LLLT (10.52 mmol l(-1) +/- 1.82 mmol l(-1)). LLLT irradiation before the Wingate test seemed to inhibit an expected post-exercise increase in CK level and to accelerate post-exercise lactate removal without affecting test performance. These findings suggest that LLLT may be of benefit in accelerating post-exercise recovery."}],"keywords":[]},{"pmid":"18991342","title":"Low-level laser irradiation promotes cell proliferation and mRNA expression of type I collagen and decorin in porcine Achilles tendon fibroblasts in vitro.","journal_abbr":"J Orthop Res","authors":["Chen CH","Tsai JL","Wang YH","et al."],"date":"2008-11-11","year":2008,"doi":"10.1002/jor.20800","cited_by":51,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"preclinical","level":5,"ctx":[],"pre":"vitro","l1":"Therefore, suitable dosages of LLLI may result in more effective tissue healing by promoting type I collagen and decorin synthesis. However, these positive effects of LLLI on the repair of the Achilles tendon in humans should be further…","kw":"Achilles Tendon Animals Cell Proliferation Cells, Cultured Collagen Type I Decorin"},{"pmid":"18922091","title_fr":"Laser et fatigue musculaire induite électriquement : étude pilote","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser"],"nm":[808],"n":5,"effect":"neutre","theme":"Performance musculaire","l1":"Chez 5 participants, le laser ne réduit pas la fatigue du quadriceps induite par électrostimulation.","l2":"Effectif et paramètres pouvant expliquer l'absence d'effet.","l3":{"points":["—"],"limites":["5 sujets."],"pratique":"—"},"em":[],"pre":"","nm_auto":true,"topic":"sport","title":"The effect of low-level laser therapy on electrically induced muscle fatigue: a pilot study.","journal":"Photomedicine and laser surgery","journal_abbr":"Photomed Laser Surg","authors":["Gorgey AS","Wadee AN","Sobhi NN"],"date":"2008-10-17","year":2008,"week":"2008-S42","doi":"10.1089/pho.2007.2161","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":31,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"OBJECTIVE","text":"The purpose of this pilot study is to determine if low-level laser therapy (LLLT) could attenuate skeletal muscle fatigue induced by surface neuromuscular electrical stimulation (NMES) in healthy volunteers."},{"label":"MATERIALS AND METHODS","text":"Five college-age participants underwent three cross-over randomized trials: two (LLLT + NMES) test trials and a control trial (NMES only), in which NMES was applied to their dominant knee extensor muscle group. The LLLT doses, 500 mW at 808 nm, were either adjusted to deliver a total energy of 7 J for 10 min or 3 J for 5 min in a blinded fashion. Following LLLT irradiation, the NMES protocol was immediately delivered for 3 min to induce fatigue in the knee extensor muscle group."},{"label":"RESULTS","text":"The five participants completed the three trials. After the control trial, torque significantly decreased (62%; p < 0.0001) at the end of 3 min. There was no significant difference between the 7 J and 3 J trials on muscle fatigue. Following both LLLT trials, torque significantly decreased (51%; p < 0.0001) at the end of 3 min. Although there was a difference (11%) in fatigue between the two LLLT trials and the control trial, this difference did not attain statistical significance (p = 0.63)."},{"label":"CONCLUSION","text":"LLLT did not attenuate muscle fatigue evoked by NMES, but this needs to be further addressed in human studies and clinical settings. The lack of significant findings could be explained by the small sample size and the selection of LLLT parameters."}],"keywords":[]},{"pmid":"18817474","title_fr":"Laser 655 nm et fatigue musculaire à l'effort","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser"],"nm":[655],"n":12,"effect":"favorable","theme":"Performance musculaire","l1":"Chez 12 volleyeurs, le laser 655 nm retarde la fatigue et l'épuisement musculaires par un mécanisme local.","l2":"Double aveugle contre placebo.","l3":{"points":["—"],"limites":["Petit effectif."],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Effect of 655-nm low-level laser therapy on exercise-induced skeletal muscle fatigue in humans.","journal":"Photomedicine and laser surgery","journal_abbr":"Photomed Laser Surg","authors":["Leal Junior EC","Lopes-Martins RA","Dalan F","et al."],"date":"2008-09-27","year":2008,"week":"2008-S39","doi":"10.1089/pho.2007.2160","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":126,"pub_types":["Randomized Controlled Trial","Research Support, Non-U.S. Gov't"],"curated":true,"depth":1,"abstract":[{"label":"OBJECTIVE","text":"To investigate if development of skeletal muscle fatigue during repeated voluntary biceps contractions could be attenuated by low-level laser therapy (LLLT)."},{"label":"BACKGROUND DATA","text":"Previous animal studies have indicated that LLLT can reduce oxidative stress and delay the onset of skeletal muscle fatigue."},{"label":"MATERIALS AND METHODS","text":"Twelve male professional volleyball players were entered into a randomized double-blind placebo-controlled trial, for two sessions (on day 1 and day 8) at a 1-wk interval, with both groups performing as many voluntary biceps contractions as possible, with a load of 75% of the maximal voluntary contraction force (MVC). At the second session on day 8, the groups were either given LLLT (655 nm) of 5 J at an energy density of 500 J/cm2 administered at each of four points along the middle of the biceps muscle belly, or placebo LLLT in the same manner immediately before the exercise session. The number of muscle contractions with 75% of MVC was counted by a blinded observer and blood lactate concentration was measured."},{"label":"RESULTS","text":"Compared to the first session (on day 1), the mean number of repetitions increased significantly by 8.5 repetitions (+/- 1.9) in the active LLLT group at the second session (on day 8), while in the placebo LLLT group the increase was only 2.7 repetitions (+/- 2.9) (p = 0.0001). At the second session, blood lactate levels increased from a pre-exercise mean of 2.4 mmol/L (+/- 0.5 mmol/L), to 3.6 mmol/L (+/- 0.5 mmol/L) in the placebo group, and to 3.8 mmol/L (+/- 0.4 mmol/L) in the active LLLT group after exercise, but this difference between groups was not statistically significant."},{"label":"CONCLUSION","text":"We conclude that LLLT appears to delay the onset of muscle fatigue and exhaustion by a local mechanism in spite of increased blood lactate levels."}],"keywords":[]},{"pmid":"18649044","title_fr":"Laser 830 nm et fatigue musculaire à l'effort","type":"rct","level":2,"pop":"adulte","ctx":["performance"],"aim":"prévention","mode":["laser"],"nm":[830],"n":10,"effect":"favorable","theme":"Performance musculaire","l1":"Chez 10 volleyeurs professionnels, le laser 830 nm retarde la fatigue musculaire lors d'efforts intenses.","l2":"Essai croisé en double aveugle ; lactates inchangés.","l3":{"points":["Double aveugle."],"limites":["10 sujets."],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Effect of 830 nm low-level laser therapy in exercise-induced skeletal muscle fatigue in humans.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Leal Junior EC","Lopes-Martins RA","Vanin AA","et al."],"date":"2008-07-23","year":2008,"week":"2008-S30","doi":"10.1007/s10103-008-0592-9","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":118,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"This study aimed to investigate the effect of 830 nm low-level laser therapy (LLLT) on skeletal muscle fatigue. Ten healthy male professional volleyball players entered a crossover randomized double-blinded placebo-controlled trial. Active LLLT (830 nm wavelength, 100 mW output, spot size 0.0028 cm(2), 200 s total irradiation time) or an identical placebo LLLT was delivered to four points on the biceps humeri muscle immediately before exercises. All subjects performed voluntary biceps humeri contractions with a load of 75% of the maximum voluntary contraction (MVC) force until exhaustion. After active LLLT the mean number of repetitions was significantly higher than after placebo irradiation [mean difference 4.5, standard deviation (SD) +/- 6.0, P = 0.042], the blood lactate levels increased after exercises, but there was no significant difference between the treatments. We concluded that 830 nm LLLT can delay the onset of skeletal muscle fatigue in high-intensity exercises, in spite of increased blood lactate levels."}],"keywords":[]},{"pmid":"18643907","title":"The ability of low level laser therapy to prevent muscle tissue damage induced by snake venom.","journal_abbr":"Photochem Photobiol","authors":["Doin-Silva R","Baranauskas V","Rodrigues-Simioni L","et al."],"date":"2008-07-17","year":2008,"doi":"10.1111/j.1751-1097.2008.00397.x","cited_by":31,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"preclinical","level":5,"ctx":["populations"],"pre":"vivo","l1":"jararacussu snake venom. Thus, low level laser therapy may be a promising tool to minimize the severity of some of the local effects of snake envenoming.","kw":"Animals Bothrops Low-Level Light Therapy Male Muscular Diseases Rats"},{"pmid":"18159917","title":"[Comprehensive treatment in Achilles tendon rupture].","journal_abbr":"Acta Ortop Mex","authors":["Matus-Jiménez J","Avalos CH"],"date":"2007-12-28","year":2007,"pub_types":["Evaluation Study","Review"],"curated":false,"type":"review","level":5,"ctx":["récupération","blessures"],"l1":"At present these times have improved by a good surgical technique and an early rehabilitation, and the patient is returned quickly as he sees less disability. It is proposed in this paper a type of surgical treatment and an early…","kw":"Achilles Tendon Adult Athletic Injuries Combined Modality Therapy Electric Stimulation Therapy Humans"},{"pmid":"17549134","title":"Chiropractic clinical practice guideline: evidence-based treatment of adult neck pain not due to whiplash.","journal_abbr":"J Can Chiropr Assoc","authors":["Canadian Chiropractic Association","Canadian Federation of Chiropractic Regulatory Boards","Clinical Practice Guidelines Development Initiative","et al."],"date":"2007-06-06","year":2007,"pmcid":"PMC1839918","cited_by":41,"curated":false,"type":"autre","level":0,"ctx":[],"l1":"Key contributors to the guideline included individuals with specialties or expert knowledge in chiropractic, medicine, research processes, literature analysis processes, clinical practice guideline processes, protective association…","kw":""},{"pmid":"16627677","title":"Effect of low-level laser (Ga-Al-As 655 nm) on skeletal muscle fatigue induced by electrical stimulation in rats.","journal_abbr":"J Appl Physiol (1985)","authors":["Lopes-Martins RA","Marcos RL","Leonardo PS","et al."],"date":"2006-04-20","year":2006,"doi":"10.1152/japplphysiol.01318.2005","cited_by":114,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"preclinical","level":5,"ctx":["récupération"],"nm":[655],"pre":"vivo","l1":"A distinct dose-response pattern was found in which 1.0 and 2.5 J/cm2 LLLT groups had significantly lower creatine kinase levels than the 0.5 J/cm2 LLLT group and the control group. We conclude that LLLT doses of 0.5 and 1.0 J/cm2 can…","kw":"Animals Creatine Kinase Dose-Response Relationship, Radiation Electric Stimulation Hypoxia Low-Level Light Therapy"},{"pmid":"16538423","title_fr":"LED infrarouge et courbatures induites expérimentalement : étude pilote","type":"rct","level":2,"pop":"adulte","ctx":["récupération"],"aim":"traitement","mode":["LED"],"nm":[],"n":null,"effect":"mitigé","theme":"Récupération & courbatures","l1":"La LED infrarouge montre un effet antalgique sur les courbatures expérimentales, à confirmer dans des essais plus grands.","l2":"Étude pilote contrôlée.","l3":{"points":["—"],"limites":["Pilote."],"pratique":"—"},"em":[],"pre":"","topic":"sport","title":"Pain reduction by infrared light-emitting diode irradiation: a pilot study on experimentally induced delayed-onset muscle soreness in humans.","journal":"Lasers in medical science","journal_abbr":"Lasers Med Sci","authors":["Vinck E","Cagnie B","Coorevits P","et al."],"date":"2006-03-15","year":2006,"week":"2006-S11","doi":"10.1007/s10103-005-0366-6","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":28,"pub_types":["Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"","text":"The present pilot study investigated the analgesic efficacy of light-emitting diode (LED). In view of a standardised and controlled pain reduction study design, this in vivo trial was conducted on experimentally induced delayed-onset muscle soreness (DOMS). Thirty-two eligible human volunteers were randomly assigned to either an experimental (n=16) or placebo group (n=16). Immediately following the induction of muscle soreness, perceived pain was measured by means of a visual analog scale (VAS), followed by a more objective mechanical pain threshold (MPT) measurement and finally an eccentric/concentric isokinetic peak torque (IPT) assessment. The experimental group was treated with infrared LED at one of both arms, the other arm served as control. Irradiation lasted 6 min at a continuous power output of 160 mW, resulting in an energy density of 3.2 J/cm(2). The subjects of the placebo group received sham irradiation at both sides. In post-treatment, a second daily assessment of MPT and VAS took place. The treatment and assessment procedure (MPT, VAS and IPT) was performed during 4 consecutive days. Statistical analysis (a general linear model followed by post hoc least significant difference) revealed no apparent significant analgesic effects of LED at the above-described light parameters and treatment procedure for none of the three outcome measures. However, as the means of all VAS and MPT variables disclose a general analgesic effect of LED irradiation in favour of the experimental group, precaution should be taken in view of any clinical decision on LED. Future research should therefore focus on the investigation of the mechanisms of LED action and on the exploration of the analgesic effects of LED in a larger randomised clinical trial and eventually in more clinical settings."}],"keywords":[]},{"pmid":"16294723","title":"[Effects of He-Ne laser on gastric mucosa in rat with chronic atrophic gastritis].","journal_abbr":"Sheng Wu Yi Xue Gong Cheng Xue Za Zhi","authors":["Yang Y","Wang J","Shao X","et al."],"date":"2005-11-22","year":2005,"pub_types":["English Abstract","Research Support, Non-U.S. Gov't"],"curated":false,"type":"preclinical","level":5,"ctx":["populations"],"pre":"both","l1":"Compared with untreated group, the gastric mucosa of 3.36J x cm(-2) He-Ne laser group was significantly thicker (P < 0.01), the inflammatory cells of gastric mucosa were decreased (P < 0.05), the morphology, structure and volume of the…","kw":"Animals Chronic Disease Gastric Mucosa Gastritis, Atrophic Low-Level Light Therapy Male"},{"pmid":"15991302","title":"Effects of He-Ne laser irradiation on chronic atrophic gastritis in rats.","journal_abbr":"World J Gastroenterol","authors":["Shao XH","Yang YP","Dai J","et al."],"date":"2005-07-02","year":2005,"doi":"10.3748/wjg.v11.i25.3958","pmcid":"PMC4504905","cited_by":4,"pub_types":["Research Support, Non-U.S. Gov't"],"curated":false,"type":"preclinical","level":5,"ctx":["populations"],"pre":"both","l1":"3.36 J/cm(2) dose of He-Ne laser has a significant effect on CAG in rats.","kw":"Animals Chronic Disease Gastric Acid Gastritis, Atrophic Low-Level Light Therapy Male"},{"pmid":"15165387","title_fr":"Laser basse énergie et œdème des entorses de cheville de grade II chez le footballeur","type":"rct","level":2,"pop":"adulte","ctx":["blessures"],"aim":"traitement","mode":["laser"],"nm":[820],"n":47,"effect":"favorable","theme":"Blessures sportives","l1":"Chez des footballeurs avec entorse de cheville de grade II, ajouter le laser 820 nm au protocole RICE réduit davantage l'œdème à 24, 48 et 72 h.","l2":"Essai randomisé à 3 bras, 47 joueurs.","l3":{"points":["Effet anti-œdème précoce."],"limites":["Petit effectif."],"pratique":"Complément du RICE."},"em":["pulse"],"pre":"","topic":"sport","title":"Low-level laser treatment can reduce edema in second degree ankle sprains.","journal":"Journal of clinical laser medicine & surgery","journal_abbr":"J Clin Laser Med Surg","authors":["Stergioulas A"],"date":"2004-05-29","year":2004,"week":"2004-S22","doi":"10.1089/104454704774076181","pmcid":null,"license":null,"oa":false,"pdf":null,"cited_by":42,"pub_types":["Clinical Trial","Randomized Controlled Trial"],"curated":true,"depth":1,"abstract":[{"label":"OBJECTIVE","text":"Low-level laser therapy (LLLT) has been used for the last few years to treat sports injuries. The purpose of this study was to compare three therapeutic protocols in treating edema in second degree ankle sprains that did not require immobilization with a splint, under placebo-controlled conditions."},{"label":"MATERIALS AND METHODS","text":"Forty-seven soccer players with second degree ankle sprains, selected at random, were divided into the following groups: The first group (n = 16) was treated with the conventional initial treatment (RICE, rest, ice, compression, elevation), the second group (n = 16) was treated with the RICE method plus placebo laser, and the third group (n = 15) was treated with the RICE method plus an 820-nm GaA1As diode laser with a radiant power output of 40 mW at 16 Hz. Before the treatment, and 24, 48, and 72 h later, the volume of the edema was measured."},{"label":"RESULTS","text":"A three by three repeated measures ANOVA with a follow up post hoc test revealed that the group treated with the RICE and an 820-nm GaA1As diode laser presented a statistically significant reduction in the volume of the edema after 24 h (40.3 +/- 2.4 mL, p < 0.01), 48 h (56.4 +/- 3.1 mL, p < 0.002), and 72 h (65.1 +/- 4.4 mL, p < 0.001)."},{"label":"CONCLUSIONS","text":"LLLT combined with RICE can reduce edema in second-degree ankle sprains."}],"keywords":[]},{"pmid":"14583158","title":"Transdermal approaches to pain in sports injury management.","journal_abbr":"Curr Sports Med Rep","authors":["Bolin DJ"],"date":"2003-10-30","year":2003,"doi":"10.1249/00149619-200312000-00004","cited_by":11,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["blessures"],"l1":"In addition, there are numerous over the counter sports creams and prescribed topical treatments that are routinely used. With the pressure to treat athletes safely and efficiently, sports practitioners must rely on well-proven evidence…","kw":"Administration, Cutaneous Analgesics, Non-Narcotic Anti-Inflammatory Agents, Non-Steroidal Athletic Injuries Capsaicin Cryotherapy"},{"pmid":"10751018","title":"Sports and other soft tissue injuries, tendinitis, bursitis, and occupation-related syndromes.","journal_abbr":"Curr Opin Rheumatol","authors":["Huang HH","Qureshi AA","Biundo JJ"],"date":"2000-04-06","year":2000,"doi":"10.1097/00002281-200003000-00009","cited_by":25,"pub_types":["Review"],"curated":false,"type":"review","level":5,"ctx":["blessures","populations"],"l1":"Nonsurgical techniques in the treatment of carpal tunnel syndrome, such as yoga, ultrasound, noninvasive laser neurolysis, manipulation, nerve and tendon gliding exercises, and medications, are reviewed. Prednisolone was shown to be…","kw":"Athletic Injuries Bursitis Humans Occupational Diseases Soft Tissue Injuries Tendinopathy"}];
